    [0x01] = 0, [0x02] = 1, [0x04] = 2, [0x05] = 3, [0x06] = 4,
}
local function isAnyKeyDown(vk)
    local mb = MOUSE_VK_TO_IMGUI[vk]
    if mb then
        local down = ImGui.IsMouseDown(mb)
        return down
    end
    return Utils.IsKeyDown(vk)
end

