function KICKER.selectionMask(hash, count)
    local feat = FeatureMgr.GetFeature(hash)
    if not feat or not count then return 0 end
    local mask = 0
    for i = 0, count - 1 do
        if feat:IsListIndexToggled(i) then mask = mask | (1 << i) end
    end
    return mask
end

local function isPlayerFriend(playerId)
    local player = Players.GetById(playerId)
    if player and player.PlayerInfo then
        return player.PlayerInfo.FriendStatus >= 2
    end
    return false
end

local function getOrgBoss(playerId)
    local idx = OFF.GPBD_FM_3_BASE + 1 + playerId * OFF.GPBD_FM_3_SIZE + 10
    return ScriptGlobal.GetInt(idx) or -1
end

local scriptUnloading = false

local Widget = { _open = {} }

function Widget.chevron(x, y, w, h)
    local r, g, b, a = ImGui.GetStyleColorVec4(ImGuiCol.Text)
    r, g, b, a = math.floor(r * 255), math.floor(g * 255),
                 math.floor(b * 255), math.floor(a * 255)
    local cx = x + w - h * 0.5
    local cy = y + h * 0.5
    local hw = h * 0.19
    local hh = hw * 0.5
    ImGui.AddLine(cx - hw, cy - hh, cx, cy + hh, r, g, b, a, 1.5)
    ImGui.AddLine(cx, cy + hh, cx + hw, cy - hh, r, g, b, a, 1.5)
end

function Widget.fitPreview(text, w, h)
    if type(text) ~= "string" then return text end
    local avail = w - h
    if avail <= 0 then return text end
    local tw = ImGui.CalcTextSize(text)
    if tw <= avail then return text end
    return text:sub(1, math.max(1, math.floor(#text * avail / tw) - 3)) .. "..."
end

function Widget.beginCombo(label, preview, flags)
    if Widget.ok == nil then
        Widget.ok = type(ImGui.CalcItemWidth) == "function"
                and type(ImGui.GetCursorScreenPos) == "function"
                and type(ImGui.GetFrameHeight) == "function"
                and type(ImGui.GetStyleColorVec4) == "function"
        if not Widget.ok then
            Logger.LogInfo("[VibeScript] combo chevron off: this ImGui build is missing "
                .. "CalcItemWidth / GetCursorScreenPos / GetFrameHeight / GetStyleColorVec4")
        end
    end
    if not Widget.ok then return ImGui.BeginCombo(label, preview, flags) end

    local x, y = ImGui.GetCursorScreenPos()
    local w, h = ImGui.CalcItemWidth(), ImGui.GetFrameHeight()
    local open = ImGui.BeginCombo(label, Widget.fitPreview(preview, w, h), (flags or 0) | 32)
    if open then
        Widget._open[#Widget._open + 1] = { x, y, w, h }
    else
        Widget.chevron(x, y, w, h)
    end
    return open
end

function Widget.endCombo()
    ImGui.EndCombo()
    local g = table.remove(Widget._open)
    if g then Widget.chevron(g[1], g[2], g[3], g[4]) end
end

function Widget.combo(label, current, items, count)
    local sel, changed = current, false
    if Widget.beginCombo(label, items[current + 1] or "") then
        for i = 1, (count or #items) do
            if ImGui.Selectable(items[i], i - 1 == current) and i - 1 ~= current then
                sel, changed = i - 1, true
            end
        end
        Widget.endCombo()
    end
    return sel, changed
end

CENTRAL_TICK = { single = {}, player = {}, cb = {}, isTick = {} }
do
    local _AddFeature = FeatureMgr.AddFeature
    FeatureMgr.AddFeature = function(...)
        local hash, cb = (select(1, ...)), (select(5, ...))
        CENTRAL_TICK._lastHash = hash
        CENTRAL_TICK._lastCb = cb
        if type(hash) == "number" and type(cb) == "function" then
            CENTRAL_TICK.cb[hash] = cb
        end
        return _AddFeature(...)
    end
end
function centralOnTick(feat)
    if feat then
        CENTRAL_TICK.single[#CENTRAL_TICK.single + 1] = { feat = feat, fn = CENTRAL_TICK._lastCb }
        if type(CENTRAL_TICK._lastHash) == "number" then
            CENTRAL_TICK.isTick[CENTRAL_TICK._lastHash] = true
        end
    end
    return feat
end
function centralPlayerOnTick(hash, fn)
    local h = {}
    for pid = 0, 31 do h[pid] = FeatureMgr.GetFeature(hash, pid) end
    CENTRAL_TICK.player[#CENTRAL_TICK.player + 1] = { hash = hash, fn = fn, h = h }
end
function CENTRAL_TICK.run()
    if scriptUnloading then return end
    local single = CENTRAL_TICK.single
    for i = 1, #single do
        local t = single[i]
        local ok, err = pcall(t.fn, t.feat)
        if not ok and not t.warned then
            t.warned = true
            Logger.LogInfo("[VibeScript] central OnTick error: " .. tostring(err))
        end
    end
    local player = CENTRAL_TICK.player
    local np = #player
    if np > 0 then
        for pid = 0, 31 do
            if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                for j = 1, np do
                    local p = player[j]
                    local ok, err = pcall(p.fn, p.h[pid] or FeatureMgr.GetFeature(p.hash, pid))
                    if not ok and not p.warned then
                        p.warned = true
                        Logger.LogInfo("[VibeScript] central player OnTick error: " .. tostring(err))
                    end
                end
            end
        end
    end
end
function CENTRAL_TICK.driver()
    if scriptUnloading then return end
    if VIBE_GATE.state ~= "clear" then return end
    local ok, err = pcall(CENTRAL_TICK.run)
    if not ok and not CENTRAL_TICK.driverWarned then
        CENTRAL_TICK.driverWarned = true
        Logger.LogInfo("[VibeScript] central driver error: " .. tostring(err))
    end
end
FeatureMgr.AddFeature(Utils.Joaat("LUA_CentralTickDriver"), "##CentralTickDriver",
    eFeatureType.Toggle, "", CENTRAL_TICK.driver)
    :RegisterCallbackTrigger(eCallbackTrigger.OnTick)
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
    :SetSearchable(false)
    :SetVisible(false)
FeatureMgr.GetFeature(Utils.Joaat("LUA_CentralTickDriver")):Toggle(true)

local pendingKicks = {}
KICKER.pendingKickIds = {}

local function doKick(playerId)
    playerId = math.tointeger(playerId)
    if not playerId or playerId < 0 or playerId > 31 then return false end
    if KICKER.pendingKickIds[playerId] then return false end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(playerId) then return false end
    KICKER.pendingKickIds[playerId] = true
    pendingKicks[#pendingKicks + 1] = playerId
    return true
end

local function kickWorker()
    if scriptUnloading or #pendingKicks == 0 then
        Script.Yield(100)
        return
    end

    local pid = table.remove(pendingKicks, 1)
    local attempts = 0
    while not scriptUnloading
        and attempts < KICKER.MAX_RETRIES
        and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) do
        if KICKER.isProtected and KICKER.isProtected(pid) then break end

        attempts = attempts + 1
        local isHost = NETWORK.NETWORK_IS_HOST()
        local verifyMs = isHost and KICKER.HOST_VERIFY_MS or KICKER.SERVER_VERIFY_MS
        local sentAt = Time.GetEpocheMs()
        FeatureMgr.TriggerFeatureCallback(
            isHost and KICKER.KICK_HOST or KICKER.KICK_SERVER, pid)

        local remaining = verifyMs - (Time.GetEpocheMs() - sentAt)
        if remaining > 0 then Script.Yield(remaining) end
    end

    KICKER.pendingKickIds[pid] = nil
    Script.Yield()
end

for _ = 1, KICKER.WORKERS do
    Script.RegisterLooped(kickWorker)
end

