lockOntoPlayers.H_NETWORK_HANDLE_FROM_PLAYER = 0x388EB2B86C73B6B3
lockOntoPlayers.H_NETWORK_IS_FRIEND          = 0x1A24A179F9B31654
lockOntoPlayers.FRIEND_TTL  = 30.0
lockOntoPlayers.friendCache = {}
lockOntoPlayers.handleBuf   = nil
lockOntoPlayers.isFriend = function(pid, ped, forceRefresh)
    local c   = lockOntoPlayers.friendCache[pid]
    local now = os.clock()
    if not forceRefresh and c and c.ped == ped
            and (now - c.at) < lockOntoPlayers.FRIEND_TTL then
        return c.friend
    end
    local friend = isPlayerFriend(pid)
    if not friend then
        if not lockOntoPlayers.handleBuf then
            lockOntoPlayers.handleBuf = Memory.Alloc(104)
        end
        lockOntoPlayers.iv(lockOntoPlayers.H_NETWORK_HANDLE_FROM_PLAYER, pid,
              lockOntoPlayers.handleBuf, 13)
        friend = Natives.InvokeBool(lockOntoPlayers.H_NETWORK_IS_FRIEND,
              lockOntoPlayers.handleBuf) == true
    end
    lockOntoPlayers.friendCache[pid] = { ped = ped, friend = friend, at = now }
    return friend
end

lockOntoPlayers.isProtected = function(pid, ped)
    local myBoss = getOrgBoss(GTA.GetLocalPlayerId())
    if myBoss >= 0 and myBoss <= 31 and getOrgBoss(pid) == myBoss then return true end
    return lockOntoPlayers.isFriend(pid, ped)
end

lockOntoPlayers.isSessionTarget = function(pid)
    if pid == GTA.GetLocalPlayerId()
            or not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then return false end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    return not lockOntoPlayers.isProtected(pid, ped)
end

function KICKER.isProtected(pid)
    if pid == GTA.GetLocalPlayerId() then return true end
    local myBoss = getOrgBoss(GTA.GetLocalPlayerId())
    if myBoss >= 0 and myBoss <= 31 and getOrgBoss(pid) == myBoss then return true end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    local c = KICKER.friendCache and KICKER.friendCache[pid]
    local now = os.clock()
    if c and c.ped == ped and (now - c.at) < 2.0 then return c.friend end
    local friend = lockOntoPlayers.isFriend(pid, ped, true)
    KICKER.friendCache = KICKER.friendCache or {}
    KICKER.friendCache[pid] = { ped = ped, friend = friend, at = now }
    return friend
end

KICKER.JOIN_GRACE = 3.0
KICKER.joinGrace = {}
function KICKER.noteJoin(pid)
    KICKER.joinGrace[pid] = os.clock() + KICKER.JOIN_GRACE
    if KICKER.friendCache then KICKER.friendCache[pid] = nil end
    lockOntoPlayers.friendCache[pid] = nil
end
function KICKER.deferFreshJoin(state, pid)
    local untilAt = KICKER.joinGrace[pid]
    if not untilAt or os.clock() >= untilAt then return false end
    local pending = state.pending[pid]
    if pending then
        pending.nextCheck = math.max(pending.nextCheck or 0, untilAt)
    else
        state.pending[pid] = { attempts = 0, nextCheck = untilAt }
    end
    return true
end

