do
    local idx = IS_ENHANCED and {
        gangByColour = 2649983,
        gangByBoss   = 2649994,
        gang         = 2650027,
        colourCache  = 2689338,
    } or {
        gangByColour = 2649980,
        gangByBoss   = 2649991,
        gang         = 2650024,
        colourCache  = 2689333,
    }
    local SLOTS      = 10
    local STEP_MS    = 500
    local IS_SESSION_ACTIVE = 0xD83C2B94E7508980
    local IS_IN_TRANSITION  = 0x68049AEFF83D8F0A
    local active     = false
    local nextStepAt = 0
    local slot       = 0
    local restore    = nil
    local statusText = nil

    local function colourIdx(gang) return idx.gang + gang * 2 + 1 end

    local function sessionReady()
        return Natives.InvokeBool(IS_SESSION_ACTIVE)
            and not Natives.InvokeBool(IS_IN_TRANSITION)
    end

    local function orgState()
        local boss = getOrgBoss(GTA.GetLocalPlayerId())
        if boss < 0 or boss > 31 then return -1, -1 end
        local gang = ScriptGlobal.GetInt(idx.gangByBoss + boss) or -1
        if gang < 0 or gang >= SLOTS then return boss, -1 end
        return boss, gang
    end

    local HOST_OF_SCRIPT = 0x1D6A14F1F9A736FC

    local function setColour(gang, colour)
        ScriptGlobal.SetInt(colourIdx(gang), colour)
        ScriptGlobal.SetInt(idx.colourCache, colour)
    end

    local function ownsWrite(r)
        if not r then return false end
        return GTA.GetLocalPlayerId() == r.localPid
            and ScriptGlobal.GetInt(idx.gangByBoss + r.boss) == r.gang
            and ScriptGlobal.GetInt(idx.gangByColour + r.colour) == r.gang
            and ScriptGlobal.GetInt(colourIdx(r.gang)) == r.written
    end

    local function release()
        if not restore then return end
        local r = restore
        if ownsWrite(r) then
            ScriptGlobal.SetInt(colourIdx(r.gang), r.colour)
            if getOrgBoss(r.localPid) == r.boss then
                ScriptGlobal.SetInt(idx.colourCache, r.colour)
            end
        end
        restore = nil
    end

    local function stop()
        release()
        statusText = nil
        active = false
    end

    rainbowBlipOnTick = function(f)
        if not f:IsToggled() then
            if active then stop() end
            return
        end

        active = true

        if not sessionReady() then
            statusText = "Waiting for session"
            return
        end

        local boss, gang = orgState()
        if boss == -1 then
            release()
            statusText = "Not in an organization"
            return
        end
        if gang == -1 then
            release()
            statusText = nil
            return
        end


        if restore and (restore.boss ~= boss or restore.gang ~= gang
            or restore.localPid ~= GTA.GetLocalPlayerId()) then
            release()
        end

        if restore == nil then
            local home = -1
            for c = 0, SLOTS - 1 do
                if ScriptGlobal.GetInt(idx.gangByColour + c) == gang then home = c; break end
            end
            if home < 0 then
                statusText = nil
                return
            end
            local cur = ScriptGlobal.GetInt(colourIdx(gang)) or -1
            restore = {
                gang = gang, colour = home, written = cur, boss = boss,
                localPid = GTA.GetLocalPlayerId(),
            }
            slot = (cur >= 0 and cur < SLOTS) and cur or home
            nextStepAt = 0
        end

        local now = Time.GetEpocheMs()
        if now < nextStepAt then return end
        nextStepAt = now + STEP_MS

        slot = (slot + 1) % SLOTS
        setColour(gang, slot)
        restore.written = slot

        local host = Natives.InvokeInt(HOST_OF_SCRIPT, "freemode", -1, 0)
        if host ~= GTA.GetLocalPlayerId() then
            statusText = "Local only"
        else
            statusText = "Session-wide"
        end
    end

    rainbowBlipStatus = function() return statusText end

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, stop)
end

centralOnTick(FeatureMgr.AddFeature(H.RAINBOW_BLIP, "Rainbow Blip", eFeatureType.Toggle,
    "Cycles through all of the colours applied to an organization. Must be script host for others to see this, otherwise local only.",
    rainbowBlipOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)

do
    local bossLimit = {
        SLOT0   = IS_ENHANCED and 1923262 or 1922989,
        MAX_IDX = IS_ENHANCED and 275059 or 275055,
        SLOTS   = 10,
        GANG_OF = IS_ENHANCED and 2649994 or 2649991,
        GANG0   = IS_ENHANCED and 2650027 or 2650024,
        freed    = nil,
        borrowed = nil,
        status   = nil,
    }

    local IS_SESSION_ACTIVE = 0xD83C2B94E7508980
    local IS_IN_TRANSITION  = 0x68049AEFF83D8F0A
    local HOST_OF_SCRIPT    = 0x1D6A14F1F9A736FC

    local function sessionReady()
        return Natives.InvokeBool(IS_SESSION_ACTIVE)
            and not Natives.InvokeBool(IS_IN_TRANSITION)
    end

    local function playerRid(pid)
        local rid
        pcall(function()
            local player = Players.GetById(pid)
            local info = player and player:GetGamerInfo()
            rid = info and math.tointeger(info.RockstarId or 0) or nil
        end)
        if rid and rid > 0 then return rid end
        return nil
    end

    function bossLimit.count()
        local s = bossLimit
        local n = ScriptGlobal.GetInt(s.MAX_IDX) or 0
        if n < 1 or n > s.SLOTS then n = s.SLOTS end
        return n
    end

    function bossLimit.restoreSlot()
        local s = bossLimit
        local b = s.freed
        if not b then return end

        local duplicate = false
        for i = 0, b.count - 1 do
            if i ~= b.slot and ScriptGlobal.GetInt(s.SLOT0 + i) == b.pid then
                duplicate = true
                break
            end
        end

        local stillFree = ScriptGlobal.GetInt(s.SLOT0 + b.slot) == -1
        local rid = playerRid(b.pid)
        if not duplicate and stillFree and rid == nil then
            return
        end
        if not duplicate and stillFree and rid == b.rid and getOrgBoss(b.pid) == b.pid then
            ScriptGlobal.SetInt(s.SLOT0 + b.slot, b.pid)
        end
        s.freed = nil
    end

    function bossLimit.dropGang()
        local s = bossLimit
        local b = s.borrowed
        if not b then return end
        if playerRid(b.pid) == b.rid
            and ScriptGlobal.GetInt(s.GANG0 + b.gang * 2) ~= b.pid
            and ScriptGlobal.GetInt(s.GANG_OF + b.pid) == b.gang
        then
            ScriptGlobal.SetInt(s.GANG_OF + b.pid, -1)
        end
        s.borrowed = nil
    end

    function bossLimit.restore()
        bossLimit.restoreSlot()
        bossLimit.dropGang()
    end

    function bossLimit.gangTick(n)
        local s  = bossLimit
        local me = GTA.GetLocalPlayerId()
        local b  = s.borrowed

        if b then
            local rid = playerRid(me)
            if rid == nil then return end
            if b.pid ~= me or b.rid ~= rid
                or ScriptGlobal.GetInt(s.GANG_OF + b.pid) ~= b.gang
                or ScriptGlobal.GetInt(s.GANG0 + b.gang * 2) == me
            then
                s.borrowed, b = nil, nil
            end
        end

        if getOrgBoss(me) ~= me then
            s.dropGang()
            return
        end

        for i = 0, n - 1 do
            local owner = ScriptGlobal.GetInt(s.GANG0 + i * 2) or 0
            if owner ~= -1 and (owner < 0 or owner > 31) then return end
            if owner == -1 then
                s.dropGang()
                return
            end
        end

        if b or (ScriptGlobal.GetInt(s.GANG_OF + me) or -1) ~= -1 then return end

        for i = n - 1, 0, -1 do
            local colour = ScriptGlobal.GetInt(s.GANG0 + i * 2 + 1) or -1
            if colour >= 0 and colour < s.SLOTS then
                local myRid = playerRid(me)
                if not myRid then return end
                s.borrowed = { gang = i, pid = me, rid = myRid }
                ScriptGlobal.SetInt(s.GANG_OF + me, i)
                return
            end
        end
    end

    function bossLimit.onTick(f)
        local s = bossLimit
        if not f:IsToggled() then s.status = nil end
        if not sessionReady() then
            return
        end


        if s.freed then
            local b = s.freed
            local rid = playerRid(b.pid)
            if rid == nil then return end
            local duplicate = false
            for i = 0, b.count - 1 do
                if i ~= b.slot and ScriptGlobal.GetInt(s.SLOT0 + i) == b.pid then
                    duplicate = true
                    break
                end
            end
            if rid ~= b.rid or getOrgBoss(b.pid) ~= b.pid
                or ScriptGlobal.GetInt(s.SLOT0 + b.slot) ~= -1 or duplicate
            then
                s.freed = nil
            end
        end
        if not f:IsToggled() then
            if s.freed or s.borrowed then s.restore() end
            return
        end

        local host = Natives.InvokeInt(HOST_OF_SCRIPT, "freemode", -1, 0)
        s.status = host == GTA.GetLocalPlayerId() and "Session-wide" or "Local only"

        local n     = s.count()
        local free  = nil
        local zeros = 0
        for i = 0, n - 1 do
            local v = ScriptGlobal.GetInt(s.SLOT0 + i) or 0
            if v ~= -1 and (v < 0 or v > 31) then
                s.freed = nil
                return
            end
            if v == 0 then zeros = zeros + 1 end
            if v == -1 and not free then free = i end
        end
        if zeros == n then return end

        if not free then
            for slot = n - 1, 0, -1 do
                local pid = ScriptGlobal.GetInt(s.SLOT0 + slot)
                local rid = playerRid(pid)
                if rid and getOrgBoss(pid) == pid then
                    s.freed = { slot = slot, pid = pid, rid = rid, count = n }
                    ScriptGlobal.SetInt(s.SLOT0 + slot, -1)
                    break
                end
            end
        end

        s.gangTick(n)
    end

    bossLimitStatus = function() return bossLimit.status end

    centralOnTick(FeatureMgr.AddFeature(H.BOSS_LIMIT,
        "No Organization Limit", eFeatureType.Toggle,
        "Bypass the session's boss limit of 10. When you are the script host, this applies to the entire lobby.",
        bossLimit.onTick))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, bossLimit.restore)
end

do
    local p = { PATCHED = 0xC3, addr = nil, retryIn = 0, missLogged = false }
    if IS_ENHANCED then
        p.ANCHOR   = "48 81 EC 30 09 00 00 48 89 CE 03 15"
        p.SITE_OFF = -1
        p.ORIG     = 0x56
    else
        p.ANCHOR   = "89 91 1C 83 02 00 E9"
        p.SITE_OFF = -6
        p.ORIG     = 0x03
    end

    p.resolve = function()
        if p.addr then return true end
        if p.retryIn > 0 then p.retryIn = p.retryIn - 1; return false end
        p.retryIn = 120
        local runBody = function()
            local hit = Memory.Scan(p.ANCHOR)
            if not hit or hit == 0 then
                if not p.missLogged then
                    p.missLogged = true
                    if VIBESCRIPT_VERBOSE then
                        Logger.LogInfo("[VibeScript] Better Escape: anchor not found yet (retrying)")
                    end
                end
                return
            end
            local site = hit + p.SITE_OFF
            local b = Memory.ReadUByte(site)
            if b ~= p.ORIG and b ~= p.PATCHED then
                if VIBESCRIPT_VERBOSE then
                    Logger.LogInfo(string.format(
                        "[VibeScript] Better Escape: unexpected site byte 0x%02X @0x%X; aborting", b or 0, site))
                end
                return
            end
            p.addr = site
            logf("Better Escape: resolved @0x%X (cur=0x%02X)", site, b)
        end
        runBody()
        return p.addr ~= nil
    end

    p.ensure = function(wantPatched)
        if not p.resolve() then return end
        do
            local cur = Memory.ReadUByte(p.addr)
            if wantPatched then
                if cur == p.ORIG then Memory.WriteByte(p.addr, p.PATCHED) end
            else
                if cur == p.PATCHED then Memory.WriteByte(p.addr, p.ORIG) end
            end
        end
    end

    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function() pcall(p.ensure, false) end)

    centralOnTick(FeatureMgr.AddFeature(H.BETTER_ESC_ENGINE, "Better Escape", eFeatureType.Toggle,
        "Removes the short delay before Escape can reopen the pause menu after closing it.",
        function(f)
            p.ensure(f:IsToggled())
        end))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end

centralOnTick(FeatureMgr.AddFeature(H.WP_INTERIOR, "Allow Exterior Waypoint", eFeatureType.Toggle,
    "Lets you set a waypoint from the pause map while inside interiors.",
    function(f)
        if not f:IsToggled() then return end
        if not HUD.IS_PAUSE_MENU_ACTIVE() then return end
        local interior = Natives.InvokeInt(0x2107BA504071A6BB, PLAYER.PLAYER_PED_ID())
        if not interior or interior == 0 then return end
        Natives.InvokeVoid(0x58FADDED207897DC, false)
    end))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)


do
    local yogaRun = {
        H_RUN    = 0xC5286FFC176F28A2,
        H_SPRINT = 0x57E457CD2C0FC168,
        H_MOVE   = 0x085BF80FA50A39D1,
        H_WATER  = 0x0B3E35AC043707D9,
        MULT     = 1.15,
    }
    centralOnTick(FeatureMgr.AddFeature(H.YOGA_RUN, "Yoga Run", eFeatureType.Toggle,
        "Reproduces GTA Online's mansion Yoga speed buff. Provides a 15% speed increase on land and water.",
        function(f)
            if not f:IsToggled() then return end
            local ped = PLAYER.PLAYER_PED_ID()
            if Natives.InvokeBool(yogaRun.H_RUN, ped) or Natives.InvokeBool(yogaRun.H_SPRINT, ped) then
                Natives.InvokeVoid(yogaRun.H_MOVE,  ped, yogaRun.MULT + 0.0)
                Natives.InvokeVoid(yogaRun.H_WATER, ped, yogaRun.MULT + 0.0)
            end
        end))
        :SetNoCallbackOnPress(true)
        :SetSaveable(false)
end


do
    local fasterLadders = {
        OFF_INTEL     = 0x10A0,
        OFF_TREES     = 0x370,
        OFF_TREE_ENT  = 0x08,
        OFF_TREE_TASK = 0x20,
        OFF_TASK_ENT  = 0x10,
        OFF_SUBTASK   = 0x20,
        OFF_TYPE_ID   = 0x34,
        OFF_RATE      = 0x20C,
        TASK_LADDER   = 1,
        STATE_IDLE    = 7,
        STATE_UP      = 8,
        STATE_DOWN    = 9,
        STATE_SLIDE   = 12,
        PRIORITIES    = 5,
        MAX_DEPTH     = 16,
        SETTLE_MS     = 150,
        task          = 0,
        orig          = nil,
        aligned       = false,
        fastAfter     = 0,
    }

    local function ladderPtr(addr)
        if not addr or addr <= 0 or addr >= 0x800000000000 then return nil end
        local v = Memory.ReadLong(addr)
        if v <= 0 or v >= 0x800000000000 then return nil end
        return v
    end

    function fasterLadders.findTask()
        local s = fasterLadders
        local cped = GTA.GetLocalPed and GTA.GetLocalPed() or nil
        if not cped then return nil end
        local pedAddr = cped:GetAddress()
        if not pedAddr or pedAddr == 0 then return nil end

        local intel = ladderPtr(pedAddr + s.OFF_INTEL)
        if not intel then return nil end
        local tree = ladderPtr(intel + s.OFF_TREES)
        if not tree then return nil end
        if Memory.ReadLong(tree + s.OFF_TREE_ENT) ~= pedAddr then return nil end

        for pri = 0, s.PRIORITIES - 1 do
            local task = ladderPtr(tree + s.OFF_TREE_TASK + pri * 8)
            local depth = 0
            while task and depth < s.MAX_DEPTH do
                if (Memory.ReadInt(task + s.OFF_TYPE_ID) & 0xFFFF) == s.TASK_LADDER
                   and Memory.ReadLong(task + s.OFF_TASK_ENT) == pedAddr then
                    return task
                end
                task = ladderPtr(task + s.OFF_SUBTASK)
                depth = depth + 1
            end
        end
        return nil
    end

    function fasterLadders.restore()
        local s = fasterLadders
        if s.orig then
            local task = s.findTask()
            if task then Memory.WriteFloat(task + s.OFF_RATE, s.orig) end
        end
        s.task, s.orig, s.aligned, s.fastAfter = 0, nil, false, 0
    end

    function fasterLadders.onTick(f)
        local s = fasterLadders
        if not f:IsToggled() then
            if s.orig then s.restore() end
            return
        end

        local task = fasterLadders.findTask()
        if not task then
            s.task, s.orig, s.aligned, s.fastAfter = 0, nil, false, 0
            return
        end

        local addr = task + s.OFF_RATE
        if s.task ~= task then
            local base = Memory.ReadFloat(addr)
            if not (base and base >= 0.5 and base <= 2.0) then base = 1.0 end
            s.task, s.orig, s.aligned, s.fastAfter = task, base, false, 0
        end

        local state = (Memory.ReadInt(task + s.OFF_TYPE_ID) >> 16) & 0xFF
        local activeClimb = state == s.STATE_UP or state == s.STATE_DOWN
            or state == s.STATE_SLIDE
        if not s.aligned and activeClimb then
            s.aligned = true
            s.fastAfter = Time.GetEpocheMs() + s.SETTLE_MS
        end

        local multiplier = 1.0
        local canBoost = activeClimb or (s.aligned and state == s.STATE_IDLE)
        if canBoost and Time.GetEpocheMs() >= s.fastAfter then
            multiplier = f:GetFloatValue()
        end

        local want = s.orig * multiplier
        if Memory.ReadFloat(addr) ~= want then Memory.WriteFloat(addr, want) end
    end

    centralOnTick(FeatureMgr.AddFeature(H.FASTER_LADDERS,
        "Faster Ladders", eFeatureType.SliderFloatToggle,
        "Climb ladders much faster.",
        fasterLadders.onTick))
        :SetNoCallbackOnPress(true)
        :SetLimitValues(1.0, 5.0)
        :SetDefaultValue(1.0)
        :SetSaveable(false)
        :Reset()
end


patchFn.wpInsideInterior = {
    LEGACY_SITES = {
        { AOB = "38 0D ?? ?? ?? ?? 75 ?? 38 0D ?? ?? ?? ?? 75 ?? 38 0D ?? ?? ?? ?? 75 ?? B9 01 00 00 00",
          PATCH_OFF = 6, ORIG_BYTES = { 0x75, 0x15 }, NEW_BYTES = { 0x90, 0x90 } },
    },
    ENHANCED_SITES = {
        { AOB = "08 C1 80 F9 01 0F 85 ?? ?? ?? ?? 80 3D ?? ?? ?? ?? 00 0F 85 ?? ?? ?? ?? 80 3D ?? ?? ?? ?? 00 0F 85 ?? ?? ?? ?? 80 3D ?? ?? ?? ?? 00 0F 85 ?? ?? ?? ?? 84 DB",
          PATCH_OFF = 18, ORIG_BYTES = { 0x0F, 0x85, 0x86, 0x02, 0x00, 0x00 },
          VERIFY_BYTES = { 0x0F, 0x85 }, CAPTURE_LEN = 6,
          NEW_BYTES = { 0x90, 0x90, 0x90, 0x90, 0x90, 0x90 } },
        { AOB = "84 C8 75 ?? 80 3D ?? ?? ?? ?? 00 75 ?? 80 3D ?? ?? ?? ?? 00 75 ?? 0F B6 1D",
          PATCH_OFF = 11, ORIG_BYTES = { 0x75, 0x32 }, NEW_BYTES = { 0x90, 0x90 },
          VERIFY_BYTES = { 0x75 }, CAPTURE_LEN = 2,
        },
    },
    sites = nil, scanned = false, applied = false, resolveFailLogged = false,
    rayBuf = Memory.Alloc(64),
}
patchFn.wpInsideInterior.resolve = function()
    local p = patchFn.wpInsideInterior
    if p.sites then return #p.sites > 0 end
    if p.scanned then return false end
    p.scanned = true
    local defs = IS_ENHANCED and p.ENHANCED_SITES or p.LEGACY_SITES
    local resolved = {}
    for i = 1, #defs do
        local d = defs[i]
        local site, orig = nil, nil
        local runBody = function()
            local hit = Memory.Scan(d.AOB)
            if not hit or hit == 0 then return end
            local s = hit + d.PATCH_OFF
            local verify = d.VERIFY_BYTES or d.ORIG_BYTES
            for j = 1, #verify do
                if Memory.ReadUByte(s + (j - 1)) ~= verify[j] then return end
            end
            if d.CAPTURE_LEN then
                orig = {}
                for j = 1, d.CAPTURE_LEN do
                    orig[j] = Memory.ReadUByte(s + (j - 1))
                end
            else
                orig = d.ORIG_BYTES
            end
            site = s
        end
        runBody()
        if site then
            resolved[#resolved + 1] = { addr = site, ORIG_BYTES = orig, NEW_BYTES = d.NEW_BYTES }
        end
    end
    p.sites = resolved
    if #resolved == 0 and not p.resolveFailLogged then
        p.resolveFailLogged = true
        if VIBESCRIPT_VERBOSE then
            Logger.LogInfo("[VibeScript] WaypointsInsideInteriors: no patch sites resolved; feature off")
        end
    end
    return #resolved > 0
end
patchFn.wpInsideInterior.apply = function()
    local p = patchFn.wpInsideInterior
    if p.applied then return true end
    if not p.resolve() then return false end
    local anyOk = false
    for i = 1, #p.sites do
        local s = p.sites[i]
        local runBody = function()
            for j = 1, #s.ORIG_BYTES do
                if Memory.ReadUByte(s.addr + (j - 1)) ~= s.ORIG_BYTES[j] then return end
            end
            for j = 1, #s.NEW_BYTES do Memory.WriteByte(s.addr + (j - 1), s.NEW_BYTES[j]) end
            anyOk = true
        end
        runBody()
    end
    p.applied = anyOk
    return p.applied
end
patchFn.wpInsideInterior.restore = function()
    local p = patchFn.wpInsideInterior
    if not p.sites then p.applied = false; return end
    do
        for i = 1, #p.sites do
            local s = p.sites[i]
            for j = 1, #s.ORIG_BYTES do Memory.WriteByte(s.addr + (j - 1), s.ORIG_BYTES[j]) end
        end
    end
    p.applied = false
end

patchFn.wpInsideInterior.CHERAX_AUTO_TP_HASH = 0xD13C7A27
patchFn.wpInsideInterior.resolveCheraxAutoTp = function()
    local p = patchFn.wpInsideInterior
    if p.cheraxAutoTp then return p.cheraxAutoTp end

    local ft = FeatureMgr.GetFeature(p.CHERAX_AUTO_TP_HASH)
    if ft then
        local gotHash = ft:GetHash()
        local isToggle = ft:IsToggleFeature()
        if gotHash == p.CHERAX_AUTO_TP_HASH and isToggle then
            p.cheraxAutoTp = ft
            if not p.cheraxLogged then
                p.cheraxLogged = true
                log(("[WPautoTP] resolved Cherax auto-teleport by hash=0x%X"):format(p.CHERAX_AUTO_TP_HASH))
            end
        end
    end
    if p.cheraxAutoTp then return p.cheraxAutoTp end

    if p.heuristicTried then return nil end
    p.heuristicTried = true
    local feats = FeatureMgr.GetAllFeatures()
    if feats then
        local toggles, chosen = {}, nil
        for _, ft in pairs(feats) do
            local name = ft:GetName(false)
            if name then
                local n = name:lower()
                if n:find("waypoint") and (n:find("teleport") or n:find("tp")) then
                    local isToggle = ft:IsToggleFeature()
                    log(("[WPautoTP] candidate '%s' toggle=%s"):format(name, tostring(isToggle)))
                    if isToggle then
                        toggles[#toggles + 1] = ft
                        if n:find("auto") then chosen = ft end
                    end
                end
            end
        end
        if not chosen and #toggles == 1 then chosen = toggles[1] end
        p.cheraxAutoTp = chosen
        if chosen then
            log(("[WPautoTP] using Cherax auto-teleport feature (name heuristic) hash=0x%X"):format(chosen:GetHash()))
        else
            log("[WPautoTP] no Cherax auto-teleport feature found (hash + name heuristic both failed); leaving teleport alone")
        end
    end
    return p.cheraxAutoTp
end
patchFn.wpInsideInterior.probeFloorZ = function(x, y, nearZ)
    local p = patchFn.wpInsideInterior
    if not p.rayBuf then return nil end
    local belowBest, aboveBest = nil, nil
    do
        local ped = PLAYER.PLAYER_PED_ID()
        local bottom = nearZ - 30.0
        local thresh = nearZ + 1.0
        local aboveCap = nearZ + 2.0
        local z = nearZ + 12.0
        for _ = 1, 16 do
            local handle = SHAPETEST.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE(
                x, y, z, x, y, bottom, -1, ped, 7)
            SHAPETEST.GET_SHAPE_TEST_RESULT(handle, p.rayBuf, p.rayBuf + 8, p.rayBuf + 32, p.rayBuf + 56)
            if Memory.ReadByte(p.rayBuf) == 0 then break end
            local hz = Memory.ReadFloat(p.rayBuf + 24)
            local nz = Memory.ReadFloat(p.rayBuf + 48)
            if nz > 0.5 then
                if hz <= thresh then
                    if belowBest == nil or hz > belowBest then belowBest = hz end
                elseif hz <= aboveCap then
                    if aboveBest == nil or hz < aboveBest then aboveBest = hz end
                end
            end
            z = hz - 0.5
            if z <= bottom then break end
        end
    end
    if belowBest ~= nil then return belowBest end
    return aboveBest
end
patchFn.wpInsideInterior.tickRoomFix = function()
    local p = patchFn.wpInsideInterior
    if not p.roomFixTicks or p.roomFixTicks <= 0 then return end
    local paused = HUD.IS_PAUSE_MENU_ACTIVE()
    if not paused then p.roomFixTicks = p.roomFixTicks - 1 end
    local runBody = function()
        local ped = PLAYER.PLAYER_PED_ID()
        local ent = ped
        if PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
            local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
            if veh and veh ~= 0 then ent = veh end
        end
        local entInt  = Natives.InvokeInt(0x2107BA504071A6BB, ent)
        local entRoom = Natives.InvokeInt(0x399685DB942336BC, ent)
        if entInt ~= 0 and entRoom ~= 0 then
            if not p.roomFixResolvedLogged then
                p.roomFixResolvedLogged = true
                log(("[WPautoTP] roomfix: entity self-resolved interior=%d room=%d"):format(entInt, entRoom))
            end
            p.roomFixTicks = 0
            return
        end
        if not paused and (p.roomFixGrace or 0) > 0 then p.roomFixGrace = p.roomFixGrace - 1; return end
        Natives.InvokeVoid(0x405DC2AEF6AF95B9, 0)
        local vpRoom = Natives.InvokeInt(0xA6575914D2A0B450)
        if vpRoom == 0 or vpRoom == -1 then return end
        local cam = V3.New(Natives.InvokeV3(0xA200EB1EE790F448))
        local camInt = cam and Natives.InvokeInt(0xB0F7F8663821D9C3, cam.x, cam.y, cam.z) or 0
        if camInt == 0 then camInt = p.roomFixDestInt or 0 end
        if camInt == 0 then return end
        if not Natives.InvokeBool(0x6726BDCCC1932F0E, camInt) then return end
        p.roomFixTries = (p.roomFixTries or 0) + 1
        Natives.InvokeVoid(0x52923C4710DD9907, ent, camInt, vpRoom)
        local newRoom = Natives.InvokeInt(0x399685DB942336BC, ent)
        log(("[WPautoTP] roomfix force try=%d camInt=%d vpRoom=%d -> entityRoom=%d"):format(p.roomFixTries, camInt, vpRoom, newRoom))
        if newRoom ~= 0 then
            p.roomFixTicks = 0
        elseif p.roomFixTries >= 5 then
            p.roomFixTicks = 0
            log("[WPautoTP] roomfix: gave up after 5 force tries (entity still outside)")
        end
    end
    runBody()
end
patchFn.wpInsideInterior.autoTeleportTick = function()
    local p = patchFn.wpInsideInterior
    if not Natives.InvokeBool(0x1DD1F58F493F1DA5) then
        p.lastWpX = nil
        return
    end
    local runBody = function()
        local blip = Natives.InvokeInt(0x1BEDE233E6CD2A1F, 8)
        if not blip or blip == 0 then return end
        local c = V3.New(Natives.InvokeV3(0xFA7C7F0AADF25D09, blip))
        if not c then return end
        if p.lastWpX and math.abs(c.x - p.lastWpX) < 1.0 and math.abs(c.y - p.lastWpY) < 1.0 then
            return
        end
        p.lastWpX, p.lastWpY = c.x, c.y
        local ped = PLAYER.PLAYER_PED_ID()
        local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
        local interior = Natives.InvokeInt(0x2107BA504071A6BB, ped)
        local targetZ
        if interior ~= 0 and math.abs(c.x - pos.x) < 300.0 and math.abs(c.y - pos.y) < 300.0 then
            local fz = p.probeFloorZ(c.x, c.y, pos.z)
            if not fz then
                Natives.InvokeVoid(0xA7E4E2D361C2627F)
                p.lastWpX, p.lastWpY = nil, nil
                log(("[WPautoTP] no floor under (%.2f, %.2f) inside interior; cleared waypoint, no teleport"):format(c.x, c.y))
                return
            end
            targetZ = fz + 1.0
            p.roomFixDestInt = Natives.InvokeInt(0xB0F7F8663821D9C3, c.x, c.y, targetZ)
            p.roomFixTicks, p.roomFixGrace, p.roomFixTries = 90, 12, 0
            p.roomFixResolvedLogged = false
        else
            targetZ = c.z
            p.roomFixTicks = 0
        end
        local entity = ped
        if PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
            local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
            if veh and veh ~= 0 then entity = veh end
        end
        STREAMING.REQUEST_COLLISION_AT_COORD(c.x, c.y, targetZ)
        ENTITY.SET_ENTITY_COORDS_NO_OFFSET(entity, c.x, c.y, targetZ, false, false, false)
        Natives.InvokeVoid(0xA7E4E2D361C2627F)
        p.lastWpX, p.lastWpY = nil, nil
        log(("[WPautoTP] teleported to (%.2f, %.2f, %.2f) [playerZ=%.2f] interior=%s"):format(c.x, c.y, targetZ, pos.z, tostring(interior ~= 0)))
    end
    runBody()
end
patchFn.wpInsideInterior.releaseCheraxAutoTp = function(keepLastWp)
    local p = patchFn.wpInsideInterior
    if p.cheraxWasOn and p.cheraxAutoTp then
        p.cheraxAutoTp:Toggle(true)
    end
    p.tookOver = false
    p.cheraxWasOn = false
    if not keepLastWp then p.lastWpX = nil end
end

centralOnTick(FeatureMgr.AddFeature(H.WP_INSIDE_INT, "Allow Interior Waypoint", eFeatureType.Toggle,
    "Drop a waypoint directly on the interior floorplan map and teleport to it. While you are inside an interior on the floorplan view, replaces Cherax's auto-teleport-on-waypoint with an interior-aware version (lands at the interior floor instead of the surface above). Outside interiors, or when you zoom the pause map out to the full world map, Cherax's normal auto-teleport stays in charge. Restores your Cherax setting when turned off.",
    function(f)
        local p = patchFn.wpInsideInterior
        if not f:IsToggled() then
            p.roomFixTicks = 0
            if p.applied then p.restore() end
            if p.tookOver or p.cheraxWasOn then p.releaseCheraxAutoTp() end
            return
        end
        p.apply()
        p.tickRoomFix()

        local ped = PLAYER.PLAYER_PED_ID()
        local interior = Natives.InvokeInt(0x2107BA504071A6BB, ped)
        local inInterior = interior ~= 0
        local pauseActive = HUD.IS_PAUSE_MENU_ACTIVE()
        if inInterior and pauseActive then
            Natives.InvokeVoid(0x58FADDED207897DC, false)
        end

        local onFullMap = false
        if inInterior and pauseActive then
            local inIntMode = Natives.InvokeBool(0x9049FE339D5F6F6F)
            onFullMap = not inIntMode
        end
        local wantOwn = inInterior and not onFullMap

        local feat = p.resolveCheraxAutoTp()
        if feat then
            if wantOwn then
                local isOn = feat:IsToggled()
                if isOn and not p.tookOver then
                    p.cheraxWasOn = true
                    feat:Toggle(false)
                    p.tookOver = true
                    log("[WPautoTP] took over Cherax auto-teleport (interior-aware)")
                elseif p.tookOver and isOn then
                    feat:Toggle(false)
                end
                if p.tookOver then p.autoTeleportTick() end
            elseif p.tookOver or p.cheraxWasOn then
                p.releaseCheraxAutoTp(true)
                log("[WPautoTP] handed auto-teleport back to Cherax (outside interior / full map)")
            end
        end
    end))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)


patchFn.autoTpObjective = {
    SCAN_SEC      = 0.4,
    SUPPRESS_DIST = 3.0,
    KOSATKA_SPRITE = 760,
    Z_OFFSET      = 6.0,
    SETTLE_SEC    = 1.0,
    ARRIVE_DIST   = 15.0,
    VERIFY_SEC    = 1.5,
    MAX_TRIES     = 3,
    ITER_CAP      = 256,
    DIAG_SEC      = 5.0,
    DIAG_MAX_SPRITE = 900,
    DIAG_REPORT   = 10,
    H_IS_SCREEN_FADED_OUT          = 0xB16FCE9DDC7BA182,
    H_IS_SCREEN_FADING_OUT         = 0x797AC7CB535BA28F,
    H_GET_IS_LOADING_SCREEN_ACTIVE = 0x10D0A8F259E93EC9,
    H_IS_PLAYER_TELEPORT_ACTIVE    = 0x02B15662D7F8886F,
    EXCLUDED_COLOURS = { [0] = true, [1] = true, [4] = true },
    SPRITES = {
        {535,-1},{536,-1},{537,-1},{538,-1},{539,-1},{540,-1},{541,-1},{542,-1},
        {1,-1},
        {432,-1},
        {568,-1},
        {64,57},{501,57},{556,57},{225,57},{280,57},{631,57},
        {760,60},
        {765,2},{459,2},
    },
    lastBlip = nil,
    lastTpX = nil, lastTpY = nil,
    nextScan = 0.0,
    pending = nil,
    nextDiag = 0.0,
}
patchFn.autoTpObjective.logNearbyBlips = function()
    local p = patchFn.autoTpObjective
    local pp = ENTITY.GET_ENTITY_COORDS(PLAYER.PLAYER_PED_ID(), true)
    local found = {}
    for sprite = 0, p.DIAG_MAX_SPRITE do
        local blip = Natives.InvokeInt(0x1BEDE233E6CD2A1F, sprite)
        local seen = 0
        while Natives.InvokeBool(0xA6DB27D19ECBB7DA, blip) and seen < p.ITER_CAP do
            seen = seen + 1
            local ent = Natives.InvokeInt(0x4BA4E2553AFEDC2C, blip)
            if not (ent ~= 0 and ENTITY.IS_ENTITY_A_PED(ent) and PED.IS_PED_A_PLAYER(ent)) then
                local c = V3.New(Natives.InvokeV3(0xFA7C7F0AADF25D09, blip))
                if c then
                    local dx, dy = c.x - pp.x, c.y - pp.y
                    found[#found + 1] = {
                        sprite = sprite,
                        colour = Natives.InvokeInt(0xDF729E8D20CF7327, blip),
                        route  = Natives.InvokeBool(0xDD2238F57B977751, blip) and 1 or 0,
                        dist   = math.sqrt(dx * dx + dy * dy),
                    }
                end
            end
            blip = Natives.InvokeInt(0x14F96AA50D6FBEA7, sprite)
        end
    end
    if #found == 0 then
        logf("[AutoTPObj] no objective matched, and no blips on the map at all")
        return
    end
    table.sort(found, function(a, b)
        if a.route ~= b.route then return a.route > b.route end
        return a.dist < b.dist
    end)
    local parts = {}
    for i = 1, math.min(#found, p.DIAG_REPORT) do
        parts[#parts + 1] = string.format("sprite=%d colour=%d route=%d %.0fm",
            found[i].sprite, found[i].colour, found[i].route, found[i].dist)
    end
    logf("[AutoTPObj] no objective matched; %d blips up, nearest/routed: %s", #found, table.concat(parts, " | "))
end
patchFn.autoTpObjective.inTransition = function()
    local p = patchFn.autoTpObjective
    return Natives.InvokeBool(p.H_IS_SCREEN_FADED_OUT)
        or Natives.InvokeBool(p.H_IS_SCREEN_FADING_OUT)
        or Natives.InvokeBool(p.H_GET_IS_LOADING_SCREEN_ACTIVE)
        or Natives.InvokeBool(p.H_IS_PLAYER_TELEPORT_ACTIVE)
        or STREAMING.IS_PLAYER_SWITCH_IN_PROGRESS()
        or not PLAYER.IS_PLAYER_PLAYING(PLAYER.PLAYER_ID())
end
patchFn.autoTpObjective.teleportTo = function(x, y, z, sprite)
    local p = patchFn.autoTpObjective
    local ped = PLAYER.PLAYER_PED_ID()
    local entity = ped
    if PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
        local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        if veh and veh ~= 0 then entity = veh end
    end
    local off = (sprite == p.KOSATKA_SPRITE) and p.Z_OFFSET or 0.0
    local tz = (z or 0.0) + off
    STREAMING.REQUEST_COLLISION_AT_COORD(x, y, tz)
    ENTITY.SET_ENTITY_COORDS_NO_OFFSET(entity, x, y, tz, false, false, false)
end
patchFn.autoTpObjective.findObjectiveCoord = function()
    local p = patchFn.autoTpObjective
    local ped = PLAYER.PLAYER_PED_ID()
    local pp = ENTITY.GET_ENTITY_COORDS(ped, true)
    local bestX, bestY, bestZ, bestSprite, bestBlip, bestColour, bestDsq
    for _, s in ipairs(p.SPRITES) do
        local sprite, colour = s[1], s[2]
        local blip = Natives.InvokeInt(0x1BEDE233E6CD2A1F, sprite)
        local seen = 0
        while Natives.InvokeBool(0xA6DB27D19ECBB7DA, blip) and seen < p.ITER_CAP do
            seen = seen + 1
            local bc = Natives.InvokeInt(0xDF729E8D20CF7327, blip)
            if (colour == -1 or bc == colour) and not p.EXCLUDED_COLOURS[bc] then
                local ent = Natives.InvokeInt(0x4BA4E2553AFEDC2C, blip)
                if not (ent ~= 0 and ENTITY.IS_ENTITY_A_PED(ent) and PED.IS_PED_A_PLAYER(ent)) then
                    local c = V3.New(Natives.InvokeV3(0xFA7C7F0AADF25D09, blip))
                    if c then
                        local dx, dy = c.x - pp.x, c.y - pp.y
                        local dsq = dx * dx + dy * dy
                        if not bestDsq or dsq < bestDsq then
                            bestX, bestY, bestZ, bestSprite, bestBlip, bestColour, bestDsq = c.x, c.y, c.z, sprite, blip, bc, dsq
                        end
                    end
                end
            end
            blip = Natives.InvokeInt(0x14F96AA50D6FBEA7, sprite)
        end
    end
    return bestX, bestY, bestZ, bestSprite, bestBlip, bestColour
end
patchFn.autoTpObjectiveOnTick = function(f)
    if scriptUnloading then return end
    local p = patchFn.autoTpObjective
    if not f:IsToggled() then
        p.lastBlip, p.lastTpX, p.lastTpY, p.pending = nil, nil, nil, nil
        return
    end
    local now = os.clock()

    if p.pending or now >= p.nextScan then
        if p.inTransition() then
            p.nextScan = now + p.SETTLE_SEC
            if p.pending then p.pending.deadline = now + p.SETTLE_SEC + p.VERIFY_SEC end
            return
        end
    end

    if p.pending then
        local pc = ENTITY.GET_ENTITY_COORDS(PLAYER.PLAYER_PED_ID(), true)
        local pdx, pdy = pc.x - p.pending.x, pc.y - p.pending.y
        if pdx * pdx + pdy * pdy <= (p.ARRIVE_DIST * p.ARRIVE_DIST) then
            p.pending = nil
        elseif now >= p.pending.deadline then
            if p.pending.tries < p.MAX_TRIES then
                p.pending.tries = p.pending.tries + 1
                p.pending.deadline = now + p.VERIFY_SEC
                p.teleportTo(p.pending.x, p.pending.y, p.pending.z, p.pending.sprite)
                logf("[AutoTPObj] teleport did not land, retry %d/%d to (%.1f, %.1f)",
                    p.pending.tries, p.MAX_TRIES, p.pending.x, p.pending.y)
            else
                logf("[AutoTPObj] teleport did not land after %d attempts, giving up on (%.1f, %.1f)",
                    p.pending.tries, p.pending.x, p.pending.y)
                p.pending = nil
            end
        end
    end

    if now < p.nextScan then return end
    p.nextScan = now + p.SCAN_SEC

    local ox, oy, oz, osprite, oblip, ocolour = p.findObjectiveCoord()
    local diag = now >= p.nextDiag
    if not oblip then
        if diag then p.nextDiag = now + p.DIAG_SEC; p.logNearbyBlips() end
        return
    end

    if oblip == p.lastBlip then
        if diag then
            p.nextDiag = now + p.DIAG_SEC
            logf("[AutoTPObj] holding: same blip handle %d as the last teleport (sprite=%d colour=%d)",
                oblip, osprite or 0, ocolour or -1)
        end
        return
    end
    if p.lastTpX then
        local dx, dy = ox - p.lastTpX, oy - p.lastTpY
        if dx * dx + dy * dy < (p.SUPPRESS_DIST * p.SUPPRESS_DIST) then
            if diag then
                p.nextDiag = now + p.DIAG_SEC
                logf("[AutoTPObj] holding: objective (%.1f, %.1f) is %.1fm from the last teleport, under SUPPRESS_DIST %.1f",
                    ox, oy, math.sqrt(dx * dx + dy * dy), p.SUPPRESS_DIST)
            end
            return
        end
    end

    p.lastBlip = oblip
    p.lastTpX, p.lastTpY = ox, oy
    p.pending = { x = ox, y = oy, z = oz, sprite = osprite, tries = 1, deadline = now + p.VERIFY_SEC }
    p.teleportTo(ox, oy, oz, osprite)
    logf("[AutoTPObj] teleported to objective (%.1f, %.1f, %.1f) sprite=%d colour=%d blip=%d", ox, oy, oz or 0.0, osprite or 0, ocolour or -1, oblip)
end

