local function copyHornNotes(notes)
    local out = {}
    for _, note in ipairs(notes or {}) do
        local idx = math.max(-1, math.min(7, math.floor(tonumber(note[1]) or -1)))
        local beats = math.max(0.125, math.min(16, tonumber(note[2]) or 1))
        out[#out + 1] = { idx, beats }
    end
    if #out == 0 then out[1] = { 0, 1 } end
    return out
end

local function hornSongBeats(notes)
    local total = 0
    for _, note in ipairs(notes or {}) do total = total + (tonumber(note[2]) or 0) end
    return math.max(total, 0.125)
end

