}

function louderRadio.deleteBus(handle)
    local s = louderRadio
    if not ENTITY.DOES_ENTITY_EXIST(handle) then s.dying[handle] = nil return end
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, handle, false, false)
    NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(handle)
    Natives.InvokeVoid(DETACH_ENTITY, handle, true, false)
    if NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle) then
        NETWORK.NETWORK_UNREGISTER_NETWORKED_ENTITY(handle)
    end
    Memory.WriteInt(s.delBuf, handle)
    ENTITY.DELETE_ENTITY(s.delBuf)
    if ENTITY.DOES_ENTITY_EXIST(handle) then
        Memory.WriteInt(s.delBuf, handle)
        ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(s.delBuf)
        s.dying[handle] = true
        ENTITY.FREEZE_ENTITY_POSITION(handle, true)
        ENTITY.SET_ENTITY_COLLISION(handle, false, false)
    else
        s.dying[handle] = nil
    end
end

function louderRadio.retryDying()
    local s = louderRadio
    if next(s.dying) == nil then return end
    local live = {}
    for _, bus in ipairs(s.buses) do live[bus.handle] = true end
    if radioCtl and radioCtl.plBus then
        for _, st in pairs(radioCtl.plBus) do
            if st.handle and st.handle ~= 0 then live[st.handle] = true end
        end
    end
    for handle in pairs(s.dying) do
        if live[handle] or Natives.InvokeInt(GET_ENTITY_MODEL, handle) ~= s.MODEL then
            s.dying[handle] = nil
        else
            louderRadio.deleteBus(handle)
        end
    end
end

function louderRadio.playerRealVehicle()
    local ped = PLAYER.PLAYER_PED_ID()
    if not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then return 0 end
    local veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
    if veh == 0 then return 0 end
    for _, bus in ipairs(louderRadio.buses) do
        if bus.handle == veh then return 0 end
    end
    if Natives.InvokeInt(GET_ENTITY_MODEL, veh) == louderRadio.MODEL
        and Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, veh, ped) then
        return 0
    end
    return veh
end

function louderRadio.inTransition()
    return Natives.InvokeBool(IS_SCREEN_FADED_OUT)
        or Natives.InvokeBool(IS_SCREEN_FADING_OUT)
        or Natives.InvokeBool(GET_IS_LOADING_SCREEN_ACTIVE)
        or Natives.InvokeBool(IS_PLAYER_TELEPORT_ACTIVE)
end

function louderRadio.deleteAll()
    local s = louderRadio
    local had = #s.buses
    local i = 1
    while i <= #s.buses do
        louderRadio.deleteBus(s.buses[i].handle)
        if ENTITY.DOES_ENTITY_EXIST(s.buses[i].handle) then
            i = i + 1
        else
            table.remove(s.buses, i)
        end
    end
    louderRadio.dropAllHolds()
    if #s.buses > 0 then
        logf("[LouderRadio] deleteAll: %d/%d bus(es) survived, retrying", #s.buses, had)
    end
    if #s.buses == 0 then STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(s.MODEL) end
end

function louderRadio.inSession()
    return Natives.InvokeBool(louderRadio.NAT_IS_SESSION_ACTIVE)
end

function louderRadio.disarmForExit(reason, mayYield)
    local s = louderRadio
    local had = #s.buses
    s.arriveSweepUntil = Time.GetEpocheMs() + s.ARRIVE_SWEEP_MS
    s.nextArriveSweepAt = 0
    louderRadio.deleteAll()
    if mayYield then
        for _ = 1, 8 do
            if #s.buses == 0 then break end
            Script.Yield(50)
            louderRadio.deleteAll()
        end
    end
    logf("[LouderRadio] disarm (%s): %d bus(es) -> %d left", reason, had, #s.buses)
    return #s.buses == 0
end

function louderRadio.startHold(stName, now)
    local s = louderRadio
    if not stName or stName == "" or stName == "OFF" then return end
    for _, h in ipairs(s.holds) do
        if h.station == stName then h.at = now; return end
    end
    if #s.holds >= s.HOLD_MAX then
        local oldest = 1
        for i = 2, #s.holds do
            if s.holds[i].at < s.holds[oldest].at then oldest = i end
        end
        louderRadio.dropHold(oldest)
    end
    local pos = ENTITY.GET_ENTITY_COORDS(PLAYER.PLAYER_PED_ID(), true)
    local veh = VEHICLE.CREATE_VEHICLE(s.MODEL, pos.x + s.HOLD_DIST, pos.y,
        pos.z - s.HOLD_DEPTH, 0.0, false, false, false)
    if not veh or veh == 0 then return end
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, false, false)
    ENTITY.SET_ENTITY_COLLISION(veh, false, false)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
    VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
    Natives.InvokeVoid(KEEP_ENGINE_ON_WHEN_ABANDONED, veh, true)
    Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, veh, true)
    Natives.InvokeVoid(SET_VEH_HAS_NORMAL_RADIO, veh)
    louderRadio.tuneBus(veh, stName)
    s.holds[#s.holds + 1] = { handle = veh, station = stName, at = now }
    logf("[LouderRadio] holding %s on a parked emitter (%d held)", stName, #s.holds)
end

function louderRadio.dropHold(i)
    local s = louderRadio
    local h = s.holds[i]
    if not h then return end
    if h.handle then louderRadio.deleteBus(h.handle) end
    table.remove(s.holds, i)
    logf("[LouderRadio] released hold on %s (%d held)", tostring(h.station), #s.holds)
end

function louderRadio.dropAllHolds()
    local s = louderRadio
    for i = #s.holds, 1, -1 do louderRadio.dropHold(i) end
end

function louderRadio.holdTick(now)
    local s = louderRadio
    if s.holdWanted then
        local want = s.holdWanted
        s.holdWanted = nil
        if want ~= s.station then louderRadio.startHold(want, now) end
    end
    for i = #s.holds, 1, -1 do
        if now - s.holds[i].at >= s.HOLD_MS then louderRadio.dropHold(i) end
    end
end

function louderRadio.stripExtras(veh)
    for id = 1, MAX_EXTRA_ID do
        if Natives.InvokeBool(DOES_EXTRA_EXIST, veh, id)
            and Natives.InvokeBool(IS_VEHICLE_EXTRA_TURNED_ON, veh, id) then
            Natives.InvokeVoid(SET_VEHICLE_EXTRA, veh, id, true)
        end
    end
end

function louderRadio.configure(veh, visible)
    ENTITY.SET_ENTITY_COLLISION(veh, false, false)
    ENTITY.SET_ENTITY_INVINCIBLE(veh, true)
    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
    louderRadio.stripExtras(veh)
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, visible and true or false, false)
    Natives.InvokeVoid(SET_ENTITY_PROOFS, veh, true, true, true, true, true, true, 1, true)
    VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
    Natives.InvokeVoid(KEEP_ENGINE_ON_WHEN_ABANDONED, veh, true)
    Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, veh, true)
    Natives.InvokeVoid(SET_VEH_HAS_NORMAL_RADIO, veh)
    Natives.InvokeVoid(SET_VEHICLE_RADIO_LOUD, veh, true)
end

function louderRadio.reannounceHidden(now, hidden)
    local s = louderRadio
    if s.visResendPending then
        s.visResendPending = false
        for _, bus in ipairs(s.buses) do
            Natives.InvokeVoid(s.N_SET_RENDER_SCORCHED, bus.handle, false)
        end
        return
    end
    if not hidden or #s.buses == 0 or now < s.nextVisResendAt then return end
    s.nextVisResendAt = now + s.VIS_RESEND_MS
    s.visResendPending = true
    for _, bus in ipairs(s.buses) do
        Natives.InvokeVoid(s.N_SET_RENDER_SCORCHED, bus.handle, true)
    end
    if not s.visResendLogged then
        s.visResendLogged = true
        logf("[LouderRadio] hidden-state re-announce beating every %dms (%d bus(es))",
            s.VIS_RESEND_MS, #s.buses)
    end
end

function louderRadio.resolveStopPatch()
    local p = louderRadio.stopPatch
    if not p.AOB or p.failed then return p.addr ~= 0 end
    if p.addr ~= 0 then return true end
    p.tries = p.tries + 1
    if p.tries > p.SCAN_TRIES then
        p.failed = true
        log("[LouderRadio] StopEmitters setter not found; enable-at-speed may lag")
        return false
    end
    local hit = Memory.Scan(p.WILD)
    if not hit or hit == 0 then return false end
    local addr = hit + p.OFF
    local cur = Memory.ReadByte(addr)
    if cur == p.PATCHED then
        Memory.WriteByte(addr, p.PRISTINE)
        logf("[LouderRadio] StopEmitters setter was stale-patched @ %X; healed", addr)
    elseif cur ~= p.PRISTINE then
        return false
    end
    p.addr = addr
    logf("[LouderRadio] StopEmitters setter resolved @ %X", addr)
    return true
end

function louderRadio.setStopPatch(on)
    local p = louderRadio.stopPatch
    if p.addr == 0 or p.applied == on then return end
    Memory.WriteByte(p.addr, on and p.PATCHED or p.PRISTINE)
    p.applied = on
end

function louderRadio.resolveWheelPatch()
    local p = louderRadio.wheelPatch
    if not p.AOB or p.failed then return p.addr ~= 0 end
    if p.addr ~= 0 then return true end
    p.tries = p.tries + 1
    if p.tries > p.SCAN_TRIES then
        p.failed = true
        log("[LouderRadio] radio-wheel gate not found; on-foot wheel unavailable")
        return false
    end
    local hit = Memory.Scan(p.AOB)
    if not hit or hit == 0 then return false end
    local addr = hit + p.OFF
    if Memory.ReadByte(addr) == p.PATCHED[1] then
        for i = 1, #p.PRISTINE do Memory.WriteByte(addr + i - 1, p.PRISTINE[i]) end
        logf("[LouderRadio] radio-wheel gate was stale-patched @ %X; healed", addr)
    end
    p.addr = addr
    logf("[LouderRadio] radio-wheel gate resolved @ %X", addr)
    return true
end

function louderRadio.setWheelPatch(on)
    local p = louderRadio.wheelPatch
    if p.addr == 0 or p.applied == on then return end
    local bytes = on and p.PATCHED or p.PRISTINE
    for i = 1, #bytes do Memory.WriteByte(p.addr + i - 1, bytes[i]) end
    p.applied = on
end


function louderRadio.tuneBus(veh, station)
    Natives.InvokeVoid(SET_VEH_RADIO_STATION, veh, station)
end

function louderRadio.attachBus(veh, idx, ped, zOff)
    local ox, oy, h = louderRadio.starChord(idx)
    Natives.InvokeVoid(DETACH_ENTITY, veh, false, false)
    Natives.InvokeVoid(ATTACH_ENTITY_TO_ENTITY, veh, ped, -1,
        ox, oy, zOff,
        louderRadio.PITCH_DEG, 0.0, math.deg(h),
        false,
        false,
        false,
        true,
        0,
        true,
        0)
end

function louderRadio.netVehicleCount()
    local n = 0
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local cveh = PoolMgr.GetCVehicle(i)
        if cveh and cveh.NetObject then n = n + 1 end
    end
    return n
end

function louderRadio.nearbyBusCount(pos)
    local s, n = louderRadio, 0
    local r2 = s.DENSITY_RADIUS * s.DENSITY_RADIUS
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0
            and Natives.InvokeInt(GET_ENTITY_MODEL, veh) == s.MODEL then
            local vp = ENTITY.GET_ENTITY_COORDS(veh, false)
            local dx, dy, dz = vp.x - pos.x, vp.y - pos.y, vp.z - pos.z
            if dx * dx + dy * dy + dz * dz <= r2 then n = n + 1 end
        end
    end
    return n
end

function louderRadio.parkBus(veh, park)
    Natives.InvokeVoid(KEEP_ENGINE_ON_WHEN_ABANDONED, veh, not park)
    VEHICLE.SET_VEHICLE_ENGINE_ON(veh, not park, true, park)
end

function louderRadio.spawnFailed(reason, n)
    local s = louderRadio
    if reason == s.lastSpawnFail then return nil end
    s.lastSpawnFail = reason
    if reason == "density" then
        logf("[LouderRadio] spawn refused: %d Festival Bus(es) already within %.0fm",
            n or 0, s.DENSITY_RADIUS)
    elseif reason == "create" then
        log("[LouderRadio] spawn refused: CREATE_VEHICLE returned 0 (vehicle pool full)")
    elseif reason == "netpool" then
        logf("[LouderRadio] spawn refused: %d/%d networked vehicles in use",
            n or 0, NETWORK.GET_MAX_NUM_NETWORK_VEHICLES())
    elseif reason == "register" then
        local d = type(n) == "table" and n or {}
        logf("[LouderRadio] spawn refused: bus stayed local after %d settle frame(s)"
            .. " (mission=%s entity=%s netVehicles=%d/%d)",
            d.frames or 0, tostring(d.mission), tostring(d.exists),
            d.used or -1, d.max or -1)
    else
        log("[LouderRadio] spawning again")
    end
    return nil
end

function louderRadio.spawnBus(pos, station, ped, zOff, visible)
    local s = louderRadio
    local nearby = louderRadio.nearbyBusCount(pos)
    if nearby >= s.DENSITY_SAFE_MAX then
        s.nextSpawnAt = Time.GetEpocheMs() + s.RESPAWN_COOLDOWN_MS
        return louderRadio.spawnFailed("density", nearby)
    end
    local veh = VEHICLE.CREATE_VEHICLE(s.MODEL, pos.x, pos.y, pos.z + s.SPAWN_DEPTH,
        0.0, false, false, false)
    if not veh or veh == 0 then return louderRadio.spawnFailed("create") end

    local bus = { handle = veh, zOff = zOff, bornAt = Time.GetEpocheMs() }
    table.insert(s.buses, bus)
    s.everSpawned[veh] = true
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, false, false)
    ENTITY.SET_ENTITY_COLLISION(veh, false, false)

    ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)

    local function abandon()
        for i = #s.buses, 1, -1 do
            if s.buses[i] == bus then table.remove(s.buses, i) break end
        end
        louderRadio.deleteBus(veh)
        return nil
    end

    local used = louderRadio.netVehicleCount()
    if used > 0 and used + s.NET_HEADROOM >= NETWORK.GET_MAX_NUM_NETWORK_VEHICLES() then
        s.nextSpawnAt = Time.GetEpocheMs() + s.RESPAWN_COOLDOWN_MS
        louderRadio.spawnFailed("netpool", used)
        return abandon()
    end
    local networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(veh)
    if not networked then
        NETWORK.NETWORK_REGISTER_ENTITY_AS_NETWORKED(veh)
        local waited = 0
        while not networked and waited < s.REGISTER_SETTLE_FRAMES do
            waited = waited + 1
            Script.Yield(0)
            if scriptUnloading or not ENTITY.DOES_ENTITY_EXIST(veh) then break end
            networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(veh)
        end
        if networked and waited > 0 and not s.registerWaitLogged then
            s.registerWaitLogged = true
            logf("[LouderRadio] network registration settled after %d frame(s)", waited)
        end
    end
    if not networked then
        louderRadio.spawnFailed("register", {
            frames  = s.REGISTER_SETTLE_FRAMES,
            mission = Natives.InvokeBool(0x0A7B270912999B3C, veh),
            exists  = ENTITY.DOES_ENTITY_EXIST(veh),
            used    = louderRadio.netVehicleCount(),
            max     = NETWORK.GET_MAX_NUM_NETWORK_VEHICLES(),
        })
        return abandon()
    end
    NETWORK.SET_NETWORK_ID_CAN_MIGRATE(NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(veh), false)

    louderRadio.configure(veh, false)
    louderRadio.attachBus(veh, #s.buses, ped, zOff)
    Natives.InvokeVoid(SET_ENTITY_VISIBLE, veh, visible and true or false, false)
    if station then
        louderRadio.tuneBus(veh, station)
        bus.station = station
    end
    louderRadio.spawnFailed(nil)
    return veh
end

function louderRadio.sweepOrphans()
    local s = louderRadio
    local ped = PLAYER.PLAYER_PED_ID()
    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local own = {}
    for _, bus in ipairs(s.buses) do own[bus.handle] = true end
    for _, h in ipairs(s.holds) do if h.handle then own[h.handle] = true end end
    if radioCtl and radioCtl.plBus then
        for _, st in pairs(radioCtl.plBus) do
            if st.handle and st.handle ~= 0 then own[st.handle] = true end
        end
    end
    local r2, swept = s.SWEEP_RADIUS * s.SWEEP_RADIUS, 0
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        if swept >= s.SWEEP_LIMIT then break end
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0 and not own[veh]
            and Natives.InvokeInt(GET_ENTITY_MODEL, veh) == s.MODEL
            and NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh) then
            local vp = ENTITY.GET_ENTITY_COORDS(veh, false)
            local dx, dy, dz = vp.x - pos.x, vp.y - pos.y, vp.z - pos.z
            if dx * dx + dy * dy + dz * dz <= r2
                and (Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, veh, ped)
                     or not (Natives.InvokeBool(s.N_IS_ENTITY_ATTACHED, veh)
                             or Natives.InvokeBool(s.N_IS_ENTITY_VISIBLE, veh))) then
                louderRadio.deleteBus(veh)
                swept = swept + 1
            end
        end
    end
    if swept > 0 then logf("[LouderRadio] swept %d orphaned speaker(s)", swept) end
    return swept
end

function louderRadio.modelBox()
    local s = louderRadio
    if s.box then return s.box end
    local buf = s.dimBuf
    Natives.InvokeVoid(GET_MODEL_DIMENSIONS, s.MODEL, buf, buf + 24)
    local box = { miny = Memory.ReadFloat(buf + 8), maxy = Memory.ReadFloat(buf + 32) }
    if not (box.maxy and box.maxy > 1.0) then return nil end
    s.box = box
    return box
end

function louderRadio.logBusAxes(veh, h)
    local s = louderRadio
    if s.axesLogged then return end
    s.axesLogged = true
    local ox, oy = Natives.InvokeV3(s.N_OFFSET_TO_WORLD, veh, 0.0, 0.0, 0.0)
    local xx, xy = Natives.InvokeV3(s.N_OFFSET_TO_WORLD, veh, 1.0, 0.0, 0.0)
    local zx, zy = Natives.InvokeV3(s.N_OFFSET_TO_WORLD, veh, 0.0, 0.0, 1.0)
    if not (ox and xx and zx) then s.axesLogged = false return end
    logf("[LouderRadio] bus axes: +X at %+.1f, +Z at %+.1f from heading",
        math.deg(math.atan(xy - oy, xx - ox) - h),
        math.deg(math.atan(zy - oy, zx - ox) - h))
end

function louderRadio.starChord(idx)
    local s      = louderRadio
    local n      = s.RING_POINTS
    local step   = s.STAR_STEP
    local r      = s.STAR_LINE_LEN / (2.0 * math.sin(math.pi * step / n))
    local a1     = (idx - 1) * (2.0 * math.pi / n)
    local a2     = a1 + step * (2.0 * math.pi / n)
    local x1, y1 = math.cos(a1) * r, math.sin(a1) * r
    local x2, y2 = math.cos(a2) * r, math.sin(a2) * r
    local h      = math.atan(y2 - y1, x2 - x1)
    return (x1 + x2) * 0.5 + math.cos(h + math.pi * 0.5) * s.STAR_LINE_OFF,
           (y1 + y2) * 0.5 + math.sin(h + math.pi * 0.5) * s.STAR_LINE_OFF,
           h
end

function louderRadio.audit(ped, now)
    local s = louderRadio
    if now < s.nextAuditAt then return end
    s.nextAuditAt = now + s.AUDIT_INTERVAL_MS

    local box     = louderRadio.modelBox()
    local pp      = ENTITY.GET_ENTITY_COORDS(ped, true)
    local groundZ = pp.z - ENTITY.GET_ENTITY_HEIGHT_ABOVE_GROUND(ped)

    local mine, unattached, nose, noseIdx = {}, 0, nil, 0
    for idx, bus in ipairs(s.buses) do
        mine[bus.handle] = true
        if not Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, bus.handle, ped) then
            unattached = unattached + 1
        end
        if box then
            local top = ENTITY.GET_ENTITY_COORDS(bus.handle, false).z + box.maxy - groundZ
            if not nose or top > nose then nose, noseIdx = top, idx end
        end
    end
    if radioCtl and radioCtl.plBus then
        for _, st in pairs(radioCtl.plBus) do
            if st.handle and st.handle ~= 0 then mine[st.handle] = true end
        end
    end

    local extra, ours, nearest, nearAttached = 0, 0, nil, false
    for i = 0, PoolMgr.GetMaxVehicleCount() - 1 do
        local veh = PoolMgr.GetVehicle(i)
        if veh and veh > 0 and not mine[veh]
            and Natives.InvokeInt(GET_ENTITY_MODEL, veh) == s.MODEL then
            extra = extra + 1
            if s.everSpawned[veh] then ours = ours + 1 end
            local vp = ENTITY.GET_ENTITY_COORDS(veh, false)
            local dx, dy, dz = vp.x - pp.x, vp.y - pp.y, vp.z - pp.z
            local d = math.sqrt(dx * dx + dy * dy + dz * dz)
            if not nearest or d < nearest then
                nearest      = d
                nearAttached = Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, veh, ped)
            end
        end
    end

    local dying = 0
    for _ in pairs(s.dying) do dying = dying + 1 end

    logf("[LouderRadio][audit] buses=%d unattached=%d nose=%s untracked=%d ours=%d%s dying=%d",
        #s.buses, unattached,
        nose and string.format("%+.2f(#%d)", nose, noseIdx) or "n/a",
        extra, ours,
        nearest and string.format(" nearest=%.1fm attachedToMe=%s", nearest, tostring(nearAttached)) or "",
        dying)
end

function louderRadio.unloadCleanup()
    louderRadio.setStopPatch(false)
    louderRadio.setWheelPatch(false)
    louderRadio.deleteAll()
    louderRadio.retryDying()
end

function louderRadio.logOffBlip(resolvedTo)
    local s = louderRadio
    if not s.offCandidateSince then return end
    local dur = Time.GetEpocheMs() - s.offCandidateSince
    if dur > s.maxOffBlipMs then s.maxOffBlipMs = dur end
    local d = FeatureMgr.GetFeature(H.LOUDER_RADIO_AUDIT)
    if d and d:IsToggled() then
        logf("[LouderRadio][off] 255 blip=%dms (max=%dms) believedOff=%s inVeh=%s -> %s",
            dur, s.maxOffBlipMs, tostring(s.station == "OFF"),
            tostring(louderRadio.playerRealVehicle() ~= 0), tostring(resolvedTo))
    end
end

function louderRadio.currentStation()
    local s = louderRadio
    local name = Natives.InvokeString(GET_PLAYER_RADIO_STATION_NAME)
    local idx = Natives.InvokeInt(GET_PLAYER_RADIO_STATION_INDEX)
    if name and name ~= "" and name ~= "OFF" then
        louderRadio.logOffBlip(name)
        s.offCandidateSince = nil
        if s.station == nil or s.station == "OFF" then
            s.station = name
            s.pendingStation = nil
        elseif name == s.station then
            s.pendingStation = nil
        elseif name ~= s.pendingStation then
            s.pendingStation = name
            s.pendingSince = Time.GetEpocheMs()
        elseif Time.GetEpocheMs() - s.pendingSince >= s.STATION_SETTLE_MS then
            s.holdWanted = s.station
            s.station = name
            s.pendingStation = nil
        end
    elseif idx == 255 or idx == -1 then
        if louderRadio.playerRealVehicle() ~= 0 or louderRadio.isOnFootRadioActive() then
            local now = Time.GetEpocheMs()
            s.offCandidateSince = s.offCandidateSince or now
            if now - s.offCandidateSince >= s.OFF_DEBOUNCE_MS then
                s.station = "OFF"
                s.pendingStation = nil
            end
        else
            s.offCandidateSince = nil
        end
    else
        louderRadio.logOffBlip("idx=" .. tostring(idx))
        s.offCandidateSince = nil
    end
    louderRadio.holdTick(Time.GetEpocheMs())
    return s.station
end

function louderRadio.setFrontendRadio(active)
    Natives.InvokeVoid(SET_FRONTEND_RADIO_ACTIVE, active)
    louderRadio.frontendOff = not active
end

function louderRadio.setMobileRadio(on)
    Natives.InvokeVoid(SET_AUDIO_FLAG, "MobileRadioInGame", on and true or false)
    if not on then Natives.InvokeVoid(SET_MOBILE_PHONE_RADIO_STATE, false) end
    louderRadio.mobileOn = on
end

function louderRadio.isOnFootRadioActive()
    local f = FeatureMgr.GetFeature(H.LOUDER_RADIO_ONFOOT)
    return f and f:IsToggled() or false
end

function louderRadio.ensureAudioMode()
    louderRadio.setFrontendRadio(false)
    if louderRadio.isOnFootRadioActive() then
        louderRadio.setMobileRadio(true)
    elseif louderRadio.mobileOn then
        louderRadio.setMobileRadio(false)
    end
end

function louderRadio.syncStationOnTransition(inVehicle, veh)
    local s = louderRadio
    if s.wasInVehicle == nil then s.wasInVehicle = inVehicle return end
    if inVehicle == s.wasInVehicle then return end
    s.wasInVehicle = inVehicle
    local st = s.station
    if not st or st == "OFF" then return end
    if inVehicle then
        if veh and veh ~= 0 then Natives.InvokeVoid(SET_VEH_RADIO_STATION, veh, st) end
    elseif louderRadio.isOnFootRadioActive() then
        Natives.InvokeVoid(SET_RADIO_TO_STATION_NAME, st)
    end
end

function louderRadio.revertAudioFlags()
    local s = louderRadio
    if s.frontendOff then louderRadio.setFrontendRadio(true) end
    if s.mobileOn then louderRadio.setMobileRadio(false) end
end

local RADIO_WHEEL_INPUTS = { 85, 332, 333 }

function louderRadio.wheelHelperOnTick()
    local s = louderRadio
    if ShouldUnload() and not scriptUnloading then
        louderRadio.revertAudioFlags()
        if #s.buses > 0 then louderRadio.deleteAll() end
        louderRadio.retryDying()
    end

    local lr = FeatureMgr.GetFeature(H.LOUDER_RADIO)
    if not (lr and lr:IsToggled()) then return end

    local dbg = FeatureMgr.GetFeature(H.LOUDER_RADIO_SHOW)
    local busVis = dbg and dbg:IsToggled() or false
    for _, bus in ipairs(s.buses) do
        Natives.InvokeVoid(SET_ENTITY_VISIBLE, bus.handle, busVis, false)
    end

    local veh = louderRadio.playerRealVehicle()

    if veh ~= 0 then return end
    if not louderRadio.isOnFootRadioActive() then return end
    if not Natives.InvokeBool(louderRadio.N_CHAT_TYPING) then
        for _, c in ipairs(RADIO_WHEEL_INPUTS) do
            Natives.InvokeVoid(ENABLE_CONTROL_ACTION, 0, c, true)
        end
    end
end

function louderRadio.tick()
    local s = louderRadio
    local feat = FeatureMgr.GetFeature(H.LOUDER_RADIO)

    if not s.didInit and isPlayerReady() then
        s.didInit = true
        if not (feat and feat:IsToggled()) then
            Natives.InvokeVoid(SET_FRONTEND_RADIO_ACTIVE, true)
            Natives.InvokeVoid(SET_MOBILE_PHONE_RADIO_STATE, false)
            Natives.InvokeVoid(SET_AUDIO_FLAG, "MobileRadioInGame", false)
            s.frontendOff, s.mobileOn = false, false
        end
    end

    if isPlayerReady() then louderRadio.retryDying() end

    local nowInSession = louderRadio.inSession()
    if s.wasInSession == nil then
        s.wasInSession = nowInSession
    elseif s.wasInSession and not nowInSession then
        s.wasInSession = false
        logf("[LouderRadio] session ended with %d bus(es) up", #s.buses)
        if #s.buses > 0 then louderRadio.disarmForExit("session ended", false) end
    elseif nowInSession and not s.wasInSession then
        s.wasInSession = true
    end

    if s.sessionChanged then
        s.sessionChanged = false
        s.arriveSweepUntil = Time.GetEpocheMs() + s.ARRIVE_SWEEP_MS
        s.nextArriveSweepAt = 0
        logf("[LouderRadio] session change: dropping %d tracked bus(es), sweeping for %.0fs",
            #s.buses, s.ARRIVE_SWEEP_MS / 1000)
        if #s.buses > 0 then louderRadio.deleteAll() end
    end
    if s.arriveSweepUntil > 0 and isPlayerReady() then
        local now = Time.GetEpocheMs()
        if now >= s.arriveSweepUntil then
            s.arriveSweepUntil = 0
        elseif now >= s.nextArriveSweepAt then
            s.nextArriveSweepAt = now + s.ARRIVE_SWEEP_EVERY
            louderRadio.sweepOrphans()
        end
    end

    if not (feat and feat:IsToggled()) then
        if s.wasOn then
            s.wasOn = false
            s.shortfallSince = nil
            s.shortfallToasted = false
            s.lastSpawnFail = nil
            if s.transportPaused then
                if s.mobileOn then louderRadio.setMobileRadio(false) end
            else
                louderRadio.revertAudioFlags()
            end
            louderRadio.setStopPatch(false)
            louderRadio.setWheelPatch(false)
            if louderRadio.playerRealVehicle() == 0 then
                Natives.InvokeVoid(SET_RADIO_TO_STATION_NAME, "OFF")
            end
        end
        if #s.buses > 0 then louderRadio.deleteAll() end
        return 250
    end
    if louderRadio.inTransition() or not isPlayerReady() or not nowInSession
        or (rejoin and rejoin.running) then
        if #s.buses > 0 then louderRadio.deleteAll() end
        s.wasInVehicle = nil
        return 250
    end

    if not s.wasOn then
        louderRadio.sweepOrphans()
        s.nextSweepAt = Time.GetEpocheMs() + s.SWEEP_RETRY_MS
        s.wasInVehicle = nil
        s.wasOnFootRadio = false
    end
    s.wasOn = true
    louderRadio.ensureAudioMode()
    if s.transportPaused then
        if not s.rigMuted then
            s.rigMuted = true
            if s.station and s.station ~= "OFF" then
                louderRadio.startHold(s.station, Time.GetEpocheMs())
            end
            for _, b in ipairs(s.buses) do
                if ENTITY.DOES_ENTITY_EXIST(b.handle) then
                    Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, b.handle, false)
                    louderRadio.parkBus(b.handle, true)
                end
            end
        end
        return 50
    end
    if s.rigMuted then
        s.rigMuted = false
        for _, b in ipairs(s.buses) do
            if ENTITY.DOES_ENTITY_EXIST(b.handle) then
                louderRadio.parkBus(b.handle, false)
                Natives.InvokeVoid(SET_VEHICLE_RADIO_ENABLED, b.handle, true)
                if b.station then louderRadio.tuneBus(b.handle, b.station) end
            end
        end
    end
    if louderRadio.resolveStopPatch() then louderRadio.setStopPatch(true) end
    if louderRadio.isOnFootRadioActive() then
        if louderRadio.resolveWheelPatch() then louderRadio.setWheelPatch(true) end
    else
        louderRadio.setWheelPatch(false)
    end

    STREAMING.REQUEST_MODEL(s.MODEL)
    if not STREAMING.HAS_MODEL_LOADED(s.MODEL) then return 50 end

    local volFeat = FeatureMgr.GetFeature(H.LOUDER_RADIO_VOL)
    local desired = volFeat and volFeat:GetIntValue() or 1
    if desired < 1 then desired = 1 elseif desired > s.MAX_BUSES then desired = s.MAX_BUSES end
    local requestedDesired = desired

    local showFeat = FeatureMgr.GetFeature(H.LOUDER_RADIO_SHOW)
    local debug    = showFeat and showFeat:IsToggled() or false
    local audFeat  = FeatureMgr.GetFeature(H.LOUDER_RADIO_AUDIT)
    local zOff     = s.Z_OFFSET

    local ped = PLAYER.PLAYER_PED_ID()
    local pos = ENTITY.GET_ENTITY_COORDS(ped, true)
    local now = Time.GetEpocheMs()


    local veh = louderRadio.playerRealVehicle()
    louderRadio.syncStationOnTransition(veh ~= 0, veh)
    local station = louderRadio.currentStation()
    local onFootRadio = louderRadio.isOnFootRadioActive()
    if onFootRadio and not s.wasOnFootRadio and veh == 0 then
        if station and station ~= "OFF" then
            Natives.InvokeVoid(SET_RADIO_TO_STATION_NAME, station)
            s.wasOnFootRadio = true
            logf("[LouderRadio] on-foot host tuned to %s", station)
        end
    else
        s.wasOnFootRadio = onFootRadio
    end
    local busTarget = s.pendingStation and "OFF" or station
    if veh == 0 and not onFootRadio then
        busTarget = "OFF"
    end
    local parked = station == nil or station == "OFF" or (veh == 0 and not onFootRadio)

    local i, lostThisPass = 1, 0
    while i <= #s.buses do
        local bus = s.buses[i]
        if not ENTITY.DOES_ENTITY_EXIST(bus.handle)
            or Natives.InvokeBool(IS_ENTITY_DEAD, bus.handle, false) then
            lostThisPass = lostThisPass + 1
            louderRadio.deleteBus(bus.handle)
            table.remove(s.buses, i)
        else
            i = i + 1
        end
    end

    if lostThisPass > 0 then
        logf("[LouderRadio] speaker loss incident: %d bus(es); rebuilding", lostThisPass)
    end

    while #s.buses > desired do
        louderRadio.deleteBus(table.remove(s.buses).handle)
    end

    if audFeat and audFeat:IsToggled() then louderRadio.audit(ped, now) end
    local reassert = now >= s.nextAssertAt
    if reassert then s.nextAssertAt = now + s.ASSERT_INTERVAL_MS end
    local retune = now >= s.nextRetuneAt
    if retune then s.nextRetuneAt = now + s.RETUNE_INTERVAL_MS end

    for idx, bus in ipairs(s.buses) do
        if bus.zOff ~= zOff
            or not Natives.InvokeBool(IS_ENTITY_ATTACHED_TO_ENTITY, bus.handle, ped) then
            louderRadio.attachBus(bus.handle, idx, ped, zOff)
            bus.zOff = zOff
        end
        if reassert and busTarget ~= "OFF" then louderRadio.configure(bus.handle, debug) end

        if busTarget and busTarget ~= "OFF" then
            Natives.InvokeVoid(SET_VEH_FORCED_RADIO_THIS_FRAME, bus.handle)
            if not Natives.InvokeBool(GET_IS_VEHICLE_ENGINE_RUNNING, bus.handle) then
                louderRadio.parkBus(bus.handle, false)
            end
        elseif parked then
            if Natives.InvokeBool(GET_IS_VEHICLE_ENGINE_RUNNING, bus.handle) then
                louderRadio.parkBus(bus.handle, true)
            end
        end

        if busTarget and (retune or busTarget == "OFF" or bus.station ~= busTarget) then
            louderRadio.tuneBus(bus.handle, busTarget)
            bus.station = busTarget
        end
    end

    if not s.axesLogged and s.buses[1] and now - s.buses[1].bornAt > 500 then
        local _, _, h = louderRadio.starChord(1)
        louderRadio.logBusAxes(s.buses[1].handle, h)
    end

    louderRadio.reannounceHidden(now, not debug)

    if #s.buses < desired and now >= s.nextSpawnAt then
        for _ = 1, s.SPAWN_PER_PASS do
            if #s.buses >= desired then break end
            local born = louderRadio.spawnBus(pos, busTarget, ped, zOff, debug)
            if not born then
                s.nextSpawnAt = now + s.RESPAWN_COOLDOWN_MS
                break
            end
            if parked then louderRadio.parkBus(born, true) end
        end
        if s.lastSpawnFail == "density" and now >= s.nextSweepAt then
            s.nextSweepAt = now + s.SWEEP_RETRY_MS
            if louderRadio.sweepOrphans() > 0 then s.nextSpawnAt = now end
        end
    end

    local radioNeedsSpeakers = busTarget and busTarget ~= "OFF" and requestedDesired > 0
    if radioNeedsSpeakers and #s.buses < requestedDesired then
        if not s.shortfallSince then s.shortfallSince = now end
        if not s.shortfallToasted and now - s.shortfallSince >= 5000 then
            s.shortfallToasted = true
            GUI.AddToast("VibeScript",
                "Louder Radio is struggling to spawn all requested speakers. Clearing the area may help.",
                10000)
        end
    else
        if s.shortfallToasted and #s.buses >= requestedDesired then
            GUI.AddToast("VibeScript", "Louder Radio: Spawned all requested speakers", 5000)
        end
        s.shortfallSince = nil
        s.shortfallToasted = false
    end

    return s.PASS_INTERVAL_MS
end

Script.RegisterLooped(function()
    if ShouldUnload() or scriptUnloading then
        if not scriptUnloading then louderRadio.revertAudioFlags() end
        if louderRadio.stopPatch.applied then louderRadio.setStopPatch(false) end
        if louderRadio.wheelPatch.applied then louderRadio.setWheelPatch(false) end
        if #louderRadio.buses > 0 then louderRadio.deleteAll() end
        Script.Yield(100)
        return
    end

    local ok, wait = pcall(louderRadio.tick)
    if not ok then
        logErr("[LouderRadio] " .. tostring(wait))
        wait = 500
    end
    Script.Yield(wait or louderRadio.PASS_INTERVAL_MS)
end)

FeatureMgr.AddFeature(H.LOUDER_RADIO, "Louder Radio", eFeatureType.Toggle,
    "Blasts your radio to you and other players. Small delay between station changes.")
    :SetSaveable(false)

FeatureMgr.AddFeature(H.LOUDER_RADIO_VOL, "Volume", eFeatureType.SliderInt,
    "Number of party buses (speakers). Max of 8 due to game limitations.")
    :SetLimitValues(1, louderRadio.SLIDER_MAX)
    :SetDefaultValue(5)
    :Reset()
    :SetSaveable(false)

FeatureMgr.AddFeature(H.LOUDER_RADIO_ONFOOT, "On Foot Radio", eFeatureType.Toggle,
    "Use the Louder Radio on foot. Allows you to use the radio wheel selector while not in a vehicle.")
    :SetSaveable(false)

FeatureMgr.AddFeature(H.LOUDER_RADIO_SHOW, "Show Speakers", eFeatureType.Toggle,
    "Renders the party buses instead of hiding them. Everyone in the session sees them, not just you.")
    :SetSaveable(false)

centralOnTick(FeatureMgr.AddFeature(H.LOUDER_RADIO_WHEEL, "##LouderRadioWheelHelper",
    eFeatureType.Toggle, "", louderRadio.wheelHelperOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
FeatureMgr.GetFeature(H.LOUDER_RADIO_WHEEL):Toggle()

end)()


;(function()

local iv = function(h, ...) return Natives.InvokeVoid(h, ...) end
local ii = function(h, ...) return Natives.InvokeInt(h, ...) end
local is = function(h, ...) return Natives.InvokeString(h, ...) end
local ib = function(h, ...) return Natives.InvokeBool(h, ...) end

local HASH = {
    NUM_STATIONS   = 0xF1620ECB50E01DE7,
    STATION_NAME   = 0xB28ECA15046CA8B9,
    PLAYER_STATION = 0xF6D733C32076AD03,
    SET_STATION    = 0xC69EDA28699D5107,
    TRACK_HASH     = 0x34D66BC058019CE0,
    TRACK_TIME     = 0x3E65CDE5215832C1,
    FREEZE         = 0x344F393B027E38C3,
    UNFREEZE       = 0xFC00454CF60B91DD,
    FILENAME_CONV  = 0x7B5280EBA9840C72,
    REQ_ADDL_TEXT  = 0x71A78003C8E71424,
    HAS_ADDL_TEXT  = 0x02245FE4BED318B8,
}
local IS_ENTITY_ATTACHED_TO_ENTITY  = 0xEFBE71898A993728
local GET_IS_VEHICLE_ENGINE_RUNNING = 0xAE31E7DF9B5B132E
local SET_VEH_FORCED_RADIO_THIS_FRAME = 0xC1805D05E6D4FE10

local TRACKID_SLOT = 16


local SNSESSION_OFF = 0xAA38
local GAMER_ARR     = 0x2CA0
local GAMER_CNT     = 0x2DA0
local HANDLE_OFF    = 0xC8

local SLOT_TRACK_CAT = IS_ENHANCED and 0x898 or 0x894
local SLOT_TRACK_IDX = IS_ENHANCED and 0x89C or 0x898

local MUSIC_COLL = 0x11A0
local MUSIC_CATS = {
    { cat = 2,  coll = 0x11A0 },
    { cat = 7,  coll = 0x12F0 },
    { cat = 8,  coll = 0x1350 },
    { cat = 9,  coll = 0x1380 },
    { cat = 10, coll = 0x13E0 },
    { cat = 11, coll = 0x13B0 },
    { cat = 12, coll = 0x1260 },
    { cat = 13, coll = 0x1290 },
    { cat = 14, coll = 0x12C0 },
}

local USB_STATION_HASH    = 0x526EAB09
local USB_SILENCE_LIST    = "TUNER_AP_SILENCE_MUSIC"
local IS_MIX_STATION      = 0x1838
local META_TYPE_TRACKLIST = 26

local USR = {
    NAME      = "RADIO_19_USER",
    HASH      = 0xF74D5272,
    NULLTRACK = 0xC96DC433,
    DB_ARR  = 0x10, DB_CNT = 0x18,
    TRK = 0x60, FILE = 0x00, ARTIST = 0x08, TITLE = 0x28, DUR = 0x48,
    FORCENEXT = 0x2C,
    SND = 0x608, PLAYTIME = 0x660,
    MODES = { [0] = "Radio (ads + DJ)", [1] = "Sequential", [2] = "Random" },
}

local edSig = function(leg, enh) if IS_ENHANCED then return enh end return leg end
local SESSION_RIP    = IS_ENHANCED and 3 or 5
local SENDER_AOB     = edSig(
    "48 85 D2 0F 84 ? ? ? ? 48 8B C4 48 89 58 08 48 89 70 10 48 89 78 18 4C 89 70 20 55 48 8D A8",
    "41 57 41 56 41 54 56 57 55 53 48 81 EC A0 06 00 00 48 85 D2 0F 84 ? ? ? ? 4C 89 C7 49 89 D4 48 8D 5C 24 28 48 89 D9 E8")
local SESSION_AOB    = edSig(
    "33 D2 48 89 2D ? ? ? ? 48 89 2D",
    "48 8B 05 ? ? ? ? 48 8B 88 38 AA 00 00 48 8D 54 24 28 E8 ? ? ? ? 48 8B 74 24 28 48 8B 05 ? ? ? ? 48 8B 88 38 AA 00 00")
local FORCE_AOB      = edSig(
    "40 55 56 57 41 54 41 55 41 56 41 57 48 83 EC 50 48 8D 6C 24 20 33 FF 48 89 5D 78 45 8B F0",
    "55 41 57 41 56 41 55 41 54 56 57 53 48 81 EC 88 00 00 00 48 8D AC 24 80 00 00 00 0F 29 75 F0 45 89 C4 89 55 EC 49 89 CF 31 DB 80 B9 38 18 00 00 00")
local GETSTATION_AOB = edSig(
    "3B 0D ? ? ? ? 73 0E 48 8B 05 ? ? ? ? 8B C9 48 8B 04 C8 C3",
    "39 0D ? ? ? ? 76 0E 48 8B 05 ? ? ? ? 89 C9 48 8B 04 C8 C3 31 C0 C3")
local METAOBJ_AOB    = edSig(
    "48 8D 0D ? ? ? ? 41 B8 5F 00 00 00 8B D0 E8",
    "48 8D 0D ? ? ? ? 89 C2 41 B8 5F 00 00 00 E8")
local CATIDX_AOB     = edSig(
    "48 83 EC 20 41 8B E8 E8 ? ? ? ? 33 DB 48 8B F8 48 85 C0 74 3E 38 58 28", nil)
local TEXTID_AOB     = edSig(
    "48 89 5C 24 08 55 48 8B EC 48 81 EC 80 00 00 00 8B D9 E8 ? ? ? ? 48 8D 15 ? ? ? ? 48 8D 4D B0 44 8B C0",
    "56 57 53 48 81 EC 80 00 00 00 89 CE E8 ? ? ? ? 48 8D 15 ? ? ? ? 48 8D 7C 24 70 48 89 F9 41 89 C0 E8 ? ? ? ? 48 89 F9 31 D2 E8 ? ? ? ? 48 8D 0D ? ? ? ? 89 C2")

local function plausiblePtr(p)
    return p ~= nil and p > 0x10000 and p < 0x7FFFFFFFFFFF
end

radioCtl = {
    net      = { senderPtr = nil },
    track    = {},
    stations = { "(waiting for session)" },
    stationNames = { "(waiting for session)" },
    playlistSentinel = "\1VIBESCRIPT_PLAYLIST",
    playlistLabel = nil,
    labelCache = {},
    durCache = {},
    songNames = { "(pick a station)" },
    tracks   = {},
    station  = nil,
    loop     = { primed = false, station = nil, hash = 0, lastMs = 0, nextPollAt = 0 },
    auto     = { nextAt = 0, stationIdx = -1, titlesReady = false,
                 followSt = nil, followHash = 0, snapSong = false,
                 clkSt = nil, clkHash = 0, clkBase = 0, clkEnd = nil },
    pending  = {},
    resync   = nil,
    SYNC_HEARTBEAT_MS  = 60000,
    SYNC_CHANGE_MIN_MS = 1500,
    lastSyncAt = 0,
    syncWatch  = { station = nil, hash = nil, primed = false },
    pickerUsed = false,
    ui       = { line1 = "", line2 = "", line3 = "", line3R = "", status = "",
                 seekKey = nil, seekStation = nil, seekHash = 0,
                 seekBaseMs = 0, seekEndMs = nil, seekValueMs = 0,
                 seekCat = 2, seekColl = MUSIC_COLL,
                 seekDragging = false, seekDragKey = nil },
    plLoop   = {},
    plBus    = {},
    memo     = {},
    usb      = { addr = nil, orig = nil, silPtr = nil },
    usr      = { ready = nil, want = nil },
    cueLogged = {},
    dumped   = {},
    dumpQueue = {},
    AOB = {
        SENDER = SENDER_AOB, SESSION = SESSION_AOB, FORCE = FORCE_AOB,
        GETSTATION = GETSTATION_AOB, METAOBJ = METAOBJ_AOB, CATIDX = CATIDX_AOB, TEXTID = TEXTID_AOB,
        SNDDUR = edSig(
            "48 8D 0D ? ? ? ? 8B D6 E8 ? ? ? ? 48 85 C0 74 08 8B 00 89 83 68 06 00 00",
            "48 8D 0D ? ? ? ? 89 FA E8 ? ? ? ? 48 85 C0 74 1F 80 38 08 75 1A 48 8D 54 24 20 48 89 C1 E8 ? ? ? ? 48 85 C0 74 08 8B 00 89 86 68 06 00 00"),
        USERMGR = edSig(
            "44 38 A3 49 18 00 00 0F 84 ? ? ? ? 48 8D 0D ? ? ? ? E8 ? ? ? ? 8B F8 41 3B C5 75 ? 8A 15 ? ? ? ? 84 D2 75 ? 44 38 25 ? ? ? ?",
            "80 BE 49 18 00 00 00 74 ? 48 8B 05 ? ? ? ? 48 85 C0 74 ? 0F B7 78 18 31 C9 0F B6 05 ? ? ? ? B3 01 83 FF 03 0F 82 ? ? ? ? 84 C0 0F 85 ? ? ? ? 8B 0D ? ? ? ? 83 F9 01"),
        USERMODE = edSig(
            "48 8B 01 48 85 C0 74 04 0F B7 40 18 83 F8 02 7E 10 80 3D ? ? ? ? 00 75 07 8B 05 ? ? ? ? C3", nil),
    },
}


function radioCtl.resolveSender()
    local net = radioCtl.net
    if net.senderPtr ~= nil then return net.senderPtr or nil end
    local hit = Memory.Scan(SENDER_AOB)
    if plausiblePtr(hit) then net.senderPtr = hit; return hit end
    net.senderPtr = false
    return nil
end


function radioCtl.resolveSession()
    local hit = Memory.Scan(SESSION_AOB)
    if not plausiblePtr(hit) then return nil, "session AOB miss" end
    local globalAddr = Memory.Rip(hit + SESSION_RIP)
    if not plausiblePtr(globalAddr) then return nil, "rip failed" end
    local cns = Memory.ReadLong(globalAddr)
    if not plausiblePtr(cns) then return nil, "not in a session" end
    local sn = Memory.ReadLong(cns + SNSESSION_OFF)
    if not plausiblePtr(sn) then return nil, "snSession null" end
    if not plausiblePtr(Memory.ReadLong(sn + 0x48)) then return nil, "conn mgr null" end
    return sn, "ok"
end


function radioCtl.resolveTrack()
    local track = radioCtl.track
    if track.ready ~= nil then return track.ready end
    track.ready = false
    local f  = Memory.Scan(FORCE_AOB)
    local gs = Memory.Scan(GETSTATION_AOB)
    if not (plausiblePtr(f) and plausiblePtr(gs)) then return false end
    local countAddr = Memory.Rip(gs + 2)
    local arrayAddr = Memory.Rip(gs + 11)
    if not (plausiblePtr(countAddr) and plausiblePtr(arrayAddr)) then return false end
    track.forceFn, track.countPtr, track.arrayPtr = f, countAddr, arrayAddr
    local mo = Memory.Scan(METAOBJ_AOB)
    if plausiblePtr(mo) then
        local mm, go = Memory.Rip(mo + 3), Memory.Rip(mo + 16)
        if plausiblePtr(mm) and plausiblePtr(go) then track.metaMgr, track.getObj = mm, go end
    end
    if CATIDX_AOB then
        local ci = Memory.Scan(CATIDX_AOB)
        if plausiblePtr(ci) then track.catIdxFn = ci - 0x10 end
    end
    local ti = Memory.Scan(TEXTID_AOB)
    if plausiblePtr(ti) then track.textIdFn = ti end
    local sd = Memory.Scan(radioCtl.AOB.SNDDUR)
    if plausiblePtr(sd) then
        local mgr = Memory.Rip(sd + 3)
        local fn  = Memory.Rip(sd + 10)
        local dec = IS_ENHANCED and Memory.Rip(sd + 33) or nil
        if plausiblePtr(mgr) and plausiblePtr(fn)
                and (not IS_ENHANCED or plausiblePtr(dec)) then
            track.sndMgr, track.sndFn, track.sndDecFn = mgr, fn, dec
            if IS_ENHANCED then
                track.sndScratch = Memory.Alloc(0x80)
                if not plausiblePtr(track.sndScratch) then track.sndFn = nil end
            end
        end
    end
    track.ready = true
    return true
end

local function findStation(nameHash)
    local track = radioCtl.track
    local count = Memory.ReadInt(track.countPtr) or 0
    if count < 1 or count > 256 then return nil end
    local arrayBase = Memory.ReadLong(track.arrayPtr)
    if not plausiblePtr(arrayBase) then return nil end
    for i = 0, count - 1 do
        local st = Memory.ReadLong(arrayBase + i * 8)
        if plausiblePtr(st) and Memory.ReadUInt(st + 0x17F0) == nameHash then return st end
    end
    return nil
end

function radioCtl.stationByName(stName)
    if not radioCtl.resolveTrack() then return nil end
    if not stName or stName == "" then return nil end
    local st = findStation(Utils.Joaat(stName))
    return plausiblePtr(st) and st or nil
end

function radioCtl.freeResult(ptr)
    if not ptr or ptr == 0 then return end
    if Memory.SizeOf then
        local ok, size = pcall(Memory.SizeOf, ptr)
        if not ok or not size or size == 0 then return end
    end
    Memory.Free(ptr)
end

function radioCtl.forEachList(coll, fn)
    local lists = Memory.ReadLong(coll)
    local n     = Memory.ReadUShort(coll + 0x08) or 0
    if not plausiblePtr(lists) or n < 1 or n > 64 then return end
    local locksOn = (Memory.ReadUByte(coll + 0x28) or 0) ~= 0
    for i = 0, n - 1 do
        local list = Memory.ReadLong(lists + i * 8)
        if plausiblePtr(list) then
            local skip = false
            if locksOn then
                local bits = Memory.ReadUInt(coll + 0x20 + (i // 32) * 4) or 0
                skip = ((bits >> (i % 32)) & 1) == 1
            end
            if not skip and fn(list, Memory.ReadUByte(list + 0x44) or 0) then return end
        end
    end
end


function radioCtl.listZeroHas(station, hash)
    local coll  = station + MUSIC_COLL
    local lists = Memory.ReadLong(coll)
    if not plausiblePtr(lists) or (Memory.ReadUShort(coll + 0x08) or 0) < 1 then return false end
    local l0 = Memory.ReadLong(lists)
    if not plausiblePtr(l0) then return false end
    for t = 0, (Memory.ReadUByte(l0 + 0x44) or 0) - 1 do
        if Memory.ReadUInt(l0 + 0x4C + t * 8) == hash then return true end
    end
    return false
end

function radioCtl.usbSilenceIdx(station)
    local u = radioCtl.usb
    if not u.silPtr then
        u.silPtr = radioCtl.metaObject(Utils.Joaat(USB_SILENCE_LIST), META_TYPE_TRACKLIST)
        if not u.silPtr then return nil end
    end
    local coll  = station + MUSIC_COLL
    local lists = Memory.ReadLong(coll)
    if not plausiblePtr(lists) then return nil end
    for i = 0, (Memory.ReadUShort(coll + 0x08) or 0) - 1 do
        if Memory.ReadLong(lists + i * 8) == u.silPtr then return i end
    end
    return nil
end

function radioCtl.usbPrep(station)
    if (Memory.ReadUInt(station + 0x17F0) or 0) ~= USB_STATION_HASH then return end
    local coll = station + MUSIC_COLL
    local n = Memory.ReadUShort(coll + 0x08) or 0
    if n < 1 or n > 32 then return end
    local sil  = radioCtl.usbSilenceIdx(station)
    local want = sil and (1 << sil) or 0
    local cur  = Memory.ReadUInt(coll + 0x20) or 0
    if cur == want then return end
    local u = radioCtl.usb
    if not u.addr then u.addr, u.orig = coll + 0x20, cur end
    Memory.WriteUInt(coll + 0x20, want)
    logf("radio: Media Player track-list locks %08X -> %08X (%d lists, silence %s)",
        cur, want, n, sil and ("index " .. sil) or "unresolved")
end

function radioCtl.usbRestore()
    local u = radioCtl.usb
    if not u.addr then return end
    Memory.WriteUInt(u.addr, u.orig)
    u.addr, u.orig = nil, nil
end


local USR_WAIT_MS = 20000
local USR_SETTLE_MS = 2500
local USR_SEEK_MS = 2500
local USR_SEEK_TRIES = 3

function radioCtl.isUserStation(stName)
    return stName == USR.NAME
end

function radioCtl.localOnlyStation(stName)
    return stName == USR.NAME or Utils.Joaat(stName or "") == USB_STATION_HASH
end

function radioCtl.resolveUser()
    local u = radioCtl.usr
    if u.ready ~= nil then return u.ready end
    u.ready = false
    local hit = Memory.Scan(radioCtl.AOB.USERMGR)
    if not plausiblePtr(hit) then
        logf("radio: Self Radio -- USERMGR scan miss, user music unavailable")
        return false
    end
    local mgr, nxt, prv, mode, rec
    if IS_ENHANCED then
        mgr, rec, mode = Memory.Rip(hit + 12), Memory.Rip(hit + 30), Memory.Rip(hit + 55)
        prv, nxt = Memory.Rip(hit + 67), Memory.Rip(hit + 81)
    else
        mgr, prv, nxt = Memory.Rip(hit + 16), Memory.Rip(hit + 34), Memory.Rip(hit + 45)
        local mh = Memory.Scan(radioCtl.AOB.USERMODE)
        if plausiblePtr(mh) then
            rec, mode = Memory.Rip(mh + 19) + 1, Memory.Rip(mh + 28)
        end
    end
    if not (plausiblePtr(mgr) and plausiblePtr(nxt) and plausiblePtr(prv)) then
        logf("radio: Self Radio -- USERMGR rip failed")
        return false
    end
    u.mgr, u.nextFlag, u.prevFlag = mgr, nxt, prv
    u.modePtr = plausiblePtr(mode) and mode or nil
    u.recPtr  = plausiblePtr(rec) and rec or nil
    u.ready = true
    logf("radio: Self Radio manager %X (next %X, prev %X, mode %s)", mgr, nxt, prv,
        u.modePtr and ("%X"):format(u.modePtr) or "unresolved")
    return true
end

function radioCtl.userMode()
    if not radioCtl.resolveUser() then return nil end
    local u = radioCtl.usr
    if not u.modePtr then return nil end
    if u.modeSaved ~= nil then return u.modeSaved end
    if u.recPtr and (Memory.ReadUByte(u.recPtr) or 0) ~= 0 then return 0 end
    local m = Memory.ReadInt(u.modePtr)
    if not m or m < 0 or m > 2 then return nil end
    return m
end

function radioCtl.userStr(addr)
    local s = Memory.ReadString(addr)
    if type(s) ~= "string" then return nil end
    s = s:sub(1, 32):gsub("%c", "")
    s = s:match("^%s*(.-)%s*$")
    if s == "" then return nil end
    return s
end

function radioCtl.userFileName(addr)
    local p = Memory.ReadLong(addr)
    if not plausiblePtr(p) then return nil end
    local out = {}
    for i = 0, 259 do
        local c = Memory.ReadUShort(p + i * 2) or 0
        if c == 0 then break end
        out[#out + 1] = (c >= 32 and c < 127) and string.char(c) or "?"
    end
    local s = table.concat(out)
    if s == "" then return nil end
    s = s:match("([^\\/]+)$") or s
    return (s:gsub("%.[%w]+$", ""))
end

function radioCtl.userTracks()
    if not radioCtl.resolveUser() then return nil end
    local u = radioCtl.usr
    local db = Memory.ReadLong(u.mgr)
    if not plausiblePtr(db) then return nil end
    local arr = Memory.ReadLong(db + USR.DB_ARR)
    local n   = Memory.ReadUShort(db + USR.DB_CNT) or 0
    if not plausiblePtr(arr) or n < 1 or n > 4096 then return nil end
    if u.cache and u.cacheArr == arr and u.cacheN == n then return u.cache end
    local out = {}
    for i = 0, n - 1 do
        local base = arr + i * USR.TRK
        local dur  = Memory.ReadUInt(base + USR.DUR) or 0
        out[i + 1] = {
            title  = radioCtl.userStr(base + USR.TITLE) or radioCtl.userFileName(base + USR.FILE),
            artist = radioCtl.userStr(base + USR.ARTIST),
            durMs  = (dur > 0 and dur < 0xFFFFFFFF) and dur or nil,
        }
    end
    u.cache, u.cacheArr, u.cacheN = out, arr, n
    logf("radio: Self Radio -- %d file(s) in the game's scan", n)
    return out
end

function radioCtl.userEntries()
    local tracks = radioCtl.userTracks()
    if not tracks then return {} end
    local out = {}
    for i, t in ipairs(tracks) do
        out[i] = { hash = USR.NULLTRACK, offset = 0, endMs = nil, id = nil,
                   index = 0, cat = 2, coll = MUSIC_COLL,
                   user = i - 1, title = t.title, artist = t.artist, durMs = t.durMs }
    end
    return out
end

function radioCtl.userDurationMs(idx)
    local t = idx and (radioCtl.userTracks() or {})[idx + 1]
    return t and t.durMs or nil
end

function radioCtl.userActiveIdx(station)
    if not plausiblePtr(station) then return nil end
    local slot = station + (Memory.ReadUByte(station + 0x182C) or 0) * 0x8C8
    if (Memory.ReadInt(slot + SLOT_TRACK_CAT) or -1) ~= 2 then return nil end
    local idx = Memory.ReadInt(slot + SLOT_TRACK_IDX)
    if not idx or idx < 0 then return nil end
    return idx
end

function radioCtl.userNowPlaying()
    local station = radioCtl.stationByName(USR.NAME)
    if not plausiblePtr(station) then return nil end
    local idx = radioCtl.userActiveIdx(station)
    if not idx then return nil end
    local t = (radioCtl.userTracks() or {})[idx + 1]
    if not t then return nil end
    local title = t.title and (t.artist and (t.title .. " - " .. t.artist) or t.title)
        or ("Untitled file %d"):format(idx + 1)
    return title, t.durMs, idx, station
end

function radioCtl.userForceMode()
    local u = radioCtl.usr
    if not u.modePtr then return end
    if u.modeSaved == nil then u.modeSaved = Memory.ReadInt(u.modePtr) or 2 end
    if (Memory.ReadInt(u.modePtr) or 2) ~= 2 then Memory.WriteInt(u.modePtr, 2) end
end

function radioCtl.userModeRestore()
    local u = radioCtl.usr
    if u.modeSaved == nil then return end
    if u.modePtr then Memory.WriteInt(u.modePtr, u.modeSaved) end
    u.modeSaved = nil
end

function radioCtl.userForce(idx, loop, offsetMs)
    if not radioCtl.resolveUser() then return false end
    local tracks = radioCtl.userTracks()
    if not tracks or not tracks[idx + 1] then return false end
    local u = radioCtl.usr
    loop = (loop and radioCtl.loopActive()) and true or false
    local off = math.floor(tonumber(offsetMs) or 0)
    if off < 1000 then off = 0 end
    local dur = tracks[idx + 1].durMs
    if dur and off >= dur then off = math.max(0, dur - 2000) end
    local now = Time.GetEpocheMs()
    if u.want and not u.want.loop and (now - (u.want.at or 0)) < USR_SETTLE_MS then
        u.want.idx, u.want.loop = idx, loop or false
        u.want.offset, u.want.seeked = off, false
        u.want.seekBy = now + USR_SEEK_MS
        u.want.until_ = now + USR_WAIT_MS
        Memory.WriteInt(u.mgr + USR.FORCENEXT, idx)
        logf("radio: Self Radio -- retargeted the pending pick to file %d/%d (%s)%s",
            idx + 1, #tracks, tracks[idx + 1].title or "untitled",
            off > 0 and (" at " .. off .. " ms") or "")
        return true
    end
    iv(HASH.UNFREEZE, USR.NAME)
    radioCtl.userForceMode()
    Memory.WriteInt(u.mgr + USR.FORCENEXT, idx)
    local station = radioCtl.stationByName(USR.NAME)
    Memory.WriteUByte(u.prevFlag, 1)
    u.want = { idx = idx, at = now, until_ = now + USR_WAIT_MS, loop = loop or false,
               offset = off, seeked = false, tries = 0, seekBy = now + USR_SEEK_MS,
               station = plausiblePtr(station) and station or nil }
    radioCtl.forcedUntil = now + 3000
    local m = radioCtl.userMode()
    logf("radio: Self Radio -- asked for file %d/%d (%s)%s, play mode %s%s",
        idx + 1, #tracks, tracks[idx + 1].title or "untitled",
        off > 0 and (" at " .. off .. " ms") or "",
        m and USR.MODES[m] or "unknown", loop and ", pinned for the loop" or "")
    return true
end

function radioCtl.userReseek(w, ms)
    local u = radioCtl.usr
    if Time.GetEpocheMs() - (w.at or 0) < 1200 then return end
    local idx, off, tries = w.idx, w.offset, (w.tries or 0) + 1
    logf("radio: Self Radio -- seek to %d ms did not take (%s); attempt %d of %d",
        off, ms and ("the file opened at " .. ms .. " ms") or "the window never opened",
        tries + 1, USR_SEEK_TRIES)
    u.want = nil
    Memory.WriteInt(u.mgr + USR.FORCENEXT, -1)
    if radioCtl.userForce(idx, false, off) and u.want then u.want.tries = tries end
end

function radioCtl.userTick(now)
    local u = radioCtl.usr
    local w = u.want
    if not w then radioCtl.userModeRestore(); return end
    if not u.ready then return end
    local function done()
        u.want = nil
        Memory.WriteInt(u.mgr + USR.FORCENEXT, -1)
        radioCtl.userModeRestore()
    end
    if w.loop and not radioCtl.loopActive() then done(); return end
    local st = w.station
    local seeking = (w.offset or 0) > 0

    local aidx = st and (Memory.ReadUByte(st + 0x182C) or 0) or 0
    local aslot = st and (st + aidx * 0x8C8) or nil
    local open = aslot and (Memory.ReadLong(aslot + USR.SND) or 0) ~= 0

    if st and seeking and not w.seeked then
        for slot = 0, 1 do
            local base = st + slot * 0x8C8
            if (Memory.ReadInt(base + SLOT_TRACK_CAT) or -1) == 2
                    and (Memory.ReadInt(base + SLOT_TRACK_IDX) or -1) == w.idx
                    and (Memory.ReadLong(base + USR.SND) or 0) == 0
                    and (Memory.ReadInt(base + USR.PLAYTIME) or -1) == 0 then
                Memory.WriteInt(base + USR.PLAYTIME, w.offset)
                w.seeked, w.wslot = true, slot
                if slot == aidx then w.promoted = true end
                logf("radio: Self Radio -- offset %d ms written into slot %d (file %d)%s",
                    w.offset, slot, w.idx + 1,
                    slot == aidx and "; it is the playing slot" or "; it is the queued slot")
                break
            end
        end
    end

    if seeking and w.seeked and not w.promoted and w.wslot ~= aidx and open then
        Memory.WriteUByte(u.nextFlag, 1)
        w.promoted = true
        logf("radio: Self Radio -- promoting slot %d to open file %d at %d ms",
            w.wslot, w.idx + 1, w.offset)
    end

    local at = st and radioCtl.userActiveIdx(st) or nil

    if at == w.idx and (not seeking or (w.seeked and open and aidx == w.wslot)) then
        if not w.loop then
            local ms = ii(HASH.TRACK_TIME, USR.NAME) or 0
            if seeking and ms >= 0 and ms + 5000 < w.offset then
                if (w.tries or 0) + 1 < USR_SEEK_TRIES then return radioCtl.userReseek(w, ms) end
                logf("radio: Self Radio -- seek to %d ms could not be applied after %d tries; "
                    .. "the file is playing from the top", w.offset, USR_SEEK_TRIES)
                done(); return
            end
            logf("radio: Self Radio -- file %d is playing%s", w.idx + 1,
                seeking and (" from " .. tostring(ms) .. " ms") or "")
            done(); return
        else
            radioCtl.userModeRestore()
        end
    elseif seeking and now > (w.seekBy or 0) and not (w.seeked and w.promoted) then
        if (w.tries or 0) + 1 < USR_SEEK_TRIES then return radioCtl.userReseek(w, nil) end
        logf("radio: Self Radio -- seek to %d ms never found its window in %d tries; "
            .. "the file is playing from the top", w.offset, USR_SEEK_TRIES)
        done(); return
    elseif now > w.until_ then
        logf("radio: Self Radio -- gave up on file %d after %d s (station is on %s, play mode %s)",
            w.idx + 1, USR_WAIT_MS // 1000, at and ("file " .. (at + 1)) or "an advert or ident",
            USR.MODES[radioCtl.userMode() or -1] or "unknown")
        done(); return
    end
    if not (seeking and w.promoted) then
        Memory.WriteInt(u.mgr + USR.FORCENEXT, w.idx)
    end
end

function radioCtl.forceTrackCall(station, hash, offsetMs)
    local off = math.floor(offsetMs or 0)
    if off < 0 then off = 0 end
    local dur = radioCtl.trackDurationMs(hash)
    if dur and off >= dur then off = math.max(0, dur - 1000) end
    local flag = Memory.ReadUByte(station + IS_MIX_STATION) or 0
    local bypass = flag == 1 and not radioCtl.listZeroHas(station, hash)
    if bypass then Memory.WriteUByte(station + IS_MIX_STATION, 0) end
    Memory.LuaCallCFunction(radioCtl.track.forceFn, station, hash, off)
    if bypass then Memory.WriteUByte(station + IS_MIX_STATION, flag) end
    return bypass
end

local META_TYPE_TEXTIDS = 0x72
local MAX_TEXTID_PAIRS  = 256
local MAX_TRACK_MS      = 4 * 3600000

local TRACK_TITLES = {
    [0x89A5BB01] = "Ron Jakowski",
}

function radioCtl.metaObject(nameHash, metaType)
    local track = radioCtl.track
    if not (track.getObj and track.metaMgr) then return nil end
    local ok, obj = pcall(function()
        local r = Memory.LuaCallCFunctionWithReturnValue(track.getObj, track.metaMgr, nameHash, metaType)
        if not r or r == 0 then return nil end
        local o = Memory.ReadLong(r)
        radioCtl.freeResult(r)
        return plausiblePtr(o) and o or nil
    end)
    return ok and obj or nil
end

function radioCtl.trackTextIds(hash, capMs)
    local obj = radioCtl.metaObject(Utils.Joaat(("RTT_%08X"):format(hash)), META_TYPE_TEXTIDS)
    if not obj then return nil end
    local cap = capMs or MAX_TRACK_MS
    local ok, out = pcall(function()
        local n = Memory.ReadUInt(obj + 0x04) or 0
        if n < 1 or n > MAX_TEXTID_PAIRS then return nil end
        local list, prev, past = {}, -1, 0
        for i = 0, n - 1 do
            local off = Memory.ReadUInt(obj + 0x08 + i * 8) or 0
            local id  = Memory.ReadUInt(obj + 0x0C + i * 8) or 0
            local last = list[#list]
            if off >= cap then
                past = past + 1
            elseif off >= prev and not (last and last.offset == off and last.id == id) then
                prev = off
                list[#list + 1] = { offset = off, id = id }
            end
        end
        if past > 0 and not radioCtl.cueLogged[hash] then
            radioCtl.cueLogged[hash] = true
            logf("radio: track %08X -- %d of %d cue markers sit past its own %d ms length, dropped",
                hash, past, n, cap)
        end
        if #list == 0 then return nil end
        return list
    end)
    return ok and out or nil
end

function radioCtl.trackDurationMs(hash)
    if not hash then return nil end
    hash = hash & 0xFFFFFFFF
    local cached = radioCtl.durCache[hash]
    if cached ~= nil then return cached or nil end
    if not radioCtl.resolveTrack() then return nil end
    local track = radioCtl.track
    if not (track.sndMgr and track.sndFn) then return nil end
    local ok, ms = pcall(function()
        local r = Memory.LuaCallCFunctionWithReturnValue(track.sndFn, track.sndMgr, hash)
        if not r or r == 0 then return nil end
        local p = Memory.ReadLong(r)
        radioCtl.freeResult(r)
        if not plausiblePtr(p) then return nil end
        if track.sndDecFn and track.sndScratch then
            if Memory.ReadUByte(p) ~= 8 then return nil end
            local d = Memory.LuaCallCFunctionWithReturnValue(track.sndDecFn, p, track.sndScratch)
            if not d or d == 0 then return nil end
            p = Memory.ReadLong(d)
            radioCtl.freeResult(d)
            if not plausiblePtr(p) then return nil end
        end
        local v = Memory.ReadUInt(p) or 0
        if v == 0 or v > MAX_TRACK_MS then return nil end
        return v
    end)
    ms = ok and ms or nil
    radioCtl.durCache[hash] = ms or false
    return ms
end

function radioCtl.stationEntries(station)
    if (Memory.ReadUInt(station + 0x17F0) or 0) == USR.HASH then
        return radioCtl.userEntries()
    end
    local titled = radioCtl.ensureTrackText()
    radioCtl.usbPrep(station)
    local out = {}
    local seenTrack, dropped, crossed = {}, 0, 0
    for _, c in ipairs(MUSIC_CATS) do
        local isMusic = c.cat == 2
        local flat = 0
        radioCtl.forEachList(station + c.coll, function(list, cnt)
            local carryTitle = nil
            for t = 0, cnt - 1 do
                local hash = Memory.ReadUInt(list + 0x4C + t * 8) or 0
                local idx  = flat
                flat = flat + 1
                if seenTrack[hash] then
                    dropped = dropped + 1
                    carryTitle = nil
                else
                    seenTrack[hash] = true
                    local markers = radioCtl.trackTextIds(hash, radioCtl.trackDurationMs(hash))
                    if markers and #markers > 1 then
                        for k, p in ipairs(markers) do
                            local nxt
                            for j = k + 1, #markers do
                                if markers[j].offset > p.offset then nxt = markers[j]; break end
                            end
                            local song, artist = radioCtl.songPartsForId(p.id)
                            local title = song and (artist and (song .. " - " .. artist) or song) or nil
                            local carried = titled and title ~= nil and title == carryTitle
                            if carried then crossed = crossed + 1 end
                            if not carried and (not titled or title) then
                                out[#out + 1] = { hash = hash, offset = p.offset,
                                                  endMs = nxt and nxt.offset or nil, id = p.id,
                                                  index = idx, cat = c.cat, coll = c.coll,
                                                  mix = true }
                                if title then carryTitle = title end
                            end
                        end
                    else
                        local id = markers and markers[1].id or nil
                        local song, artist = radioCtl.songPartsForId(id)
                        if not song then song, artist = radioCtl.songParts(hash) end
                        if isMusic or not titled or song then
                            out[#out + 1] = { hash = hash, offset = 0, endMs = nil, id = id,
                                              index = idx, cat = c.cat, coll = c.coll }
                        end
                        carryTitle = song and (artist and (song .. " - " .. artist) or song) or nil
                    end
                end
            end
        end)
    end
    if (dropped > 0 or crossed > 0) and radioCtl.dupLogged ~= station then
        radioCtl.dupLogged = station
        logf("radio: %08X list -- %d track(s) repeated across lists, %d cue(s) repeating the title already playing, each kept once",
            Memory.ReadUInt(station + 0x17F0) or 0, dropped, crossed)
    end
    if #out == 0 then return nil end
    return out
end

function radioCtl.dumpStation(station, stName)
    logf("radio dump: %s (%08X)", stName, Memory.ReadUInt(station + 0x17F0) or 0)
    for _, c in ipairs(MUSIC_CATS) do
        local li = -1
        radioCtl.forEachList(station + c.coll, function(list, cnt)
            li = li + 1
            logf("radio dump:  cat %d list %d -- %d track(s)", c.cat, li, cnt)
            for t = 0, cnt - 1 do
                local hash    = Memory.ReadUInt(list + 0x4C + t * 8) or 0
                local dur     = radioCtl.trackDurationMs(hash)
                local markers = radioCtl.trackTextIds(hash)
                logf("radio dump:   track %d hash=%08X len=%s markers=%d",
                    t, hash, dur and tostring(dur) or "?", markers and #markers or 0)
                for k, p in ipairs(markers or {}) do
                    local song, artist = radioCtl.songPartsForId(p.id)
                    logf("radio dump:    %2d @%8d id=%d %s%s", k, p.offset, p.id,
                        song and (artist and (song .. " - " .. artist) or song) or "(no title)",
                        (dur and p.offset >= dur) and "  PAST-END" or "")
                end
            end
        end)
    end
end

function radioCtl.queueDumpAll()
    local q = {}
    for _, nm in ipairs(radioCtl.stations) do
        if nm ~= radioCtl.playlistSentinel and nm:sub(1, 1) ~= "(" then q[#q + 1] = nm end
    end
    radioCtl.dumpQueue = q
    radioCtl.dumped = {}
    logf("radio dump: starting, %d station(s)", #q)
    GUI.AddToast("VibeScript", ("Dumping %d stations to the log..."):format(#q), 3000)
end

function radioCtl.dumpNext()
    local q = radioCtl.dumpQueue
    local stName = table.remove(q, 1)
    if not stName then return end
    local station = radioCtl.stationByName(stName)
    if plausiblePtr(station) then
        radioCtl.dumped[stName] = true
        radioCtl.dumpStation(station, stName)
    else
        logf("radio dump: %s -- station object not found", stName)
    end
    if #q == 0 then
        logf("radio dump: complete")
        GUI.AddToast("VibeScript", "Station dump complete.", 3000)
    end
end

function radioCtl.categoryTrackCount(station, coll)
    local n = 0
    radioCtl.forEachList(station + (coll or MUSIC_COLL), function(_, cnt) n = n + cnt end)
    return n
end

function radioCtl.mixNext(e)
    if e and e.mix then return { afterThis = true } end
    return nil
end

function radioCtl.collForCat(cat)
    for _, c in ipairs(MUSIC_CATS) do if c.cat == cat then return c.coll end end
    return MUSIC_COLL
end

function radioCtl.forceHash(station, stName, hash, loop, offsetMs, cat, coll, nextTrack, userIdx)
    if radioCtl.isUserStation(stName) then
        if userIdx then radioCtl.userForce(userIdx, loop, offsetMs) end
        return
    end
    local track = radioCtl.track
    cat, coll = cat or 2, coll or MUSIC_COLL
    radioCtl.usbPrep(station)
    iv(HASH.FREEZE, stName)
    local bypassed = radioCtl.forceTrackCall(station, hash, offsetMs)
    iv(HASH.UNFREEZE, stName)
    if bypassed then
        logf("radio: %s force %08X @ %d ms -- mix re-resolution suppressed",
            stName, hash, math.floor(offsetMs or 0))
    end
    local ci = radioCtl.trackCatIndex(station, hash, cat, coll)
    local nxtCat, nxtIdx = cat, nil
    if loop then
        nxtIdx = ci
    elseif nextTrack and nextTrack.afterThis then
        local total = radioCtl.categoryTrackCount(station, coll)
        if ci and total > 0 then nxtIdx = (ci + 1) % total end
    elseif nextTrack then
        nxtCat = nextTrack.cat or 2
        nxtIdx = radioCtl.trackCatIndex(station, nextTrack.hash, nxtCat, nextTrack.coll)
    end
    if not nxtIdx and ci then nxtCat, nxtIdx = cat, (ci > 0 and (ci - 1) or 1) end
    if nxtIdx and nxtIdx < 0xFF then
        Memory.WriteUByte(station + 0x17FF, nxtCat)
        Memory.WriteUByte(station + 0x1800, nxtIdx)
    end
    radioCtl.forcedUntil = Time.GetEpocheMs() + 3000
end


function radioCtl.trackCatIndex(station, hash, cat, coll)
    local track = radioCtl.track
    if track.catIdxFn then
        local r = Memory.LuaCallCFunctionWithReturnValue(track.catIdxFn, station, cat or 2, hash)
        local ci = (r and r ~= 0) and Memory.ReadUInt(r) or nil
        radioCtl.freeResult(r)
        return ci
    end
    return radioCtl.categoryIndexOf(station, hash, coll)
end

function radioCtl.categoryIndexOf(station, hash, coll)
    local flat, found = 0, nil
    radioCtl.forEachList(station + (coll or MUSIC_COLL), function(list, cnt)
        for t = 0, cnt - 1 do
            if Memory.ReadUInt(list + 0x4C + t * 8) == hash then found = flat + t; return true end
        end
        flat = flat + cnt
    end)
    return found
end


function radioCtl.ensureTrackText()
    if ib(HASH.HAS_ADDL_TEXT, TRACKID_SLOT) then return true end
    iv(HASH.REQ_ADDL_TEXT, "TRACKID", TRACKID_SLOT)
    return ib(HASH.HAS_ADDL_TEXT, TRACKID_SLOT)
end

function radioCtl.gxt(label)
    local s = is(HASH.FILENAME_CONV, label)
    if not s or s == "" or s == label or s == "NULL" then return nil end
    return s
end

function radioCtl.songPartsForId(id)
    if not id or id <= 1 then return nil, nil end
    local s = radioCtl.gxt(tostring(id) .. "S")
    local a = radioCtl.gxt(tostring(id) .. "A")
    if not s then return a, nil end
    return s, a
end

function radioCtl.songParts(hash)
    local track = radioCtl.track
    local song, artist
    if track.textIdFn then
        local ok, id = pcall(function()
            local r = Memory.LuaCallCFunctionWithReturnValue(track.textIdFn, hash)
            local v = (r and r ~= 0) and Memory.ReadInt(r) or 0
            radioCtl.freeResult(r)
            return v
        end)
        if ok then song, artist = radioCtl.songPartsForId(id) end
    end
    if song then return song, artist end
    return TRACK_TITLES[hash & 0xFFFFFFFF], nil
end

function radioCtl.songPartsForEntry(e)
    if not e then return nil, nil end
    if e.user then return e.title, e.artist end
    if e.id then return radioCtl.songPartsForId(e.id) end
    return radioCtl.songParts(e.hash)
end

function radioCtl.songName(hash)
    local song, artist = radioCtl.songParts(hash)
    if not song then return nil end
    if artist then return song .. " - " .. artist end
    return song
end

function radioCtl.songTitle(e)
    local song, artist = radioCtl.songPartsForEntry(e)
    if not song then
        if e.user then return ("Untitled file %d"):format(e.user + 1) end
        return ("(0x%08X)"):format(e.hash)
    end
    return artist and (song .. " - " .. artist) or song
end

function radioCtl.writeSyncHistory()
    local track = radioCtl.track
    if not radioCtl.resolveTrack() then return nil end
    local pp = radioPl and radioPl.play
    local dial = is(HASH.PLAYER_STATION)
    local function usable(n) return n and n ~= "" and n ~= "OFF" and n or nil end
    local stName = (pp and pp.active and usable(pp.station))
                or usable(dial) or usable(radioCtl.station)
    if not stName then
        logf("radio sync: no station to snapshot (dial %s); nothing sent",
            (dial == nil or dial == "") and "empty" or dial)
        return nil
    end
    if radioCtl.localOnlyStation(stName) then
        if radioCtl.localOnlyLogged ~= stName then
            radioCtl.localOnlyLogged = stName
            logf("radio sync: %s is local-only (the receiver drops its sync); nothing sent", stName)
        end
        return nil
    end
    local station = findStation(Utils.Joaat(stName))
    if not plausiblePtr(station) then return nil end
    local audHash = (ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF
    if pp and pp.active and pp.hash and pp.hash ~= 0
        and audHash ~= (pp.hash & 0xFFFFFFFF) then
        logf("radio sync: %s is on %08X, not the entry %08X; nothing sent",
            stName, audHash, pp.hash & 0xFFFFFFFF)
        return nil
    end
    local cat, coll, idx
    if pp and pp.active and pp.station == stName and pp.hash == audHash then
        cat, coll = pp.cat or 2, pp.coll
        idx = radioCtl.trackCatIndex(station, audHash, cat, coll)
    end
    if idx == nil then
        for _, c in ipairs(MUSIC_CATS) do
            local found = radioCtl.trackCatIndex(station, audHash, c.cat, c.coll)
            if found ~= nil then cat, coll, idx = c.cat, c.coll, found; break end
        end
    end
    if idx == nil then
        logf("radio sync: unresolved %08X on %s; snapshot not sent", audHash, stName)
        return nil
    end
    if track.getObj and track.metaMgr then
        local r = Memory.LuaCallCFunctionWithReturnValue(track.getObj, track.metaMgr, audHash, 0x5F)
        if r and r ~= 0 then
            local obj = Memory.ReadLong(r); radioCtl.freeResult(r)
            if plausiblePtr(obj) then idx = Memory.ReadUByte(obj + 8) end
        end
    end
    local curSlot  = station + Memory.ReadUByte(station + 0x182C) * 0x8C8
    local head     = Memory.ReadUInt(station + 0x14C4)
    local slot0    = station + 0x1488 + ((head + 0xE) % 0xF) * 4
    local prevRing = Memory.ReadUInt(slot0)
    local prevCat  = Memory.ReadUByte(curSlot + SLOT_TRACK_CAT)
    local prevIdx  = Memory.ReadUInt(curSlot + SLOT_TRACK_IDX)
    Memory.WriteUInt(slot0, (idx % 0x100) * 0x10000 + cat)
    Memory.WriteUByte(curSlot + SLOT_TRACK_CAT, cat)
    Memory.WriteUInt(curSlot + SLOT_TRACK_IDX, idx)
    logf("radio sync: %s hash=%08X category=%d index=%d", stName, audHash, cat, idx)
    return station, function()
        Memory.WriteUInt(slot0, prevRing)
        Memory.WriteUByte(curSlot + SLOT_TRACK_CAT, prevCat)
        Memory.WriteUInt(curSlot + SLOT_TRACK_IDX, prevIdx)
    end
end

function radioCtl.autoSyncActive()
    local f = FeatureMgr.GetFeature(H.RADIO_AUTO_SYNC)
    return not f or f:IsToggled()
end

function radioCtl.broadcastToOthers(quiet)
    if not radioCtl.autoSyncActive() then return false end
    local fn = radioCtl.resolveSender()
    if not fn then if not quiet then GUI.AddToast("VibeScript", "Sender AOB miss.", 3500) end return end
    local sn, status = radioCtl.resolveSession()
    if not sn then if not quiet then GUI.AddToast("VibeScript", "No sync: " .. status, 3500) end return end
    local count = Memory.ReadInt(sn + GAMER_CNT) or 0
    if count < 1 or count > 32 then
        if not quiet then GUI.AddToast("VibeScript", ("Unexpected gamer count (%d)"):format(count), 3500) end
        return
    end
    local syncStation, restore = radioCtl.writeSyncHistory()
    if not syncStation then
        if not quiet then GUI.AddToast("VibeScript", "No sync: current song index unresolved.", 3500) end
        return
    end
    local sent = 0
    for i = 0, count - 1 do
        local g = Memory.ReadLong(sn + GAMER_ARR + i * 8)
        if plausiblePtr(g) then
            Memory.LuaCallCFunction(fn, 0, sn, g + HANDLE_OFF)
            sent = sent + 1
        end
    end
    if restore then restore() end
    radioCtl.lastSyncAt = Time.GetEpocheMs()
    if not quiet then GUI.AddToast("VibeScript", ("Radio synced to %d player(s)."):format(sent), 3000) end
end

function radioCtl.armResync(stName, hash, offset, pid)
    if not stName or not hash then return end
    if pid == nil and not radioCtl.autoSyncActive() then return end
    if radioCtl.localOnlyStation(stName) then return end
    local now = Time.GetEpocheMs()
    radioCtl.resync = {
        station = stName,
        hash = hash & 0xFFFFFFFF,
        offset = math.max(0, tonumber(offset) or 0),
        pid = pid,
        armedAt = now,
        nextAt = now + 50,
        deadline = now + 5000,
    }
end

function radioCtl.syncToOnePlayer(pid)
    local fn = radioCtl.resolveSender()
    if not fn then return false, "sender AOB miss" end
    local sn, status = radioCtl.resolveSession()
    if not sn then return false, status end
    local p = Players.GetById(pid)
    local rid
    pcall(function() if p then rid = tonumber(p:GetGamerInfo().RockstarId) end end)
    if not rid then return false, "no RockstarId for player" end
    local count = Memory.ReadInt(sn + GAMER_CNT) or 0
    if count < 1 or count > 32 then return false, ("bad gamer count %d"):format(count) end
    local handle
    for i = 0, count - 1 do
        local g = Memory.ReadLong(sn + GAMER_ARR + i * 8)
        if plausiblePtr(g) and Memory.ReadLong(g + HANDLE_OFF) == rid then
            handle = g + HANDLE_OFF; break
        end
    end
    if not handle then return false, "player not in session gamer list" end
    local syncStation, restore = radioCtl.writeSyncHistory()
    if not syncStation then return false, "current song index unresolved" end
    Memory.LuaCallCFunction(fn, 0, sn, handle)
    if restore then restore() end
    return true, "ok"
end


function radioCtl.stationLabel(stName)
    local cached = radioCtl.labelCache[stName]
    if cached then return cached end
    local s = radioCtl.gxt(stName)
    if s then
        radioCtl.labelCache[stName] = s
        return s
    end
    return stName
end

function radioCtl.refreshStations()
    local list = {}
    local pp = radioPl and radioPl.play
    local playing = pp and pp.active and radioPl.lists[pp.listIdx] or nil
    local playlistLabel = playing and ("Playlist: " .. playing.name) or nil
    if playing then list[#list + 1] = radioCtl.playlistSentinel end

    local realCount = 0
    local n = ii(HASH.NUM_STATIONS) or 0
    for i = 0, n - 1 do
        local nm = is(HASH.STATION_NAME, i)
        if nm and nm ~= "" then
            list[#list + 1] = nm
            realCount = realCount + 1
        end
    end
    if realCount == 0 then list[#list + 1] = "(waiting for session)" end

    local same = #list == #radioCtl.stations and radioCtl.playlistLabel == playlistLabel
    if same then
        for i = 1, #list do
            if list[i] ~= radioCtl.stations[i] then same = false; break end
        end
    end
    if same then return false end

    local labels = {}
    for i, nm in ipairs(list) do
        if nm == radioCtl.playlistSentinel then
            labels[i] = playlistLabel
        else
            labels[i] = (nm:sub(1, 1) == "(") and nm or radioCtl.stationLabel(nm)
        end
    end
    local f = FeatureMgr.GetFeature(H.RADIO_STATION)
    local keep = f and radioCtl.stations[f:GetListIndex() + 1] or nil
    radioCtl.stations, radioCtl.stationNames = list, labels
    radioCtl.playlistLabel = playlistLabel
    if f then
        f:SetList(labels)
        local at = 0
        if keep then
            for i, nm in ipairs(list) do if nm == keep then at = i - 1; break end end
        end
        f:SetListIndex(at)
    end
    radioCtl.ensureTrackText()
    return true
end

function radioCtl.tuneTo(stName)
    if not stName or stName == "" then return end
    iv(HASH.SET_STATION, stName)
end

function radioCtl.chosenStationValue()
    local f = FeatureMgr.GetFeature(H.RADIO_STATION)
    return f and radioCtl.stations[f:GetListIndex() + 1] or nil
end

function radioCtl.pickerIsPlaylist()
    local pp = radioPl and radioPl.play
    return pp and pp.active
        and radioCtl.chosenStationValue() == radioCtl.playlistSentinel
end

function radioCtl.chosenStationName()
    local nm = radioCtl.chosenStationValue()
    if not nm or nm == radioCtl.playlistSentinel or nm:sub(1, 1) == "(" then return nil end
    return nm
end

function radioCtl.loadSongs()
    if radioCtl.chosenStationValue() == radioCtl.playlistSentinel then
        if radioPl and radioPl.play.active then return radioPl.syncPicker(false) end
        return true
    end
    local stName = radioCtl.chosenStationName()
    if not stName then return true end
    local station = radioCtl.stationByName(stName)
    if not plausiblePtr(station) then return true end
    local entries = radioCtl.stationEntries(station)
    if radioCtl.isUserStation(stName) and (not entries or #entries == 0) then
        radioCtl.station, radioCtl.tracks = stName, {}
        radioCtl.songNames = { radioCtl.resolveUser()
            and "(no music files found)" or "(Self Radio unavailable)" }
        local ef = FeatureMgr.GetFeature(H.RADIO_SONG)
        if ef then ef:SetList(radioCtl.songNames); ef:SetListIndex(0) end
        return true
    end
    if not entries or #entries == 0 then return true end
    local namesReady = radioCtl.ensureTrackText()
    local newStation = radioCtl.station ~= stName
    radioCtl.station, radioCtl.tracks = stName, entries
    local titles, dupes = {}, {}
    for i, e in ipairs(entries) do
        titles[i] = radioCtl.songTitle(e)
        dupes[titles[i]] = (dupes[titles[i]] or 0) + 1
    end
    local labels, seen = {}, {}
    for i, e in ipairs(entries) do
        local title = titles[i]
        if dupes[title] > 1 then
            seen[title] = (seen[title] or 0) + 1
            local off = e.offset or 0
            if off > 0 then
                title = ("%s  [%d:%02d]"):format(title, off // 60000, (off // 1000) % 60)
            elseif seen[title] > 1 then
                title = ("%s  (%d)"):format(title, seen[title])
            end
        end
        labels[i] = ("%02d  %s"):format(i, title)
    end
    radioCtl.songNames = labels
    local sf = FeatureMgr.GetFeature(H.RADIO_SONG)
    if sf then
        sf:SetList(labels)
        if newStation then sf:SetListIndex(0) end
    end
    return namesReady
end

function radioCtl.playPicked(loop)
    if not radioCtl.station or #radioCtl.tracks == 0 then return nil end
    local sf  = FeatureMgr.GetFeature(H.RADIO_SONG)
    local idx = sf and sf:GetListIndex() or 0
    local e = radioCtl.tracks[idx + 1]
    if not e then return nil end
    local stName = radioCtl.station
    radioCtl.tuneTo(stName)
    local station = radioCtl.stationByName(stName)
    if not plausiblePtr(station) then return nil end
    radioCtl.forceHash(station, stName, e.hash, loop, e.offset, e.cat, e.coll,
        radioCtl.mixNext(e), e.user)
    return station, stName, e
end


function radioCtl.loopActive()
    local f = FeatureMgr.GetFeature(H.RADIO_LOOP)
    return f and f:IsToggled() or false
end

function radioCtl.retargetLoop(stName, e)
    local now = Time.GetEpocheMs()
    local lastMs = ii(HASH.TRACK_TIME, stName) or 0
    local function point(t)
        t.station, t.hash = stName, e.hash
        t.offset, t.endMs = e.offset or 0, e.endMs
        t.cat, t.coll = e.cat, e.coll
        t.user = e.user
        t.lastMs = lastMs
        t.nextPollAt = now + 500
    end
    for _, st in pairs(radioCtl.plLoop) do
        if st.primed then point(st) end
    end
    local lp = radioCtl.loop
    if not lp.primed then return end
    point(lp)
end

function radioCtl.loopPoll(st, perPlayer, pid)
    local stName = st.station
    if not stName then return end
    if is(HASH.PLAYER_STATION) ~= stName then radioCtl.tuneTo(stName) end
    local nowMs   = ii(HASH.TRACK_TIME, stName) or 0
    if nowMs < 0 then return end
    local audHash = (ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF
    local restart = nowMs < st.lastMs
    local drift   = audHash ~= st.hash
    local ranOut  = st.endMs ~= nil and nowMs >= st.endMs
    st.lastMs = nowMs
    if restart or drift or ranOut then
        local station = radioCtl.stationByName(stName)
        if plausiblePtr(station) then
            radioCtl.forceHash(station, stName, st.hash, true, st.offset, st.cat, st.coll,
                nil, st.user)
            st.lastMs = ii(HASH.TRACK_TIME, stName) or 0
            if radioCtl.localOnlyStation(stName) then
            elseif perPlayer then
                radioCtl.syncToOnePlayer(pid)
                radioCtl.armResync(stName, st.hash, st.offset, pid)
            else
                radioCtl.broadcastToOthers(true)
            end
        end
    end
end

function radioCtl.loopSelfOnTick(f)
    if f:IsToggled() then radioCtl.pickerUsed = true end
    local lp = radioCtl.loop
    if f:IsToggled() and radioPl and radioPl.play.active then
        lp.primed = false
        f:Toggle()
        GUI.AddToast("VibeScript", "Stop the playlist before enabling Loop Song.", 3000)
        return
    end
    if not f:IsToggled() then lp.primed = false; return end
    if not isPlayerReady() then return end
    local now = Time.GetEpocheMs()
    if not lp.primed then
        local station, stName, e = radioCtl.playPicked(true)
        if not station then
            GUI.AddToast("VibeScript", "Pick a station and song first.", 3000)
            f:Toggle(); return
        end
        lp.primed, lp.station, lp.hash = true, stName, e.hash
        lp.offset, lp.endMs = e.offset or 0, e.endMs
        lp.cat, lp.coll, lp.user = e.cat, e.coll, e.user
        lp.lastMs = ii(HASH.TRACK_TIME, stName) or 0
        lp.nextPollAt = now + 500
        radioCtl.broadcastToOthers()
        radioCtl.armResync(stName, e.hash, e.offset)
        return
    end
    if now < lp.nextPollAt then return end
    lp.nextPollAt = now + 500
    radioCtl.loopPoll(lp, false, 0)
end

function radioCtl.stepNoList(dir)
    local stName = is(HASH.PLAYER_STATION)
    if not stName or stName == "" or stName == "OFF" then
        GUI.AddToast("VibeScript", "Turn your radio on first.", 3000); return
    end
    local station = radioCtl.stationByName(stName)
    if not plausiblePtr(station) then GUI.AddToast("VibeScript", "Station object not found.", 3000); return end
    local entries = radioCtl.stationEntries(station)
    if not entries then GUI.AddToast("VibeScript", "Station has no track list.", 3000); return end
    local n = #entries
    if n < 2 then GUI.AddToast("VibeScript", "Station has too few tracks.", 3000); return end
    local curHash = (ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF
    local curMs   = ii(HASH.TRACK_TIME, stName) or 0
    local curIdx = -1
    if radioCtl.isUserStation(stName) then
        curIdx = radioCtl.userActiveIdx(station) or -1
        if curIdx >= n then curIdx = -1 end
    else
        for i = 1, n do
            if entries[i].hash == curHash and entries[i].offset <= curMs then curIdx = i - 1 end
        end
    end
    local nextIdx = ((curIdx >= 0 and curIdx or 0) + dir) % n
    local e = entries[nextIdx + 1]
    if not e or e.hash == 0 then GUI.AddToast("VibeScript", "Next track hash invalid.", 3000); return end
    radioCtl.forceHash(station, stName, e.hash, radioCtl.loopActive(), e.offset, e.cat, e.coll,
        radioCtl.mixNext(e), e.user)
    radioCtl.retargetLoop(stName, e)
    radioCtl.broadcastToOthers(true)
    radioCtl.armResync(stName, e.hash, e.offset)
    GUI.AddToast("VibeScript", ("Song %d/%d"):format(nextIdx + 1, n), 2500)
end

function radioCtl.stepSong(dir)
    if not radioCtl.resolveTrack() then
        GUI.AddToast("VibeScript", "Could not resolve force-track.", 3000); return
    end
    if radioCtl.station and #radioCtl.tracks > 0 then
        local sf = FeatureMgr.GetFeature(H.RADIO_SONG)
        local n  = #radioCtl.tracks
        local stName = radioCtl.station
        local idx = (sf and sf:GetListIndex() or 0)
        if radioCtl.isUserStation(stName) and idx == radioCtl.auto.audSongIdx then
            local live = radioCtl.userActiveIdx(radioCtl.stationByName(stName))
            if live and live < n then idx = live end
        end
        local nextIdx = (idx + dir) % n
        local e = radioCtl.tracks[nextIdx + 1]
        radioCtl.tuneTo(stName)
        local station = radioCtl.stationByName(stName)
        if not plausiblePtr(station) then GUI.AddToast("VibeScript", "Station object not found.", 3000); return end
        radioCtl.forceHash(station, stName, e.hash, radioCtl.loopActive(), e.offset, e.cat, e.coll,
        radioCtl.mixNext(e), e.user)
        if sf then sf:SetListIndex(nextIdx) end
        radioCtl.retargetLoop(stName, e)
        radioCtl.broadcastToOthers(true)
        radioCtl.armResync(stName, e.hash, e.offset)
    else
        radioCtl.stepNoList(dir)
    end
end

function radioCtl.loopPlayerOnTick(f)
    local pid = f:GetPlayerIndex()
    if f:IsToggled() then radioCtl.pickerUsed = true end
    if not f:IsToggled() then radioCtl.plLoop[pid] = nil; return end
    if not isPlayerReady() then return end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then radioCtl.plLoop[pid] = nil; return end
    local st  = radioCtl.plLoop[pid]
    local now = Time.GetEpocheMs()
    if not st or not st.primed then
        local station, stName, e = radioCtl.playPicked(true)
        if not station then
            GUI.AddToast("VibeScript", "Pick a station and song first.", 3000)
            f:Toggle(); return
        end
        st = { primed = true, station = stName, hash = e.hash,
               offset = e.offset or 0, endMs = e.endMs, cat = e.cat, coll = e.coll,
               user = e.user,
               lastMs = ii(HASH.TRACK_TIME, stName) or 0, nextPollAt = now + 500 }
        radioCtl.plLoop[pid] = st
        if radioCtl.localOnlyStation(stName) then
            GUI.AddToast("VibeScript", ("Looping here only: %s does not reach other players.")
                :format(radioCtl.stationLabel(stName)), 4500)
            return
        end
        local ok, why = radioCtl.syncToOnePlayer(pid)
        radioCtl.armResync(stName, e.hash, e.offset, pid)
        if not ok then
            logf("[RadioLoopPlayer] player %d sync failed (%s)", pid, why)
            GUI.AddToast("VibeScript", "Could not sync to that player: " .. tostring(why), 4000)
        else
            GUI.AddToast("VibeScript", "Looping song for player.", 3000)
        end
        return
    end
    if now < st.nextPollAt then return end
    st.nextPollAt = now + 500
    radioCtl.loopPoll(st, true, pid)
end


function radioCtl.playNow()
    local station, stName, e = radioCtl.playPicked(radioCtl.loopActive())
    if not station then GUI.AddToast("VibeScript", "Pick a station and song first.", 3000); return end
    radioCtl.retargetLoop(stName, e)
    radioCtl.broadcastToOthers(true)
    radioCtl.armResync(stName, e.hash, e.offset)
end

function radioCtl.seekTo(req)
    if type(req) ~= "table" or not req.station or not req.hash or not req.offset then return end
    local pz = radioCtl.paused
    if pz then
        if pz.station ~= req.station or pz.hash ~= req.hash then return end
        local at = math.max(req.baseMs or 0, math.floor(req.offset))
        if req.endMs then at = math.min(at, req.endMs) end
        pz.offset = at
        return
    end
    local stName = is(HASH.PLAYER_STATION)
    local audHash = stName and ((ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF) or 0
    if stName ~= req.station or audHash ~= req.hash then
        GUI.AddToast("VibeScript", "Seek cancelled: the radio track changed.", 2500)
        return
    end
    local station = radioCtl.stationByName(stName)
    if not plausiblePtr(station) then
        GUI.AddToast("VibeScript", "Could not seek the current radio track.", 3000)
        return
    end
    if radioCtl.isUserStation(stName) then
        if req.user == nil or radioCtl.userActiveIdx(station) ~= req.user then
            GUI.AddToast("VibeScript", "Seek cancelled: the song changed.", 2500)
            return
        end
        radioCtl.userForce(req.user, radioCtl.loopActive(), math.floor(req.offset))
        return
    end
    local offset = math.max(req.baseMs or 0, math.floor(req.offset))
    if req.endMs then offset = math.min(offset, req.endMs) end

    local pp = radioPl and radioPl.play
    if pp and pp.active then
        if pp.station ~= stName or pp.hash ~= req.hash
                or (pp.offset or 0) ~= (req.baseMs or 0) then
            GUI.AddToast("VibeScript", "Seek cancelled: the playlist is changing songs.", 2500)
            return
        end
        if pp.stopMs and offset >= pp.stopMs then
            radioPl.advance()
            return
        end
    end

    radioCtl.forceHash(station, stName, req.hash, radioCtl.loopActive(), offset,
        (pp and pp.active) and pp.cat or req.cat,
        (pp and pp.active) and pp.coll or req.coll,
        radioCtl.mixNext({ mix = (req.baseMs or 0) > 0 or req.endMs ~= nil }))

    if pp and pp.active then
        local now = Time.GetEpocheMs()
        pp.armed, pp.seeking, pp.tries = false, true, 0
        pp.landOff, pp.forcedAt, pp.nextPollAt = offset, now, now
        pp.measure = false
        pp.lastMs = ii(HASH.TRACK_TIME, stName) or offset
    end

    local lp = radioCtl.loop
    if lp.primed and lp.station == stName and lp.hash == req.hash then
        lp.lastMs = ii(HASH.TRACK_TIME, stName) or offset
        lp.nextPollAt = Time.GetEpocheMs() + 500
    end
    radioCtl.broadcastToOthers(true)
    radioCtl.armResync(stName, req.hash, offset)
end

function radioCtl.memoTick(now)
    if radioCtl.paused then return end
    if now < (radioCtl.memoAt or 0) then return end
    radioCtl.memoAt = now + 100

    local live = is(HASH.PLAYER_STATION)
    if live == "" or live == "OFF" then live = nil end
    if live and radioCtl.memo[live] == nil then
        local h = (ii(HASH.TRACK_HASH, live) or 0) & 0xFFFFFFFF
        if h ~= 0 then
            radioCtl.memo[live] = { hash = h, ms = ii(HASH.TRACK_TIME, live) or 0, at = now }
        end
    end

    local n, oldName, oldAt = 0, nil, nil
    for stName, m in pairs(radioCtl.memo) do
        if now - m.at > 30000 then
            radioCtl.memo[stName] = nil
        else
            n = n + 1
            if oldAt == nil or m.at < oldAt then oldName, oldAt = stName, m.at end
            radioCtl.checkStation(stName, m, now, stName == live)
        end
    end
    if n > 8 and oldName then radioCtl.memo[oldName] = nil end
end

function radioCtl.checkStation(stName, m, now, audible)
    if radioCtl.isUserStation(stName) then return end
    local hash = (ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF
    if hash == 0 then return end
    local ms = ii(HASH.TRACK_TIME, stName) or 0
    if ms < 0 then return end

    if m.hash == hash and now > (radioCtl.forcedUntil or 0) then
        local projected = m.ms + (now - m.at)
        if ms + 3000 < projected then
            local pp = radioPl and radioPl.play
            local lp = radioCtl.loop
            local owned = (pp and pp.active and pp.station == stName)
                or (lp.primed and radioCtl.loopActive() and lp.station == stName)
            local station = not owned and radioCtl.stationByName(stName) or nil
            if plausiblePtr(station) then
                local dur = radioCtl.trackDurationMs(hash)
                local landed, rolling = projected, false
                if dur and projected >= dur then
                    landed, rolling = math.max(0, dur - 1500), true
                end
                local ui = radioCtl.ui
                local cat, coll
                if ui.seekStation == stName then cat, coll = ui.seekCat, ui.seekColl end
                logf("radio: %s restarted %08X at %d ms, expected %d -- snapping to %d%s (%s)",
                    stName, hash, ms, projected, landed,
                    rolling and " rolling over" or "", audible and "audible" or "background")
                radioCtl.forceHash(station, stName, hash, false, landed, cat, coll)
                if audible then
                    radioCtl.broadcastToOthers(true)
                    radioCtl.armResync(stName, hash, landed)
                end
                ms = landed
            end
        end
    end

    radioCtl.memo[stName] = { hash = hash, ms = ms, at = now }
end

function radioCtl.comboIdx(featureHash)
    local f = FeatureMgr.GetFeature(featureHash)
    return f and f:GetListIndex() or -1
end

function radioCtl.transportOwnsAudible()
    local ui = radioCtl.ui
    local pp = radioPl and radioPl.play
    if pp and pp.active then
        if not radioCtl.pickerIsPlaylist() then return false end
        local gf = FeatureMgr.GetFeature(H.RADIO_SONG)
        return gf ~= nil and (gf:GetListIndex() + 1) == pp.pos
    end
    if not ui.seekStation or not ui.seekHash then return false end
    if radioCtl.chosenStationName() ~= ui.seekStation then return false end
    local gf = FeatureMgr.GetFeature(H.RADIO_SONG)
    return gf ~= nil and radioCtl.auto.audSongIdx ~= nil
        and gf:GetListIndex() == radioCtl.auto.audSongIdx
end

radioCtl.paused = nil

function radioCtl.setPauseMuted(on, pz)
    if on then
        pz.frontendWasOff = louderRadio.frontendOff and true or false
        louderRadio.transportPaused = true
        if not pz.frontendWasOff then louderRadio.setFrontendRadio(false) end
        return
    end
    louderRadio.transportPaused = false
    if scriptUnloading or not pz then return end
    local f = FeatureMgr.GetFeature(H.LOUDER_RADIO)
    louderRadio.setFrontendRadio(not (f and f:IsToggled()))
end

function radioCtl.pauseNow()
    local stName = is(HASH.PLAYER_STATION)
    if not stName or stName == "" or stName == "OFF" then
        GUI.AddToast("VibeScript", "Nothing is playing to pause.", 2500)
        return false
    end
    local hash = (ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF
    if hash == 0 then
        GUI.AddToast("VibeScript", "Nothing is playing to pause.", 2500)
        return false
    end
    local pp = radioPl and radioPl.play
    local owned = pp and pp.active and pp.station == stName
    radioCtl.paused = {
        station = stName,
        hash    = hash,
        user    = radioCtl.isUserStation(stName)
                  and radioCtl.userActiveIdx(radioCtl.stationByName(stName)) or nil,
        offset  = ii(HASH.TRACK_TIME, stName) or 0,
        cat     = owned and pp.cat or nil,
        coll    = owned and pp.coll or nil,
        baseMs  = owned and (pp.offset or 0) or 0,
        endMs   = owned and pp.endMs or nil,
        stopMs  = owned and pp.stopMs or nil,
        playlist = owned and true or false,
        stIdx   = radioCtl.comboIdx(H.RADIO_STATION),
        songIdx = radioCtl.comboIdx(H.RADIO_SONG),
    }
    radioCtl.setPauseMuted(true, radioCtl.paused)
    return true
end

function radioCtl.resumePaused()
    local pz = radioCtl.paused
    radioCtl.paused = nil
    if not pz then return end
    local pp = radioPl and radioPl.play
    local station = radioCtl.stationByName(pz.station)
    if not plausiblePtr(station) then
        radioCtl.setPauseMuted(false, pz)
        if pz.playlist and pp and pp.active then radioPl.advance() end
        return
    end
    radioCtl.forceHash(station, pz.station, pz.hash, true,
        pz.offset, pz.cat, pz.coll, nil, pz.user)
    radioCtl.setPauseMuted(false, pz)
    if pz.playlist and pp and pp.active then
        local now = Time.GetEpocheMs()
        pp.armed, pp.seeking, pp.tries = false, true, 0
        pp.landOff, pp.forcedAt, pp.nextPollAt = pz.offset, now, now
        pp.measure = false
        pp.held = false
        pp.graceAt, pp.offSince = 0, 0
        pp.lastMs = ii(HASH.TRACK_TIME, pz.station) or pz.offset
    end
    radioCtl.broadcastToOthers(true)
    radioCtl.armResync(pz.station, pz.hash, pz.offset)
end

function radioCtl.voidPause(reason)
    if not radioCtl.paused then return end
    local pz = radioCtl.paused
    radioCtl.paused = nil
    radioCtl.setPauseMuted(false, pz)
    if reason then GUI.AddToast("VibeScript", reason, 2500) end
end

function radioCtl.push(action)
    radioCtl.pickerUsed = true
    radioCtl.pending[#radioCtl.pending + 1] = action
end

function radioCtl.setClocks(elapsedMs, lenMs)
    local ui = radioCtl.ui
    local es = elapsedMs // 1000
    if es < 0 then es = 0 end
    ui.line3 = radioCtl.fmtClock(es)
    if not lenMs then ui.line3R = ""; return end
    local rs = ((lenMs + 500) // 1000) - es
    if rs < 0 then rs = 0 end
    ui.line3R = "-" .. radioCtl.fmtClock(rs)
end

function radioCtl.fmtClock(sec)
    if sec < 0 then sec = 0 end
    return ("%d:%02d"):format(sec // 60, sec % 60)
end

function radioCtl.clockTick()
    local a = radioCtl.auto
    if radioCtl.paused then return end
    if not a.clkSt or not GUI.IsOpen() then return end
    if ((ii(HASH.TRACK_HASH, a.clkSt) or 0) & 0xFFFFFFFF) ~= a.clkHash then return end
    local ms = ii(HASH.TRACK_TIME, a.clkSt) or 0
    if ms < a.clkBase or (a.clkEnd and ms >= a.clkEnd) then return end
    radioCtl.setClocks(ms - a.clkBase,
        (a.clkEnd and a.clkEnd > a.clkBase) and (a.clkEnd - a.clkBase) or nil)
    local ui = radioCtl.ui
    if not ui.seekDragging and ui.seekHoldKey == nil and ui.seekStation == a.clkSt
            and ui.seekHash == a.clkHash and ui.seekEndMs then
        ui.seekValueMs = math.max(0,
            math.min(ui.seekEndMs - ui.seekBaseMs, ms - ui.seekBaseMs))
    end
end

function radioCtl.holdPausedReadout()
    local pz = radioCtl.paused
    if not pz or not GUI.IsOpen() then return end
    local ui = radioCtl.ui
    ui.line1 = radioCtl.stationLabel(pz.station) .. "   (paused)"
    local sameTrack = ui.seekStation == pz.station and ui.seekHash == pz.hash
                      and ui.seekEndMs
    local base = sameTrack and ui.seekBaseMs or (pz.baseMs or 0)
    local endMs = sameTrack and ui.seekEndMs or (pz.endMs or pz.stopMs)
    radioCtl.setClocks(pz.offset - base,
        (endMs and endMs > base) and (endMs - base) or nil)
    if not ui.seekDragging and sameTrack then
        ui.seekValueMs = math.max(0,
            math.min(ui.seekEndMs - ui.seekBaseMs, pz.offset - ui.seekBaseMs))
    end
end

function radioCtl.autoTick(now)
    local a = radioCtl.auto
    if now < a.nextAt then return end
    a.nextAt = now + 750
    if radioCtl.refreshStations() then a.stationIdx = -1 end

    local stName = is(HASH.PLAYER_STATION)
    local liveOn = stName and stName ~= "" and stName ~= "OFF"
    local audHash = 0
    if liveOn then audHash = (ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF end
    local playlistActive = radioPl and radioPl.play.active

    local watchMs = liveOn and (ii(HASH.TRACK_TIME, stName) or 0) or -1
    if liveOn and audHash ~= 0 and watchMs >= 0 and not radioCtl.isUserStation(stName) then
        local ms = watchMs
        if a.watchSt == stName and a.watchHash == audHash
                and ms + 2000 < (a.watchMs or 0) and now > (radioCtl.forcedUntil or 0) then
            logf("radio: %s restarted %08X (%d -> %d ms) with no force of ours pending",
                stName, audHash, a.watchMs, ms)
        end
        a.watchSt, a.watchHash, a.watchMs = stName, audHash, ms
    else
        a.watchSt = nil
    end

    if radioCtl.paused then
        local pz = radioCtl.paused
        if not liveOn or stName ~= pz.station then
            radioCtl.voidPause("Pause cleared: the radio station changed.")
        elseif radioCtl.comboIdx(H.RADIO_STATION) ~= pz.stIdx
                or radioCtl.comboIdx(H.RADIO_SONG) ~= pz.songIdx then
            radioCtl.voidPause("Pause cleared: the selection changed.")
        else
            radioCtl.holdPausedReadout()
            return
        end
    end

    local sf = FeatureMgr.GetFeature(H.RADIO_STATION)
    if not playlistActive and liveOn and audHash ~= 0
            and (stName ~= a.followSt or audHash ~= a.followHash) then
        a.followSt, a.followHash = stName, audHash
        if sf then
            for i, nm in ipairs(radioCtl.stations) do
                if nm == stName then
                    if sf:GetListIndex() ~= i - 1 then sf:SetListIndex(i - 1) end
                    break
                end
            end
        end
        a.snapSong = true
    end
    if not playlistActive and liveOn and radioCtl.isUserStation(stName) then
        local uidx = radioCtl.userActiveIdx(radioCtl.stationByName(stName))
        if uidx and uidx ~= a.followUser then a.followUser, a.snapSong = uidx, true end
    end

    local idx = sf and sf:GetListIndex() or -1
    local usrMoved = radioCtl.isUserStation(radioCtl.station)
        and #(radioCtl.userTracks() or {}) ~= #radioCtl.tracks
    if idx ~= a.stationIdx or not a.titlesReady or usrMoved then
        a.stationIdx = idx
        a.titlesReady = radioCtl.loadSongs()
    end

    if not playlistActive and a.snapSong and liveOn and radioCtl.station == stName then
        a.snapSong = false
        local gf = FeatureMgr.GetFeature(H.RADIO_SONG)
        if gf then
            local ms, hit = ii(HASH.TRACK_TIME, stName) or 0, nil
            if radioCtl.isUserStation(stName) then
                hit = a.followUser
            else
                for i, e in ipairs(radioCtl.tracks) do
                    if e.hash == a.followHash and e.offset <= ms then hit = i - 1 end
                end
            end
            if hit then gf:SetListIndex(hit); a.audSongIdx = hit end
        end
    end

    if not GUI.IsOpen() then return end
    local ui = radioCtl.ui
    if not liveOn then
        ui.line1, ui.line2, ui.line3, ui.line3R = "Radio off", "", "", ""
        a.clkSt = nil
        ui.seekKey, ui.seekStation, ui.seekEndMs = nil, nil, nil
        ui.seekDragging, ui.seekValueMs, ui.seekReadOnly = false, 0, false
        ui.seekUser, ui.seekHoldKey = nil, nil
    else
        ui.line1 = radioCtl.stationLabel(stName)
        local ms = ii(HASH.TRACK_TIME, stName) or 0
        local base, nextAt = 0, nil
        local usrTitle, usrDur, usrIdx
        if radioCtl.isUserStation(stName) then
            usrTitle, usrDur, usrIdx = radioCtl.userNowPlaying()
        end
        if usrTitle then
            ui.line2 = usrTitle
        elseif audHash ~= 0 and radioCtl.resolveTrack() then
            local id
            local pairsFor = radioCtl.trackTextIds(audHash, radioCtl.trackDurationMs(audHash))
            if pairsFor then
                for _, p in ipairs(pairsFor) do
                    if p.offset <= ms then id, base = p.id, p.offset
                    else nextAt = p.offset; break end
                end
            end
            local song, artist
            if id then song, artist = radioCtl.songPartsForId(id) end
            if not song then
                song, artist = radioCtl.songParts(audHash)
                base, nextAt = 0, nil
            end
            ui.line2 = song and (artist and (song .. " - " .. artist) or song) or "(no track title)"
        else
            ui.line2 = ""
        end
        local endAt = nextAt
        if usrTitle then
            endAt = usrDur
        elseif not endAt and audHash ~= 0 then
            endAt = radioCtl.trackDurationMs(audHash)
        end
        radioCtl.setClocks(ms - base, (endAt and endAt > base) and (endAt - base) or nil)
        a.clkSt, a.clkHash, a.clkBase, a.clkEnd = stName, audHash, base, endAt

        local seekEntry, seekIdx
        if usrIdx then
            seekIdx = usrIdx
        elseif radioCtl.station == stName then
            for i, e in ipairs(radioCtl.tracks) do
                if e.hash == audHash and e.offset <= ms
                        and (not e.endMs or ms < e.endMs)
                        and (not seekEntry or e.offset > seekEntry.offset) then
                    seekEntry, seekIdx = e, i - 1
                end
            end
        end
        a.audSongIdx = seekIdx
        local seekBase = seekEntry and (seekEntry.offset or 0) or base
        local seekEnd  = seekEntry and (seekEntry.endMs
            or radioCtl.trackDurationMs(audHash)) or endAt
        local seekCat  = seekEntry and seekEntry.cat or 2
        local seekColl = seekEntry and seekEntry.coll or MUSIC_COLL
        local pp = radioPl and radioPl.play
        if pp and pp.active and pp.station == stName and pp.hash == audHash then
            seekBase, seekEnd = pp.offset or 0, pp.stopMs
            seekCat, seekColl = pp.cat or 2, pp.coll or MUSIC_COLL
        end
        ui.seekReadOnly = radioCtl.isUserStation(stName) and usrIdx == nil
        ui.seekUser = usrIdx
        if seekEnd and seekEnd > seekBase then
            local key = stName .. ":" .. tostring(audHash) .. ":" .. tostring(seekIdx)
                .. ":" .. tostring(seekBase) .. ":" .. tostring(seekEnd)
            if ui.seekKey ~= key then ui.seekDragging = false end
            ui.seekKey, ui.seekStation, ui.seekHash = key, stName, audHash
            ui.seekBaseMs, ui.seekEndMs = seekBase, seekEnd
            ui.seekCat, ui.seekColl = seekCat, seekColl
            if ui.seekHoldKey == ui.seekKey then
                if ui.seekHoldUntil == nil then ui.seekHoldUntil = now + 2500 end
                local held = math.max(0, math.min(seekEnd - seekBase, ui.seekHoldValue or 0))
                local live = math.max(0, math.min(seekEnd - seekBase, ms - seekBase))
                if now > ui.seekHoldUntil or math.abs(live - held) < 3000 then
                    ui.seekHoldKey = nil
                    ui.seekValueMs = live
                else
                    ui.seekValueMs = held
                end
            elseif not ui.seekDragging then
                ui.seekValueMs = math.max(0, math.min(seekEnd - seekBase, ms - seekBase))
            end
        else
            ui.seekKey, ui.seekStation, ui.seekEndMs = nil, nil, nil
            ui.seekDragging, ui.seekValueMs = false, 0
        end
    end
    local picked = radioCtl.chosenStationName()
    if radioCtl.station and not a.titlesReady then
        ui.status = "Loading song titles..."
    elseif radioCtl.loop.primed and radioCtl.loopActive() then
        ui.status = "Looping for the session."
    else
        ui.status = ""
    end
end

function radioCtl.janitorOnTick(f)
    if scriptUnloading then return end
    radioCtl.userTick(Time.GetEpocheMs())
    local left = (radioCtl.jSkip or 0) - 1
    if left > 0 and #radioCtl.pending == 0 and #radioCtl.dumpQueue == 0
            and not (radioPl and #radioPl.pending > 0) then
        radioCtl.jSkip = left
        return
    end
    radioCtl.jSkip = 8
    for pid, st in pairs(radioCtl.plBus) do
        if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            if st.handle and st.handle ~= 0 then louderRadio.deleteBus(st.handle) end
            radioCtl.plBus[pid] = nil
        end
    end
    for pid in pairs(radioCtl.plLoop) do
        if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then radioCtl.plLoop[pid] = nil end
    end
    if #radioCtl.pending > 0 then
        local acts = radioCtl.pending
        radioCtl.pending = {}
        for _, act in ipairs(acts) do
            local playlistActive = radioPl and radioPl.play.active
            if radioCtl.paused and act ~= "resume" and act ~= "dumpall"
                    and not (type(act) == "table" and act.kind == "seek") then
                radioCtl.voidPause(nil)
            end
            if act == "pause" then
                radioCtl.pauseNow()
            elseif act == "resume" then
                radioCtl.resumePaused()
            elseif act == "prev" then
                if playlistActive then radioPl.previous() else radioCtl.stepSong(-1) end
            elseif act == "next" then
                if playlistActive then radioPl.advance() else radioCtl.stepSong(1) end
            elseif act == "play" then
                if playlistActive and radioCtl.pickerIsPlaylist() then
                    radioPl.playPickerSelection()
                elseif playlistActive then
                    local picked = radioCtl.chosenStationName()
                    if picked then
                        radioCtl.loadSongs()
                        if radioCtl.station == picked and #radioCtl.tracks > 0 then
                            radioPl.stop(nil)
                            radioCtl.playNow()
                        else
                            GUI.AddToast("VibeScript", "That station's songs are still loading.", 2500)
                        end
                    else
                        GUI.AddToast("VibeScript", "Pick a normal station and song first.", 2500)
                    end
                else
                    radioCtl.playNow()
                end
            elseif act == "dumpall" then
                radioCtl.queueDumpAll()
            elseif type(act) == "table" and act.kind == "seek" then radioCtl.seekTo(act)
            end
        end
    end
    local now = Time.GetEpocheMs()
    local rs = radioCtl.resync
    if rs and not radioCtl.paused and now >= rs.nextAt then
        local hash = (ii(HASH.TRACK_HASH, rs.station) or 0) & 0xFFFFFFFF
        local ms = ii(HASH.TRACK_TIME, rs.station) or -1
        local elapsed = now - rs.armedAt
        local landed = hash == rs.hash and ms >= rs.offset - 500
            and ms <= rs.offset + elapsed + 1500
        if landed then
            radioCtl.resync = nil
            if rs.pid then
                local ok, why = radioCtl.syncToOnePlayer(rs.pid)
                if not ok then logf("radio sync: player %d re-send failed (%s)", rs.pid, why) end
            else
                pcall(radioCtl.broadcastToOthers, true)
            end
        elseif now >= rs.deadline then
            radioCtl.resync = nil
            logf("radio sync: force did not land on %s hash=%08X offset=%d (got %08X @ %d)",
                rs.station, rs.hash, rs.offset, hash, ms)
        else
            rs.nextAt = now + 100
        end
    end
    if #radioCtl.dumpQueue > 0 then radioCtl.dumpNext() end
    pcall(radioCtl.syncWatchTick, now)
    radioCtl.memoTick(now)
    radioCtl.autoTick(now)
    radioCtl.clockTick()
    if radioPl then radioPl.onTick(now) end
end

function radioCtl.syncWatchTick(now)
    local w = radioCtl.syncWatch
    if not radioCtl.autoSyncActive() then
        w.station, w.hash = nil, nil
        return
    end
    if radioCtl.paused or radioCtl.resync then w.station, w.hash = nil, nil return end
    local pp = radioPl and radioPl.play
    local stName = (pp and pp.active and pp.station) or is(HASH.PLAYER_STATION)
    if not stName or stName == "" or stName == "OFF" then w.station, w.hash = nil, nil return end
    if radioCtl.localOnlyStation(stName) then w.station, w.hash = nil, nil return end
    if pp and pp.active and not pp.armed then w.station, w.hash = nil, nil return end
    local hash = (ii(HASH.TRACK_HASH, stName) or 0) & 0xFFFFFFFF
    if hash == 0 then return end
    local changed = (w.station ~= stName or w.hash ~= hash)
    w.station, w.hash = stName, hash
    if changed and not w.primed then w.primed = true return end
    local since = now - (radioCtl.lastSyncAt or 0)
    if changed then
        if since < radioCtl.SYNC_CHANGE_MIN_MS then return end
        logf("radio sync: %s moved to %08X on its own; re-sending", stName, hash)
    elseif since < radioCtl.SYNC_HEARTBEAT_MS then
        return
    end
    radioCtl.broadcastToOthers(true)
end

function radioCtl.cleanupAll()
    radioCtl.voidPause(nil)
    radioCtl.resync = nil
    radioCtl.usbRestore()
    radioCtl.usr.want = nil
    radioCtl.userModeRestore()
    louderRadio.transportPaused = false
    for _, st in pairs(radioCtl.plBus) do
        if st.handle and st.handle ~= 0 then louderRadio.deleteBus(st.handle) end
    end
    radioCtl.plBus = {}
    radioCtl.plLoop = {}
    radioCtl.loop.primed = false
    if radioPl then radioPl.stop(nil) end
end

function radioCtl.unloadMemoryCleanup()
    radioCtl.usbRestore()
    radioCtl.usr.want = nil
    local track = radioCtl.track
    if track.sndScratch and track.sndScratch ~= 0 then
        Memory.Free(track.sndScratch)
        track.sndScratch = nil
        track.sndFn = nil
        track.sndDecFn = nil
    end
end


FeatureMgr.AddFeature(H.RADIO_STATION, "Station", eFeatureType.Combo,
    "Radio station. Songs load automatically. While a playlist runs, browsing a station is harmless until Play is pressed.")
    :SetList(radioCtl.stationNames)
    :SetSaveable(false)
FeatureMgr.AddFeature(H.RADIO_SONG, "Song", eFeatureType.Combo, "Song to play.", function(f)
    if radioPl and radioPl.play.active then return end
    local e = radioCtl.tracks[(f:GetListIndex() or 0) + 1]
    if not e then return end
    local function moved(t) return t.hash ~= e.hash or t.user ~= e.user end
    local primed = radioCtl.loop.primed and moved(radioCtl.loop)
    if not primed then
        for _, st in pairs(radioCtl.plLoop) do
            if st.primed and moved(st) then primed = true; break end
        end
    end
    if primed then radioCtl.push("play") end
end)
    :SetList(radioCtl.songNames)
    :SetSaveable(false)
centralOnTick(FeatureMgr.AddFeature(H.RADIO_LOOP, "Loop Song", eFeatureType.Toggle,
    "Keep replaying the picked song, re-syncing the whole session each time it restarts.",
    radioCtl.loopSelfOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
FeatureMgr.AddFeature(H.RADIO_AUTO_SYNC, "Auto Sync", eFeatureType.Toggle,
    "Enable syncing your radio to the entire lobby. Without this on, they will hear different songs when you change the radio manually.")
    :SetSaveable(false)
FeatureMgr.GetFeature(H.RADIO_AUTO_SYNC):Toggle(true)

function radioCtl.renderPanel()
    local ui = radioCtl.ui
    ImGui.Text("Now playing")
    ImGui.Text("  " .. (ui.line1 ~= "" and ui.line1 or "..."))
    if ui.line2 ~= "" then ImGui.Text("  " .. ui.line2) end
    if ui.seekEndMs and ui.seekEndMs > ui.seekBaseMs then
        local totalMs = ui.seekEndMs - ui.seekBaseMs
        local posMs = math.max(0, math.min(totalMs, ui.seekValueMs or 0))
        ImGui.SetNextItemWidth(-1)
        if ui.seekReadOnly then
            ImGui.SliderFloat("##radio_seek", posMs / 1000, 0, totalMs / 1000, "", 1)
            if ImGui.IsItemHovered() then
                ImGui.SetTooltip("Self Radio is between files -- this is the station's own advert or ident.")
            end
        else
            local seconds, changed = ImGui.SliderFloat("##radio_seek", posMs / 1000,
                0, totalMs / 1000, "", 1)
            if ImGui.IsItemActivated() then
                ui.seekDragging, ui.seekDragKey = true, ui.seekKey
            end
            if changed then
                ui.seekDragging = true
                ui.seekDragKey = ui.seekDragKey or ui.seekKey
                ui.seekValueMs = math.floor(seconds * 1000 + 0.5)
            end
            if ImGui.IsItemDeactivatedAfterEdit() then
                ui.seekDragging = false
                if ui.seekDragKey == ui.seekKey then
                    radioCtl.push({
                        kind = "seek", station = ui.seekStation, hash = ui.seekHash,
                        baseMs = ui.seekBaseMs, endMs = ui.seekEndMs,
                        offset = ui.seekBaseMs + ui.seekValueMs,
                        cat = ui.seekCat, coll = ui.seekColl, user = ui.seekUser,
                    })
                    ui.seekHoldKey, ui.seekHoldValue = ui.seekKey, ui.seekValueMs
                    ui.seekHoldUntil = nil
                end
                ui.seekDragKey = nil
            elseif ImGui.IsItemDeactivated() then
                ui.seekDragging, ui.seekDragKey = false, nil
            end
            if ui.seekDragging then
                ImGui.SetTooltip(radioCtl.fmtClock(
                    math.max(0, math.min(totalMs, ui.seekValueMs or 0)) // 1000))
            elseif ImGui.IsItemHovered() then
                ImGui.SetTooltip("Drag to preview; the radio seeks once when you release.")
            end
        end
    else
        ImGui.TextDisabled("Seek unavailable")
    end

    local x0, availW = ImGui.GetCursorPosX(), ImGui.GetContentRegionAvail()
    local inset = ImGui.CalcTextSize("  ") or 0
    local transportW = 40 + 70 + 40 + 16
    ImGui.AlignTextToFramePadding()
    ImGui.Text("  " .. (ui.line3 ~= "" and ui.line3 or "0:00"))
    ImGui.SameLine()
    ImGui.SetCursorPosX(x0 + math.max(0, (availW - transportW) * 0.5))
    if ImGui.Button("<<##radio", 40, 0) then radioCtl.push("prev") end
    ImGui.SameLine()
    if radioCtl.paused then
        if ImGui.Button("Play##radio", 70, 0) then radioCtl.push("resume") end
    elseif radioCtl.transportOwnsAudible() then
        if ImGui.Button("Pause##radio", 70, 0) then radioCtl.push("pause") end
    else
        if ImGui.Button("Play##radio", 70, 0) then radioCtl.push("play") end
    end
    ImGui.SameLine()
    if ImGui.Button(">>##radio", 40, 0) then radioCtl.push("next") end
    if ui.line3R ~= "" and availW then
        local w = ImGui.CalcTextSize(ui.line3R) or 0
        ImGui.SameLine()
        ImGui.SetCursorPosX(x0 + availW - w - inset)
        ImGui.Text(ui.line3R)
    end
    ImGui.Separator()
    ClickGUI.RenderFeature(H.RADIO_STATION)
    ClickGUI.RenderFeature(H.RADIO_SONG)
    ClickGUI.RenderFeature(H.RADIO_AUTO_SYNC)
    ImGui.SameLine()
    ClickGUI.RenderFeature(H.RADIO_LOOP)
    if ui.status ~= "" then
        ImGui.Separator()
        ImGui.Text(ui.status)
    end
    if radioPl then radioPl.renderPanel() end
end



centralOnTick(FeatureMgr.AddFeature(H.RADIO_JANITOR, "##RadioJanitor", eFeatureType.Toggle, "",
    radioCtl.janitorOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
    :SetSearchable(false)
    :SetVisible(false)
FeatureMgr.GetFeature(H.RADIO_JANITOR):Toggle(true)

end)()

;(function()

local ii = function(h, ...) return Natives.InvokeInt(h, ...) end
local is = function(h, ...) return Natives.InvokeString(h, ...) end
local ib = function(h, ...) return Natives.InvokeBool(h, ...) end

local PLAYER_STATION = 0xF6D733C32076AD03
local TRACK_HASH     = 0x34D66BC058019CE0
local TRACK_TIME     = 0x3E65CDE5215832C1
local RETUNING       = 0xA151A7394A214E65

local PL_DIR  = FileMgr.GetMenuRootPath() .. "\\lua\\VibeScript"
local PL_FILE = PL_DIR .. "\\radio_playlists.cfg"

local POLL_MS   = 400
local ARM_MS    = 4000
local ARM_TRIES = 3
local GRACE_MS  = 10000
local OFF_DEBOUNCE_MS = 500
local LEAD_MIN  = 250
local LEAD_MAX  = 2000
local ARM_WINDOW  = 8000
local ADOPT_MS  = 2000
local ARM_RETRY_MS = 800
local MIN_PLAY_MS = 3000
local ACQUIRE_SETTLE_MS = 500
local ACQUIRE_RETRY_MS  = 500
local ACQUIRE_TIMEOUT_MS = 4000

radioPl = {
    lists    = {},
    sel      = 1,
    confirmDelete = nil,
    status   = "",
    openRequest = false, popupVisible = false,
    browse = { want = nil, station = nil, cache = {}, songIdx = 0, nextAt = 0 },
    pending = {},
    play = { active = false, listIdx = 0, shuffle = false, order = {}, pos = 0,
             station = nil, hash = 0, offset = 0, endMs = nil, title = "", artist = "",
             armed = false, tries = 0, forcedAt = 0, lastMs = 0, nextPollAt = 0,
             held = false, graceAt = 0, offSince = 0,
             acquireUntil = 0, acquireNextAt = 0, acquireSeenAt = 0,
             stopMs = nil, measure = false, landOff = 0, armedAt = 0,
             seeking = false },
    leadMs = 900,
}

function radioPl.sanitize(s)
    return (tostring(s or ""):gsub("[\t\r\n]", " "):gsub("^%s+", ""):gsub("%s+$", ""))
end

function radioPl.save()
    local lines = { "V\t4" }
    for _, pl in ipairs(radioPl.lists) do
        lines[#lines + 1] = "P\t" .. radioPl.sanitize(pl.name)
        for _, t in ipairs(pl.tracks) do
            lines[#lines + 1] = ("T\t%s\t%d\t%d\t%d\t%s\t%s\t%d\t%d"):format(
                t.station, t.hash, t.offset or 0, t.endMs or -1,
                radioPl.sanitize(t.song), radioPl.sanitize(t.artist), t.cat or 2,
                t.user or -1)
        end
    end
    FileMgr.CreateDir(PL_DIR)
    local ok = FileMgr.WriteFileContent(PL_FILE, table.concat(lines, "\n"), false)
    radioPl.status = ok and "Saved." or "Save failed."
    return ok
end

function radioPl.load()
    if not FileMgr.DoesFileExist(PL_FILE) then return end
    local ok, lists, skipped = pcall(function()
        local content = FileMgr.ReadFileContent(PL_FILE)
        if not content or content == "" then return nil end
        local lists, cur, skipped = {}, nil, 0
        for line in content:gmatch("[^\r\n]+") do
            local kind, rest = line:match("^(%a)\t(.*)$")
            if kind == "V" then
            elseif kind == "P" then
                cur = { name = rest, tracks = {} }
                lists[#lists + 1] = cur
            elseif kind == "T" and cur then
                local f = {}
                for part in (rest .. "\t"):gmatch("([^\t]*)\t") do f[#f + 1] = part end
                local st, h = f[1], tonumber(f[2] or "")
                if st and st ~= "" and h then
                    local rec = { station = st, hash = h & 0xFFFFFFFF, offset = 0, endMs = nil }
                    if #f >= 6 then
                        rec.offset = tonumber(f[3]) or 0
                        local e = tonumber(f[4]) or -1
                        rec.endMs = (e >= 0) and e or nil
                        rec.song, rec.artist = f[5] or "", f[6] or ""
                        rec.cat = tonumber(f[7]) or 2
                        local uf = tonumber(f[8])
                        rec.user = (uf and uf >= 0) and uf or nil
                    else
                        rec.song, rec.artist = f[3] or "", f[4] or ""
                        rec.cat = 2
                    end
                    rec.coll = radioCtl.collForCat(rec.cat)
                    cur.tracks[#cur.tracks + 1] = rec
                else
                    skipped = skipped + 1
                end
            else
                skipped = skipped + 1
            end
        end
        return lists, skipped
    end)
    if not ok then
        radioPl.status = "Playlist file is malformed; not loaded."
        logErr("Radio playlist file is malformed; not loaded: " .. tostring(lists),
            logging.BROKEN_FILE_TOAST_MS)
        return
    end
    if lists then radioPl.lists = lists end
    if (skipped or 0) > 0 then
        radioPl.status = ("%d unreadable line(s) skipped."):format(skipped)
        logErr(("Radio playlist: %d unreadable line(s) skipped; the rest loaded.")
            :format(skipped), logging.BROKEN_FILE_TOAST_MS)
    end
end


function radioPl.current()
    return radioPl.lists[radioPl.sel]
end

function radioPl.newList()
    radioPl.lists[#radioPl.lists + 1] = { name = "Playlist " .. (#radioPl.lists + 1), tracks = {} }
    radioPl.sel = #radioPl.lists
    radioPl.save()
end

function radioPl.duplicateList()
    local pl = radioPl.current()
    if not pl then return end
    local copy = { name = pl.name .. " Copy", tracks = {} }
    for i, t in ipairs(pl.tracks) do
        copy.tracks[i] = { station = t.station, hash = t.hash, offset = t.offset, endMs = t.endMs,
                           cat = t.cat, coll = t.coll, song = t.song, artist = t.artist }
    end
    radioPl.lists[#radioPl.lists + 1] = copy
    radioPl.sel = #radioPl.lists
    radioPl.save()
end

function radioPl.deleteList()
    if not radioPl.current() then return end
    if radioPl.play.active and radioPl.play.listIdx == radioPl.sel then
        radioPl.stop("Playlist deleted.")
    elseif radioPl.play.active and radioPl.play.listIdx > radioPl.sel then
        radioPl.play.listIdx = radioPl.play.listIdx - 1
    end
    table.remove(radioPl.lists, radioPl.sel)
    radioPl.sel = math.max(1, math.min(radioPl.sel, #radioPl.lists))
    radioPl.save()
end

function radioPl.findTrack(pl, station, e)
    for i, t in ipairs(pl.tracks) do
        if t.station == station and t.hash == e.hash
                and (t.offset or 0) == (e.offset or 0) and t.user == e.user then
            return i
        end
    end
    return nil
end

function radioPl.entryTitle(e)
    if e.user then return ("Untitled file %d"):format(e.user + 1) end
    return ("0x%08X"):format(e.hash or 0)
end

function radioPl.userIndexFor(entry)
    local tracks = radioCtl.userTracks()
    if not tracks then return nil end
    local song = (entry.song or ""):lower()
    if song ~= "" then
        local artist = (entry.artist or ""):lower()
        for i, t in ipairs(tracks) do
            if (t.title or ""):lower() == song and (t.artist or ""):lower() == artist then
                return i - 1
            end
        end
    end
    if entry.user and tracks[entry.user + 1] then return entry.user end
    return nil
end

function radioPl.addTrack(station, e, song, artist)
    local pl = radioPl.current()
    if not pl or not station or not e then return false end
    if radioPl.findTrack(pl, station, e) then
        radioPl.status = "Already in this playlist."
        return false
    end
    pl.tracks[#pl.tracks + 1] = { station = station, hash = e.hash,
                                  offset = e.offset or 0, endMs = e.endMs,
                                  cat = e.cat or 2, coll = e.coll, user = e.user,
                                  song = radioPl.sanitize(song), artist = radioPl.sanitize(artist) }
    radioPl.save()
    return true
end

function radioPl.ptrOK(ptr)
    return ptr ~= nil and ptr > 0x10000 and ptr < 0x7FFFFFFFFFFF
end

function radioPl.addResolved(pl, stName, e, song, artist)
    local title = (song and song ~= "") and song or radioPl.entryTitle(e)
    if radioPl.addTrack(stName, e, song, artist) then
        GUI.AddToast("VibeScript", ("Added %s to %s."):format(title, pl.name), 3500)
    else
        GUI.AddToast("VibeScript", ("%s is already in %s."):format(title, pl.name), 3500)
    end
end

function radioPl.addPlaying()
    local pl = radioPl.current()
    if not pl then
        GUI.AddToast("VibeScript", "Make a playlist first.", 3000); return
    end
    local p = radioPl.play
    if p.active and p.station and p.hash ~= 0 then
        radioPl.addResolved(pl, p.station, { hash = p.hash, offset = p.offset,
            endMs = p.endMs, cat = p.cat, coll = p.coll, user = p.user },
            p.title, p.artist)
        return
    end
    if not radioCtl.resolveTrack() then
        GUI.AddToast("VibeScript", "Could not resolve force-track.", 3000); return
    end
    local stName = is(PLAYER_STATION)
    if not stName or stName == "" or stName == "OFF" then
        stName = (louderRadio and louderRadio.station) or radioCtl.station
    end
    if not stName or stName == "" or stName == "OFF" then
        GUI.AddToast("VibeScript", "No station to read a song from.", 3000); return
    end
    local station = radioCtl.stationByName(stName)
    if not radioPl.ptrOK(station) then
        GUI.AddToast("VibeScript", "Station object not found.", 3000); return
    end
    local entries = radioCtl.stationEntries(station)
    if not entries then
        GUI.AddToast("VibeScript", "Station has no track list.", 3000); return
    end
    local hash = (ii(TRACK_HASH, stName) or 0) & 0xFFFFFFFF
    local ms   = ii(TRACK_TIME, stName) or 0
    local hit
    if radioCtl.isUserStation(stName) then
        local u = radioCtl.userActiveIdx(station)
        hit = u and entries[u + 1] or nil
    else
        for _, e in ipairs(entries) do
            if e.hash == hash and (e.offset or 0) <= ms then hit = e end
        end
    end
    if not hit then
        GUI.AddToast("VibeScript", "Could not identify the current song.", 3000); return
    end
    local song, artist = radioCtl.songPartsForEntry(hit)
    radioPl.addResolved(pl, stName, hit, song, artist)
end

function radioPl.moveTrack(i, dir)
    local pl = radioPl.current()
    if not pl then return end
    local j = i + dir
    if j < 1 or j > #pl.tracks then return end
    pl.tracks[i], pl.tracks[j] = pl.tracks[j], pl.tracks[i]
    radioPl.save()
end

function radioPl.removeTrack(i)
    local pl = radioPl.current()
    if not pl or not pl.tracks[i] then return end
    table.remove(pl.tracks, i)
    radioPl.save()
end


function radioPl.fulfilBrowse(now)
    local want = radioPl.browse.want
    if not want or now < radioPl.browse.nextAt then return end
    radioPl.browse.nextAt = now + 500
    local hit = radioPl.browse.cache[want]
    if hit and hit.titled then radioPl.browse.want = nil; radioPl.browse.station = want; return end
    local station = radioCtl.stationByName(want)
    if not station then radioPl.browse.want = nil; return end
    local entries = radioCtl.stationEntries(station)
    if not entries then radioPl.browse.want = nil; return end
    local entry = { entries = entries, labels = {}, songs = {}, artists = {}, titled = true }
    for i, e in ipairs(entries) do
        local song, artist = radioCtl.songPartsForEntry(e)
        entry.songs[i], entry.artists[i] = song or "", artist or ""
        if song then
            entry.labels[i] = artist and (song .. "  -  " .. artist) or song
        elseif e.user then
            entry.labels[i] = ("Untitled file %d"):format(e.user + 1)
        else
            entry.labels[i] = ("(0x%08X)"):format(e.hash)
            entry.titled = false
        end
    end
    local dupes = {}
    for _, lbl in ipairs(entry.labels) do dupes[lbl] = (dupes[lbl] or 0) + 1 end
    for i, e in ipairs(entries) do
        local off = e.offset or 0
        if dupes[entry.labels[i]] > 1 and off > 0 then
            entry.labels[i] = ("%s  [%d:%02d]"):format(entry.labels[i], off // 60000, (off // 1000) % 60)
        end
    end
    radioPl.browse.cache[want] = entry
    radioPl.browse.station = want
    if entry.titled then radioPl.browse.want = nil end
end


function radioPl.shuffleOrder(n)
    local order = {}
    for i = 1, n do order[i] = i end
    for i = n, 2, -1 do
        local j = math.random(i)
        order[i], order[j] = order[j], order[i]
    end
    return order
end

function radioPl.syncPicker(selectPlaylist)
    local p = radioPl.play
    if not p.active then return true end
    local pl = radioPl.lists[p.listIdx]
    if not pl then return true end

    local sf = FeatureMgr.GetFeature(H.RADIO_STATION)
    if selectPlaylist then
        radioCtl.refreshStations()
        if sf then
            for i, nm in ipairs(radioCtl.stations) do
                if nm == radioCtl.playlistSentinel then
                    sf:SetListIndex(i - 1)
                    radioCtl.auto.stationIdx = i - 1
                    break
                end
            end
        end
    end
    if not radioCtl.pickerIsPlaylist() then return true end

    local labels = {}
    for queuePos, trackIdx in ipairs(p.order) do
        local e = pl.tracks[trackIdx]
        local title
        if e then
            title = (e.song and e.song ~= "") and e.song or radioPl.entryTitle(e)
            if e.artist and e.artist ~= "" then title = title .. " - " .. e.artist end
        else
            title = "(missing entry)"
        end
        labels[queuePos] = ("%02d  %s"):format(queuePos, title)
    end
    if #labels == 0 then labels[1] = "(empty playlist)" end
    radioCtl.songNames = labels
    local gf = FeatureMgr.GetFeature(H.RADIO_SONG)
    if gf then
        gf:SetList(labels)
        gf:SetListIndex(math.max(0, math.min(#labels - 1, p.pos - 1)))
    end
    radioCtl.auto.titlesReady = true
    return true
end

function radioPl.start(shuffle)
    local pl = radioPl.current()
    if not pl or #pl.tracks == 0 then
        GUI.AddToast("VibeScript", "That playlist is empty.", 3000); return
    end
    if not radioCtl.resolveTrack() then
        GUI.AddToast("VibeScript", "Could not resolve force-track.", 3000); return
    end
    local lf = FeatureMgr.GetFeature(H.RADIO_LOOP)
    if lf and lf:IsToggled() then lf:Toggle() end
    radioCtl.pickerUsed = true
    local p = radioPl.play
    p.active, p.listIdx, p.shuffle = true, radioPl.sel, shuffle and true or false
    p.seeking = false
    p.held, p.graceAt, p.offSince = false, 0, 0
    p.acquireUntil, p.acquireNextAt, p.acquireSeenAt = 0, 0, 0
    p.order = shuffle and radioPl.shuffleOrder(#pl.tracks) or (function()
        local o = {}; for i = 1, #pl.tracks do o[i] = i end; return o
    end)()
    p.pos = 0
    radioPl.advance()
    radioPl.syncPicker(true)
end

function radioPl.stop(reason)
    local p = radioPl.play
    if not p.active then return end
    p.active, p.station, p.hash, p.title, p.artist = false, nil, 0, "", ""
    p.offset, p.endMs, p.stopMs, p.measure = 0, nil, nil, false
    p.user, p.userStation = nil, nil
    p.landOff, p.armedAt = 0, 0
    p.seeking = false
    p.held, p.graceAt, p.offSince = false, 0, 0
    p.acquireUntil, p.acquireNextAt, p.acquireSeenAt = 0, 0, 0
    local a = radioCtl.auto
    a.nextAt, a.stationIdx, a.followSt, a.followHash = 0, -1, nil, 0
    a.snapSong, a.titlesReady = false, false
    if reason then GUI.AddToast("VibeScript", reason, 3500) end
end

function radioPl.peekNext()
    local p  = radioPl.play
    local pl = radioPl.lists[p.listIdx]
    if not pl or #p.order == 0 then return nil end
    local n = p.pos + 1
    if n > #p.order then n = 1 end
    return pl.tracks[p.order[n]]
end

function radioPl.nextSlot(stName)
    local nx = radioPl.peekNext()
    if nx and nx.station == stName and (nx.offset or 0) == 0 then
        return { hash = nx.hash, cat = nx.cat, coll = nx.coll }
    end
    return nil
end

function radioPl.advance(skips, toastPrefix)
    local p  = radioPl.play
    local pl = radioPl.lists[p.listIdx]
    if not pl or #pl.tracks == 0 then radioPl.stop("Playlist is empty."); return end
    skips = skips or 0
    if skips > #p.order then radioPl.stop("No playable songs in that playlist."); return end

    p.pos = p.pos + 1
    if p.pos > #p.order then
        p.pos = 1
    end
    local entry = pl.tracks[p.order[p.pos]]
    if not entry then return radioPl.advance(skips + 1, toastPrefix) end

    local station = radioCtl.stationByName(entry.station)
    if not station then return radioPl.advance(skips + 1, toastPrefix) end

    local uidx = nil
    if radioCtl.isUserStation(entry.station) then
        uidx = radioPl.userIndexFor(entry)
        if not uidx then
            logf("playlist: '%s' is not in the Self Radio folder any more; skipping",
                entry.song ~= "" and entry.song or radioPl.entryTitle(entry))
            return radioPl.advance(skips + 1, toastPrefix)
        end
    end

    local was   = (ii(TRACK_HASH, entry.station) or 0) & 0xFFFFFFFF
    local wasMs = ii(TRACK_TIME, entry.station) or 0

    local off = entry.offset or 0
    local adopted = was == (entry.hash & 0xFFFFFFFF)
                    and wasMs >= off and wasMs < off + ADOPT_MS
    if uidx then adopted = radioCtl.userActiveIdx(station) == uidx and wasMs < ADOPT_MS end

    radioCtl.tuneTo(entry.station)
    if not adopted then
        radioCtl.forceHash(station, entry.station, entry.hash, false, entry.offset,
            entry.cat, entry.coll, radioPl.nextSlot(entry.station), uidx)
    end

    local now = Time.GetEpocheMs()
    p.station, p.hash = entry.station, entry.hash
    p.offset, p.endMs = entry.offset or 0, entry.endMs
    p.cat, p.coll = entry.cat, entry.coll
    p.user, p.userStation = uidx, uidx and station or nil
    p.stopMs  = entry.endMs or (uidx and radioCtl.userDurationMs(uidx))
                or (not uidx and radioCtl.trackDurationMs(entry.hash)) or nil
    p.measure = not adopted and (was ~= (entry.hash & 0xFFFFFFFF))
    p.landOff = entry.offset or 0
    p.seeking = false
    p.armed, p.tries, p.forcedAt = false, 0, now
    logf("playlist: %s '%s' on %s at offset %d; end=%s; station now %08X @ %d ms",
        adopted and "adopted" or "forcing",
        entry.song ~= "" and entry.song or ("0x%08X"):format(entry.hash), entry.station,
        p.landOff, p.stopMs and tostring(p.stopMs) or "unknown",
        (ii(TRACK_HASH, entry.station) or 0) & 0xFFFFFFFF, ii(TRACK_TIME, entry.station) or 0)
    p.held = false
    p.acquireUntil = now + ACQUIRE_TIMEOUT_MS
    p.acquireNextAt = now + ACQUIRE_RETRY_MS
    p.acquireSeenAt = 0
    p.lastMs, p.nextPollAt = ii(TRACK_TIME, entry.station) or 0, now
    p.title  = entry.song ~= "" and entry.song or radioPl.entryTitle(entry)
    p.artist = entry.artist or ""

    radioCtl.broadcastToOthers(true)
    radioPl.syncPicker(false)
    local notice = toastPrefix or "Next up"
    if entry.artist ~= "" then
        GUI.AddToast("VibeScript", ("%s: %s  by %s"):format(notice, p.title, entry.artist), 4500)
    else
        GUI.AddToast("VibeScript", ("%s: %s"):format(notice, p.title), 4500)
    end
end

function radioPl.previous()
    local p = radioPl.play
    if not p.active or #p.order == 0 then return end
    p.pos = p.pos - 2
    if p.pos < 0 then p.pos = #p.order - 1 end
    radioPl.advance(nil, "Back to")
end

function radioPl.playPickerSelection()
    local p = radioPl.play
    if not p.active or not radioCtl.pickerIsPlaylist() then return end
    local gf = FeatureMgr.GetFeature(H.RADIO_SONG)
    local target = gf and (gf:GetListIndex() + 1) or p.pos
    if target < 1 or target > #p.order then return end
    p.pos = target - 1
    radioPl.advance(nil, "Playing")
end

function radioPl.liveStation(now)
    local p = radioPl.play
    local name = is(PLAYER_STATION)
    if name and name ~= "" and name ~= "OFF" then
        p.offSince = 0
        return name
    end
    local hosted = PED.IS_PED_IN_ANY_VEHICLE(PLAYER.PLAYER_PED_ID(), false)
        or (louderRadio and louderRadio.isOnFootRadioActive())
    if not hosted then p.offSince = 0; return nil end
    if p.offSince == 0 then p.offSince = now; return nil end
    if now - p.offSince < OFF_DEBOUNCE_MS then return nil end
    return "OFF"
end

function radioPl.resume(now)
    local p     = radioPl.play
    local away  = now - p.graceAt
    local want  = p.lastMs + away
    p.graceAt = 0
    p.forcedAt = p.forcedAt + away
    if p.stopMs and want >= p.stopMs then radioPl.advance() return end
    local audHash = (ii(TRACK_HASH, p.station) or 0) & 0xFFFFFFFF
    local ms      = ii(TRACK_TIME, p.station) or 0
    if audHash == p.hash and ms >= (p.offset - 500)
            and (p.endMs == nil or ms < p.endMs) then
        p.lastMs = ms
        return
    end
    local station = radioCtl.stationByName(p.station)
    if not radioPl.ptrOK(station) then radioPl.advance() return end
    p.landOff = math.max(want, p.offset or 0)
    radioCtl.forceHash(station, p.station, p.hash, false, p.landOff, p.cat, p.coll,
        radioPl.nextSlot(p.station))
    p.armed, p.tries, p.forcedAt = false, 0, now
    p.lastMs = ii(TRACK_TIME, p.station) or 0
end

function radioPl.retuneGuard(now)
    local p = radioPl.play
    if radioCtl.paused then
        local live = is(PLAYER_STATION)
        if not live or live == "" or live == "OFF" or live ~= radioCtl.paused.station then
            radioCtl.voidPause(nil)
            radioPl.stop("Playlist stopped: radio station changed.")
        end
        return true
    end
    local mine = radioPl.liveStation(now)
    if mine == nil then
        if p.offSince == 0 then
            p.held, p.graceAt = false, 0
            p.acquireUntil, p.acquireNextAt, p.acquireSeenAt = 0, 0, 0
        end
        return false
    end
    if mine == p.station then
        if p.graceAt ~= 0 then
            if ib(RETUNING) then return true end
            radioPl.resume(now)
            GUI.AddToast("VibeScript", "Playlist resumed.", 2500)
        end
        if not p.held then
            if ib(RETUNING) then p.acquireSeenAt = 0; return true end
            if p.acquireSeenAt == 0 then p.acquireSeenAt = now; return true end
            if now - p.acquireSeenAt < ACQUIRE_SETTLE_MS then return true end
            p.acquireUntil, p.acquireNextAt, p.acquireSeenAt = 0, 0, 0
            logf("playlist: acquired player radio on %s", p.station)
        end
        p.held = true
        return false
    end
    if ib(RETUNING) then return not p.held end
    if not p.held then
        p.acquireSeenAt = 0
        if p.acquireUntil == 0 then
            p.acquireUntil = now + ACQUIRE_TIMEOUT_MS
            p.acquireNextAt = 0
        elseif now >= p.acquireUntil then
            logf("playlist: could not acquire player radio; still on %s, wanted %s",
                tostring(mine), tostring(p.station))
            radioPl.stop("Playlist stopped: could not tune to its station.")
            return true
        end
        if now >= p.acquireNextAt then
            radioCtl.tuneTo(p.station)
            p.acquireNextAt = now + ACQUIRE_RETRY_MS
        end
        return true
    end
    if p.graceAt == 0 then
        p.graceAt = now
        GUI.AddToast("VibeScript", ("Playlist paused. Tune back within %d seconds "
            .. "to resume it."):format(GRACE_MS // 1000), 4000)
        return true
    end
    if now - p.graceAt < GRACE_MS then return true end
    radioPl.stop((mine == "OFF") and "Playlist stopped: radio turned off."
                                 or  "Playlist stopped: station changed.")
    return true
end

function radioPl.push(action)
    radioCtl.pickerUsed = true
    radioPl.pending[#radioPl.pending + 1] = action
end

function radioPl.onTick(now)
    radioPl.fulfilBrowse(now)
    if radioPl.popupVisible then radioPl.fillDurations() end
    if #radioPl.pending > 0 then
        local acts = radioPl.pending
        radioPl.pending = {}
        for _, act in ipairs(acts) do
            radioCtl.voidPause(nil)
            if act == "play" then radioPl.start(false)
            elseif act == "shuffle" then radioPl.start(true)
            elseif act == "stop" then radioPl.stop("Playlist stopped.")
            elseif act == "addnow" then radioPl.addPlaying()
            end
        end
    end
    local p = radioPl.play
    if not p.active then return end
    if scriptUnloading then radioPl.stop(nil); return end
    if not isPlayerReady() then return end
    if not p.station then radioPl.stop(nil); return end
    if now < p.nextPollAt then return end
    p.nextPollAt = now + POLL_MS

    if radioPl.retuneGuard(now) then return end
    if radioCtl.loopActive() then
        local lf = FeatureMgr.GetFeature(H.RADIO_LOOP)
        if lf then lf:Toggle() end
        radioCtl.loop.primed = false
        GUI.AddToast("VibeScript", "Stop the playlist before enabling Loop Song.", 3000)
    end

    local audHash = (ii(TRACK_HASH, p.station) or 0) & 0xFFFFFFFF
    local ms      = ii(TRACK_TIME, p.station) or 0

    if not p.armed then
        local landWindow = p.seeking and 500 or ARM_WINDOW
        local landed = ms >= (p.landOff - 500) and ms <= (p.landOff + landWindow)
                       and (p.endMs == nil or ms < p.endMs)
        if p.user then landed = radioCtl.userActiveIdx(p.userStation) == p.user end
        if audHash == p.hash and landed then
            local wasSeeking = p.seeking
            p.armed, p.seeking, p.lastMs = true, false, ms
            p.armedAt = wasSeeking and (now - MIN_PLAY_MS) or now
            if p.stopMs and p.stopMs <= ms + MIN_PLAY_MS then
                logf("playlist: '%s' length %d ms not credible at start %d ms; using observed end",
                    p.title, p.stopMs, ms)
                p.stopMs = nil
            end
            if p.measure then
                p.measure = false
                radioPl.leadMs = math.min(math.max(now - p.forcedAt, LEAD_MIN), LEAD_MAX)
            end
            logf("playlist: armed '%s' on %s at %d ms after %d ms; end=%s lead=%d",
                p.title, p.station, ms, now - p.forcedAt,
                p.stopMs and tostring(p.stopMs) or "unknown", radioPl.leadMs)
            radioCtl.broadcastToOthers(true)
        elseif now - p.forcedAt > ((p.tries == 0) and ARM_RETRY_MS or ARM_MS) then
            p.tries = p.tries + 1
            logf("playlist: force of '%s' on %s has not landed (hash=%08X ms=%d), retry %d",
                p.title, p.station, audHash, ms, p.tries)
            if p.tries >= ARM_TRIES then radioPl.advance() return end
            local station = radioCtl.stationByName(p.station)
            local retryOff = p.seeking and p.landOff or p.offset
            if station then
                radioCtl.forceHash(station, p.station, p.hash, false,
                    retryOff, p.cat, p.coll, radioPl.nextSlot(p.station), p.user)
            end
            p.landOff, p.forcedAt = retryOff, now
        end
        p.nextPollAt = now
        return
    end

    if audHash == 0 then return end

    if now - p.armedAt >= MIN_PLAY_MS then
        if p.stopMs then
            local nxt  = radioPl.peekNext()
            local at   = math.max(p.stopMs - radioPl.leadMs, p.offset + 500)
            if ms >= at then
                logf("playlist: hand off '%s' at %d ms (end %d, lead %d, %s)",
                    p.title, ms, p.stopMs, radioPl.leadMs,
                    (nxt and nxt.station == p.station) and "same station" or "retune")
                radioPl.advance() return
            end
            local due = at - ms - 100
            if due < POLL_MS then p.nextPollAt = now + math.max(due, 0) end
        end
        local moved = p.user ~= nil and radioCtl.userActiveIdx(p.userStation) ~= p.user
        if audHash ~= p.hash or ms < p.lastMs or moved then
            logf("playlist: '%s' ended by observation at %d ms (expected end %s)",
                p.title, p.lastMs, p.stopMs and tostring(p.stopMs) or "unknown")
            radioPl.advance() return
        end
    end
    p.lastMs = ms
end


function radioPl.renderPanel()
    local p = radioPl.play
    ImGui.Separator()
    ImGui.Text("Playlists")
    local pl = radioPl.current()
    local creatorReserve = (ImGui.CalcTextSize("Creator") or 0) + 24
    ImGui.SetNextItemWidth(-creatorReserve)
    if Widget.beginCombo("##vs_pl_pick", pl and pl.name or "(no playlists yet)") then
        for i, l in ipairs(radioPl.lists) do
            if ImGui.Selectable(("%s  (%d)##vs_pl_%d"):format(l.name, #l.tracks, i),
                    i == radioPl.sel, 0, 0, 0) then
                radioPl.sel = i
            end
        end
        Widget.endCombo()
    end
    ImGui.SameLine()
    if ImGui.Button("Creator##vs_pl", 0, 0) then radioPl.openRequest = true end
    if p.active then
        if ImGui.Button("Stop##vs_pl", 56, 0) then radioPl.push("stop") end
    else
        if ImGui.Button("Play##vs_pl", 56, 0) then radioPl.push("play") end
        ImGui.SameLine()
        if ImGui.Button("Shuffle##vs_pl", 0, 0) then radioPl.push("shuffle") end
    end
    ImGui.SameLine()
    if ImGui.Button("Add Current Song##vs_pl_now", 0, 0) then radioPl.push("addnow") end
    if ImGui.IsItemHovered() then
        ImGui.SetTooltip("Adds the currently playing song to the playlist picked above.")
    end
    if p.active then
        local playing = radioPl.lists[p.listIdx]
        ImGui.TextDisabled(("  %s  %d/%d%s"):format(playing and playing.name or "?",
            p.pos, #p.order, p.shuffle and "  shuffle" or ""))
        if p.graceAt ~= 0 then
            ImGui.TextDisabled("  Paused - tune back to that station to resume.")
        end
    end
end


function radioPl.fmtMs(ms)
    local s = math.floor((ms or 0) / 1000 + 0.5)
    if s >= 3600 then
        return ("%d:%02d:%02d"):format(s // 3600, (s // 60) % 60, s % 60)
    end
    return ("%d:%02d"):format(s // 60, s % 60)
end

function radioPl.entryMs(t)
    if t.endMs then return t.endMs - (t.offset or 0) end
    local total = radioCtl.durCache[t.hash & 0xFFFFFFFF]
    if not total then return nil end
    local ms = total - (t.offset or 0)
    return (ms > 0) and ms or nil
end

function radioPl.listTotalMs(pl)
    local total, unknown = 0, 0
    for _, t in ipairs(pl.tracks) do
        local ms = radioPl.entryMs(t)
        if ms then total = total + ms else unknown = unknown + 1 end
    end
    return total, unknown
end

function radioPl.fillDurations()
    local pl = radioPl.current()
    if not pl then return end
    local budget = 6
    for _, t in ipairs(pl.tracks) do
        if not t.endMs and radioCtl.durCache[t.hash & 0xFFFFFFFF] == nil then
            radioCtl.trackDurationMs(t.hash)
            budget = budget - 1
            if budget <= 0 then return end
        end
    end
end


function radioPl.renderCreatorLists(listH)
    ImGui.Text("Playlists")
    if ImGui.BeginChild("##vs_pl_lists", -1, listH, true, 0) then
        for i, l in ipairs(radioPl.lists) do
            if ImGui.Selectable(("%s  (%d)##vs_pl_row_%d"):format(l.name, #l.tracks, i),
                    i == radioPl.sel, 0, 0, 0) then
                radioPl.sel = i
            end
        end
    end
    ImGui.EndChild()
    if ImGui.Button("New##vs_plc", 74, 0) then radioPl.newList() end
    ImGui.SameLine()
    if ImGui.Button("Copy##vs_plc", 74, 0) then radioPl.duplicateList() end
    ImGui.SameLine()
    local pl = radioPl.current()
    if ImGui.Button("Delete##vs_plc", 74, 0) and pl then radioPl.confirmDelete = radioPl.sel end
    if radioPl.confirmDelete == radioPl.sel and pl then
        if ImGui.Button("Confirm##vs_plc", 74, 0) then
            radioPl.confirmDelete = nil
            radioPl.deleteList()
        end
        ImGui.SameLine()
        if ImGui.Button("Cancel##vs_plc", 74, 0) then radioPl.confirmDelete = nil end
        ImGui.TextColored(255, 170, 90, 255, ("Delete \"%s\"?"):format(pl.name))
        ImGui.TextColored(255, 170, 90, 255, ("%d song(s) go with it."):format(#pl.tracks))
    else
        radioPl.confirmDelete = nil
    end
    local pl = radioPl.current()
    if pl then
        local edited
        ImGui.SetNextItemWidth(-1)
        pl.name, edited = ImGui.InputText("##vs_pl_name", pl.name, 0)
        if edited then
            pl.name = radioPl.sanitize(pl.name)
            radioPl.save()
        end
    end
end

function radioPl.renderCreatorTracks(listH)
    local pl = radioPl.current()
    if not pl then ImGui.TextDisabled("Make a playlist to start adding songs."); return end
    local total, unknown = radioPl.listTotalMs(pl)
    local head = ("%s  --  %d song(s)"):format(pl.name, #pl.tracks)
    if #pl.tracks > 0 then
        head = head .. "  --  " .. radioPl.fmtMs(total)
        if unknown > 0 then head = head .. ("  (+%d unknown)"):format(unknown) end
    end
    ImGui.Text(head)
    local action
    if ImGui.BeginChild("##vs_pl_tracks", -1, listH, true, 0) then
        local NUM_W, LEN_W, ORDER_W = 34, 54, 76
        local availW = ImGui.GetContentRegionAvail() or 640
        local flex = math.max(240, availW - (NUM_W + LEN_W + ORDER_W))
        ImGui.Columns(6, "##vs_pl_table", false)
        ImGui.SetColumnWidth(0, NUM_W)
        ImGui.SetColumnWidth(1, flex * 0.36)
        ImGui.SetColumnWidth(2, flex * 0.30)
        ImGui.SetColumnWidth(3, flex * 0.34)
        ImGui.SetColumnWidth(4, LEN_W)
        ImGui.Text("#");       ImGui.NextColumn()
        ImGui.Text("Song");    ImGui.NextColumn()
        ImGui.Text("Artist");  ImGui.NextColumn()
        ImGui.Text("Station"); ImGui.NextColumn()
        ImGui.Text("Length");  ImGui.NextColumn()
        ImGui.Text("Order");   ImGui.NextColumn()
        for i, t in ipairs(pl.tracks) do
            ImGui.PushID(i)
            ImGui.Text(("%02d"):format(i))
            ImGui.NextColumn()
            ImGui.Text(t.song ~= "" and t.song or ("0x%08X"):format(t.hash))
            ImGui.NextColumn()
            ImGui.Text(t.artist ~= "" and t.artist or "-")
            ImGui.NextColumn()
            ImGui.Text(radioCtl.labelCache[t.station] or t.station)
            ImGui.NextColumn()
            local ms = radioPl.entryMs(t)
            if ms then ImGui.Text(radioPl.fmtMs(ms)) else ImGui.TextDisabled("-") end
            ImGui.NextColumn()
            if ImGui.SmallButton("^") and i > 1 then action = { "up", i } end
            ImGui.SameLine()
            if ImGui.SmallButton("v") and i < #pl.tracks then action = { "down", i } end
            ImGui.SameLine()
            if ImGui.SmallButton("X") then action = { "del", i } end
            ImGui.NextColumn()
            ImGui.PopID()
        end
        ImGui.Columns(1, "##vs_pl_table_end", false)
    end
    ImGui.EndChild()
    if action then
        if action[1] == "up" then radioPl.moveTrack(action[2], -1)
        elseif action[1] == "down" then radioPl.moveTrack(action[2], 1)
        else radioPl.removeTrack(action[2]) end
    end
end

function radioPl.renderCreatorAdd()
    local b = radioPl.browse
    local y0 = ImGui.GetCursorPosY()
    ImGui.Separator()
    ImGui.Text("Add songs")

    local stName = b.station
    if stName and stName:sub(1, 1) == "(" then stName = nil end
    local preview = "(pick a station)"
    for i, nm in ipairs(radioCtl.stations) do
        if nm == stName then preview = radioCtl.stationNames[i]; break end
    end
    ImGui.SetNextItemWidth(280)
    if Widget.beginCombo("Station##vs_pl_add", preview) then
        for i, nm in ipairs(radioCtl.stationNames) do
            local internal = radioCtl.stations[i]
            if internal ~= radioCtl.playlistSentinel
                    and ImGui.Selectable(nm .. "##vs_pl_st_" .. i,
                        internal == stName, 0, 0, 0) then
                b.station, b.songIdx = internal, 0
                b.want = internal
            end
        end
        Widget.endCombo()
    end

    local entry = stName and b.cache[stName] or nil
    ImGui.SameLine()
    ImGui.SetNextItemWidth(340)
    local songPrev = entry and entry.labels[b.songIdx + 1] or
        (stName and "(loading songs...)" or "(pick a station first)")
    if Widget.beginCombo("Song##vs_pl_add", songPrev) then
        if entry then
            for i, lbl in ipairs(entry.labels) do
                if ImGui.Selectable(lbl .. "##vs_pl_sg_" .. i, i - 1 == b.songIdx, 0, 0, 0) then
                    b.songIdx = i - 1
                end
            end
        end
        Widget.endCombo()
    end

    if ImGui.Button("Add Song##vs_pl_add", 110, 0) and entry then
        local i = b.songIdx + 1
        if entry.entries[i] then
            radioPl.addTrack(stName, entry.entries[i], entry.songs[i], entry.artists[i])
        end
    end
    ImGui.SameLine()
    if ImGui.Button("Add Whole Station##vs_pl_add", 150, 0) and entry then
        local added, dupes = 0, 0
        for i, e in ipairs(entry.entries) do
            if radioPl.addTrack(stName, e, entry.songs[i], entry.artists[i]) then
                added = added + 1
            else
                dupes = dupes + 1
            end
        end
        radioPl.status = (dupes > 0)
            and ("Added %d, skipped %d already in the list."):format(added, dupes)
            or  ("Added %d song(s)."):format(added)
    end
    ImGui.SameLine()
    if ImGui.Button("Close##vs_pl_add", 90, 0) then ImGui.CloseCurrentPopup() end
    if radioPl.status ~= "" then
        ImGui.SameLine()
        ImGui.TextDisabled(radioPl.status)
    end
    radioPl.addH = ImGui.GetCursorPosY() - y0
end

function radioPl.renderCreator()
    ImGui.Text("Build song lists that play in order or shuffled. Each song is forced on its own")
    ImGui.Text("station and synced to everyone in the lobby as it starts.")
    ImGui.Separator()
    local _, availY = ImGui.GetContentRegionAvail()
    local rowH  = ImGui.GetFrameHeightWithSpacing()
    local textH = ImGui.GetTextLineHeightWithSpacing()
    local colH  = math.max(200, (availY or 0) - (radioPl.addH or rowH * 4))
    if ImGui.BeginChild("##vs_pl_left", 270, colH, false, 0) then
        radioPl.renderCreatorLists(colH - textH - rowH * 2 - 4)
    end
    ImGui.EndChild()
    ImGui.SameLine()
    if ImGui.BeginChild("##vs_pl_right", -1, colH, false, 0) then
        radioPl.renderCreatorTracks(colH - textH - 4)
    end
    ImGui.EndChild()
    radioPl.renderCreatorAdd()
end

EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
    if scriptUnloading then return end
    if radioPl.openRequest then
        ImGui.OpenPopup("Radio Playlists", 0)
        radioPl.openRequest = false
    end
    ImGui.SetNextWindowSize(980, 560, ImGuiCond.FirstUseEver)
    if ImGui.BeginPopupModal("Radio Playlists", true, 0) then
        radioPl.popupVisible = true
        local ok, err = pcall(radioPl.renderCreator)
        if not ok then ImGui.TextColored(255, 90, 90, 255, "Creator error: " .. tostring(err)) end
        ImGui.EndPopup()
    elseif radioPl.popupVisible then
        radioPl.popupVisible = false
        radioPl.status = ""
        radioPl.confirmDelete = nil
    end
end)

radioPl.load()

end)()


