aptTeleport.LABELS = {}
for i = 1, #aptTeleport.PROPS do aptTeleport.LABELS[i] = aptTeleport.PROPS[i][2] end

function aptTeleport.picked(hash)
    local f = FeatureMgr.GetFeature(hash)
    local e = aptTeleport.PROPS[(f and f:GetListIndex() or 0) + 1]
    if not e then return nil end
    return e[1], e[2]
end

function aptTeleport.getIdx(hash)
    local f = FeatureMgr.GetFeature(hash)
    return f and f:GetListIndex() or 0
end

function aptTeleport.setIdx(hash, i)
    local f = FeatureMgr.GetFeature(hash)
    if not f then return end
    if not i or i < 0 or i >= #aptTeleport.PROPS then i = 0 end
    f:SetListIndex(i)
end

function aptTeleport.invite(pid, propId)
    local mask = 1 << pid
    GTA.TriggerScriptEvent(mask, {
        aptTeleport.SE_INVITE, GTA.GetLocalPlayerId(), mask,
        -1,
        -1,
        1,
        propId,
        0,
        0, 0,
        0,
    })
end

function aptTeleport.onTick(_)
    local apt = aptTeleport
    if scriptUnloading then
        apt.want, apt.queue, apt.batch, apt.solo = nil, {}, nil, {}
        return
    end

    local one = table.remove(apt.solo, 1)
    if one then
        if NETWORK.NETWORK_IS_PLAYER_CONNECTED(one.pid) then
            apt.invite(one.pid, one.prop)
            GUI.AddToast("VibeScript",
                ("Sent %s to %s."):format(PLAYER.GET_PLAYER_NAME(one.pid), one.name), 4000)
            log(("[AptTeleport] pid=%d property=%d name=%s")
                :format(one.pid, one.prop, one.name))
        else
            GUI.AddToast("VibeScript", "That player is no longer in the session.", 3000)
        end
        return
    end

    if apt.want then
        local w = apt.want
        apt.want = nil
        local q = {}
        for pid = 0, 31 do
            if lockOntoPlayers.isSessionTarget(pid) then q[#q + 1] = pid end
        end
        if #q == 0 then
            apt.queue, apt.batch = {}, nil
            GUI.AddToast("VibeScript", "Nobody else is in the session.", 3000)
        else
            apt.queue = q
            apt.batch = { prop = w.prop, name = w.name, sent = 0 }
        end
        return
    end

    if not apt.batch then return end

    local pid = table.remove(apt.queue, 1)
    if pid then
        if lockOntoPlayers.isSessionTarget(pid) then
            apt.invite(pid, apt.batch.prop)
            apt.batch.sent = apt.batch.sent + 1
        end
        return
    end

    GUI.AddToast("VibeScript", ("Sent %d player%s to %s."):format(
        apt.batch.sent, apt.batch.sent == 1 and "" or "s", apt.batch.name), 4000)
    log(("[AptTeleport] property=%d name=%s sent=%d")
        :format(apt.batch.prop, apt.batch.name, apt.batch.sent))
    apt.batch = nil
end

FeatureMgr.AddFeature(H.APT_TP_PICK, "Apartment", eFeatureType.Combo,
