function disarmAll.serve(pid, now)
    local st = disarmAll.state[pid]
    if not st then
        st = { idx = 1, nextAt = 0 }
        disarmAll.state[pid] = st
    end
    if now < st.nextAt then return false end

    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return false end

    local list = disarmAll.WEAPONS
    local last = math.min(st.idx + disarmAll.PER_SERVE - 1, #list)
    for i = st.idx, last do
        WEAPON.REMOVE_WEAPON_FROM_PED(ped, list[i])
    end
    disarmAll.sent = disarmAll.sent + (last - st.idx + 1)

    st.idx = last + 1
    if st.idx > #list then
        st.idx = 1
        st.nextAt = now + disarmAll.PASS_INTERVAL_MS
        disarmAll.passes = disarmAll.passes + 1
    end
    return true
end

function disarmAll.inScope()
    local n, total = 0, 0
    for pid = 0, 31 do
        if lockOntoPlayers.isSessionTarget(pid) then
            total = total + 1
            local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) then n = n + 1 end
        end
    end
    return n, total
end

function disarmAll.onTick(f)
    if scriptUnloading then
        disarmAll.state = {}
        return
    end
    if not f:IsToggled() then
        if disarmAll.startedAt then
            logf("[DisarmAll] off after %d removal(s), %d full pass(es)",
                disarmAll.sent, disarmAll.passes)
            disarmAll.state, disarmAll.sent, disarmAll.passes = {}, 0, 0
            disarmAll.startedAt = nil
        end
        return
    end

    local now = Time.GetEpocheMs()

    if not disarmAll.startedAt then
        disarmAll.startedAt = now
        disarmAll.nextLogAt = now + disarmAll.LOG_EVERY_MS
        logf("[DisarmAll] on, %d weapon hashes per pass", #disarmAll.WEAPONS)
    elseif now >= disarmAll.nextLogAt then
        disarmAll.nextLogAt = now + disarmAll.LOG_EVERY_MS
        local scoped, total = disarmAll.inScope()
        logf("[DisarmAll] %d removal(s), %d full pass(es), %d of %d target(s) in scope",
            disarmAll.sent, disarmAll.passes, scoped, total)
    end

    if now < disarmAll.nextServeAt then return end

    for _ = 1, 32 do
        disarmAll.cursor = (disarmAll.cursor + 1) % 32
        local pid = disarmAll.cursor
        if lockOntoPlayers.isSessionTarget(pid) and disarmAll.serve(pid, now) then
            disarmAll.nextServeAt = now + disarmAll.SERVE_INTERVAL_MS
            return
        end
    end
end

