deathBarrier = {
    MODEL = Utils.Joaat("prop_windmill_01"),
    H_OFFSET = 0x1899F328B0E12848,
    H_LOAD_COLLISION = 0x0DC7CABAB1E9B67E,
    H_ACTIVATE_PHYSICS = 0x710311ADF0E20730,
    JANITOR_HASH = Utils.Joaat("LUA_DeathBarrierJanitor"),
    PULSE_INTERVAL_MS = 25,
    MAX_PULSES_PER_TICK = 2,
    cursor = 0,
    targets = {},
    allowed = {},
    modelRequested = false,
    delBuf = Memory.AllocInt(),
    offsets = {
        { 0.0, false, 0.0 },
        { 0.0,  0.0, 0.3 }, { 0.0,  0.0, 0.9 },
        { 0.0,  0.0, 1.5 }, { 0.0,  0.0, 2.1 },
        { 0.0,  0.0, 2.7 }, { 0.0,  0.0, 3.3 },
        { 0.0,  0.0, 3.9 }, { 0.0,  0.0, 4.5 },
        { 0.0,  0.0, 5.1 },
        { 0.5,  0.3, 0.4 }, { -0.5,  0.3, 0.4 },
        { 0.5, -0.3, 0.4 }, { -0.5, -0.3, 0.4 },
    },
}

function deathBarrier.deleteObject(handle)
    local d = deathBarrier
    if not handle or handle == 0 or not ENTITY.DOES_ENTITY_EXIST(handle) then return end

    NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(handle)
    if NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(handle) then
        NETWORK.NETWORK_UNREGISTER_NETWORKED_ENTITY(handle)
    end
    Memory.WriteInt(d.delBuf, handle)
    ENTITY.DELETE_ENTITY(d.delBuf)
    if ENTITY.DOES_ENTITY_EXIST(handle) then
        Memory.WriteInt(d.delBuf, handle)
        ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(d.delBuf)
    end
end

function deathBarrier.clearPulse(state)
    if not state or not state.objects then return end
    for i = #state.objects, 1, -1 do
        deathBarrier.deleteObject(state.objects[i])
        state.objects[i] = nil
    end
end

function deathBarrier.clearTarget(pid)
    local state = deathBarrier.targets[pid]
    if not state then return end
    deathBarrier.clearPulse(state)
    deathBarrier.targets[pid] = nil
    deathBarrier.allowed[pid] = nil
end

function deathBarrier.cleanupAll()
    local d = deathBarrier
    for pid = 0, 31 do d.clearTarget(pid) end
    if d.modelRequested then
        STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(d.MODEL)
        d.modelRequested = false
    end
end

function deathBarrier.janitor(f)
    if not f:IsToggled() then return end
    local d = deathBarrier
    for pid in pairs(d.allowed) do d.allowed[pid] = nil end

    local active = false
    for pid = 0, 31 do
        if d.targets[pid] then
            if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                active = true
            else
                d.clearTarget(pid)
            end
        end
    end

    if not active then
        if d.modelRequested then
            STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(d.MODEL)
            d.modelRequested = false
        end
        d.cursor = (d.cursor + 1) % 32
        return
    end

    local picked, last = 0, d.cursor
    for step = 0, 31 do
        local pid = (d.cursor + step) % 32
        if d.targets[pid] then
            d.allowed[pid] = true
            picked = picked + 1
            last = pid
            if picked >= d.MAX_PULSES_PER_TICK then break end
        end
    end
    d.cursor = (last + 1) % 32
end

function deathBarrier.onPlayerTick(f)
    local d = deathBarrier
    local pid = f:GetPlayerIndex()
    local toggled = f:IsToggled()
    telemetryCountToggleEdge("Cripple", pid, toggled)
    if not toggled then
        d.clearTarget(pid)
        return
    end

    local state = d.targets[pid]
    if not state then
        state = { objects = {}, nextPulseAt = 0 }
        d.targets[pid] = state
        return
    end

    d.clearPulse(state)
    if not d.allowed[pid] then return end

    local now = Time.GetEpocheMs()
    if now < state.nextPulseAt then return end

    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if ped == 0 or not ENTITY.DOES_ENTITY_EXIST(ped) then return end

    STREAMING.REQUEST_MODEL(d.MODEL)
    d.modelRequested = true
    if not STREAMING.HAS_MODEL_LOADED(d.MODEL) then return end

    local lead = ENTITY.GET_ENTITY_SPEED(ped) > 0.35 and 0.5 or 1.3
    local spawned = 0
    for i, offset in ipairs(d.offsets) do
        local oy = i == 1 and lead or offset[2]
        local x, y, z = Natives.InvokeV3(d.H_OFFSET, ped, offset[1], oy, offset[3])
        if x then
            local object = GTA.CreateWorldObject(d.MODEL, x, y, z, true, true)
            if object and object ~= 0 then
                ENTITY.SET_ENTITY_AS_MISSION_ENTITY(object, true, true)
                ENTITY.SET_ENTITY_VISIBLE(object, false, false)
                ENTITY.SET_ENTITY_ALPHA(object, 0, false)
                ENTITY.SET_ENTITY_INVINCIBLE(object, true)
                ENTITY.SET_ENTITY_COLLISION(object, true, true)
                Natives.InvokeVoid(d.H_LOAD_COLLISION, object, true, true)
                Natives.InvokeVoid(d.H_ACTIVATE_PHYSICS, object)
                state.objects[#state.objects + 1] = object
                spawned = spawned + 1
            end
        end
    end
    state.nextPulseAt = now + (spawned > 0 and d.PULSE_INTERVAL_MS or 100)
end

