function playerState.speed.syncOnTick(f)
    local pid = f:GetPlayerIndex()
    local on  = f:IsToggled()
    telemetryCountToggleEdge("EnginePowerSync", pid, on)
    if not on then
        playerState.speed.syncMirror[pid] = nil
        return
    end

    local selfFeat = FeatureMgr.GetFeature(H.ENGINE_POWER_MULT)
    local perFeat  = FeatureMgr.GetFeature(H.PLAYER_SPEED_MULT, pid)
    if not (selfFeat and perFeat) then return end
    local selfV = selfFeat:GetFloatValue() or 1.0
    local perV  = perFeat:GetFloatValue() or 1.0

    local m = playerState.speed.syncMirror[pid]
    if not m then
        perFeat:SetFloatValue(selfV + .0)
        playerState.speed.syncMirror[pid] = { self = selfV, per = selfV }
        return
    end

    if perV ~= m.per then
        selfFeat:SetFloatValue(perV + .0)
        m.self, m.per = perV, perV
    elseif selfV ~= m.self then
        perFeat:SetFloatValue(selfV + .0)
        m.self, m.per = selfV, selfV
    end
end

