playerState.semiGod = {
    REWARD_HEALTH  = Utils.sJoaat("REWARD_HEALTH"),
    REWARD_ARMOUR  = Utils.sJoaat("REWARD_ARMOUR"),
    state = {},
}

playerState.semiGod.TRIGGER = {
    enh   = { aob = "8B 53 ? 89 F9 E8 ? ? ? ? E9", rip = 6 },
    leg   = { aob = "E8 ? ? ? ? FF C3 3B DE 72 A5", rip = 1 },
    addr  = nil,
    tried = false,
}

function playerState.semiGod.trigger()
    local t = playerState.semiGod.TRIGGER
    if t.addr or t.tried then return t.addr end
    t.tried = true
    local p    = IS_ENHANCED and t.enh or t.leg
    local edn  = IS_ENHANCED and "Enhanced" or "Legacy"
    local hit  = Memory.Scan(p.aob)
    local addr = (hit and hit > 0x10000) and Memory.Rip(hit + p.rip) or nil
    if addr and addr > 0x10000 then
        t.addr = addr
        logf("[AutoHeal] CGivePickupRewardsEvent::Trigger @ 0x%X (%s)", addr, edn)
    else
        logErr(("Auto Heal: CGivePickupRewardsEvent::Trigger not found (%s) - "
            .. "health and armor cannot be given on this build."):format(edn))
    end
    return t.addr
end

function playerState.semiGod.stateFor(pid)
    local s = playerState.semiGod.state[pid]
    if not s then
        s = {}
        playerState.semiGod.state[pid] = s
    end
    return s
end

function playerState.semiGod.give(pid, st, health, wantHealth)
    local sg = playerState.semiGod
    local fn = sg.trigger()
    if not fn then return end
    if wantHealth then Memory.LuaCallCFunction(fn, 1 << pid, sg.REWARD_HEALTH) end
    Memory.LuaCallCFunction(fn, 1 << pid, sg.REWARD_ARMOUR)
    if not st.logged then
        st.logged = true
        logf("[AutoHeal] pid=%d: frame-rate heal/armor loop started at health=%d", pid, health)
    end
end

function playerState.semiGod.tickHealth(pid, ped, st)
    local health = Natives.InvokeInt(0xEEF059FAD016D209, ped) or 0
    if health <= 0 then return end
    local maxHealth = Natives.InvokeInt(0x4700A416E8324EF3, ped) or 0
    local wantHealth = maxHealth > 0 and health < maxHealth
    playerState.semiGod.give(pid, st, health, wantHealth)
end

function playerState.semiGod.onTick(f)
    local sg  = playerState.semiGod
    local pid = f:GetPlayerIndex()
    local on  = f:IsToggled()
    telemetryCountToggleEdge("SemiGodMode", pid, on)
    if scriptUnloading then return end

    if not on then
        sg.state[pid] = nil
        return
    end

    if pid < 0 or pid > 31 or pid == GTA.GetLocalPlayerId() then return end
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
        sg.state[pid] = nil
        return
    end
    if not isPlayerReady() then return end

    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
    if not ped or ped == 0 then return end

    playerState.semiGod.tickHealth(pid, ped, sg.state[pid] or sg.stateFor(pid))
end

