playerState.neverWanted = {
    nextAt       = {},
    eventPtr     = 0,
    EVENT_CLEAR  = 800157557,
    SUB_CLEAR    = -914973885,
    N_SET_LEVEL  = 0x39FF19C64EF7DA5B,
    N_SET_NOW    = 0xE0A7D1E497FFCD6F,
    N_CLEAR      = 0xB302540597885499,
    N_SEND_ENH   = 0x71A6F836422FDD2B,
    N_SEND_LEG   = 0x5AE99C571D5BBE5D,
}

function playerState.neverWanted.sendRemote(pid)
    local nw = playerState.neverWanted
    if nw.eventPtr == 0 then
        nw.eventPtr = Memory.Alloc(5 * 8)
        if not nw.eventPtr or nw.eventPtr == 0 then
            nw.eventPtr = 0
            return false
        end
    end

    local mask = 1 << pid
    Memory.WriteLong(nw.eventPtr,      nw.EVENT_CLEAR)
    Memory.WriteLong(nw.eventPtr + 8,  GTA.GetLocalPlayerId())
    Memory.WriteLong(nw.eventPtr + 16, mask)
    Memory.WriteLong(nw.eventPtr + 24, nw.SUB_CLEAR)
    Memory.WriteLong(nw.eventPtr + 32, math.random(0, 9999))

    if IS_ENHANCED then
        Natives.InvokeVoid(nw.N_SEND_ENH, 1, nw.eventPtr, 5, mask, nw.EVENT_CLEAR)
    else
        Natives.InvokeVoid(nw.N_SEND_LEG, 1, nw.eventPtr, 5, mask)
    end
    return true
end

function playerState.neverWanted.cleanup()
    local nw = playerState.neverWanted
    if nw.eventPtr and nw.eventPtr ~= 0 then
        Memory.Free(nw.eventPtr)
        nw.eventPtr = 0
    end
    nw.nextAt = {}
end

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, playerState.neverWanted.cleanup)

function playerState.neverWanted.onTick(f)
    local pid = f:GetPlayerIndex()
    local on  = f:IsToggled()
    telemetryCountToggleEdge("NeverWanted", pid, on)
    if not on then
        playerState.neverWanted.nextAt[pid] = nil
        return
    end

    local now = MISC.GET_GAME_TIMER()
    if now < (playerState.neverWanted.nextAt[pid] or 0) then return end
    playerState.neverWanted.nextAt[pid] = now + 50

    local nw = playerState.neverWanted
    Natives.InvokeVoid(nw.N_SET_LEVEL, pid, 0, false)
    Natives.InvokeVoid(nw.N_SET_NOW, pid, false)
    Natives.InvokeVoid(nw.N_CLEAR, pid)
    if pid ~= GTA.GetLocalPlayerId() then
        nw.sendRemote(pid)
    end
end

