playerState.vehAuthor = {
    SPECTATE_MS   = 6000,
    ACQUIRE_MS    = 3000,
    RETRY_MS      = 2000,
    RESTORE_MS    = 3000,
    SETTLE_MS     = 350,
    DIAG_MS       = 3000,
    VERIFY_AT     = { 1000, 3000, 6000 },
    specs      = {},
    specByName = {},
    state      = {},
    todo       = {},
    todoWant   = {},
    runnerHash = Utils.Joaat("LUA_VehAuthorRunner"),
}

function playerState.vehAuthor.register(spec)
    local va = playerState.vehAuthor
    spec.h = {}
    for pid = 0, 31 do spec.h[pid] = FeatureMgr.GetFeature(spec.hash, pid) end
    va.specs[#va.specs + 1] = spec
    va.specByName[spec.name] = spec
end

function playerState.vehAuthor.stateFor(pid)
    local va = playerState.vehAuthor
    local st = va.state[pid]
    if not st then
        st = {
            key   = nil,
            on    = {},
            done  = {},
            last  = {},
            arm   = {},
            settle = {},
            restore   = nil,
            tries     = 0,
            wait      = 0,
            specUntil = 0,
            nextDiag  = 0,
        }
        va.state[pid] = st
    end
    return st
end

function playerState.vehAuthor.diag(pid, st, now, fmt, ...)
    if now < (st.nextDiag or 0) then return end
    st.nextDiag = now + playerState.vehAuthor.DIAG_MS
    logf("[VehAuthor] pid=%d: " .. fmt, pid, ...)
end

function playerState.vehAuthor.tickEdges(pid, now)
    local va    = playerState.vehAuthor
    local specs = va.specs
    local st    = va.state[pid]
    local anyOn = false
    for i = 1, #specs do
        local sp = specs[i]
        local f  = sp.h[pid]
        local on = (f and f:IsToggled()) or false
        if sp.telemetry then telemetryCountToggleEdge(sp.telemetry, pid, on) end
        if on then anyOn = true end
        local was = (st and st.on[sp.name]) or false
        if on ~= was then
            st = st or playerState.vehAuthor.stateFor(pid)
            st.on[sp.name]   = on or nil
            st.done[sp.name] = nil
            logf("[VehAuthor] pid=%d: %s %s", pid, sp.name, on and "armed" or "disarmed")
            if on then
                sp.everUsed = true
                st.arm[sp.name] = true
                st.nextDiag = 0
                if sp.canSpectate then st.specUntil = now + va.SPECTATE_MS end
            else
                st.arm[sp.name] = nil
                local veh = st.last[sp.name]
                if veh then
                    st.restore = st.restore or {}
                    st.restore[sp.name] = { veh = veh, until_ = now + va.RESTORE_MS }
                    st.last[sp.name] = nil
                end
            end
        end
    end
    return anyOn
end

function playerState.vehAuthor.tickRestore(pid, st, now)
    local va = playerState.vehAuthor
    local r  = st.restore
    for name, job in pairs(r) do
        if not ENTITY.DOES_ENTITY_EXIST(job.veh) then
            r[name] = nil
        elseif NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(job.veh) then
            va.specByName[name].restore(job.veh, pid)
            logf("[VehAuthor] pid=%d: %s undone on vehicle %d", pid, name, job.veh)
            r[name] = nil
        elseif now >= job.until_ then
            logf("[VehAuthor] pid=%d: no control of vehicle %d - %s stays applied",
                pid, job.veh, name)
            r[name] = nil
        else
            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(job.veh)
        end
    end
    if not next(r) then st.restore = nil end
end

function playerState.vehAuthor.takeControl(veh, force)
    if NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh) then return true end
    if force then return playerState.speed.requestControl(veh) end
    NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(veh)
    return NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(veh)
end

function playerState.vehAuthor.registerForSync(veh, register)
    if not (Script and Script.ExecuteAsScript) then return "no-context" end
    local result = "no-netid"
    local ok = pcall(Script.ExecuteAsScript, "freemode", function()
        if not register then
            Natives.InvokeVoid(0xAD738C3085FE7E11, veh, false, true)
            result = "released"
            return
        end
        if not Natives.InvokeBool(0x0A7B270912999B3C, veh) then
            Natives.InvokeVoid(0xAD738C3085FE7E11, veh, true, true)
        end
        local netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(veh)
        if netId and netId ~= 0 then
            NETWORK.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES(netId, true)
            NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, true)
        end
        result = Natives.InvokeBool(0x0A7B270912999B3C, veh) and "registered" or "not-registered"
    end)
    if not ok then return "context-failed" end
    return result
end

function playerState.vehAuthor.tickVerify(pid, st, now)
    local va = playerState.vehAuthor
    local v  = st.verify
    local at = va.VERIFY_AT[v.i]
    if not at then st.verify = nil return end
    if now - v.since < at then return end
    v.i = v.i + 1
    if not ENTITY.DOES_ENTITY_EXIST(v.veh) then
        logf("[VehAuthor] pid=%d: verify +%dms vehicle %d no longer exists", pid, at, v.veh)
        st.verify = nil
        return
    end
    logf("[VehAuthor] pid=%d: verify +%dms veh=%d ours=%s mission=%s canBeDamaged=%s tyresCanBurst=%s lockOnAllowed=%s",
        pid, at, v.veh,
        tostring(NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(v.veh)),
        tostring(Natives.InvokeBool(0x0A7B270912999B3C, v.veh)),
        tostring(Natives.InvokeBool(0xD95CC5D2AB15A09F, v.veh)),
        tostring(Natives.InvokeBool(0x678B9BB8C3F58FEB, v.veh)),
        tostring(Natives.InvokeBool(0x613A431BCD5A22EB, v.veh)))
end

function playerState.vehAuthor.sameVehicleKey(old, new)
    if not old or not new then return false end
    local oldKind, oldId, oldBody = old:match("^(%a+):(%d+)/(.*)$")
    local newKind, newId, newBody = new:match("^(%a+):(%d+)/(.*)$")
    if not oldBody or oldBody ~= newBody then return false end
    if oldKind == "net" and newKind == "net" then return oldId == newId end
    return true
end

function playerState.vehAuthor.tickPlayer(pid, now)
    local va = playerState.vehAuthor
    local anyOn = playerState.vehAuthor.tickEdges(pid, now)
    local st = va.state[pid]
    if not st then return end

    if st.restore then playerState.vehAuthor.tickRestore(pid, st, now) end
    if st.verify then playerState.vehAuthor.tickVerify(pid, st, now) end

    if not anyOn then
        playerState.speed.stopSyncFor(pid, "vehAuthor")
        if not st.restore then va.state[pid] = nil end
        return
    end

    if st.specUntil ~= 0 and now >= st.specUntil then
        playerState.speed.stopSyncFor(pid, "vehAuthor")
        st.specUntil = 0
    end

    local key, veh, status = playerState.vehTrack.keyFor(pid)

    if status == "outscope" then
        local wantSpectate = false
        if st.specUntil ~= 0 then
            for name in pairs(st.arm) do
                if va.specByName[name].canSpectate then wantSpectate = true break end
            end
        end
        if wantSpectate then
            playerState.speed.forceSync(pid, "vehAuthor")
        else
            playerState.speed.stopSyncFor(pid, "vehAuthor")
            st.specUntil = 0
        end
        playerState.vehAuthor.diag(pid, st, now,
            "stalled: their vehicle is out of scope (spectate %s)",
            wantSpectate and "holding" or "spent")
        return
    end
    if status ~= "ok" then
        if status ~= "pending" then playerState.speed.stopSyncFor(pid, "vehAuthor") end
        playerState.vehAuthor.diag(pid, st, now, "stalled: %s", status)
        return
    end

    if st.key ~= key and playerState.vehAuthor.sameVehicleKey(st.key, key) then
        logf("[VehAuthor] pid=%d: vehicle %d renamed %s -> %s (same car, nothing re-applied)",
            pid, veh, st.key, key)
        st.key = key
    end
    if st.key ~= key then
        st.key, st.tries, st.wait, st.acquireSince = key, 0, 0, nil
        for name in pairs(st.done) do st.done[name] = nil end
        for name in pairs(st.settle) do st.settle[name] = nil end
        logf("[VehAuthor] pid=%d: now in vehicle %d (%s)", pid, veh, key)
    end
    if now < st.wait then return end

    local todo, want, n = va.todo, va.todoWant, 0
    local specs = va.specs
    for i = 1, #specs do
        local sp = specs[i]
        if st.on[sp.name] then
            local w = (sp.variant and sp.variant(pid)) or true
            if st.done[sp.name] == w then
                st.settle[sp.name] = nil
            elseif not sp.variant then
                n = n + 1
                todo[n], want[n] = sp, w
            else
                local s = st.settle[sp.name]
                if not s or s.want ~= w then
                    st.settle[sp.name] = { want = w, since = now }
                elseif now - s.since >= va.SETTLE_MS then
                    n = n + 1
                    todo[n], want[n] = sp, w
                end
            end
        end
    end
    for i = n + 1, #todo do todo[i], want[i] = nil, nil end
    if n == 0 then
        playerState.speed.stopSyncFor(pid, "vehAuthor")
        return
    end

    local force = false
    for i = 1, n do
        if todo[i].forceOwner then force = true break end
    end
    if not playerState.vehAuthor.takeControl(veh, force) then
        st.tries = st.tries + 1
        st.acquireSince = st.acquireSince or now
        local waited = now - st.acquireSince
        playerState.vehAuthor.diag(pid, st, now,
            "stalled: no control of vehicle %d yet (%dms, %d tries)", veh, waited, st.tries)
        if waited >= va.ACQUIRE_MS then
            logf("[VehAuthor] pid=%d: no control of vehicle %d after %dms (%d tries) - retrying in %ds",
                pid, veh, waited, st.tries, va.RETRY_MS // 1000)
            st.tries, st.acquireSince, st.wait = 0, nil, now + va.RETRY_MS
        end
        return
    end
    st.acquireSince = nil

    for i = 1, n do
        local sp = todo[i]
        sp.apply(veh, pid, want[i])
        if sp.syncScriptState then
            st.regStatus = playerState.vehAuthor.registerForSync(veh, true)
        end
        st.done[sp.name]   = want[i]
        st.last[sp.name]   = veh
        st.arm[sp.name]    = nil
        st.settle[sp.name] = nil
        logf("[VehAuthor] pid=%d: %s written to vehicle %d%s", pid, sp.name, veh,
            sp.syncScriptState and (" [script state: %s]"):format(st.regStatus or "?") or "")
        st.verify = { veh = veh, since = now, i = 1 }
    end
    st.tries = 0
    if not next(st.arm) then playerState.speed.stopSyncFor(pid, "vehAuthor") end
end

function playerState.vehAuthor.runner(f)
    if scriptUnloading then return end
    if not f:IsToggled() then return end
    if #playerState.vehAuthor.specs == 0 then return end
    if not isPlayerReady() then return end
    local va  = playerState.vehAuthor
    local now = Time.GetEpocheMs()
    local me  = GTA.GetLocalPlayerId()
    for pid = 0, 31 do
        if pid ~= me and NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            playerState.vehAuthor.tickPlayer(pid, now)
        elseif va.state[pid] then
            for i = 1, #va.specs do
                local key = va.specs[i].telemetry
                if key then telemetryCountToggleEdge(key, pid, false) end
            end
            playerState.speed.stopSyncFor(pid, "vehAuthor")
            va.state[pid] = nil
        end
    end
end

function playerState.vehAuthor.applyVehGod(veh)
    Natives.InvokeVoid(0x115722B1B9C14C1C, veh)
    Natives.InvokeVoid(0x953DA1E1B12C0491, veh)
    Natives.InvokeVoid(0x45F6D8EEF34ABEF1, veh, 1000.0)
    Natives.InvokeVoid(0xB77D05AC8C78AADB, veh, 1000.0)
    Natives.InvokeVoid(0x70DB57649FA8D0D8, veh, 1000.0)
    Natives.InvokeVoid(0x3882114BDE571AD4, veh, true, true)
    Natives.InvokeVoid(0x1760FFA8AB074D66, veh, false)
    Natives.InvokeVoid(0xFAEE099C6F890BB8, veh,
        true, true, true, true, true, true, true, false)
    Natives.InvokeVoid(0x3E8C8727991A8A0B, veh, true)
    Natives.InvokeVoid(0x4C7028F78FFD3681, veh, false)
    Natives.InvokeVoid(0x983765856F2564F9, veh, false)
    Natives.InvokeVoid(0xEB9DC3C7D8596C46, veh, false)
    local doors = Natives.InvokeInt(0x92922A607497B14D, veh) or 0
    for i = 0, doors - 1 do
        Natives.InvokeVoid(0x2FA133A4A9D37ED8, veh, i, false)
    end
    Natives.InvokeVoid(0x465BF26AB9684352, veh, true)
    Natives.InvokeVoid(0x37C8252A7C92D017, veh, true)
end

