do
    local L = lockCineCam
    scanDoctor.register("LCCDIR", { sig = L.DIR_AOB })
    scanDoctor.register("LCCTMR", { sig = L.TIME_AOB })
    scanDoctor.register("LCCHST", { sig = L.HIST_AOB })
    scanDoctor.register("LCCBU",  { sig = L.BU_AOB })
    scanDoctor.register("LCCGCS", { sig = L.GCS_AOB })
    scanDoctor.register("LCCHP",  { sig = L.HIPRIO_AOB })
    scanDoctor.register("LCCOCC", { sig = L.OCC_AOB })
    local latchCodes = {
        ["low-orbit ShouldUpdate"]   = "LCCLOSU",
        ["orbit ShouldUpdate"]       = "LCCOSU",
        ["mountPart top latch"]      = "LCCMPT",
        ["mountPart mid latch"]      = "LCCMPM",
        ["low-orbit orient bail"]    = "LCCLOOB",
        ["low-orbit collide bail"]   = "LCCLOCB",
        ["low-orbit occlusion bail"] = "LCCLOC",
        ["low-orbit collide-freeze"] = "LCCLOCF",
        ["low-orbit close-freeze"]   = "LCCLOZF",
        ["heli distance re-plan"]    = "LCCHDR",
        ["heli follow sweep bail"]   = "LCCHFS",
        ["cam-man freeze bail"]      = "LCCCMF",
        ["cam-man valid-check entry"]= "LCCCMPV",
        ["heli acquire freeze bail"] = "LCCHAF",
        ["cam-man too-far bail"]     = "LCCCMTF",
        ["cam-man too-close bail"]   = "LCCCMTC",
        ["cam-man occlusion bail"]   = "LCCCMOB",
        ["cam-man interior bail"]    = "LCCCMIB",
    }
    for _, sig in ipairs(IS_ENHANCED and L.ENH_LATCH_SIGS or L.LATCH_SIGS) do
        local code = latchCodes[sig.name]
        if code then scanDoctor.register(code, { sig = sig.aob }) end
    end
end

function lockCineCam.plausiblePtr(p)
    return p and p > 0x10000 and p < 0x7FFFFFFFFFFF
end

function lockCineCam.resolve()
    local s = lockCineCam
    if s.resolved == true then return true end
    if s.resolved == false then return false end
    s.attempts = s.attempts + 1
    local dh = Memory.Scan(s.DIR_AOB)
    local th = Memory.Scan(s.TIME_AOB)
    local hh = Memory.Scan(s.HIST_AOB)
    if dh and dh ~= 0 and th and th ~= 0 and hh and hh ~= 0 then
        local dg = Memory.Rip(dh + 3)
        local tg = Memory.Rip(th + 2)
        local hg = Memory.Rip(hh + s.HIST_RIP)
        if dg and dg ~= 0 and tg and tg ~= 0 and hg and hg ~= 0 then
            s.dirGlobal, s.timeGlobal, s.histBuf, s.resolved = dg, tg, hg, true
            return true
        end
    end
    if s.attempts >= 90 then
        s.resolved = false
        logErr("[LockCineCam] AOB scan failed (" ..
            (IS_ENHANCED and "Enhanced" or "Legacy") .. ")")
    end
    return false
end

function lockCineCam.activeCtx()
    local s = lockCineCam
    local dir = Memory.ReadLong(s.dirGlobal)
    if not s.plausiblePtr(dir) then return nil end
    local idx = Memory.ReadInt(dir + s.O_CURRENT)
    if idx < 0 then return nil end
    local count = Memory.ReadInt(dir + s.O_CTX_COUNT) & 0xFFFF
    if idx >= count then return nil end
    local arr = Memory.ReadLong(dir + s.O_CONTEXTS)
    if not s.plausiblePtr(arr) then return nil end
    local ctx = Memory.ReadLong(arr + idx * 8)
    if not s.plausiblePtr(ctx) then return nil end
    return ctx
end

function lockCineCam.gated()
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    return PED.IS_PED_IN_ANY_VEHICLE(ped, false)
end

function lockCineCam.notOurView(ctx)
    local s = lockCineCam
    if not CAM.IS_CINEMATIC_CAM_INPUT_ACTIVE() then return "R/B latch not down" end
    if CAM.IS_BONNET_CINEMATIC_CAM_RENDERING() then return "first-person/bonnet mount" end
    if NETWORK.NETWORK_IS_IN_SPECTATOR_MODE() then return "spectating" end
    if MISC.IS_STUNT_JUMP_IN_PROGRESS() then return "stunt jump" end
    if STREAMING.IS_PLAYER_SWITCH_IN_PROGRESS() then return "player switch" end
    if CUTSCENE.IS_CUTSCENE_PLAYING() then return "cutscene" end
    if s.ctxOk[ctx] then
        s.ctxCand, s.ctxCandN = 0, 0
        return nil
    end
    if ctx ~= s.ctxCand then s.ctxCand, s.ctxCandN = ctx, 0 end
    s.ctxCandN = s.ctxCandN + 1
    if s.ctxCandN < s.CTX_SETTLE then return "unseen context settling" end
    s.ctxOk[ctx] = true
    s.ctxCand, s.ctxCandN = 0, 0
    local base = s.gameBase()
    local vt   = Memory.ReadLong(ctx)
    logf("[LockCine] adopted context 0x%X (vt +0x%X) after %d clean frames",
        ctx, (base ~= 0 and s.plausiblePtr(vt) and vt > base) and (vt - base) or 0, s.CTX_SETTLE)
    return nil
end

function lockCineCam.shotAt(ctx, idx)
    local s = lockCineCam
    if idx < 0 then return nil end
    local cnt = Memory.ReadInt(ctx + s.O_SHOT_CNT) & 0xFFFF
    if idx >= cnt then return nil end
    local arr = Memory.ReadLong(ctx + s.O_SHOTS)
    if not s.plausiblePtr(arr) then return nil end
    local shot = Memory.ReadLong(arr + idx * 8)
    if not s.plausiblePtr(shot) then return nil end
    return shot
end

function lockCineCam.engage(ctx, idx)
    local s = lockCineCam
    local shot = s.shotAt(ctx, idx)
    if not shot then return false end
    local orig = Memory.ReadInt(shot + s.O_SHOT_PRIO)
    if orig < 0 or orig >= s.PRIO_BOOST then return false end
    Memory.WriteInt(shot + s.O_SHOT_PRIO, s.PRIO_BOOST)
    s.lock = { ctx = ctx, shot = shot, idx = idx, origPrio = orig }
    return true
end

function lockCineCam.disengage()
    local s = lockCineCam
    if s.lock then
        if s.plausiblePtr(s.lock.shot)
            and Memory.ReadInt(s.lock.shot + s.O_SHOT_PRIO) == s.PRIO_BOOST then
            Memory.WriteInt(s.lock.shot + s.O_SHOT_PRIO, s.lock.origPrio)
        end
        s.lock = nil
    end
end

function lockCineCam.fillHistory(hash)
    local s = lockCineCam
    for i = 0, s.HIST_SLOTS - 1 do
        Memory.WriteInt(s.histBuf + i * 4, hash)
    end
end

function lockCineCam.gameBase()
    local s = lockCineCam
    if s.moduleBase ~= 0 then return s.moduleBase end
    local b = Memory.GetBaseAddress("GTA5.exe")
    if b and b > 0x10000 then s.moduleBase = b return b end
    local b2 = Memory.GetBaseAddress()
    if b2 and b2 > 0x10000 then s.moduleBase = b2 return b2 end
    return 0
end

function lockCineCam.patchIsValidFor(ctx, idx)
    local s = lockCineCam
    local shot = s.shotAt(ctx, idx)
    if not shot then return end
    local cam = Memory.ReadLong(shot + s.O_SHOT_CAM)
    if not s.plausiblePtr(cam) then return end
    local vt = Memory.ReadLong(cam)
    if not s.plausiblePtr(vt) then return end
    local fn = Memory.ReadLong(vt + s.ISV_SLOT * 8)
    if not s.plausiblePtr(fn) or s.isvPatched[fn] then return end
    local b0 = Memory.ReadByte(fn) & 0xFF
    if b0 == 0x00 or b0 == 0xCC or b0 == 0xB0 then
        s.isvPatched[fn] = true
        return
    end
    s.isvPatched[fn] = { Memory.ReadByte(fn), Memory.ReadByte(fn + 1), Memory.ReadByte(fn + 2) }
    for i = 1, #s.ISV_PATCH do Memory.WriteByte(fn + i - 1, s.ISV_PATCH[i]) end
    local base = s.gameBase()
    logf("[LockCine] IsValid patched: vtRva=0x%X fnRva=0x%X",
        (vt > base) and (vt - base) or 0, (fn > base) and (fn - base) or 0)
end

function lockCineCam.patchShotValidFor(ctx, idx)
    local s = lockCineCam
    local shot = s.shotAt(ctx, idx)
    if not shot then return end
    local vt = Memory.ReadLong(shot)
    if not s.plausiblePtr(vt) then return end
    local fn = Memory.ReadLong(vt + s.SHOT_ISV_VOFF)
    if not s.plausiblePtr(fn) or s.isvPatched[fn] then return end
    local b0 = Memory.ReadByte(fn) & 0xFF
    if b0 == 0x00 or b0 == 0xCC or b0 == 0xB0 then
        s.isvPatched[fn] = true
        return
    end
    s.isvPatched[fn] = { Memory.ReadByte(fn), Memory.ReadByte(fn + 1), Memory.ReadByte(fn + 2) }
    for i = 1, #s.ISV_PATCH do Memory.WriteByte(fn + i - 1, s.ISV_PATCH[i]) end
    local base = s.gameBase()
    logf("[LockCine] shot IsValid patched: vtRva=0x%X fnRva=0x%X",
        (vt > base) and (vt - base) or 0, (fn > base) and (fn - base) or 0)
end

function lockCineCam.restoreIsValid()
    local s = lockCineCam
    for fn, saved in pairs(s.isvPatched) do
        if type(saved) == "table" then
            for i = 1, #saved do Memory.WriteByte(fn + i - 1, saved[i]) end
        end
    end
    s.isvPatched = {}
end

function lockCineCam.patchBaseUpdate(enable)
    local s = lockCineCam
    if enable then
        s.buHealed = false
        if s.buApplied or s.buFailed then return end
        if not s.buAddr then
            local a = Memory.Scan(s.BU_AOB)
            if a and a ~= 0 then
                s.buAddr, s.buMiss = a + s.BU_JZ_OFF, 0
            else
                s.buMiss = s.buMiss + 1
                if s.buMiss >= s.PATCH_SCAN_TRIES then
                    s.buFailed = true
                    log("[LockCine] BaseUpdate sig not on this build -- giving up (no per-frame rescan)")
                end
                return
            end
        end
        local b0 = Memory.ReadByte(s.buAddr) & 0xFF
        local b1 = Memory.ReadByte(s.buAddr + 1) & 0xFF
        if b0 == 0x0F and b1 == 0x84 then
            s.buSaved = {}
            for i = 0, 5 do
                s.buSaved[i + 1] = Memory.ReadByte(s.buAddr + i)
                Memory.WriteByte(s.buAddr + i, 0x90)
            end
            s.buApplied = true
            if not s.buLogged then
                s.buLogged = true
                log("[LockCine] BaseUpdate LOS-bail NOP'd -- shots no longer tear down")
            end
        elseif b0 == 0x90 and b1 == 0x90 then
            s.buApplied = true
            if not s.buLogged then
                s.buLogged = true
                log("[LockCine] BaseUpdate already NOP'd (adopted)")
            end
        else
            s.buAddr = nil
        end
    else
        if s.buHealed then return end
        s.buHealed = true
        if not s.buAddr and not s.buFailed then
            local a = Memory.Scan(s.BU_AOB)
            if a and a ~= 0 then s.buAddr = a + s.BU_JZ_OFF end
        end
        if s.buAddr and (Memory.ReadByte(s.buAddr) & 0xFF) == 0x90
            and (Memory.ReadByte(s.buAddr + 1) & 0xFF) == 0x90 then
            local src = (type(s.buSaved) == "table") and s.buSaved or s.BU_ORIG
            for i = 1, 6 do Memory.WriteByte(s.buAddr + i - 1, src[i]) end
        end
        s.buSaved, s.buApplied = nil, false
    end
end

function lockCineCam.byteState(addr, orig, patched)
    local isOrig, isPatched = true, true
    for i = 1, #orig do
        local b = Memory.ReadByte(addr + i - 1) & 0xFF
        if b ~= orig[i] then isOrig = false end
        if b ~= patched[i] then isPatched = false end
    end
    return isOrig and "pristine" or (isPatched and "patched" or "other")
end

function lockCineCam.patchNoSwitch(enable)
    local s = lockCineCam
    if enable then
        s.gcsHealed = false
        if s.gcsApplied or s.gcsFailed then return end
        if not s.gcsAddr then
            local a = Memory.Scan(s.GCS_AOB)
            if a and a ~= 0 then
                s.gcsAddr = a + s.GCS_OFF
            else
                s.gcsMiss = (s.gcsMiss or 0) + 1
                if s.gcsMiss >= s.PATCH_SCAN_TRIES then
                    s.gcsFailed = true
                    log("[LockCine] GetChangeShotStatus sig not on this build -- anti-switch unavailable here (no per-frame rescan)")
                end
                return
            end
        end
        local st = s.byteState(s.gcsAddr, s.GCS_ORIG, s.GCS_PATCH)
        if st == "pristine" then
            for i = 1, #s.GCS_PATCH do Memory.WriteByte(s.gcsAddr + i - 1, s.GCS_PATCH[i]) end
            s.gcsApplied = true
            if not s.gcsLogged then
                s.gcsLogged = true
                log("[LockCine] GetChangeShotStatus locked -> no automatic shot switching")
            end
        elseif st == "patched" then
            s.gcsApplied = true
        else
            s.gcsAddr = nil
        end
    else
        if s.gcsHealed then return end
        s.gcsHealed = true
        if not s.gcsAddr and not s.gcsFailed then
            local a = Memory.Scan(s.GCS_AOB)
            if a and a ~= 0 then s.gcsAddr = a + s.GCS_OFF end
        end
        if s.gcsAddr and (s.gcsApplied or s.byteState(s.gcsAddr, s.GCS_ORIG, s.GCS_PATCH) == "patched") then
            for i = 1, #s.GCS_ORIG do Memory.WriteByte(s.gcsAddr + i - 1, s.GCS_ORIG[i]) end
        end
        s.gcsApplied = false
    end
end

function lockCineCam.patchNoHiPrio(enable)
    local s = lockCineCam
    if not s.HIPRIO_AOB then return end
    if enable then
        s.hiprioHealed = false
        if s.hiprioApplied or s.hiprioFailed then return end
        if not s.hiprioAddr then
            local a = Memory.Scan(s.HIPRIO_AOB)
            if a and a ~= 0 then
                s.hiprioAddr = a + s.HIPRIO_OFF
            else
                s.hiprioMiss = (s.hiprioMiss or 0) + 1
                if s.hiprioMiss >= s.PATCH_SCAN_TRIES then
                    s.hiprioFailed = true
                    log("[LockCine] ComputeShouldChangeForHigherPriorityShot sig not on this build -- priority-switch not blocked")
                end
                return
            end
        end
        local st = s.byteState(s.hiprioAddr, s.HIPRIO_ORIG, s.HIPRIO_PATCH)
        if st == "pristine" then
            for i = 1, #s.HIPRIO_PATCH do Memory.WriteByte(s.hiprioAddr + i - 1, s.HIPRIO_PATCH[i]) end
            s.hiprioApplied = true
            log("[LockCine] ComputeShouldChangeForHigherPriorityShot locked -> no priority auto-switch")
        elseif st == "patched" then
            s.hiprioApplied = true
        else
            s.hiprioAddr = nil
        end
    else
        if s.hiprioHealed then return end
        s.hiprioHealed = true
        if not s.hiprioAddr and not s.hiprioFailed then
            local a = Memory.Scan(s.HIPRIO_AOB)
            if a and a ~= 0 then s.hiprioAddr = a + s.HIPRIO_OFF end
        end
        if s.hiprioAddr and (s.hiprioApplied or s.byteState(s.hiprioAddr, s.HIPRIO_ORIG, s.HIPRIO_PATCH) == "patched") then
            for i = 1, #s.HIPRIO_ORIG do Memory.WriteByte(s.hiprioAddr + i - 1, s.HIPRIO_ORIG[i]) end
        end
        s.hiprioApplied = false
    end
end

function lockCineCam.patchOcclusion(enable)
    local s = lockCineCam
    if not s.OCC_AOB then return end
    if enable then
        s.occHealed = false
        if s.occApplied or s.occFailed then return end
        if not s.occAddr then
            local a = Memory.Scan(s.OCC_AOB)
            if a and a ~= 0 then
                s.occAddr = a + s.OCC_OFF
            else
                s.occMiss = (s.occMiss or 0) + 1
                if s.occMiss >= s.PATCH_SCAN_TRIES then
                    s.occFailed = true
                    log("[LockCine] occlusion helper sig not on this build -- occlusion freeze not blocked")
                end
                return
            end
        end
        local st = s.byteState(s.occAddr, s.OCC_ORIG, s.OCC_PATCH)
        if st == "pristine" then
            for i = 1, #s.OCC_PATCH do Memory.WriteByte(s.occAddr + i - 1, s.OCC_PATCH[i]) end
            s.occApplied = true
            log("[LockCine] occlusion helper -> always visible (no camera occlusion freeze)")
        elseif st == "patched" then
            s.occApplied = true
        else
            s.occAddr = nil
        end
    else
        if s.occHealed then return end
        s.occHealed = true
        if not s.occAddr and not s.occFailed then
            local a = Memory.Scan(s.OCC_AOB)
            if a and a ~= 0 then s.occAddr = a + s.OCC_OFF end
        end
        if s.occAddr and (s.occApplied or s.byteState(s.occAddr, s.OCC_ORIG, s.OCC_PATCH) == "patched") then
            for i = 1, #s.OCC_ORIG do Memory.WriteByte(s.occAddr + i - 1, s.OCC_ORIG[i]) end
        end
        s.occApplied = false
    end
end

function lockCineCam.patchLatches(enable)
    local s = lockCineCam
    local sigs = IS_ENHANCED and s.ENH_LATCH_SIGS or s.LATCH_SIGS
    local function siteState(sig)
        local site = sig.addr + sig.off
        local pv = (sig.kind == "nop6" or sig.kind == "nop2") and 0x90 or 0xEB
        local isPristine, isPatched = true, true
        for i = 1, #sig.orig do
            local b  = Memory.ReadByte(site + i - 1) & 0xFF
            local pb = sig.patched and sig.patched[i] or pv
            if b ~= sig.orig[i] then isPristine = false end
            if b ~= pb then isPatched = false end
        end
        return isPristine and "pristine" or (isPatched and "patched" or "other")
    end
    if enable then
        s.latchOffDone = false
        for _, sig in ipairs(sigs) do
            if not sig.applied and not sig.failed then
                if not sig.addr then
                    local a = Memory.Scan(sig.aob)
                    if a and a ~= 0 then
                        sig.addr = a
                    else
                        sig.miss = (sig.miss or 0) + 1
                        if sig.miss >= s.PATCH_SCAN_TRIES then sig.failed = true end
                    end
                end
                if not sig.addr then
                    if not sig.warned then sig.warned = true
                        logf("[LockCine] latch %s: NOT FOUND%s",
                            sig.name, sig.failed and " (giving up)" or "")
                    end
                else
                    local base = s.gameBase()
                    local rva  = (base ~= 0 and sig.addr > base) and (sig.addr - base) or 0
                    local st   = siteState(sig)
                    if st == "pristine" then
                        local site = sig.addr + sig.off
                        if sig.kind == "nop6" then
                            for i = 0, 5 do Memory.WriteByte(site + i, 0x90) end
                        elseif sig.kind == "nop2" then
                            for i = 0, 1 do Memory.WriteByte(site + i, 0x90) end
                        elseif sig.kind == "jmp6" then
                            for i = 1, #sig.patched do Memory.WriteByte(site + i - 1, sig.patched[i]) end
                        else
                            Memory.WriteByte(site, 0xEB)
                        end
                        sig.applied = true
                        if not sig.logged then
                            sig.logged = true
                            logf("[LockCine] latch %s: un-stuck (rva=0x%X %s)", sig.name, rva, sig.kind) end
                    elseif st == "patched" then
                        sig.applied = true
                        if not sig.logged then
                            sig.logged = true
                            logf("[LockCine] latch %s: already applied (adopted, rva=0x%X)", sig.name, rva) end
                    elseif not sig.warned then
                        sig.warned = true
                        logf("[LockCine] latch %s: unexpected bytes rva=0x%X+%d -- skipped", sig.name, rva, sig.off)
                    end
                end
            end
        end
    else
        if s.latchOffDone then return end
        s.latchOffDone = true
        for _, sig in ipairs(sigs) do
            if not sig.addr and not sig.failed then
                local a = Memory.Scan(sig.aob)
                if a and a ~= 0 then sig.addr = a end
            end
            if sig.addr and (sig.applied or siteState(sig) == "patched") then
                local site = sig.addr + sig.off
                for i = 1, #sig.orig do Memory.WriteByte(site + i - 1, sig.orig[i]) end
            end
            sig.applied = false
            sig.warned  = false
        end
    end
end

function lockCineCam.diagToast(msg)
    local s = lockCineCam
    local t = os.clock()
    if t < (s.diag.toastAt or 0) then return end
    s.diag.toastAt = t + 3.0
    GUI.AddToast("LockCine debug", msg, 3000)
end

function lockCineCam.ensureBoost(ctx, idx)
    local s = lockCineCam
    local L = s.lock
    if L and L.ctx == ctx and L.idx == idx then return end
    s.disengage()
    s.engage(ctx, idx)
end

function lockCineCam.onTick(f)
    local s = lockCineCam
    if scriptUnloading then s.forceCleanup() return end
    if not f:IsToggled() or not s.gated() then
        s.switch.active, s.switch.pending, s.switch.wantEnter = false, false, false
        s.swapPending = false
        if not s.offDone then
            s.ctxOk, s.ctxCand, s.ctxCandN = {}, 0, 0
            s.frz.cam = nil
            s.disengage()
            s.restoreIsValid()
            s.patchBaseUpdate(false)
            s.patchLatches(false)
            s.patchNoSwitch(false)
            s.patchNoHiPrio(false)
            s.patchOcclusion(false)
            s.offDone = true
        end
        return
    end
    s.offDone = false
    if not s.resolve() then
        if s.resolved == false then
            s.diagToast("AOB scan FAILED - game build changed? offsets stale")
        end
        return
    end
    local now = Memory.ReadInt(s.timeGlobal)
    local ctx  = s.activeCtx()
    local why  = ctx and s.notOurView(ctx) or nil
    if why then
        ctx = nil
        if s.viewSkipped ~= why then
            s.viewSkipped = why
            log("[LockCine] cinematic context active but not the R/B view (" .. why .. ") -- left alone")
        end
    elseif s.viewSkipped then
        s.viewSkipped = false
    end
    local sw  = s.switch
    local idx = ctx and Memory.ReadInt(ctx + s.O_SHOT_IDX) or nil
    if sw.pending then
        sw.pending = false
        if ctx then
            sw.active, sw.oldIdx, sw.ticks = true, nil, 0
        else
            sw.wantEnter, sw.enterTicks, sw.enterWait = true, 0, 0
        end
    end
    if ctx and (s.lastIdx == nil or idx ~= s.lastIdx) then
        s.birthUntil = now + s.BIRTH_MS
    end
    if ctx then
        local pveh = PED.GET_VEHICLE_PED_IS_IN(
            PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId()), false)
        local pphys = pveh ~= 0 and GTA.HandleToPointer(pveh) or nil
        local pptr  = pphys and pphys:GetAddress() or 0
        if pveh ~= s.lastVeh or pptr ~= s.lastVehPtr then
            if s.lastVeh ~= 0 and pptr ~= 0 then s.swapPending, s.swapTicks = true, 0 end
            s.lastVeh, s.lastVehPtr = pveh, pptr
        end
    end
    local inBirth = sw.active or (ctx ~= nil and now < s.birthUntil) or false
    local hold = ctx ~= nil and not inBirth
    s.patchBaseUpdate(hold)
    s.patchLatches(hold)
    if not hold then s.frz.cam = nil end
    if not ctx then
        s.switch.active = false
        s.lastIdx = nil
        s.swapPending = false
        s.disengage()
        s.restoreIsValid()
        s.patchNoSwitch(false)
        s.patchNoHiPrio(false)
        s.patchOcclusion(false)
        if sw.wantEnter then s.enterView() end
        return
    end

    if sw.wantEnter then sw.wantEnter, sw.enterTicks = false, 0 end


    if s.lastIdx ~= nil and idx ~= s.lastIdx and not sw.active and not inBirth and logging.enabled then
        local base  = s.gameBase()
        local shot  = s.shotAt(ctx, idx)
        local cam   = shot and Memory.ReadLong(shot + s.O_SHOT_CAM)
        local vt    = (cam and s.plausiblePtr(cam)) and Memory.ReadLong(cam) or 0
        local isvfn = s.plausiblePtr(vt) and Memory.ReadLong(vt + s.ISV_SLOT * 8) or 0
        local isvB0 = s.plausiblePtr(isvfn) and (Memory.ReadByte(isvfn) & 0xFF) or 0
        local buB0  = s.buAddr and (Memory.ReadByte(s.buAddr) & 0xFF) or 0
        logf("[LockCine] *** SWITCHED idx %d->%d camVt=0x%X IsValid[0]=0x%02X(%s) BaseUpdate[0]=0x%02X(%s)",
            s.lastIdx, idx, (base ~= 0 and vt > base) and (vt - base) or 0,
            isvB0, (isvB0 == 0xB0) and "patched" or "RAW",
            buB0, (buB0 == 0x90) and "NOP" or "RAW")
    end
    s.lastIdx = idx

    if sw.active then
        if sw.oldIdx == nil then
            sw.oldIdx, sw.ticks = idx, 0
            s.disengage()
            local shot = s.shotAt(ctx, idx)
            local meta = shot and Memory.ReadLong(shot + s.O_SHOT_META)
            local hash = (meta and s.plausiblePtr(meta))
                and Memory.ReadInt(meta + s.O_META_NAME) or 0
            s.fillHistory(hash)
            s.patchNoSwitch(false)
            Memory.WriteInt(ctx + s.O_PREV_TIME, 0)
        end
        sw.ticks = sw.ticks + 1
        if idx ~= sw.oldIdx or sw.ticks >= s.SWITCH_CAP then
            sw.active, sw.oldIdx = false, nil
        end
        return
    end

    if s.swapPending then
        s.swapTicks = s.swapTicks + 1
        if s.swapTicks == s.SWAP_FIRE then
            s.restoreIsValid()
            s.patchNoSwitch(false)
            s.disengage()
            s.fillHistory(0)
            Memory.WriteInt(ctx + s.O_PREV_TIME, 0)
            s.birthUntil = now + s.BIRTH_MS
        end
        if s.swapTicks >= s.SWAP_HOLD then
            s.swapPending = false
        else
            return
        end
    end

    do
        local f = s.frz
        local cp, cr = CAM.GET_FINAL_RENDERED_CAM_COORD(), CAM.GET_FINAL_RENDERED_CAM_ROT(2)
        local vp = s.lastVeh ~= 0 and ENTITY.GET_ENTITY_COORDS(s.lastVeh, false) or nil
        local still = f.cam ~= nil
            and math.abs(cp.x - f.cam[1]) < s.FREEZE_EPS
            and math.abs(cp.y - f.cam[2]) < s.FREEZE_EPS
            and math.abs(cp.z - f.cam[3]) < s.FREEZE_EPS
            and math.abs(cr.x - f.cam[4]) < s.FREEZE_REPS
            and math.abs(cr.y - f.cam[5]) < s.FREEZE_REPS
            and math.abs(cr.z - f.cam[6]) < s.FREEZE_REPS
        if not vp then
            f.cam = nil
        elseif not still then
            f.cam = { cp.x, cp.y, cp.z, cr.x, cr.y, cr.z }
            f.veh, f.ms, f.fired = { vp.x, vp.y, vp.z }, now, false
        elseif not f.fired then
            local dwell = now - f.ms
            local dx, dy, dz = vp.x - f.veh[1], vp.y - f.veh[2], vp.z - f.veh[3]
            local moved2 = dx * dx + dy * dy + dz * dz
            local cx, cy, cz = vp.x - cp.x, vp.y - cp.y, vp.z - cp.z
            local away2 = cx * cx + cy * cy + cz * cz
            if dwell > s.FREEZE_MS and moved2 > s.FREEZE_MOVE * s.FREEZE_MOVE
            and (away2 > s.FREEZE_FAR * s.FREEZE_FAR or dwell > s.FREEZE_SURE) then
                f.fired = true
                logf("[LockCine] shot %d frozen %dms (car moved %.0fm, now %.0fm away) -- rebuilding",
                    idx, dwell, math.sqrt(moved2), math.sqrt(away2))
                s.swapPending, s.swapTicks = true, 0
                return
            end
        end
    end

    s.ensureBoost(ctx, idx)
    s.fillHistory(0)
    Memory.WriteInt(ctx + s.O_PREV_TIME, now)
    s.patchNoSwitch(true)
    s.patchNoHiPrio(true)
    s.patchOcclusion(true)
    s.patchIsValidFor(ctx, idx)
    s.patchShotValidFor(ctx, idx)
end

function lockCineCam.forceCleanup()
    local s = lockCineCam
    s.buHealed, s.gcsHealed, s.hiprioHealed, s.occHealed = false, false, false, false
    s.latchOffDone = false
    s.offDone = false
    s.switch.active, s.switch.pending, s.switch.wantEnter = false, false, false
    s.swapPending = false
    s.ctxOk, s.ctxCand, s.ctxCandN = {}, 0, 0
    s.frz.cam = nil
    s.disengage()
    s.restoreIsValid()
    s.patchBaseUpdate(false)
    s.patchLatches(false)
    s.patchNoSwitch(false)
    s.patchNoHiPrio(false)
    s.patchOcclusion(false)
end
function lockCineCam.doSwitch()
    local f = FeatureMgr.GetFeature(H.LOCK_CINE_CAM)
    if not (f and f:IsToggled()) then
        GUI.AddToast("VibeScript", "Enable Lock Cinematic Camera first.", 2500)
        return
    end
    lockCineCam.switch.pending = true
end

function lockCineCam.enterView()
    local s = lockCineCam
    local sw = s.switch
    if sw.enterWait > 0 then sw.enterWait = sw.enterWait - 1 return end
    if sw.enterTicks >= s.ENTER_TAPS then sw.wantEnter = false return end
    sw.enterTicks = sw.enterTicks + 1
    PAD.SET_CONTROL_VALUE_NEXT_FRAME(0, s.VEH_CIN_CAM, 1.0)
    PAD.SET_CONTROL_VALUE_NEXT_FRAME(2, s.VEH_CIN_CAM, 1.0)
    sw.enterWait = s.ENTER_GAP
end

centralOnTick(FeatureMgr.AddFeature(H.LOCK_CINE_CAM, "Lock Cinematic Camera", eFeatureType.Toggle,
    "Holds the current cinematic camera angle instead of letting the game cycle through them.",
    lockCineCam.onTick)
    :SetNoCallbackOnPress(true)
    :SetSaveable(false))

FeatureMgr.AddFeature(H.LOCK_CINE_CAM_SWITCH, "Switch Cinematic Angle", eFeatureType.Button,
    "Manually change to the next cinematic camera angle while Lock Cinematic Camera is on.",
    function()
        lockCineCam.doSwitch()
    end)
    :SetSaveable(false)

customCam = {
    N_CREATE   = 0xC3981DCE61D9E13F,
    N_EXISTS   = 0xA7A932170592B50E,
    N_ACTIVE   = 0x026FB97D0A425F84,
    N_DESTROY  = 0x865908C81A2C22E9,
    N_FOV      = 0xB13C14F66A00D047,
    N_NEARCLIP = 0xC7848EFCCC545182,
    N_HARDATT  = 0x202A5ED9CE01D6E7,
    N_ATTACH   = 0xFEDB7D269E8C60E3,
    N_CAMROT   = 0x85973643155D0B07,
    N_RENDER   = 0x07E5B515DB0636FC,
    N_W2L      = 0x2274BC1C4885E333,
    N_FRAMETIME= 0x15C40837039FFAF7,
    N_GPCAMROT = 0x837765A25378F0BB,
    N_GPRELH   = 0x743607648ADD4587,
    N_SETRELH  = 0xB4EC2312F4E5B1F1,
    NEAR_CLIP  = 0.05,
    SEAT_BONE  = "seat_dside_f",
    MOUSE_DEG  = 20.0,
    STICK_DPS  = 140.0,
    STICK_DEAD = 0.05,
    MAX_PITCH  = 89.0,
    PRF_SCRIPT_CAM_HEADING = 77,
    cam       = nil,
    ownsCam   = false,
    rendering = false,
    unloadRequested = false,
    capReq    = false,
    resetReq  = false,
    status    = "",
    look      = { pitch = 0.0, yaw = 0.0 },
    still     = { heading = 0.0 },
    armed     = { mode = nil, ent = nil },
}

customCam.MODE_CENTER = 0
customCam.MODE_FOLLOW = 1
customCam.MODE_LOOK   = 2
customCam.MODE_STILL  = 3
customCam.MODE_LABELS = { "Mouse/RS - W/ Centering (native)", "Follow vehicle / player",
                          "Mouse/RS", "Stay still" }

customCam.MODE_IDS = { [0] = "center", [1] = "follow", [2] = "mouse", [3] = "still" }

customCam.MODE_REMAP_V1 = { [0] = 1, [1] = 2, [2] = 3, [3] = 0 }
customCam.MODE_REMAP_V2 = { [0] = 1, [1] = 0, [2] = 2, [3] = 3 }

customCam.DEF = { x = 0.40, y = -15.00, z = 2.00,
                  pitch = -6.00, yaw = 0.00, roll = 0.00, fov = 50.00 }

customCam.SLIDERS = {
    { H.CUSTOM_CAM_X,     "Camera: Side",     -50.0,  50.0, customCam.DEF.x,
      "Sideways offset in metres, relative to the car or the player. 0 is centred." },
    { H.CUSTOM_CAM_Y,     "Camera: Forward",  -50.0,  50.0, customCam.DEF.y,
      "Forward offset in metres. Negative pulls the camera back behind you." },
    { H.CUSTOM_CAM_Z,     "Camera: Up",       -25.0,  50.0, customCam.DEF.z,
      "Height in metres. Raise it for a chase or overhead view." },
    { H.CUSTOM_CAM_PITCH, "Camera: Pitch",    -89.0,  89.0, customCam.DEF.pitch,
      "Up/down tilt in degrees. Negative looks down." },
    { H.CUSTOM_CAM_YAW,   "Camera: Yaw",     -180.0, 180.0, customCam.DEF.yaw,
      "Turn in degrees. 0 looks straight ahead, 180 looks back at you." },
    { H.CUSTOM_CAM_ROLL,  "Camera: Roll",    -180.0, 180.0, customCam.DEF.roll,
      "Tilt sideways in degrees." },
    { H.CUSTOM_CAM_FOV,   "Camera: FOV",        5.0, 130.0, customCam.DEF.fov,
      "Field of view. Higher feels faster and shows more around you." },
}

function customCam.get(hash, dflt)
    local f = FeatureMgr.GetFeature(hash)
    return f and f:GetFloatValue() or dflt
end

function customCam.set(hash, v)
    local f = FeatureMgr.GetFeature(hash)
    if f then f:SetFloatValue(v + .0) end
end

function customCam.wrap(a)
    while a > 180.0 do a = a - 360.0 end
    while a < -180.0 do a = a + 360.0 end
    return a
end

function customCam.clamp(v, lo, hi)
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

function customCam.mode()
    local f = FeatureMgr.GetFeature(H.CUSTOM_CAM_MODE)
    return f and f:GetListIndex() or customCam.MODE_CENTER
end

function customCam.onFootAllowed()
    local f = FeatureMgr.GetFeature(H.CUSTOM_CAM_FOOT)
    return f and f:IsToggled() or false
end

function customCam.getModeId()
    return customCam.MODE_IDS[customCam.mode()] or "center"
end

function customCam.setModeId(id)
    for i, name in pairs(customCam.MODE_IDS) do
        if name == id then customCam.setMode(i) return end
    end
    customCam.setMode(nil)
end

function customCam.setMode(i)
    local f = FeatureMgr.GetFeature(H.CUSTOM_CAM_MODE)
    if not f then return end
    if not i or i < 0 or i >= #customCam.MODE_LABELS then i = customCam.MODE_CENTER end
    f:SetListIndex(i)
    customCam.armed.mode = nil
end

function customCam.seedAim(ent, mode)
    local s = customCam
    local er = ENTITY.GET_ENTITY_ROTATION(ent, 2)
    if mode == s.MODE_LOOK then
        s.look.pitch = s.clamp(er.x + s.get(H.CUSTOM_CAM_PITCH, s.DEF.pitch), -s.MAX_PITCH, s.MAX_PITCH)
        s.look.yaw   = s.wrap(er.z + s.get(H.CUSTOM_CAM_YAW, s.DEF.yaw))
    elseif mode == s.MODE_CENTER then
        local _, gp = s.gameplayAim()
        s.look.pitch = s.clamp(gp, -s.MAX_PITCH, s.MAX_PITCH)
    elseif mode == s.MODE_STILL then
        s.still.heading = er.z
    end
end

function customCam.lookDelta(dt)
    local s = customCam
    local lr = PAD.GET_DISABLED_CONTROL_NORMAL(0, 1)
    local ud = PAD.GET_DISABLED_CONTROL_NORMAL(0, 2)
    local sens = s.get(H.CUSTOM_CAM_SENS, 1.0)
    if PAD.IS_USING_KEYBOARD_AND_MOUSE(2) then
        return lr * s.MOUSE_DEG * sens, ud * s.MOUSE_DEG * sens
    end
    if math.abs(lr) < s.STICK_DEAD then lr = 0.0 end
    if math.abs(ud) < s.STICK_DEAD then ud = 0.0 end
    return lr * s.STICK_DPS * sens * dt, ud * s.STICK_DPS * sens * dt
end

function customCam.applyLook(dt)
    local s = customCam
    local dYaw, dPitch = s.lookDelta(dt)
    s.look.yaw   = s.wrap(s.look.yaw - dYaw)
    s.look.pitch = s.clamp(s.look.pitch - dPitch, -s.MAX_PITCH, s.MAX_PITCH)
end

function customCam.nudgeGameplayAim(dt)
    local s = customCam
    local dYaw, dPitch = s.lookDelta(dt)
    if dYaw ~= 0.0 then
        local h = Natives.InvokeFloat(s.N_GPRELH) or 0.0
        Natives.InvokeVoid(s.N_SETRELH, s.wrap(h - dYaw) + .0)
    end
    if dPitch ~= 0.0 then
        s.look.pitch = s.clamp(s.look.pitch - dPitch, -s.MAX_PITCH, s.MAX_PITCH)
    end
end

function customCam.worldOffset(heading, x, y, z)
    local h = math.rad(heading)
    local sh, ch = math.sin(h), math.cos(h)
    return x * ch - y * sh, x * sh + y * ch, z
end

function customCam.orbitOffset(yaw, pitch, x, y, z)
    local yr, pr = math.rad(yaw), math.rad(pitch)
    local sy, cy = math.sin(yr), math.cos(yr)
    local sp, cp = math.sin(pr), math.cos(pr)
    local fx, fy, fz = -sy * cp, cy * cp, sp
    return x * cy + y * fx, x * sy + y * fy, y * fz + z
end

function customCam.unWorldOffset(heading, dx, dy, dz)
    local h = math.rad(heading)
    local sh, ch = math.sin(h), math.cos(h)
    return dx * ch + dy * sh, -dx * sh + dy * ch, dz
end

function customCam.unOrbitOffset(yaw, pitch, dx, dy, dz)
    local yr, pr = math.rad(yaw), math.rad(pitch)
    local sy, cy = math.sin(yr), math.cos(yr)
    local sp, cp = math.sin(pr), math.cos(pr)
    local fx, fy, fz = -sy * cp, cy * cp, sp
    local x = dx * cy + dy * sy
    local wx, wy, wz = dx - x * cy, dy - x * sy, dz
    local cp2 = cp * cp
    if cp2 < 0.0001 then return x, 0.0, wz end
    local y = ((wx * fx + wy * fy + wz * fz) - wz * sp) / cp2
    return x, y, wz - y * sp
end

function customCam.gameplayAim()
    local r = V3.New(Natives.InvokeV3(customCam.N_GPCAMROT, 2))
    return r.z, r.x
end

function customCam.target()
    local veh = louderRadio.playerRealVehicle()
    if veh ~= 0 and ENTITY.DOES_ENTITY_EXIST(veh) then return veh, true end
    local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
    if ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) then return ped, false end
    return 0, false
end

function customCam.capture(ent)
    local s    = customCam
    local mode = s.mode()
    local cp   = CAM.GET_FINAL_RENDERED_CAM_COORD()
    local cr   = CAM.GET_FINAL_RENDERED_CAM_ROT(2)
    local er   = ENTITY.GET_ENTITY_ROTATION(ent, 2)
    local x, y, z
    if mode == s.MODE_FOLLOW then
        local o = V3.New(Natives.InvokeV3(s.N_W2L, ent, cp.x + .0, cp.y + .0, cp.z + .0))
        x, y, z = o.x, o.y, o.z
        s.set(H.CUSTOM_CAM_PITCH, s.wrap(cr.x - er.x))
        s.set(H.CUSTOM_CAM_YAW,   s.wrap(cr.z - er.z))
        s.set(H.CUSTOM_CAM_ROLL,  s.wrap(cr.y - er.y))
    else
        local ep = ENTITY.GET_ENTITY_COORDS(ent, true)
        local dx, dy, dz = cp.x - ep.x, cp.y - ep.y, cp.z - ep.z
        if mode == s.MODE_STILL then
            x, y, z = s.unWorldOffset(er.z, dx, dy, dz)
            s.set(H.CUSTOM_CAM_PITCH, s.wrap(cr.x))
            s.set(H.CUSTOM_CAM_YAW,   s.wrap(cr.z - er.z))
        else
            x, y, z = s.unOrbitOffset(cr.z, cr.x, dx, dy, dz)
            s.set(H.CUSTOM_CAM_PITCH, s.wrap(cr.x - er.x))
            s.set(H.CUSTOM_CAM_YAW,   s.wrap(cr.z - er.z))
        end
        s.set(H.CUSTOM_CAM_ROLL, s.wrap(cr.y))
    end
    s.set(H.CUSTOM_CAM_X, x) s.set(H.CUSTOM_CAM_Y, y) s.set(H.CUSTOM_CAM_Z, z)
    s.set(H.CUSTOM_CAM_FOV, CAM.GET_FINAL_RENDERED_CAM_FOV())
    s.armed.mode = nil
    s.status = ("captured (%.2f, %.2f, %.2f)"):format(x, y, z)
end

customCam.FOOT = { x = 0.0, y = -2.5, z = 1.3, pitch = -8.0, yaw = 0.0, roll = 0.0, fov = 55.0 }

function customCam.apply(x, y, z, pitch, yaw, roll, fov)
    local s = customCam
    s.set(H.CUSTOM_CAM_X, x) s.set(H.CUSTOM_CAM_Y, y) s.set(H.CUSTOM_CAM_Z, z)
    s.set(H.CUSTOM_CAM_PITCH, pitch) s.set(H.CUSTOM_CAM_YAW, yaw)
    s.set(H.CUSTOM_CAM_ROLL, roll) s.set(H.CUSTOM_CAM_FOV, fov)
end

function customCam.seedVehicle(veh)
    local s = customCam
    local x, y, z = 0.0, -0.15, 1.15
    local b = ENTITY.GET_ENTITY_BONE_INDEX_BY_NAME(veh, s.SEAT_BONE)
    if b and b ~= -1 then
        local w = ENTITY.GET_WORLD_POSITION_OF_ENTITY_BONE(veh, b)
        local o = V3.New(Natives.InvokeV3(s.N_W2L, veh, w.x + .0, w.y + .0, w.z + .0))
        x, y, z = o.x, o.y - 0.30, o.z + 0.85
    end
    s.apply(x, y, z, -6.0, 0.0, 0.0, 70.0)
    s.status = ("seeded from the seat bone (%.2f, %.2f, %.2f)"):format(x, y, z)
end

function customCam.defaults(ent, inVeh)
    local s = customCam
    if inVeh and ent ~= 0 then
        s.seedVehicle(ent)
    else
        local d = s.FOOT
        s.apply(d.x, d.y, d.z, d.pitch, d.yaw, d.roll, d.fov)
        s.status = "on-foot follow view"
    end
    s.armed.mode = nil
end

function customCam.destroy()
    local s = customCam
    if not s.ownsCam or not s.cam then
        s.cam, s.ownsCam, s.rendering = nil, false, false
        return
    end
    if not Natives.InvokeBool(s.N_EXISTS, s.cam) then
        s.cam, s.ownsCam, s.rendering = nil, false, false
        return
    end
    if s.rendering then
        Natives.InvokeVoid(s.N_RENDER, false, false, 0, true, false, 0)
        s.rendering = false
    end
    Natives.InvokeVoid(s.N_ACTIVE, s.cam, false)
    Natives.InvokeVoid(s.N_DESTROY, s.cam, false)
    s.cam, s.ownsCam = nil, false
end

function customCam.unloadCleanup()
    customCam.unloadRequested = true
end

function customCam.preempted()
    if NETWORK.NETWORK_IS_IN_SPECTATOR_MODE() then return "spectating" end

    local vd = vehicleDismantle
    if not vd then return nil end
    if vd.sweep or vd.cam then return "vehicle sweep" end
    if vd.specWant and vd.specWant.on then return "spectating" end
    if vd.spectatedPid and vd.spectatedPid() ~= nil then return "spectating" end
    return nil
end

function customCam.onTick(f)
    local s = customCam
    if scriptUnloading or s.unloadRequested or ShouldUnload() then s.destroy() return end

    local preempted = s.preempted()
    if preempted then
        if s.cam or s.rendering then s.destroy() end
        s.status = "paused for " .. preempted
        return
    end

    local ent, inVeh = s.target()

    if s.capReq then
        s.capReq = false
        if ent ~= 0 then s.capture(ent) else s.status = "no player to capture from" end
    end
    if s.resetReq then
        s.resetReq = false
        s.defaults(ent, inVeh)
    end

    if not f:IsToggled() or ent == 0 or (not inVeh and not s.onFootAllowed()) then
        if s.cam or s.rendering then s.destroy() end
        return
    end

    if not s.cam or not Natives.InvokeBool(s.N_EXISTS, s.cam) then
        local c = Natives.InvokeInt(s.N_CREATE, "DEFAULT_SCRIPTED_CAMERA", true)
        if not c or c == 0 then
            s.status = "could not create the camera"
            return
        end
        s.cam = c
        s.ownsCam = true
        Natives.InvokeVoid(s.N_NEARCLIP, s.cam, s.NEAR_CLIP + .0)
        Natives.InvokeVoid(s.N_ACTIVE, s.cam, true)
        s.armed.mode = nil
        s.status = "on"
    end

    local mode = s.mode()
    if s.armed.mode ~= mode or s.armed.ent ~= ent then
        s.seedAim(ent, mode)
        s.armed.mode, s.armed.ent = mode, ent
    end

    local ox = s.get(H.CUSTOM_CAM_X, s.DEF.x)
    local oy = s.get(H.CUSTOM_CAM_Y, s.DEF.y)
    local oz = s.get(H.CUSTOM_CAM_Z, s.DEF.z)
    local roll = s.get(H.CUSTOM_CAM_ROLL, s.DEF.roll)

    if mode == s.MODE_LOOK or mode == s.MODE_CENTER then
        local yaw, pitch
        local dt = Natives.InvokeFloat(s.N_FRAMETIME) or 0.0
        if mode == s.MODE_CENTER then
            s.nudgeGameplayAim(dt)
            yaw   = s.gameplayAim()
            pitch = s.look.pitch
        else
            s.applyLook(dt)
            yaw, pitch = s.look.yaw, s.look.pitch
        end
        local wx, wy, wz = s.orbitOffset(yaw, pitch, ox, oy, oz)
        Natives.InvokeVoid(s.N_ATTACH, s.cam, ent, wx + .0, wy + .0, wz + .0, false)
        Natives.InvokeVoid(s.N_CAMROT, s.cam, pitch + .0, roll + .0, yaw + .0, 2)
        if not inVeh and mode == s.MODE_LOOK then
            PED.SET_PED_RESET_FLAG(ent, s.PRF_SCRIPT_CAM_HEADING, true)
        end
    elseif mode == s.MODE_STILL then
        local wx, wy, wz = s.worldOffset(s.still.heading, ox, oy, oz)
        Natives.InvokeVoid(s.N_ATTACH, s.cam, ent, wx + .0, wy + .0, wz + .0, false)
        Natives.InvokeVoid(s.N_CAMROT, s.cam,
            s.get(H.CUSTOM_CAM_PITCH, s.DEF.pitch) + .0, roll + .0,
            s.wrap(s.still.heading + s.get(H.CUSTOM_CAM_YAW, s.DEF.yaw)) + .0, 2)
    else
        Natives.InvokeVoid(s.N_HARDATT, s.cam, ent,
            s.get(H.CUSTOM_CAM_PITCH, s.DEF.pitch) + .0, roll + .0,
            s.get(H.CUSTOM_CAM_YAW, s.DEF.yaw) + .0,
            ox + .0, oy + .0, oz + .0, true)
    end
    Natives.InvokeVoid(s.N_FOV, s.cam, s.get(H.CUSTOM_CAM_FOV, s.DEF.fov) + .0)

    if not s.rendering then
        Natives.InvokeVoid(s.N_RENDER, true, false, 0, true, false, 0)
        s.rendering = true
    end
end

Script.RegisterLooped(function()
    local ok, due = pcall(ShouldUnload)
    if customCam.ownsCam and customCam.cam
            and (customCam.unloadRequested or scriptUnloading or (ok and due)) then
        customCam.destroy()
    end
    Script.Yield(0)
end)

