function blameKill.onUnload()
    blameKill.restoreGunDamage()
    if blameKill.gun.projectileBuf and blameKill.gun.projectileBuf ~= 0 then
        Memory.Free(blameKill.gun.projectileBuf)
        blameKill.gun.projectileBuf = 0
    end
    blameKill.revertPatch(true)
end
