H.SILENT_KILL     = Utils.Joaat("LUA_SilentKill")
H.SILENT_KILL_ALL = Utils.Joaat("LUA_SilentKillAll")
H.SILENT_RUNNER   = Utils.Joaat("LUA_SilentKillRunner")

silentKill = {
    queue = {},
    TAG   = 59,
    DRAIN = 6,
}

function silentKill.fire(victimPid)
    if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(victimPid) then return "noconn" end
    if Natives.InvokeBool(0x424D4687FA1E5652, victimPid) then return "dead" end
    local victim = Players.GetCPed(victimPid)
    if not victim then return "noped" end
    local pos = victim.Position
    if not pos then return "noped" end

    if CExplosionArgs and GTA and GTA.AddExplosion then
        local args = CExplosionArgs.New(silentKill.TAG, pos)
        args.EntExplosionOwner = victim
        args.SizeScale = 1.0
        args.MakeSound = false
        args.NoFx      = true
        args.CamShake  = 0.0
        GTA.AddExplosion(args)
        return "ok"
    end

    local victimPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(victimPid)
    if not victimPed or victimPed == 0 then return "noped" end
    FIRE.ADD_OWNED_EXPLOSION(victimPed, pos.x, pos.y, pos.z, silentKill.TAG,
        1.0, false, true, 0.0)
    return "ok"
end

function silentKill.onTick(f)
    if not f:IsToggled() or scriptUnloading then return end
    local q = silentKill.queue
    if #q == 0 then return end
    if not isPlayerReady() then return end

    local done = 0
    while #q > 0 and done < silentKill.DRAIN do
        local job = table.remove(q, 1)
        if job.all then
            for pid = 0, 31 do
                if lockOntoPlayers.isSessionTarget(pid) then
                    q[#q + 1] = { v = pid, session = true }
                end
            end
        else
            local res = job.session and not lockOntoPlayers.isSessionTarget(job.v)
                and "protected" or silentKill.fire(job.v)
            done = done + 1
            log(("[SilentKill] victim=%s result=%s"):format(tostring(job.v), res))
        end
    end
end

