function blameKill.renderBlamerCombo(suffix)
    ImGui.SetNextItemWidth(-((ImGui.CalcTextSize("Blame On") or 0) + 18))
    if Widget.beginCombo("Blame On##bk" .. suffix, blameKill.blamerName()) then
        local me = GTA.GetLocalPlayerId()
        for _, pid in pairs(Players.Get() or {}) do
            if pid ~= me then
                local isCur = (pid == blameKill.blamerPid)
                if ImGui.Selectable(
                        ("%s##bk%s%d"):format(blameKill.nameOf(pid), suffix, pid),
                        isCur) and not isCur then
                    blameKill.setBlamer(pid)
                end
            end
        end
        Widget.endCombo()
    end
end



;(function()

soundSpam = {
    BURST_MS  = 1000,
    MAX_HELD  = 32,
    FLAT_STACK_PER_CUE = 32,
    CONTINUOUS_STACK_PER_CUE = 8,
    FLAT_MIN_HOLD_MS = 1000,
    CLUSTER_RADIUS = 40.0,
    SPATIAL_RANGE  = 90,
    SPATIAL_EVENTS_PER_SEC = 24,
    ALL_KEY   = 32,
    SESSION_KEY_BASE = 64,
    ALL_RANGE = false,

    live     = {},
    due      = {},
    heldN    = 0,
    onceAll  = false,
    stopAll  = false,
    allArmed = false,
    banksAt  = 0,
    banksWarm = false,
    emitters   = {},
    emitterN   = 0,
    spatialDue = 0,
}
local ss = soundSpam

ss.SOUNDS = {
    { label = "Mission Failed",       name = "ScreenFlash",                      set = "WastedSounds",                       flat = true },
    { label = "Wasted",               name = "Bed",                              set = "WastedSounds",                       flat = true },
    { label = "Wasted Flash",         name = "MP_Flash",                         set = "WastedSounds",                       flat = true },
    { label = "Wasted Impact",        name = "MP_Impact",                        set = "WastedSounds",                       flat = true },
    { label = "Air Defences",         name = "Air_Defences_Activated",           set = "DLC_sum20_Business_Battle_AC_Sounds", bank = "ALARM_KLAXON_07" },
    { label = "Loud Bass",            name = "07",                               set = "DLC_GR_CS2_Sounds",                  flat = true },
    { label = "Cash Grab",            name = "LOCAL_PLYR_CASH_COUNTER_COMPLETE", set = "DLC_HEISTS_GENERAL_FRONTEND_SOUNDS", flat = true },
    { label = "10 Second Warning",    name = "10_SEC_WARNING",                   set = "HUD_MINI_GAME_SOUNDSET",             flat = true },
    { label = "Explosion Timer",      name = "Explosion_Timer",                  set = "DLC_Lowrider_Relay_Race_Sounds" },
    { label = "Beeping",              name = "Exploding_Entity_Loop",            set = "MP_MISSION_COUNTDOWN_SOUNDSET",      loop = true },
    { label = "Silo Alarm",           name = "silo_alarm_loop",                  set = "dlc_xm_silo_finale_sounds",          loop = true, bank = "DLC_CHRISTMAS2017/XM_SILO" },
    { label = "Plane Alarm",          name = "Plane_Alarm_Loop",                 set = "DLC_GR_WVM_Oppressor2_Sounds",       loop = true },
    { label = "Escort Alarm",         name = "alarm_loop",                       set = "DLC_SM_Escort_Sounds",               loop = true, bank = "SCRIPT/ALARM_KLAXON_03" },
    { label = "Machine Gun",          name = "Fire_Loop",                        set = "DLC_IE_VV_Gun_Player_Sounds",        loop = true },
}

ss.sessionCues = {}
ss.banks = {}
local seenBank = {}
for _, e in ipairs(ss.SOUNDS) do
    ss.sessionCues[#ss.sessionCues + 1] = e
    if e.bank and not seenBank[e.bank] then
        seenBank[e.bank] = true
        ss.banks[#ss.banks + 1] = e.bank
    end
end

function ss.banksReady(now)
    if not NETWORK.NETWORK_IS_SESSION_ACTIVE() then
        ss.banksAt, ss.banksWarm = 0, false
        return false
    end
    if ss.banksWarm then return true end
    if ss.banksAt == 0 then ss.banksAt = now end
    local ready = true
    for i = 1, #ss.banks do
        if not AUDIO.REQUEST_SCRIPT_AUDIO_BANK(ss.banks[i], true, -1) then ready = false end
    end
    ss.banksWarm = ready and now - ss.banksAt >= 1500
    return ss.banksWarm
end

ss.parts = {}
function ss.partsFor(cues)
    local p = ss.parts[cues]
    if p then return p[1], p[2] end
    local flat, spatial = {}, {}
    for i = 1, #cues do
        local out = cues[i].flat and flat or spatial
        out[#out + 1] = cues[i]
    end
    ss.parts[cues] = { flat, spatial }
    return flat, spatial
end

function ss.cuesNeedBank(cues)
    for i = 1, #cues do if cues[i].bank then return true end end
    return false
end

function ss.labelsFor(cues)
    local out = {}
    for _, e in ipairs(cues) do out[#out + 1] = e.label end
    return out
end
ss.sessionLabels = ss.labelsFor(ss.sessionCues)

ss.oneCue = {}
function ss.expand(hash, cues)
    local f = FeatureMgr.GetFeature(hash)
    local i = f and f:GetListIndex() or 0
    local one = cues[i + 1] or cues[1]
    if not one then return {} end
    local c = ss.oneCue[one]
    if not c then c = { one }; ss.oneCue[one] = c end
    return c
end

function ss.delayMs()
    local f = FeatureMgr.GetFeature(H.SOUND_DELAY)
    return f and f:GetIntValue() or 250
end

function ss.buildEmitters()
    local em, n = ss.emitters, 0
    local r2 = ss.CLUSTER_RADIUS * ss.CLUSTER_RADIUS
    for pid = 0, 31 do
        if NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
            local ped = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(pid)
            if ped and ped ~= 0 then
                local p = ENTITY.GET_ENTITY_COORDS(ped, true)
                if p then
                    local covered = false
                    for i = 1, n do
                        local e = em[i]
                        local dx, dy, dz = e.x - p.x, e.y - p.y, e.z - p.z
                        if dx * dx + dy * dy + dz * dz <= r2 then covered = true break end
                    end
                    if not covered then
                        n = n + 1
                        local e = em[n]
                        if not e then e = {}; em[n] = e end
                        e.pid, e.ped, e.x, e.y, e.z = pid, ped, p.x, p.y, p.z
                    end
                end
            end
        end
    end
    ss.emitterN = n
    return n
end

function ss.isEmitter(pid)
    for i = 1, ss.emitterN do
        if ss.emitters[i].pid == pid then return true end
    end
    return false
end

function ss.loopAllOn()
    local f = ss.loopAllFeat or FeatureMgr.GetFeature(H.SOUND_LOOP_ALL)
    return f ~= nil and f:IsToggled()
end

function ss.reap(key, doomed)
    local L = ss.live[key]
    if not L then if not doomed then ss.due[key] = nil end return end
    for i = #L, 1, -1 do
        local r = L[i]
        if not doomed or doomed(r) then
            AUDIO.STOP_SOUND(r.id)
            AUDIO.RELEASE_SOUND_ID(r.id)
            ss.heldN = ss.heldN - 1
            table.remove(L, i)
        end
    end
    if #L == 0 then ss.live[key] = nil end
    if not doomed then ss.due[key] = nil end
end

function ss.stopEvery()
    for key in pairs(ss.live) do ss.reap(key) end
    ss.due, ss.heldN = {}, 0
    ss.allArmed, ss.spatialDue = false, 0
end

function ss.sessionKey(pid) return ss.SESSION_KEY_BASE + pid end
function ss.keyPid(key)
    if key >= ss.SESSION_KEY_BASE then return key - ss.SESSION_KEY_BASE end
    return nil
end

function ss.anchorPed(key)
    if key == ss.ALL_KEY then return PLAYER.PLAYER_PED_ID() end
    return PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(ss.keyPid(key))
end

function ss.findHeld(key, e)
    local L = ss.live[key]
    if not L then return nil end
    for i = 1, #L do
        if L[i].name == e.name and L[i].set == e.set then return L[i] end
    end
    return nil
end

function ss.stackCount(key, e)
    local L, n = ss.live[key], 0
    if not L then return 0 end
    for i = 1, #L do
        if L[i].name == e.name and L[i].set == e.set then n = n + 1 end
    end
    return n
end

function ss.inCues(cues, r)
    for i = 1, #cues do
        if cues[i].name == r.name and cues[i].set == r.set then return true end
    end
    return false
end

ss.reapCtx = { ped = 0, cues = nil, now = 0, pos = nil }
function ss.pToggleOwned(r) return r.expires == nil end
function ss.pExpired(r)     return r.expires ~= nil and r.expires <= ss.reapCtx.now end
function ss.pStaleContinuous(r) return r.expires == nil and not r.finishTracked end
function ss.pStaleToggled(r)
    local c = ss.reapCtx
    if r.expires ~= nil then return false end
    if r.ped ~= c.ped then return true end
    if not ss.inCues(c.cues, r) then
        return not r.finishTracked
    end
    if r.x and c.pos and not r.finishTracked then
        local dx, dy, dz = r.x - c.pos.x, r.y - c.pos.y, r.z - c.pos.z
        return dx * dx + dy * dy + dz * dz > 100.0
    end
    return false
end

function ss.playCue(id, ped, e, range, pos)
    if e.flat then
        AUDIO.PLAY_SOUND_FROM_ENTITY(id, e.name, ped, e.set, true, range)
        return nil
    end
    local p = pos or ENTITY.GET_ENTITY_COORDS(ped, true)
    if not p then return false end
    AUDIO.PLAY_SOUND_FROM_COORD(id, e.name, p.x, p.y, p.z, e.set, true, range or 0, false)
    return p
end

function ss.holdCue(key, ped, e, range, expires, pos)
    if ss.heldN >= ss.MAX_HELD then return false end
    local id = AUDIO.GET_SOUND_ID()
    if not id or id < 0 then return false end
    local p = ss.playCue(id, ped, e, range, pos)
    if p == false then AUDIO.RELEASE_SOUND_ID(id) return false end

    local L = ss.live[key]
    if not L then L = {}; ss.live[key] = L end
    L[#L + 1] = { id = id, ped = ped, name = e.name, set = e.set,
                  expires = expires, x = p and p.x, y = p and p.y, z = p and p.z,
                  finishTracked = not e.loop,
                  born = MISC.GET_GAME_TIMER() }
    ss.heldN = ss.heldN + 1
    return true
end

function ss.pruneFinished(key, now)
    local L = ss.live[key]
    if not L then return end
    for i = #L, 1, -1 do
        local r = L[i]
        if r.finishTracked and now - r.born >= ss.FLAT_MIN_HOLD_MS
                and AUDIO.HAS_SOUND_FINISHED(r.id) then
            AUDIO.RELEASE_SOUND_ID(r.id)
            ss.heldN = ss.heldN - 1
            table.remove(L, i)
        end
    end
    if #L == 0 then ss.live[key] = nil end
end

function ss.hasRetiring(key, cues)
    local L = ss.live[key]
    if not L then return false end
    for i = 1, #L do
        if L[i].finishTracked and not ss.inCues(cues, L[i]) then return true end
    end
    return false
end

function ss.fireOne(key, ped, e, range, expires, pos)
    if e.loop then
        local r = ss.findHeld(key, e)
        if r and (expires == nil or r.expires ~= nil) then
            if expires == nil or r.expires ~= nil then r.expires = expires end
            return true
        end
        return ss.holdCue(key, ped, e, range, expires, pos)
    else
        local id = AUDIO.GET_SOUND_ID()
        if not id or id < 0 then return false end
        if ss.playCue(id, ped, e, range, pos) == false then
            AUDIO.RELEASE_SOUND_ID(id)
            return false
        end
        AUDIO.RELEASE_SOUND_ID(id)
    end
    return true
end

function ss.fire(key, cues, range)
    local ped = ss.anchorPed(key)
    if not ped or ped == 0 then return false end
    local expires = MISC.GET_GAME_TIMER() + ss.BURST_MS
    local sent    = 0
    for i = 1, #cues do
        if ss.fireOne(key, ped, cues[i], range, expires) then sent = sent + 1 end
    end
    return sent > 0
end

function ss.pump(key, cues, now, range)
    local ped = ss.anchorPed(key)
    if not ped or ped == 0 then return end

    ss.reapCtx.ped, ss.reapCtx.cues, ss.reapCtx.pos = ped, cues, nil
    ss.reap(key, ss.pStaleToggled)
    ss.pruneFinished(key, now)
    local retiring = ss.hasRetiring(key, cues)

    if (ss.due[key] or 0) <= now then
        ss.due[key] = now + math.max(1, ss.delayMs())
        for i = 1, #cues do
            local e = cues[i]
            local cap = e.loop and ss.CONTINUOUS_STACK_PER_CUE or ss.FLAT_STACK_PER_CUE
            if (e.loop or not retiring) and ss.stackCount(key, e) < cap then
                ss.holdCue(key, ped, e, range, nil)
            end
        end
    end
end

function ss.pumpSpatial(cues, now)
    if now < ss.spatialDue then return end
    local n = ss.buildEmitters()

    for key in pairs(ss.live) do
        local pid = ss.keyPid(key)
        if pid and not ss.isEmitter(pid) then ss.reap(key, ss.pStaleContinuous) end
    end
    if n == 0 then return end

    local finite = 0
    for c = 1, #cues do if not cues[c].loop then finite = finite + 1 end end
    local need = n * finite
    if need > 0 and ss.heldN + need > ss.MAX_HELD then
        ss.spatialDue = now + 50
        return
    end

    local minPeriod = math.ceil(n * math.max(1, #cues) * 1000 / ss.SPATIAL_EVENTS_PER_SEC)
    ss.spatialDue = now + math.max(minPeriod, math.max(1, ss.delayMs()))

    local contCap = math.max(1, math.min(ss.CONTINUOUS_STACK_PER_CUE,
        math.floor(ss.MAX_HELD / math.max(1, n * math.max(1, #cues - finite)))))

    for i = 1, n do
        local em  = ss.emitters[i]
        local key = ss.sessionKey(em.pid)
        ss.reapCtx.ped, ss.reapCtx.cues, ss.reapCtx.pos = em.ped, cues, em
        ss.reap(key, ss.pStaleToggled)
        local retiring = ss.hasRetiring(key, cues)
        for c = 1, #cues do
            local e = cues[c]
            if e.loop then
                if ss.stackCount(key, e) < contCap then
                    ss.holdCue(key, em.ped, e, ss.SPATIAL_RANGE, nil, em)
                end
            elseif not retiring then
                ss.holdCue(key, em.ped, e, ss.SPATIAL_RANGE, nil, em)
            end
        end
    end
end

function ss.reapSessionSpatial(doomed)
    for pid = 0, 31 do
        local key = ss.sessionKey(pid)
        ss.reap(key, doomed)
        if not ss.live[key] then ss.due[key] = nil end
    end
end

function ss.fireSession(cues)
    local flat, spatial = ss.partsFor(cues)
    if #flat > 0 then ss.fire(ss.ALL_KEY, flat, ss.ALL_RANGE) end
    if #spatial > 0 then
        local n = ss.buildEmitters()
        local expires = MISC.GET_GAME_TIMER() + ss.BURST_MS
        for i = 1, n do
            local em = ss.emitters[i]
            for c = 1, #spatial do
                ss.fireOne(ss.sessionKey(em.pid), em.ped, spatial[c],
                    ss.SPATIAL_RANGE, expires, em)
            end
        end
    end
end

function ss.pumpSession(cues, now)
    local flat, spatial = ss.partsFor(cues)
    if #flat > 0 then
        ss.pump(ss.ALL_KEY, flat, now, ss.ALL_RANGE)
    else
        ss.pruneFinished(ss.ALL_KEY, now)
        if not ss.live[ss.ALL_KEY] then ss.due[ss.ALL_KEY] = nil end
    end

    if #spatial > 0 then
        ss.pumpSpatial(spatial, now)
    else
        ss.reapSessionSpatial(ss.pStaleContinuous)
        ss.spatialDue = 0
    end
end

function ss.sessionOnTick(_)
    if ShouldUnload() then
        ss.allArmed = false
        if not scriptUnloading and next(ss.live) then ss.stopEvery() end
        return
    end
    local now = MISC.GET_GAME_TIMER()
    if not NETWORK.NETWORK_IS_SESSION_ACTIVE() then
        ss.banksAt, ss.banksWarm = 0, false
    end
    local loopAll = ss.loopAllOn()
    if not loopAll then ss.allArmed = false end

    if ss.stopAll then
        ss.stopAll = false
        ss.onceAll = false
        ss.stopEvery()
    end

    local looping = loopAll and ss.allArmed
    if ss.onceAll or looping then
        local allCues = ss.expand(H.SOUND_PICK_ALL, ss.sessionCues)
        local banksReady = not ss.cuesNeedBank(allCues) or ss.banksReady(now)
        if ss.onceAll and banksReady then
            ss.onceAll = false
            ss.fireSession(allCues)
        end
        if looping and banksReady then
            ss.pumpSession(allCues, now)
        end
    else
        ss.due[ss.ALL_KEY] = nil
        ss.spatialDue = 0
    end

    if next(ss.live) then
        ss.reapCtx.now = now
        for key in pairs(ss.live) do
            local pid = ss.keyPid(key)
            if not pid or NETWORK.NETWORK_IS_PLAYER_CONNECTED(pid) then
                ss.reap(key, ss.pExpired)
                ss.pruneFinished(key, now)
            else
                ss.reap(key)
            end
        end
    end

end


FeatureMgr.AddFeature(H.SOUND_PICK_ALL, "Sound", eFeatureType.Combo,
    "Wasted is most effective")
    :SetList(ss.sessionLabels)
    :SetSaveable(false)

FeatureMgr.GetFeature(H.SOUND_PICK_ALL):SetListIndex(0)

FeatureMgr.AddFeature(H.SOUND_DELAY, "Loop Delay (ms)", eFeatureType.SliderInt,
    "")
    :SetLimitValues(0, 1000)
    :SetStepSize(10)
    :SetDefaultValue(250)
    :SetSaveable(false)
    :Reset()

FeatureMgr.AddFeature(H.SOUND_PLAY_ALL, "Play For Everyone", eFeatureType.Button,
    "Blast their ears",
    function(_)
        if ss.loopAllOn() then ss.allArmed = true else ss.onceAll = true end
        telemetryCountAction("SoundSpamPlayAll")
    end)
    :SetSaveable(false)

centralOnTick(FeatureMgr.AddFeature(H.SOUND_LOOP_ALL, "Loop For Everyone", eFeatureType.Toggle,
    "",
    ss.sessionOnTick))
    :SetNoCallbackOnPress(true)
    :SetSaveable(false)
ss.loopAllFeat = FeatureMgr.GetFeature(H.SOUND_LOOP_ALL)

FeatureMgr.AddFeature(H.SOUND_STOP_ALL, "Stop All Sounds", eFeatureType.Button,
    "Silence",
    function(_) ss.stopAll = true end)
    :SetSaveable(false)

EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
    ss.live, ss.due = {}, {}
    ss.onceAll, ss.stopAll, ss.allArmed, ss.heldN = false, false, false, 0
    ss.banksAt, ss.banksWarm = 0, false
    ss.emitterN, ss.spatialDue = 0, 0
end)


function ss.getIdx(hash)
    local f = FeatureMgr.GetFeature(hash)
    return f and f:GetListIndex() or 0
end

function ss.setIdx(hash, i, cues)
    local f = FeatureMgr.GetFeature(hash)
    if not f then return end
    if not i or i < 0 or i >= #cues then i = 0 end
    f:SetListIndex(i)
end

function ss.restoreDefaults()
    ss.onceAll, ss.stopAll = false, false
    ss.stopEvery()
    ss.setIdx(H.SOUND_PICK_ALL, 0, ss.sessionCues)
end


function ss.renderSession()
    ImGui.PushID("SessionSoundSpam")
    if ClickGUI.BeginCustomChildWindow("Sound Spam") then
        ClickGUI.RenderFeature(H.SOUND_PICK_ALL)
        ClickGUI.RenderFeature(H.SOUND_DELAY)
        ClickGUI.RenderFeature(H.SOUND_PLAY_ALL)
        ImGui.SameLine()
        ClickGUI.RenderFeature(H.SOUND_STOP_ALL)
        ClickGUI.RenderFeature(H.SOUND_LOOP_ALL)
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()
end


end)()

do
local ringSession = {
    HOLD_CAP = 24,
    gate        = nil,
    pending     = 0,
    stopPending = false,
    held        = {},
    freed       = false,
}

ringSession.toast = function(msg) GUI.AddToast("VibeScript", msg, 5000) end

ringSession.GATE_SITES = IS_ENHANCED and {
    { "48 85 C9 74 4F 43 80 7C 25 69 00 74 18 80 3D ? ? ? ? 00 74 0F 89 F1 E8",       20, 0x74, 0xEB },
    { "39 44 1E 20 75 72 41 80 7C 1E 69 00 74 1B 80 3D ? ? ? ? 00 74 12 4D 8D 3C 1E", 21, 0x74, 0xEB },
} or {
    { "80 BC 1F ? ? ? ? 00 74 11 80 3D ? ? ? ? 00 74 08",                             16, 0x00, 0x01 },
}

ringSession.gates = function()
    if ringSession.gate ~= nil then return ringSession.gate end
    local out = {}
    for i, s in ipairs(ringSession.GATE_SITES) do
        local hit = Memory.Scan(s[1])
        if hit and hit ~= 0 then
            local addr = hit + s[2]
            local cur  = Memory.ReadByte(addr) & 0xFF
            if cur == s[3] then
                out[#out + 1] = { addr = addr, orig = s[3], patch = s[4] }
                Logger.LogInfo(("[VibeScript][RingSession] gate site %d @0x%X orig=0x%02X patch=0x%02X")
                    :format(i, addr, s[3], s[4]))
            else
                Logger.LogInfo(("[VibeScript][RingSession] gate site %d REJECTED @0x%X have=0x%02X want=0x%02X")
                    :format(i, addr, cur, s[3]))
            end
        else
            Logger.LogInfo(("[VibeScript][RingSession] gate site %d AOB miss (%s)")
                :format(i, IS_ENHANCED and "Enhanced" or "Legacy"))
        end
    end
    ringSession.gate = (#out > 0) and out or false
    return ringSession.gate
end

ringSession.release = function(id)
    if id then pcall(Natives.InvokeVoid, 0x353FC880830B88FA, id) end
end

ringSession.run = function()
    local gates = ringSession.gates()
    if not gates then
        ringSession.toast("Infinite Phone Ringing couldn't find the audio gate on this build.")
        return
    end

    local ped = Natives.InvokeInt(0xD80958FC74E988A6)
    if not ped or ped == 0 then
        ringSession.toast("Can't reach your ped right now.")
        return
    end

    while #ringSession.held >= ringSession.HOLD_CAP do
        ringSession.release(table.remove(ringSession.held, 1))
    end

    local id = Natives.InvokeInt(0x430386FE9BF80B45)
    if not id or id < 0 then
        ringSession.toast("No free sound slot right now - try again.")
        return
    end

    local play = function()
        Natives.InvokeVoid(0xE65F427EB70AB1ED, id, "Remote_Ring", ped,
            "Phone_SoundSet_Michael", true, false)
    end
    local spoofed = false
    if Script and Script.ExecuteAsScript then
        spoofed = pcall(Script.ExecuteAsScript, "main_persistent", play)
    end
    if not spoofed then play() end

    Script.Yield()

    for _, g in ipairs(gates) do Memory.WriteByte(g.addr, g.patch) end
    pcall(Natives.InvokeVoid, 0xA3B0C41BA5CC0BB5, id)
    for _, g in ipairs(gates) do Memory.WriteByte(g.addr, g.orig) end

    ringSession.held[#ringSession.held + 1] = id

    local restored = {}
    for _, g in ipairs(gates) do
        local b = Memory.ReadByte(g.addr) & 0xFF
        restored[#restored + 1] = ("%02X%s"):format(b, b == g.orig and "" or "!LEAK")
    end
    Logger.LogInfo(("[VibeScript][RingSession] rang ped=%d sound=%d spoofed=%s gates=%s held=%d")
        :format(ped, id, tostring(spoofed), table.concat(restored, ","), #ringSession.held))
    ringSession.toast("The session's phones are ringing. They won't stop.")
end

ringSession.runStop = function()
    local n = #ringSession.held
    if n == 0 then
        ringSession.toast("Nothing of ours is ringing.")
        return
    end
    local ped = Natives.InvokeInt(0xD80958FC74E988A6)
    if not ped or ped == 0 then
        ringSession.toast("Can't reach your ped right now.")
        return
    end

    local stopped = 0
    while #ringSession.held > 0 do
        local id = ringSession.held[1]
        local replay = function()
            Natives.InvokeVoid(0xE65F427EB70AB1ED, id, "Remote_Ring", ped,
                "Phone_SoundSet_Michael", true, 1)
        end
        if not (Script and Script.ExecuteAsScript
                and pcall(Script.ExecuteAsScript, "main_persistent", replay)) then
            replay()
        end
        Script.Yield()
        pcall(Natives.InvokeVoid, 0xA3B0C41BA5CC0BB5, id)
        table.remove(ringSession.held, 1)
        ringSession.release(id)
        stopped = stopped + 1
        Script.Yield()
    end

    Logger.LogInfo(("[VibeScript][RingSession] stop broadcast for %d sound id(s)"):format(stopped))
    ringSession.toast(("Called off %d ring%s."):format(stopped, stopped == 1 and "" or "s"))
end

Script.RegisterLooped(function()
    local tearingDown = scriptUnloading
    if not tearingDown and type(ShouldUnload) == "function" then
        local ok, due = pcall(ShouldUnload)
        tearingDown = ok and due
    end
    if tearingDown then
        if not ringSession.freed then
            ringSession.freed = true
            local n = #ringSession.held
            for i = 1, n do ringSession.release(ringSession.held[i]) end
            ringSession.held = {}
            if n > 0 then
                Logger.LogInfo(("[VibeScript][RingSession] released %d held sound id(s)"):format(n))
            end
        end
        Script.Yield(100)
        return
    end

    if ringSession.stopPending then
        ringSession.stopPending = false
        ringSession.pending = 0
        local ok, err = pcall(ringSession.runStop)
        if not ok then
            Logger.LogInfo("[VibeScript][RingSession] " .. tostring(err))
            GUI.AddToast("VibeScript", "Stop Ringing hit an error (see log).", 4000)
        end
        Script.Yield()
        return
    end

    if ringSession.pending <= 0 then Script.Yield(100) return end
    ringSession.pending = ringSession.pending - 1
    local ok, err = pcall(ringSession.run)
    if not ok then
        Logger.LogInfo("[VibeScript][RingSession] " .. tostring(err))
        GUI.AddToast("VibeScript", "Infinite Phone Ringing hit an error (see log).", 4000)
    end
    Script.Yield()
end)

FeatureMgr.AddFeature(H.RING_SESSION, "Infinite Phone Ringing", eFeatureType.Button,
    "Classic infinite phone ringing sound. Only works in your session though...",
    function() ringSession.pending = ringSession.pending + 1 end)
    :SetSaveable(false)

FeatureMgr.AddFeature(H.RING_SESSION_STOP, "Stop Ringing", eFeatureType.Button,
    "Calls off every ring you have sent this session. Only reaches rings sent from this script.",
    function() ringSession.stopPending = true end)
    :SetSaveable(false)

playerState.ringSessionReset = function()
    ringSession.pending, ringSession.stopPending = 0, false
end
end

