function TGT.level(cat)
    local t = state.tgt
    return (t and t[cat]) or TGT.D
end
function TGT.registerRange()
    if TGT.level(TGT.GANG) == TGT.A or TGT.level(TGT.NPC) == TGT.A then
        return TGT.REGISTER_RANGE
    end
    return 0
end
function TGT.huntsPlayers() return TGT.level(TGT.PLAYER) == TGT.A end
function TGT.heat()
    return TGT.level(TGT.PLAYER) + TGT.level(TGT.NPC) + TGT.level(TGT.GANG)
end


local function activeCap()
    return state.experimental and HARD_CAP or GROUP_SLOTS
end

local function boardingForced()
    return state.cabinPack
end

local boardForcedByUs = false

local function syncBoardingLock()
    local forced = boardingForced()
    local want

    if forced and not state.instantBoard then
        boardForcedByUs, want = true, true
    elseif not forced and boardForcedByUs then
        boardForcedByUs, want = false, false
    else
        return
    end

    state.instantBoard = want
    local f = FeatureMgr.GetFeature(joaat("LUA_BG_InstantBoard"))
    if f then f:SetBoolValue(want) end
end

local function instantBoardOn()
    return state.instantBoard or boardingForced()
end

local function toast(msg, ms)
    GUI.AddToast(SCRIPT_NAME, tostring(msg), ms or 2500, eToastPos.TOP_RIGHT)
end

local LOG_KEEP = 40
local logBuf = {}

local function log(msg)
    if not RS.logOn then return end
    local text = tostring(msg)
    Logger.LogInfo("[" .. SCRIPT_NAME .. "] " .. text)
    logBuf[#logBuf + 1] = text
    if #logBuf > LOG_KEEP then table.remove(logBuf, 1) end
end

local function logf(fmt, ...)
    log(string.format(fmt, ...))
end

local function logErr(msg)
    local text = tostring(msg)
    Logger.LogError("[" .. SCRIPT_NAME .. "] " .. text)
    logBuf[#logBuf + 1] = "ERROR: " .. text
    if #logBuf > LOG_KEEP then table.remove(logBuf, 1) end
end

local function nowMs()
    return math.floor(os.clock() * 1000)
end

local function entityExists(e)
    if not e or e == 0 then return false end
    return Natives.InvokeBool(N.DOES_ENTITY_EXIST, e)
end

local function requestModel(hash)
    Natives.InvokeVoid(N.REQUEST_MODEL, hash)
    for _ = 1, 100 do
        if Natives.InvokeBool(N.HAS_MODEL_LOADED, hash) then return true end
        Script.Yield(10)
    end
    return false
end

local PTR = {
    aimEnt  = Memory.AllocInt(),
    delete  = Memory.AllocInt(),
    blip    = Memory.AllocInt(),
    grpLead = Memory.AllocInt(),
    grpSize = Memory.AllocInt(),
}

local function removeBlipSafe(blip)
    if not blip or blip == 0 then return end
    Memory.WriteInt(PTR.blip, blip)
    Natives.InvokeVoid(N.REMOVE_BLIP, PTR.blip)
end

local function despawnPed(handle, netId)
    if not entityExists(handle) then return end

    Natives.InvokeVoid(N.NETWORK_REQUEST_CONTROL_OF_ENTITY, handle)

    Natives.InvokeVoid(N.DETACH_ENTITY, handle, true, false)

    if netId then
        Natives.InvokeVoid(N.SET_NETWORK_ID_CAN_MIGRATE, netId, true)
    end
    if Natives.InvokeBool(N.NETWORK_GET_ENTITY_IS_NETWORKED, handle) then
        Natives.InvokeVoid(N.NETWORK_UNREGISTER_NETWORKED_ENTITY, handle)
    end

    Natives.InvokeVoid(N.SET_ENTITY_AS_MISSION, handle, true, true)
    Memory.WriteInt(PTR.delete, handle)
    Natives.InvokeVoid(N.DELETE_ENTITY, PTR.delete)

    if entityExists(handle) then
        Memory.WriteInt(PTR.delete, handle)
        Natives.InvokeVoid(N.SET_PED_AS_NO_LONGER_NEEDED, PTR.delete)
    end
end

local function myPed()
    return Natives.InvokeInt(N.PLAYER_PED_ID)
end

local function myId()
    return Natives.InvokeInt(N.PLAYER_ID)
end

local function myCoords()
    return Natives.InvokeV3(N.GET_ENTITY_COORDS, myPed(), true)
end

local function playerGroup()
    local g = Natives.InvokeInt(N.GET_PLAYER_GROUP, myId())
    if g then return g end
    return 0
end

local function groupFollowerCount(grp)
    local n = -1
    Memory.WriteInt(PTR.grpLead, 0)
    Memory.WriteInt(PTR.grpSize, 0)
    Natives.InvokeVoid(N.GET_GROUP_SIZE, grp, PTR.grpLead, PTR.grpSize)
    n = Memory.ReadInt(PTR.grpSize)
    return n
end


local function ringSlot(i, baseR, spacing)
    local r = baseR
    local rem = i
    for _ = 1, 16 do
        local cap = math.max(1, math.floor((2 * math.pi * r) / spacing))
        if rem < cap then
            local ang = math.pi + (rem / cap) * math.pi * 2
            return math.sin(ang) * r, math.cos(ang) * r
        end
        rem = rem - cap
        r = r + spacing
    end
    return 0.0, -baseR
end

PTR.groundZ = Memory.Alloc(4)

local function groundZ(x, y, z)
    local hit = false
    hit = Natives.InvokeBool(N.GET_GROUND_Z_FOR_3D_COORD,
        x, y, z + 2.0, PTR.groundZ, false, false)
    if hit then
        local g = Memory.ReadFloat(PTR.groundZ)
        if g and math.abs(g - z) < 25.0 then return g + 0.25 end
    end
    return z + 0.25
end

local PROBE_FROM_Z        = 1000.0
local UNDER_GROUND_MARGIN = 5.0

PTR.probe = Memory.Alloc(4)

local function isUnderground(bx, by, bz)
    local hit = false
    hit = Natives.InvokeBool(N.GET_GROUND_Z_FOR_3D_COORD,
        bx, by, PROBE_FROM_Z, PTR.probe, false, false)
    if not hit then return false, nil end

    local g = Memory.ReadFloat(PTR.probe)
    if not g then return false, nil end
    return bz < (g - UNDER_GROUND_MARGIN), g
end

local function groundZFar(x, y, z)
    local hit = false
    hit = Natives.InvokeBool(N.GET_GROUND_Z_FOR_3D_COORD,
        x, y, z + 2.0, PTR.groundZ, false, false)
    if hit then
        local g = Memory.ReadFloat(PTR.groundZ)
        if g and g > UNDERMAP_Z then return g + 0.25, true end
    end
    return z + 0.25, false
end

local function formationOffset(slot, total, formValue)
    local n = math.max(total, 1)

    if formValue == 1 then
        local r = math.max(3.0, (n * FORM_SPACING) / (2 * math.pi))
        local ang = math.pi + (slot / n) * math.pi * 2
        return math.sin(ang) * r, math.cos(ang) * r

    elseif formValue == 2 then
        local DEPTH = 2.2
        local ahead  = (slot % 2 == 1)
        local idx    = math.floor(slot / 2)
        local behind = math.ceil(n / 2)
        local ranked = math.max(1, ahead and (n - behind) or behind)
        local x = (idx - (ranked - 1) * 0.5) * FORM_SPACING
        return x, ahead and DEPTH or -DEPTH

    elseif formValue == 3 then
        local ARM = 5
        local pair  = math.floor(slot / 2)
        local side  = (slot % 2 == 0) and -1.0 or 1.0
        local pos   = pair % ARM
        local layer = math.floor(pair / ARM)
        local x = side * (pos + 1) * FORM_SPACING * 0.6
        local y = -((pos + 1) * FORM_SPACING * 0.65 + layer * FORM_SPACING * 1.4)
        return x, y

    elseif formValue == 4 then
        local files = (n > 12) and 4 or 2
        local file  = slot % files
        local idx   = math.floor(slot / files)
        local lane  = math.floor(file / 2) + 1
        local side  = (file % 2 == 0) and -1.0 or 1.0
        return side * FORM_SPACING * (0.9 + (lane - 1) * 0.9), -(1.6 + idx * FORM_SPACING)
    end

    return ringSlot(slot, 3.0, FORM_SPACING)
end

local function currentFormationValue()
    local f = FORMATIONS[state.formIdx + 1]
    return f and f.v or 0
end

function FORMATIONS.groupValue()
    local f = FORMATIONS[state.formIdx + 1]
    return f and f.eng or 0
end


local HOSTILE_GROUPS = {
    "AMBIENT_GANG_LOST", "AMBIENT_GANG_MEXICAN",
    "AMBIENT_GANG_FAMILY", "AMBIENT_GANG_BALLAS",
    "AMBIENT_GANG_MARABUNTE", "AMBIENT_GANG_CULT",
    "AMBIENT_GANG_SALVA", "AMBIENT_GANG_WEICHENG",
    "AMBIENT_GANG_HILLBILLY", "HATES_PLAYER",
    "COP", "ARMY", "GUARD_DOG", "SECURITY_GUARD",
    "PRISONER", "FIREMAN",
}

TGT.HOSTILE_SET = {}
for _, groupName in ipairs(HOSTILE_GROUPS) do TGT.HOSTILE_SET[joaat(groupName)] = true end

function TGT.classify(ent, pPed)
    if not ent or ent == 0 or ent == pPed then return nil end
    if Natives.InvokeBool(N.IS_PED_A_PLAYER, ent) then return TGT.PLAYER end
    local rel = Natives.InvokeInt(N.GET_PED_RELATIONSHIP_GROUP_HASH, ent)
    if bgGroupHash and rel == bgGroupHash then return nil end
    if TGT.HOSTILE_SET[rel] then return TGT.GANG end
    return TGT.NPC
end

function TGT.isProtectedPlayer(ent)
    if not state.disableFriendOrgTargeting or not ent or ent == 0
       or not Natives.InvokeBool(N.IS_PED_A_PLAYER, ent) then
        return false
    end
    local pid = Natives.InvokeInt(N.NETWORK_GET_PLAYER_INDEX_FROM_PED, ent)
    return pid and pid >= 0 and pid < 32
       and lockOntoPlayers.isProtected(pid, ent) == true
end

function TGT.markFiring(pPed, now)
    if pPed and pPed ~= 0 and Natives.InvokeBool(N.IS_PED_SHOOTING, pPed) then
        local firstFrame = not TGT.ownerFighting(now)
        TGT.firedAt = now

        if firstFrame then
            local released = 0
            for _, bg in ipairs(guards) do
                if bg.deafUntil and entityExists(bg.handle) then
                    bg.deafUntil = nil
                    Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS,
                        bg.handle, false)
                    released = released + 1
                end
            end
            if RS.logOn then
                logf("hip fire: opened %d Passive guard(s) before candidate scan", released)
            end
        end
    end
end
function TGT.ownerFighting(now)
    return (now - (TGT.firedAt or -1e9)) < TGT.FIRE_GRACE_MS
end

function TGT.releaseDeaf(bg, now)
    if not bg.deafUntil or bg.deafUntil > now then return end
    bg.deafUntil = nil
    Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, bg.handle, false)
end

function TGT.filter(bg, pPed, now)
    if bg.deafUntil then return false end

    local tgtEnt = Natives.InvokeInt(N.GET_PED_TARGET_FROM_COMBAT_PED, bg.handle, 0)

    if TGT.isProtectedPlayer(tgtEnt) then
        Natives.InvokeVoid(N.CLEAR_PED_TASKS, bg.handle)
        Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, bg.handle, true)
        bg.huntTarget, bg.orderedFor, bg.aimTaskFor = nil, nil, nil
        bg.aimTaskAt, bg.followAt, bg.wasInCombat = 0, 0, false

        if (bg.vetoRunAt or 0) + (TGT.DEAF_MAX_MS * 2) < now then bg.vetoRun = 0 end
        bg.vetoRun = (bg.vetoRun or 0) + 1
        bg.vetoRunAt = now
        local wait = math.min(TGT.DEAF_MAX_MS,
            (TGT.DEAF_MS * (2 ^ math.min(8, bg.vetoRun - 1))) // 1)
        bg.deafUntil = now + wait

        if RS.logOn and (now - TGT.traceAt) > 1000 then
            TGT.traceAt = now
            logf("filter: ped=%d protected-player=%d stand-down=%dms",
                bg.handle, tgtEnt, wait)
        end
        return true
    end
    local cat = TGT.classify(tgtEnt, pPed)

    if tgtEnt and tgtEnt ~= 0
       and Natives.InvokeBool(N.IS_ENTITY_DEAD, tgtEnt, false) then
        Natives.InvokeVoid(N.CLEAR_PED_TASKS, bg.handle)
        bg.orderedFor, bg.aimTaskFor, bg.wasInCombat = nil, nil, false
        bg.sweepAt, bg.followAt = 0, 0
        if RS.logOn then
            logf("combat retarget: ped=%d dropped dead target=%d", bg.handle, tgtEnt)
        end
        return true
    end

    if RS.logOn and (now - TGT.traceAt) > 1000 then
        TGT.traceAt = now
        logf("filter: ped=%d tgt=%d cat=%s lvl=%s ord=%s shooting=%s",
            bg.handle, tgtEnt or -1, tostring(cat),
            cat and tostring(TGT.level(cat)) or "-",
            tostring(bg.orderedFor), tostring(TGT.ownerFighting(now)))
    end

    if not cat then return false end

    if bg.orderedFor then
        if not entityExists(bg.orderedFor)
           or Natives.InvokeBool(N.IS_ENTITY_DEAD, bg.orderedFor, false) then
            bg.orderedFor = nil
        elseif bg.orderedFor == tgtEnt then
            return false
        else
            bg.orderedFor = nil
        end
    end

    if TGT.ownerFighting(now) then
        bg.orderedFor = tgtEnt
        return false
    end

    local lvl = TGT.level(cat)
    if lvl ~= TGT.P then return false end

    Natives.InvokeVoid(N.CLEAR_PED_TASKS, bg.handle)
    Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, bg.handle, true)

    if (bg.vetoRunAt or 0) + (TGT.DEAF_MAX_MS * 2) < now then bg.vetoRun = 0 end
    bg.vetoRun = (bg.vetoRun or 0) + 1
    bg.vetoRunAt = now
    local wait = math.min(TGT.DEAF_MAX_MS,
        (TGT.DEAF_MS * (2 ^ math.min(8, bg.vetoRun - 1))) // 1)

    bg.deafUntil = now + wait
    bg.followAt, bg.aimTaskFor, bg.wasInCombat = 0, nil, false
    TGT.vetoes = TGT.vetoes + 1
    TGT.vetoCat[cat] = (TGT.vetoCat[cat] or 0) + 1
    return true
end

local function bindRelationships(pHash)
    if not bgGroupHash or not pHash then return end

    Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, 0, bgGroupHash, pHash)
    Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, 0, pHash, bgGroupHash)

    local genericPlayer = joaat("PLAYER")
    if genericPlayer ~= pHash then
        Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, 0, bgGroupHash, genericPlayer)
        Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, 0, genericPlayer, bgGroupHash)
    end

    Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, 0, bgGroupHash, bgGroupHash)

    local gangRel = (TGT.level(TGT.GANG) == TGT.A) and 5 or 2
    for _, groupName in ipairs(HOSTILE_GROUPS) do
        local gh = joaat(groupName)
        Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, gangRel, bgGroupHash, gh)
        Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, gangRel, gh, bgGroupHash)
    end

    local civilianGroups = { "CIVMALE", "CIVFEMALE" }
    local civRel = (TGT.level(TGT.NPC) == TGT.A) and 5 or 2
    for _, groupName in ipairs(civilianGroups) do
        local gh = joaat(groupName)
        Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, civRel, bgGroupHash, gh)
        Natives.InvokeVoid(N.SET_RELATIONSHIP_BETWEEN_GROUPS, civRel, gh, bgGroupHash)
    end
end

local function readPlayerRelHash()
    local hash = Natives.InvokeInt(N.GET_PED_RELATIONSHIP_GROUP_HASH, myPed())
    if hash and hash ~= 0 then return hash end
    return joaat("PLAYER")
end

function preview.destroy()
    if preview.ped == 0 then return end
    local ped = preview.ped
    preview.ped, preview.key = 0, nil
    preview.prevRel = nil
    preview.relLead = nil
    preview.weaponHash = nil
    preview.primaryHash = nil
    preview.secondaryHash = nil
    preview.loadoutKey = nil
    Memory.WriteInt(PTR.delete, ped)
    Natives.InvokeVoid(N.DELETE_ENTITY, PTR.delete)
    if preview.hdArea then
        Natives.InvokeVoid(N.CLEAR_HD_AREA)
        preview.hdArea = false
    end
end

function preview.key_now()
    local cat = MODELS[state.catIdx + 1]
    local m = cat and cat[state.modelIdx + 1]
    return m and m.h or nil
end

preview.DIST = 3.1 / 0.95
preview.SIDE = preview.DIST * 0.39
preview.DROP = preview.DIST * 0.292

preview.VARY_MS = 1500

preview.ALPHA = 255

preview.SPIN_DPS = 0.0
preview.POSE_DICT = "amb@world_human_hang_out_street@male_a@base"
preview.POSE_CLIP = "base"

function preview.playIdle()
    local key = preview.key or ""
    if key:sub(1, 4) == "a_c_" then return end

    local dict, clip = preview.POSE_DICT, preview.POSE_CLIP
    if not Natives.InvokeBool(N.HAS_ANIM_DICT_LOADED, dict) then
        Natives.InvokeVoid(N.REQUEST_ANIM_DICT, dict)
        return
    end

    if not Natives.InvokeBool(N.IS_ENTITY_PLAYING_ANIM, preview.ped, dict, clip, 3) then
        Natives.InvokeVoid(N.TASK_PLAY_ANIM, preview.ped,
            dict, clip, 3.0, -3.0, -1, 1, 1.0, false, false, false)
    end
end

local PREVIEW_MELEE = {
    [0x99B507EA] = true, [0x958A4A8F] = true,
    [0xDD5DF8D9] = true, [0xCD274149] = true,
    [1737195953] = true, [1317494643] = true, [1141786504] = true,
    [2227010557] = true, [4192643659] = true, [1703483498] = true,
    [2460120199] = true, [4191993645] = true, [3638508604] = true,
    [2343591895] = true, [3756226112] = true, [419712736] = true,
    [2484171525] = true, [940833800] = true, [3670016037] = true,
    [2481070269] = true, [741814745] = true, [4256991824] = true,
    [2694266206] = true, [615608432] = true, [600439132] = true,
    [1233104067] = true, [4159824478] = true, [126349499] = true,
    [2874559379] = true, [3125143736] = true, [2663087251] = true,
}
local PREVIEW_NO_RELOAD = {
    [0xB1CA77B1] = true,
    [0x42BF8A85] = true,
    [0xA284510B] = true,
    [1305664598] = true, [4272043364] = true, [3056410471] = true,
    [1672152130] = true, [2138347493] = true, [1834241177] = true,
    [125959754] = true, [3676729658] = true, [62870901] = true,
}

function preview.animate(now)
    local hash = preview.weaponHash or 0
    if preview.animMode == "aim" then
        if now < (preview.aimUntil or 0) then return end
        preview.animMode = "idle"
        preview.nextAimAt = now + math.random(7000, 11000)
        preview.playIdle()
        return
    elseif preview.animMode == "holster" then
        if now < (preview.animUntil or 0) then return end
        preview.animMode = "holstered"
        preview.animUntil = now + 1200
        return
    elseif preview.animMode == "holstered" then
        if now < (preview.animUntil or 0) then return end
        local other = (preview.weaponHash == preview.primaryHash)
            and preview.secondaryHash or preview.primaryHash
        if other and other ~= 0 and other ~= preview.weaponHash then
            preview.weaponHash = other
            Natives.InvokeVoid(N.SET_CURRENT_PED_WEAPON, preview.ped, other, false)
        end
        Natives.InvokeVoid(N.TASK_SWAP_WEAPON, preview.ped, true)
        preview.animMode = "draw"
        preview.animUntil = now + 1900
        return
    elseif preview.animMode == "draw" then
        if now < (preview.animUntil or 0) then return end
        preview.animMode = "settle"
        preview.animUntil = now + 900
        return
    elseif preview.animMode == "reload" then
        if now < (preview.animUntil or 0) then return end
        preview.animMode = "settle"
        preview.animUntil = now + 700
        return
    elseif preview.animMode == "settle" then
        if now < (preview.animUntil or 0) then return end
        preview.animMode = "idle"
        preview.nextAimAt = now + math.random(7000, 11000)
        preview.playIdle()
        return
    end

    preview.playIdle()
    if hash == 0 or now < (preview.nextAimAt or 0) then return end

    if PREVIEW_MELEE[hash] then
        if preview.primaryHash ~= preview.secondaryHash then
            Natives.InvokeVoid(N.TASK_SWAP_WEAPON, preview.ped, false)
            preview.animMode = "holster"
            preview.animUntil = now + 1900
            preview.nextShowcase = "aim"
        end
        return
    end

    if preview.nextShowcase == "holster" then
        Natives.InvokeVoid(N.TASK_SWAP_WEAPON, preview.ped, false)
        preview.animMode = "holster"
        preview.animUntil = now + 1900
        preview.nextShowcase = "aim"
        return
    end
    if not PREVIEW_NO_RELOAD[hash] and preview.nextShowcase == "reload" then
        Natives.InvokeVoid(N.TASK_RELOAD_WEAPON, preview.ped, true)
        preview.animMode = "reload"
        preview.animUntil = now + 3200
        preview.nextShowcase = "holster"
        return
    end
    preview.nextShowcase = PREVIEW_NO_RELOAD[hash] and "holster" or "reload"

    local cx, cy, cz = Natives.InvokeV3(N.GET_FINAL_RENDERED_CAM_COORD)
    if not cx then return end
    local variant = math.random(1, 3)
    local side = (variant == 1 and -0.8) or (variant == 2 and 0.8) or 0.0
    local lift = (variant == 3 and 0.65) or 0.15
    Natives.InvokeVoid(N.TASK_AIM_GUN_AT_COORD, preview.ped,
        cx + side, cy, cz + lift, 3400, false, false)
    preview.animMode = "aim"
    preview.aimUntil = now + 3700
end

function preview.syncWeapon()
    local key = preview.key or ""
    if key:sub(1, 4) == "a_c_" then return end

    local primary = WEAPON_LIST[state.weaponIdx + 1]
    local secondary = (state.weapon2Idx or 0) > 0
        and WEAPON_LIST[state.weapon2Idx] or nil
    local primaryHash = primary and primary.h or 0
    local secondaryHash = secondary and secondary.h or PISTOL_HASH
    local loadoutKey = tostring(primaryHash) .. ":" .. tostring(secondaryHash)
    if preview.loadoutKey == loadoutKey then return end
    preview.loadoutKey = loadoutKey
    preview.primaryHash = primaryHash
    preview.secondaryHash = secondaryHash
    preview.weaponHash = primaryHash
    preview.animMode = "idle"
    preview.aimUntil = 0
    preview.animUntil = 0
    preview.nextShowcase = "holster"
    preview.nextAimAt = nowMs() + math.random(5000, 8000)

    Natives.InvokeVoid(N.REMOVE_ALL_PED_WEAPONS, preview.ped, true)
    if primaryHash == 0 then return end
    Natives.InvokeVoid(N.GIVE_WEAPON_TO_PED, preview.ped, primaryHash, 30, false, true)
    if secondaryHash ~= 0 and secondaryHash ~= primaryHash then
        Natives.InvokeVoid(N.GIVE_WEAPON_TO_PED, preview.ped, secondaryHash, 30, false, false)
    end
    Natives.InvokeVoid(N.SET_CURRENT_PED_WEAPON, preview.ped, primaryHash, true)
    Natives.InvokeVoid(N.SET_PED_CAN_SWITCH_WEAPON, preview.ped, false)
    Natives.InvokeVoid(N.SET_PED_DROPS_WEAPONS_WHEN_DEAD, preview.ped, false)
end

function preview.place()
    local cx, cy, cz = Natives.InvokeV3(N.GET_FINAL_RENDERED_CAM_COORD)
    if not cx then return nil end

    local anchor = myPed()
    if entityExists(anchor) and
       not Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, anchor, false) then
        local ax, ay, az = Natives.InvokeV3(N.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS,
                                            anchor, 0.0, 0.0, 0.0)
        if ax then
            local rx, ry, rz = cx - ax, cy - ay, cz - az
            local pr = preview.prevRel
            if pr then
                local dx, dy, dz = rx - pr.x, ry - pr.y, rz - pr.z
                if (dx * dx + dy * dy + dz * dz) <= 1.0 then
                    local lead = preview.relLead or { x = 0.0, y = 0.0, z = 0.0 }
                    lead.x = lead.x * 0.72 + dx * 0.28
                    lead.y = lead.y * 0.72 + dy * 0.28
                    lead.z = lead.z * 0.72 + dz * 0.28
                    local mag2 = lead.x * lead.x + lead.y * lead.y + lead.z * lead.z
                    if mag2 > 0.0144 then
                        local k = 0.12 / math.sqrt(mag2)
                        lead.x, lead.y, lead.z = lead.x * k, lead.y * k, lead.z * k
                    end
                    preview.relLead = lead
                    cx, cy, cz = cx + lead.x, cy + lead.y, cz + lead.z
                end
            end
            preview.prevRel = { x = rx, y = ry, z = rz }
        end
    else
        preview.prevRel = nil
        preview.relLead = nil
    end

    local pitch, _, yaw = Natives.InvokeV3(N.GET_FINAL_RENDERED_CAM_ROT, 2)
    if not yaw then return nil end

    local ry, rp = math.rad(yaw), math.rad(pitch)
    local cp = math.cos(rp)
    local fx, fy, fz = -math.sin(ry) * cp, math.cos(ry) * cp, math.sin(rp)
    local rx, rry    =  math.cos(ry),     math.sin(ry)

    return cx + fx * preview.DIST + rx  * preview.SIDE,
           cy + fy * preview.DIST + rry * preview.SIDE,
           cz + fz * preview.DIST - preview.DROP,
           pitch, yaw
end

function preview.lean(pitch, yaw, spin)
    local P, Y, s = math.rad(pitch), math.rad(yaw), math.rad(spin)
    local sP, cP = math.sin(P), math.cos(P)
    local sY, cY = math.sin(Y), math.cos(Y)
    local ss, cs = math.sin(s), math.cos(s)

    local bz = -sP * cs
    local bx =  sY * cP * cs + cY * ss
    local by = -cY * cP * cs + sY * ss
    local az = -sP * ss
    local cz =  cP

    if bz >  1.0 then bz =  1.0 end
    if bz < -1.0 then bz = -1.0 end

    return math.deg(math.asin(bz)),
           math.deg(math.atan(-az, cz)),
           math.deg(math.atan(-bx, by))
end

function preview.pin(spin)
    if preview.ped == 0 then return end

    local playerPed = myPed()
    if not entityExists(playerPed) then return end

    local x, y, z, pitch, yaw = preview.place()
    if not x then return end

    local rotX, rotY, rotZ = preview.lean(pitch, yaw, spin)

    local inVehicle = Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, playerPed, false)
    local firstPerson = inVehicle
        and Natives.InvokeInt(N.GET_FOLLOW_VEHICLE_CAM_VIEW_MODE) == 4
        or (not inVehicle and Natives.InvokeInt(N.GET_FOLLOW_PED_CAM_VIEW_MODE) == 4)
    local anchor = playerPed
    if firstPerson and inVehicle then
        local vehicle = Natives.InvokeInt(N.GET_VEHICLE_PED_IS_IN, playerPed, false)
        if entityExists(vehicle) then anchor = vehicle end
    elseif firstPerson then
        Natives.InvokeVoid(N.DETACH_ENTITY, preview.ped, true, false)
        Natives.InvokeVoid(N.SET_ENTITY_COORDS_NO_OFFSET, preview.ped,
            x, y, z + preview.rootLift, false, false, false)
        Natives.InvokeVoid(N.SET_ENTITY_ROTATION, preview.ped,
            rotX, rotY, rotZ, 2, true)
        return
    end

    local ax, ay, az = Natives.InvokeV3(N.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS,
                                        anchor, 0.0, 0.0, 0.0)
    if not ax then return end

    Natives.InvokeVoid(N.ATTACH_ENTITY_TO_ENTITY,
        preview.ped, anchor, -1,
        x - ax, y - ay, (z + preview.rootLift) - az,
        rotX, rotY, rotZ,
        false,
        false,
        false,
        true,
        2,
        false,
        false)

    if not preview.pinnedAt then
        preview.pinnedAt = nowMs()
        logf("Preview pinned: anchor=%d attachedTo=%d lift=%.2f", anchor,
            Natives.InvokeInt(N.GET_ENTITY_ATTACHED_TO, preview.ped) or 0, preview.rootLift)
    end
end

preview.LINGER_MS = 50

preview.REQ_MS = 100

function preview.modelReady(hash)
    if Natives.InvokeBool(N.HAS_MODEL_LOADED, hash) then return true end
    local now = nowMs()
    if hash ~= preview.reqFor or now - (preview.reqAt or 0) > preview.REQ_MS then
        preview.reqFor, preview.reqAt = hash, now
        Natives.InvokeVoid(N.REQUEST_MODEL, hash)
    end
    return false
end

function preview.update()
    local want = state.showPreview and not isShuttingDown and GUI.IsOpen()
        and (nowMs() - preview.seenAt) < preview.LINGER_MS
        and not Natives.InvokeBool(N.IS_CINEMATIC_IDLE_CAM_RENDERING)

    if not want then preview.destroy() return end

    local key = preview.key_now()
    if not key then preview.destroy() return end

    if key ~= preview.key or not entityExists(preview.ped) then
        preview.destroy()
        local hash = joaat(key)
        if not preview.modelReady(hash) then return end

        local x, y, z = preview.place()
        if not x then return end

        local ped = GTA.CreatePed(hash, 26, x, y, z, 0.0, false, false)
        Natives.InvokeVoid(N.SET_MODEL_NO_LONGER, hash)
        if not ped or ped == 0 then return end

        preview.ped, preview.key = ped, key
        Natives.InvokeVoid(N.SET_ENTITY_COORDS, ped, x, y, z, false, false, false, false)
        local _, _, rootZ = Natives.InvokeV3(N.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS, ped, 0.0, 0.0, 0.0)
        local lift = (rootZ or z) - z
        preview.rootLift = (lift >= 0.0 and lift <= 1.5) and lift or 0.0
        preview.pinnedAt = nil
        Natives.InvokeVoid(N.FREEZE_ENTITY_POSITION, ped, true)
        Natives.InvokeVoid(N.SET_ENTITY_INVINCIBLE, ped, true)
        Natives.InvokeVoid(N.SET_ENTITY_COLLISION, ped, false, false)
        Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, ped, true)
        Natives.InvokeVoid(N.SET_PED_CAN_RAGDOLL, ped, false)
        Natives.InvokeVoid(N.SET_PED_LEG_IK_MODE, ped, 0)
        Natives.InvokeVoid(N.SET_PED_CAN_PLAY_AMBIENT_ANIMS, ped, false)
        Natives.InvokeVoid(N.SET_PED_CAN_PLAY_AMBIENT_BASE_ANIMS, ped, false)
        Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.NEVER_LEAVES_GROUP, true)
        Natives.InvokeVoid(N.CLEAR_PED_TASKS_IMMEDIATELY, ped)
        Natives.InvokeVoid(N.SET_ENTITY_ALPHA, ped, preview.ALPHA, false)
        Natives.InvokeVoid(N.SET_ENTITY_MOTION_BLUR, ped, false)
        Natives.InvokeVoid(N.SET_ENTITY_ALWAYS_PRERENDER, ped, true)
        Natives.InvokeVoid(N.SET_ENTITY_LOD_DIST, ped, 0xFFFF)
        Natives.InvokeVoid(N.SET_PED_LOD_MULTIPLIER, ped, 100.0)
        preview.varAt = 0
        preview.spinAt = nil
        preview.weaponHash = nil
        preview.primaryHash = nil
        preview.secondaryHash = nil
        preview.loadoutKey = nil
        preview.animMode = "idle"
        preview.aimUntil = 0
        preview.animUntil = 0
        preview.nextShowcase = "holster"
        preview.nextAimAt = nowMs() + math.random(5000, 8000)
    end

    if preview.ped == 0 then return end

    Natives.InvokeVoid(N.SET_ENTITY_MOTION_BLUR, preview.ped, false)
    Natives.InvokeVoid(N.SET_ENTITY_ALWAYS_PRERENDER, preview.ped, true)
    Natives.InvokeVoid(N.SET_ENTITY_LOD_DIST, preview.ped, 0xFFFF)
    Natives.InvokeVoid(N.SET_PED_LOD_MULTIPLIER, preview.ped, 100.0)
    Natives.InvokeVoid(N.REQUEST_PED_VISIBILITY_TRACKING, preview.ped)
    local hx, hy, hz = Natives.InvokeV3(N.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS,
                                        preview.ped, 0.0, 0.0, 0.0)
    if hx then
        Natives.InvokeVoid(N.SET_HD_AREA, hx, hy, hz, 4.0)
        preview.hdArea = true
    end
    Natives.InvokeVoid(N.SET_PED_CAN_PLAY_AMBIENT_ANIMS, preview.ped, false)
    Natives.InvokeVoid(N.SET_PED_CAN_PLAY_AMBIENT_BASE_ANIMS, preview.ped, false)
    Natives.InvokeVoid(N.SET_PED_MOVE_ANIMS_BLEND_OUT, preview.ped)
    preview.syncWeapon()

    local now = nowMs()
    preview.animate(now)
    if now - (preview.varAt or 0) > preview.VARY_MS then
        preview.varAt = now
        Natives.InvokeVoid(N.SET_PED_RANDOM_COMPONENT_VARIATION, preview.ped, 0)
        Natives.InvokeVoid(N.SET_PED_RANDOM_PROPS, preview.ped)
        Natives.InvokeVoid(N.SET_ENTITY_ALPHA, preview.ped, preview.ALPHA, false)
    end

    preview.spinAt = now

    preview.pin(preview.heading)
end

local function initRelationships()
    if bgGroupHash then return end

    Script.QueueJob(function()
        local ptr = Memory.AllocInt()
        if not ptr or ptr == 0 then
            bgGroupHash = joaat("PLAYER")
            playerRelHash = readPlayerRelHash()
            bindRelationships(playerRelHash)
            log("WARN: Relationship-group allocation failed; using PLAYER fallback")
            return
        end
        Memory.WriteInt(ptr, 0)
        Natives.InvokeBool(N.ADD_RELATIONSHIP_GROUP, "BG_SQUAD_V4", ptr)
        bgGroupHash = Memory.ReadInt(ptr)
        Memory.Free(ptr)

        if not bgGroupHash or bgGroupHash == 0 then
            bgGroupHash = joaat("PLAYER")
            log("WARN: Using PLAYER group fallback")
        end

        playerRelHash = readPlayerRelHash()
        bindRelationships(playerRelHash)
        log("Relationships initialised (bg=" .. tostring(bgGroupHash) ..
            " player=" .. tostring(playerRelHash) .. ")")
    end)
end


local function tryJoinGroup(bg, grp)
    if not grp or grp == 0 then return false end
    Natives.InvokeVoid(N.SET_PED_AS_GROUP_MEMBER, bg.handle, grp)
    Natives.InvokeVoid(N.SET_PED_NEVER_LEAVES_GROUP, bg.handle, true)
    Natives.InvokeVoid(N.SET_GROUP_SEPARATION_RANGE, grp, 9999.0)

    local isMember = Natives.InvokeBool(N.IS_PED_GROUP_MEMBER, bg.handle, grp)
    if isMember then
        bg.tier = 1
        bg.groupMissCount = 0
        return true
    end
    return false
end

local function applyTeleportFlag(bg)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, bg.handle,
        PCF.TELEPORT_IF_CANT_REACH_PLAYER, bg.tier == 1 and state.autoTeleport)
end

local function liveTier1Count()
    local n = 0
    for _, bg in ipairs(guards) do
        if bg.tier == 1 then n = n + 1 end
    end
    return n
end

local function reconcileTiers(grp)
    if not grp or grp == 0 then return end

    for _, bg in ipairs(guards) do
        if bg.tier == 1 and entityExists(bg.handle) then
            local isMember = Natives.InvokeBool(N.IS_PED_GROUP_MEMBER, bg.handle, grp)
            if not isMember then
                bg.groupMissCount = (bg.groupMissCount or 0) + 1
                if bg.groupMissCount >= 3 then
                    bg.tier = 2
                    bg.followAt = 0
                end
            else
                bg.groupMissCount = 0
            end
        end
    end

    lastGroupSize = groupFollowerCount(grp)

    local free = GROUP_SLOTS - liveTier1Count()
    if free <= 0 then return end

    for _, bg in ipairs(guards) do
        if free <= 0 then break end
        if bg.tier == 2 and entityExists(bg.handle) then
            if tryJoinGroup(bg, grp) then
                free = free - 1
            end
        end
    end
end


local function applyFriendlyProtection(ped, pPed, pId)
    if bgGroupHash then
        Natives.InvokeVoid(N.SET_PED_RELATIONSHIP_GROUP_HASH, ped, bgGroupHash)
    end

    Natives.InvokeVoid(N.SET_CAN_ATTACK_FRIENDLY, ped, false, false)

    Natives.InvokeVoid(N.SET_ENTITY_PROOFS, ped,
        false, false, false, false, false, false, false, false)
    Natives.InvokeVoid(N.SET_PED_CAN_BE_TARGETTED, ped, true)

    Natives.InvokeVoid(N.SET_PED_CAN_BE_TARGETTED_BY_PLAYER,
        ped, pId, not state.immuneToMe)

    if playerRelHash then
        Natives.InvokeVoid(N.SET_ENTITY_CAN_BE_DAMAGED_BY_RELATIONSHIP_GROUP,
            ped, not state.immuneToMe, playerRelHash)
    end

    Natives.InvokeVoid(N.SET_PED_CAN_BE_TARGETTED_BY_TEAM, ped, pId, true)
end

local function applyHealth(ped, heal)
    if not entityExists(ped) then return end

    local base  = baseHealth[ped] or DEFAULT_PED_HEALTH
    local floorHp = base * DYING_FRACTION
    local want  = math.floor(floorHp + (base - floorHp) * state.healthPct / 100 + 0.5)
    if want <= floorHp then want = math.floor(floorHp) + 1 end

    Natives.InvokeVoid(N.SET_PED_MAX_HEALTH, ped, want)

    local cur = want
    cur = Natives.InvokeInt(N.GET_ENTITY_HEALTH, ped) or want

    if cur <= 0 then return end

    if heal or cur > want then
        Natives.InvokeVoid(N.SET_ENTITY_HEALTH, ped, want, 0, 0)
    end
end

local function applySettings(ped, packed)
    if not entityExists(ped) then return end

    applyFriendlyProtection(ped, myPed(), myId())

    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.NO_CRITICAL_HITS, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.IGNORE_BEING_ON_FIRE, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.NEVER_LEAVES_GROUP, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped,
        PCF.DONT_INFLUENCE_WANTED_LEVEL, state.neverWanted)
    Natives.InvokeVoid(N.SET_PED_SUFFERS_CRITICAL_HITS, ped, false)

    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.DISABLE_EVASIVE_DIVES, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.BLOCK_WEAPON_SWITCHING, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.DISABLE_EXPLOSION_REACTIONS, true)
    RS.ragdollApply(ped, packed)

    Natives.InvokeVoid(N.SET_PED_FLEE_ATTRIBUTES, ped, 0, false)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.DISABLE_SHOCKING_EVENTS, true)
    Natives.InvokeVoid(N.SET_PED_CONFIG_FLAG, ped, PCF.DISABLE_PANIC_IN_VEHICLE, true)

    local sight = PERCEPTION_RANGE
    Natives.InvokeVoid(N.SET_PED_HIGHLY_PERCEPTIVE, ped, true)
    Natives.InvokeVoid(N.SET_PED_SEEING_RANGE, ped, sight)
    Natives.InvokeVoid(N.SET_PED_HEARING_RANGE, ped, sight)
    Natives.InvokeVoid(N.SET_PED_ID_RANGE, ped, sight)

    Natives.InvokeVoid(N.SET_ENTITY_INVINCIBLE, ped, state.godMode)
    applyHealth(ped, false)

    Natives.InvokeVoid(N.SET_ENTITY_VISIBLE, ped, not state.invisible)
    if not state.invisible then
        Natives.InvokeVoid(N.SET_ENTITY_ALPHA, ped, 255, false)
    end

    do
        Natives.InvokeVoid(N.SET_PED_COMBAT_ABILITY, ped, 2)
        Natives.InvokeVoid(N.SET_PED_ACCURACY, ped, 100)
        Natives.InvokeVoid(N.SET_PED_COMBAT_MOVEMENT, ped, 2)
        Natives.InvokeVoid(N.SET_PED_COMBAT_RANGE, ped, 1)

        local wHash = WEAPON_LIST[state.weaponIdx + 1] and WEAPON_LIST[state.weaponIdx + 1].h
        if not wHash or not NO_FULL_AUTO[wHash] then
            Natives.InvokeVoid(N.SET_PED_FIRING_PATTERN, ped, FIRING_FULL_AUTO)
        end

        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 0, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 1, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 2, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 3, false)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 5, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 13, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 20, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 26, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 42, false)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 46, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 52, true)
        Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 58, true)
    end

    Natives.InvokeVoid(N.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, ped, false)

end

local function applySettingsToAll()
    for _, bg in ipairs(guards) do
        applySettings(bg.handle, bg.cpPacked)
        applyHealth(bg.handle, true)
        bg.followAt = 0
    end
    local grp = playerGroup()
    if grp ~= 0 then
        Natives.InvokeVoid(N.SET_GROUP_FORMATION, grp, FORMATIONS.groupValue())
        Natives.InvokeVoid(N.SET_GROUP_FORMATION_SPACING, grp, 2.0, -1.0, -1.0)
    end
end

function TGT.applyToAll(prevHeat)
    local steppingDown = TGT.heat() < (prevHeat or 0)

    local cleared = 0
    for _, bg in ipairs(guards) do
        if steppingDown and entityExists(bg.handle) and not bg.dead and not bg.cpPacked
           and not bg.enteringVeh
           and not Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, bg.handle, false)
           and Natives.InvokeBool(N.IS_PED_IN_COMBAT, bg.handle, 0) then
            Natives.InvokeVoid(N.CLEAR_PED_TASKS, bg.handle)
            cleared = cleared + 1
        end
        bg.aimTaskFor, bg.aimTaskAt, bg.wasInCombat = nil, 0, false
        bg.orderedFor = nil
        bg.sweepAt, bg.followAt = 0, 0
    end

    if cleared > 0 then
        logf("combat style (player=%d npc=%d gang=%d): stood %d guard(s) down mid-fight",
            TGT.level(TGT.PLAYER), TGT.level(TGT.NPC), TGT.level(TGT.GANG), cleared)
    end
end

local function secondaryWeapon()
    local w = (state.weapon2Idx or 0) > 0 and WEAPON_LIST[state.weapon2Idx] or nil
    if w then return w.h, w.n end
    return PISTOL_HASH, "AP Pistol"
end

local function giveSelectedWeapon(ped)
    Natives.InvokeVoid(N.REMOVE_ALL_PED_WEAPONS, ped, true)

    local weapon = WEAPON_LIST[state.weaponIdx + 1]
    if not weapon then return end

    Natives.InvokeVoid(N.GIVE_WEAPON_TO_PED, ped, weapon.h, 9999, false, true)
    Natives.InvokeVoid(N.SET_PED_AMMO, ped, weapon.h, 9999, false)
    Natives.InvokeVoid(N.SET_PED_INFINITE_AMMO, ped, true, weapon.h)
    Natives.InvokeVoid(N.SET_PED_INFINITE_AMMO_CLIP, ped, true)

    local secH = secondaryWeapon()
    if weapon.h ~= secH then
        Natives.InvokeVoid(N.GIVE_WEAPON_TO_PED, ped, secH, 9999, false, false)
        Natives.InvokeVoid(N.SET_PED_AMMO, ped, secH, 9999, false)
        Natives.InvokeVoid(N.SET_PED_INFINITE_AMMO, ped, true, secH)
    end

    Natives.InvokeVoid(N.SET_CURRENT_PED_WEAPON, ped, weapon.h, true)
    Natives.InvokeVoid(N.SET_PED_COMBAT_ATTRIBUTES, ped, 42, false)
    Natives.InvokeVoid(N.SET_PED_CAN_SWITCH_WEAPON, ped, false)
    Natives.InvokeVoid(N.SET_PED_DROPS_WEAPONS_WHEN_DEAD, ped, false)
end

local function rearmAll()
    Script.QueueJob(function()
        for _, bg in ipairs(guards) do
            if entityExists(bg.handle) then
                giveSelectedWeapon(bg.handle)
                Script.Yield(0)
            end
        end
        local w = WEAPON_LIST[state.weaponIdx + 1]
        local _, secName = secondaryWeapon()
        toast("Armed with: " .. (w and w.n or "?") .. " + " .. secName)
    end)
end


local function pinToNetwork(bg)
    Natives.InvokeVoid(N.SET_ENTITY_AS_MISSION, bg.handle, true, true)
    local netId = Natives.InvokeInt(N.PED_TO_NET, bg.handle)
    if netId and netId ~= 0 then
        bg.netId = netId
        Natives.InvokeVoid(N.SET_NETWORK_ID_EXISTS_ON_ALL_MACHINES, netId, true)
        Natives.InvokeVoid(N.SET_NETWORK_ID_ALWAYS_EXISTS_FOR_PLAYER,
            netId, myId(), true)
        Natives.InvokeVoid(N.SET_NETWORK_ID_CAN_MIGRATE, netId, false)
    end
end


local function spawnBodyguards(modelHash, modelName)
    if #guards >= activeCap() then
        toast("At limit (" .. activeCap() .. "). Delete some first.")
        return
    end

    initRelationships()

    Script.QueueJob(function()
        Script.Yield(200)

        if #guards >= activeCap() then
            toast("Limit reached (" .. activeCap() .. ")")
            return
        end

        if not requestModel(modelHash) then
            toast("Failed to load: " .. modelName)
            return
        end

        local px, py, pz = myCoords()
        if not px then toast("Position error") return end

        local grp = playerGroup()
        local count = math.min(state.pedCount, activeCap() - #guards)
        local spawned = 0

        for i = 1, count do
            if #guards >= activeCap() then break end

            local ox, oy = ringSlot(#guards, 2.5, FORM_SPACING)
            local sx, sy = px + ox, py + oy
            local sz = groundZ(sx, sy, pz)

            local ped = GTA.CreatePed(modelHash, 26, sx, sy, sz, 0.0, true, false)
            if ped and ped ~= 0 then
                local bg = {
                    handle   = ped,
                    model    = modelName,
                    modelHash = modelHash,
                    name     = modelName .. " #" .. nextGuardOrdinal,
                    blip     = 0,
                    tier     = 2,
                    followAt = 0,
                    groupMissCount = 0,
                }
                nextGuardOrdinal = nextGuardOrdinal + 1

                pinToNetwork(bg)

                tryJoinGroup(bg, grp)

                baseHealth[ped] = Natives.InvokeInt(N.GET_PED_MAX_HEALTH, ped)
                if not baseHealth[ped] or baseHealth[ped] <= 0 then
                    baseHealth[ped] = DEFAULT_PED_HEALTH
                end

                giveSelectedWeapon(ped)
                applySettings(ped)
                applyHealth(ped, true)

                local blip = Natives.InvokeInt(N.ADD_BLIP_FOR_ENTITY, ped)
                if blip and blip ~= 0 then
                    Natives.InvokeVoid(N.SET_BLIP_COLOUR, blip, 57)
                    Natives.InvokeVoid(N.SET_BLIP_SCALE, blip, 0.7)
                    bg.blip = blip
                end

                guards[#guards + 1] = bg
                spawned = spawned + 1
            end
            Script.Yield(0)
        end

        Natives.InvokeVoid(N.SET_MODEL_NO_LONGER, modelHash)

        if grp ~= 0 then
            Natives.InvokeVoid(N.SET_GROUP_FORMATION, grp, FORMATIONS.groupValue())
        end

        syncBoardingLock()

        if spawned > 0 then
            RS.used = true
            if #guards > GROUP_SLOTS then RS.usedOver7 = true end
        end

        toast(string.format("Spawned %dx %s (%d total, %d in group)",
            spawned, modelName, #guards, liveTier1Count()))
    end)
end

local function spawnFromDropdown()
    local cat = MODELS[state.catIdx + 1]
    if not cat then toast("Invalid category") return end
    local modelInfo = cat[state.modelIdx + 1]
    if not modelInfo then toast("Invalid model") return end
    spawnBodyguards(joaat(modelInfo.h), modelInfo.n)
end


local function teleportAllToMe()
    local px, py, pz = myCoords()
    if not px then return end

    local myVeh = 0
    if Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, myPed(), false) then
        myVeh = Natives.InvokeInt(N.GET_VEHICLE_PED_IS_IN, myPed(), false) or 0
    end

    local aboard = RS.seatedSet(myVeh)

    local count, placed = 0, 0
    for _, bg in ipairs(guards) do
        if entityExists(bg.handle) then
            local here = false
            if myVeh ~= 0 then
                here = bg.cpPacked or (aboard[bg.handle] ~= nil)
            end

            if not here then
                local ox, oy = ringSlot(placed, 3.0, FORM_SPACING)
                local tx, ty = px + ox, py + oy
                Natives.InvokeVoid(N.SET_ENTITY_COORDS, bg.handle,
                    tx, ty, groundZ(tx, ty, pz), false, false, false, false)
                bg.followAt = 0
                placed = placed + 1
            end
            count = count + 1
        end
    end

    if placed == count then
        toast("Teleported " .. placed .. " guards")
    else
        toast(string.format("Teleported %d guards (%d already with you)",
            placed, count - placed))
    end
end

