local function seatLooseGroup(veh, maxSeats)
    local sent, seat, taken = 0, 0, 0
    for _, bg in ipairs(guards) do
        if seat >= maxSeats then break end
        if bg.tier == 1 and entityExists(bg.handle) and not bg.dead
           and not bg.cpPacked
           and not Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, bg.handle, false) then
            while seat < maxSeats do
                if seatOccupier(veh, seat) == 0 then
                    CABIN.unride(bg)
                    RS.ragdollLock(bg.handle)
                    Natives.InvokeVoid(N.SET_PED_INTO_VEHICLE, bg.handle, veh, seat)
                    bg.enteringVeh = false
                    bg.noSeat, bg.warpTries = false, 0
                    sent = sent + 1
                    seat = seat + 1
                    break
                end
                taken = taken + 1
                seat = seat + 1
            end
        end
    end
    return sent, taken
end

local function reseatSquad(why)
    local player = myPed()
    if not Natives.InvokeBool(N.IS_PED_IN_ANY_VEHICLE, player, false) then return nil end
    local veh = Natives.InvokeInt(N.GET_VEHICLE_PED_IS_IN, player, false)
    if not veh or veh == 0 then return nil end

    local maxSeats = seatCap(veh)
    CABIN.releaseAll(why)
    local rearmed  = ejectFromSeats(why)

    local sent, taken = seatLooseGroup(veh, maxSeats)

    logf("%s: seats=%d groupSeated=%d occupiedSkipped=%d reArmed=%d riders=%s",
        why, maxSeats, sent, taken, rearmed, tostring(state.cabinPack))
    return sent, rearmed
end

function state.setCabinPack(want, why, quiet)
    want = (want == true) and state.experimental
    state.cabinPack = want

    local rf = FeatureMgr.GetFeature(joaat("LUA_BG_CabinPack"))
    if rf then rf:SetBoolValue(want) end

    if want then
        RS.usedPack = true
        for _, bg in ipairs(guards) do
            if entityExists(bg.handle) and not bg.dead then
                RS.ragdollApply(bg.handle, bg.cpPacked)
            end
        end
        Script.QueueJob(function() reseatSquad(why or "cabin packing armed") end)
    else
        CABIN.releaseAll(why or "cabin packing disabled")
        for _, bg in ipairs(guards) do
            if entityExists(bg.handle) and not bg.dead then
                RS.ragdollApply(bg.handle, bg.cpPacked)
            end
        end
    end

    syncBoardingLock()
    if not want and not state.experimental and not quiet then
        toast("Enable Experimental Mode first")
    end
    return want
end

function state.setExperimental(want, why)
    state.experimental = (want == true)

    local ef = FeatureMgr.GetFeature(joaat("LUA_BG_Experimental"))
    if ef then ef:SetBoolValue(state.experimental) end

    local pc = FeatureMgr.GetFeature(joaat("LUA_BG_PedCount"))
    if pc then
        pc:SetLimitValues(1, activeCap())
        if state.pedCount > activeCap() then
            state.pedCount = activeCap()
            pc:SetValue(state.pedCount)
        end
    end

    if not state.experimental then
        state.setCabinPack(false, why or "experimental mode off", true)
        Script.QueueJob(function()
            local surplus = {}
            for i = #guards, GROUP_SLOTS + 1, -1 do
                surplus[#surplus + 1] = guards[i]
            end

            local removed = 0
            for _, bg in ipairs(surplus) do
                if entityExists(bg.handle) then
                    deleteGuard(bg)
                    removed = removed + 1
                end
                Script.Yield(0)
            end
            if removed > 0 then
                toast("Experimental off: removed " .. removed .. " guard(s)")
                logf("experimental mode off: deleted %d guard(s) past %d",
                    removed, GROUP_SLOTS)
            end
        end)
    end
    return state.experimental
end

