local CONFIG_DIR = settings.dir .. "\\bodyguards\\"
local LEGACY_DIR = FileMgr.GetMenuRootPath() .. "\\Lua\\BodyguardConfigs\\"
FileMgr.CreateDir(CONFIG_DIR)

local savedConfigs = {}
local legacyOnly = {}

local function configDirFor(name)
    if legacyOnly[name] then return LEGACY_DIR end
    return CONFIG_DIR
end

local function refreshConfigList()
    savedConfigs = {}
    legacyOnly = {}

    local seen = {}
    for _, dir in ipairs({ CONFIG_DIR, LEGACY_DIR }) do
        local files = FileMgr.FindFiles(dir, ".cfg", false)
        if files then
            for _, path in ipairs(files) do
                local name = path:match("([^\\]+)%.cfg$") or path:match("([^/]+)%.cfg$")
                if name and not seen[name] then
                    seen[name] = true
                    savedConfigs[#savedConfigs + 1] = name
                    if dir == LEGACY_DIR then legacyOnly[name] = true end
                end
            end
        end
    end
    table.sort(savedConfigs)

    local f = FeatureMgr.GetFeature(joaat("LUA_BG_ConfigList"))
    if f then
        if #savedConfigs > 0 then
            f:SetList(savedConfigs)
        else
            f:SetList({"(no configs saved)"})
        end
        f:SetListIndex(0)
    end
end

local function serializeConfig()
    local primary = WEAPON_LIST[state.weaponIdx + 1]
    local secondary = state.weapon2Idx > 0 and WEAPON_LIST[state.weapon2Idx] or nil
    local lines = {
        "-- Bodyguard Script Config",
        "version=9",
        "pedCount=" .. state.pedCount,
        "catIdx=" .. state.catIdx,
        "modelIdx=" .. state.modelIdx,
        "weaponIdx=" .. state.weaponIdx,
        "weapon2Idx=" .. state.weapon2Idx,
        "weaponHash=" .. (primary and primary.h or 0),
        "weapon2Hash=" .. (secondary and secondary.h or 0),
        "formIdx=" .. state.formIdx,
        "tgtPlayer=" .. TGT.level(TGT.PLAYER),
        "tgtNpc=" .. TGT.level(TGT.NPC),
        "tgtGang=" .. TGT.level(TGT.GANG),
        "healthPct=" .. state.healthPct,
        "godMode=" .. tostring(state.godMode),
        "immuneToMe=" .. tostring(state.immuneToMe),
        "disableFriendOrgTargeting=" .. tostring(state.disableFriendOrgTargeting),
        "noRagdoll=" .. tostring(state.noRagdoll),
        "neverWanted=" .. tostring(state.neverWanted),
        "invisible=" .. tostring(state.invisible),
        "autoTeleport=" .. tostring(state.autoTeleport),
        "cabinPack=" .. tostring(state.cabinPack),
        "instantBoard=" .. tostring(state.instantBoard),
        "showPreview=" .. tostring(state.showPreview),
        "experimental=" .. tostring(state.experimental),
    }
    local cat = MODELS[state.catIdx + 1]
    local modelInfo = cat and cat[state.modelIdx + 1]
    if modelInfo then
        lines[#lines + 1] = "modelName=" .. modelInfo.n
        lines[#lines + 1] = "modelHash=" .. modelInfo.h
    end
    return table.concat(lines, "\n")
end

local function deserializeConfig(content)
    local cfg = {}
    for line in content:gmatch("[^\n]+") do
        if not line:match("^%-%-") then
            local key, val = line:match("^(%w+)=(.+)$")
            if key and val then cfg[key] = val end
        end
    end
    return cfg
end

local function applyConfig(cfg)
    local function toBool(s) return s == "true" end
    local function toInt(s) return math.tointeger(tonumber(s)) or 0 end

    local prevHeat = TGT.heat()
    local wantExperimental = toBool(cfg.experimental)
    local wantCabin
    if cfg.cabinPack ~= nil then
        wantCabin = toBool(cfg.cabinPack)
    elseif cfg.riderMode ~= nil then
        wantCabin = toBool(cfg.riderMode)
    else
        wantCabin = false
    end

    state.setExperimental(wantExperimental, "config disabled experimental mode")

    state.pedCount     = math.max(1, math.min(activeCap(), toInt(cfg.pedCount or "1")))
    state.catIdx       = math.max(0, math.min(#MODELS - 1, toInt(cfg.catIdx or "0")))
    state.modelIdx     = math.max(0, math.min(#MODELS[state.catIdx + 1] - 1,
        toInt(cfg.modelIdx or "0")))
    local primaryHash
    if cfg.weaponHash then
        primaryHash = toInt(cfg.weaponHash)
    else
        local oldIdx = math.max(0, math.min(#LEGACY_WEAPON_LIST - 1,
            toInt(cfg.weaponIdx or "17")))
        primaryHash = LEGACY_WEAPON_LIST[oldIdx + 1].h
    end
    state.weaponIdx = WEAPON_INDEX_BY_HASH[primaryHash]
        or WEAPON_INDEX_BY_HASH[0x83BF0278]

    local secondaryHash
    if cfg.weapon2Hash then
        secondaryHash = toInt(cfg.weapon2Hash)
    else
        local oldIdx = math.max(0, math.min(#LEGACY_WEAPON_LIST,
            toInt(cfg.weapon2Idx or "0")))
        secondaryHash = oldIdx > 0 and LEGACY_WEAPON_LIST[oldIdx].h or 0
    end
    local secondaryPrimaryIdx = WEAPON_INDEX_BY_HASH[secondaryHash]
    state.weapon2Idx = secondaryHash == 0 and 0
        or (secondaryPrimaryIdx and (secondaryPrimaryIdx + 1) or 0)
    state.formIdx      = math.max(0, math.min(#FORMATIONS - 1,
        toInt(cfg.formIdx or "0")))
    local TIER_MAP = {
        [0] = { TGT.P, TGT.P, TGT.P },
        [1] = { TGT.D, TGT.D, TGT.D },
        [2] = { TGT.D, TGT.D, TGT.A },
        [3] = { TGT.A, TGT.D, TGT.D },
        [4] = { TGT.A, TGT.A, TGT.A },
    }
    local function toLevel(s, dflt) return math.max(0, math.min(2, toInt(s or tostring(dflt)))) end
    if cfg.tgtPlayer or cfg.tgtNpc or cfg.tgtGang then
        state.tgt[TGT.PLAYER] = toLevel(cfg.tgtPlayer, TGT.D)
        state.tgt[TGT.NPC]    = toLevel(cfg.tgtNpc,    TGT.D)
        state.tgt[TGT.GANG]   = toLevel(cfg.tgtGang,   TGT.D)
    else
        local m = TIER_MAP[toInt(cfg.behavIdx or "1")] or TIER_MAP[1]
        state.tgt[TGT.PLAYER], state.tgt[TGT.NPC], state.tgt[TGT.GANG] = m[1], m[2], m[3]
        logf("config: migrated behavIdx=%s to player=%d npc=%d gang=%d",
            tostring(cfg.behavIdx), m[1], m[2], m[3])
    end
    state.healthPct    = math.max(10, math.min(1000, toInt(cfg.healthPct or "100")))
    state.godMode      = toBool(cfg.godMode)
    state.immuneToMe   = toBool(cfg.immuneToMe)
    state.disableFriendOrgTargeting = (cfg.disableFriendOrgTargeting == nil)
        or toBool(cfg.disableFriendOrgTargeting)
    state.noRagdoll    = toBool(cfg.noRagdoll)
    state.neverWanted  = toBool(cfg.neverWanted)
    state.invisible    = toBool(cfg.invisible)
    state.autoTeleport = toBool(cfg.autoTeleport)
    state.instantBoard = toBool(cfg.instantBoard)
    state.showPreview = (cfg.showPreview == nil) or toBool(cfg.showPreview)

    state.setCabinPack(wantCabin, "config applied cabin packing", true)

    local function setToggle(hash, val)
        local ft = FeatureMgr.GetFeature(hash)
        if ft then ft:SetBoolValue(val) end
    end

    local f = FeatureMgr.GetFeature(joaat("LUA_BG_PedCount"))
    if f then
        f:SetLimitValues(1, activeCap())
        if state.pedCount > activeCap() then state.pedCount = activeCap() end
        f:SetValue(state.pedCount)
    end

    f = FeatureMgr.GetFeature(joaat("LUA_BG_Health"))
    if f then f:SetValue(state.healthPct) end

    f = FeatureMgr.GetFeature(joaat("LUA_BG_Category"))
    if f then
        f:SetListIndex(state.catIdx)
        local mf = FeatureMgr.GetFeature(joaat("LUA_BG_Model"))
        if mf and MODEL_NAMES[state.catIdx + 1] then
            mf:SetList(MODEL_NAMES[state.catIdx + 1])
            mf:SetListIndex(state.modelIdx)
        end
    end

    f = FeatureMgr.GetFeature(joaat("LUA_BG_Weapon"))
    if f then f:SetListIndex(state.weaponIdx) end

    f = FeatureMgr.GetFeature(joaat("LUA_BG_Weapon2"))
    if f then f:SetListIndex(state.weapon2Idx) end

    f = FeatureMgr.GetFeature(joaat("LUA_BG_Formation"))
    if f then f:SetListIndex(state.formIdx) end

    f = FeatureMgr.GetFeature(joaat("LUA_BG_TgtPlayer"))
    if f then f:SetListIndex(TGT.level(TGT.PLAYER)) end
    f = FeatureMgr.GetFeature(joaat("LUA_BG_TgtNpc"))
    if f then f:SetListIndex(TGT.level(TGT.NPC)) end
    f = FeatureMgr.GetFeature(joaat("LUA_BG_TgtGang"))
    if f then f:SetListIndex(TGT.level(TGT.GANG)) end

    setToggle(joaat("LUA_BG_GodMode"), state.godMode)
    setToggle(joaat("LUA_BG_ImmuneToMe"), state.immuneToMe)
    setToggle(joaat("LUA_BG_DisableFriendOrgTargeting"),
        state.disableFriendOrgTargeting)
    setToggle(joaat("LUA_BG_NoRagdoll"), state.noRagdoll)
    setToggle(joaat("LUA_BG_NeverWanted"), state.neverWanted)
    setToggle(joaat("LUA_BG_Invisible"), state.invisible)
    setToggle(joaat("LUA_BG_AutoTeleport"), state.autoTeleport)
    setToggle(joaat("LUA_BG_InstantBoard"), state.instantBoard)
    setToggle(joaat("LUA_BG_Preview"), state.showPreview)

    bindRelationships(playerRelHash)
    applySettingsToAll()
    for _, bg in ipairs(guards) do applyTeleportFlag(bg) end
    TGT.applyToAll(prevHeat)
end

local function loadSelectedConfig()
    local listF = FeatureMgr.GetFeature(joaat("LUA_BG_ConfigList"))
    if not listF then return nil, nil end
    local name = savedConfigs[listF:GetListIndex() + 1]
    if not name then toast("No config selected") return nil, nil end

    local ok, cfg = pcall(function()
        local content = FileMgr.ReadFileContent(configDirFor(name) .. name .. ".cfg")
        if not content or content == "" then return nil end
        return deserializeConfig(content)
    end)
    if not ok then
        toast("Config file is malformed: " .. name, 10000)
        return nil, nil
    end
    if not cfg then
        toast("Failed to read: " .. name)
        return nil, nil
    end
    if not cfg.version then
        toast("Invalid config file")
        return nil, nil
    end
    return cfg, name
end

