FeatureMgr.AddFeature(joaat("LUA_BG_ConfigSave"), "Save",
    eFeatureType.Button, "Save every current setting to a named config file", function()
    local name = (state.configName or ""):match("^%s*(.-)%s*$") or ""
    if name == "" then toast("Enter a config name first") return end
    name = name:gsub("[^%w%-%_ ]", "")
    if name == "" then toast("Invalid config name") return end

    if FileMgr.WriteFileContent(CONFIG_DIR .. name .. ".cfg", serializeConfig(), false) then
        toast("Saved: " .. name)
        refreshConfigList()
    else
        toast("Failed to save config")
    end
end, true)
    :SetSaveable(false)

