FeatureMgr.AddFeature(joaat("LUA_BG_ConfigSpawn"), "Apply & Spawn",
    eFeatureType.Button, "Apply the saved settings and immediately spawn a batch with them", function()
    local cfg, name = loadSelectedConfig()
    if not cfg then return end
    applyConfig(cfg)

    local cat = MODELS[state.catIdx + 1]
    local modelInfo = cat and cat[state.modelIdx + 1]

    local modelHash, modelName
    if modelInfo then
        modelHash, modelName = joaat(modelInfo.h), modelInfo.n
    elseif cfg.modelHash and cfg.modelName then
        modelHash, modelName = joaat(cfg.modelHash), cfg.modelName
    end

    if not modelHash then toast("Could not resolve model from config") return end
    toast("Spawning " .. name .. "...")
    spawnBodyguards(modelHash, modelName)
end, true)
    :SetSaveable(false)

Script.QueueJob(function()
    Script.Yield(100)

    local f = FeatureMgr.GetFeature(joaat("LUA_BG_PedCount"))
    if f then f:SetLimitValues(1, GROUP_SLOTS); f:SetValue(1) end
    local f = FeatureMgr.GetFeature(joaat("LUA_BG_Health"))
    if f then f:SetLimitValues(10, 1000); f:SetValue(state.healthPct) end
    local f = FeatureMgr.GetFeature(joaat("LUA_BG_Category"))
    if f then f:SetList(CATEGORY_NAMES); f:SetListIndex(0) end
    local f = FeatureMgr.GetFeature(joaat("LUA_BG_Model"))
    if f then f:SetList(MODEL_NAMES[1]); f:SetListIndex(0) end
    local f = FeatureMgr.GetFeature(joaat("LUA_BG_Weapon"))
    if f then f:SetList(WEAPON_NAMES); f:SetListIndex(state.weaponIdx) end
    local f = FeatureMgr.GetFeature(joaat("LUA_BG_Weapon2"))
    if f then f:SetList(WEAPON2_NAMES); f:SetListIndex(0) end
    local f = FeatureMgr.GetFeature(joaat("LUA_BG_Formation"))
    if f then f:SetList(FORMATION_NAMES); f:SetListIndex(0) end
    for _, r in ipairs({ { "LUA_BG_TgtPlayer", TGT.PLAYER }, { "LUA_BG_TgtNpc", TGT.NPC },
                         { "LUA_BG_TgtGang", TGT.GANG } }) do
        local f = FeatureMgr.GetFeature(joaat(r[1]))
        if f then f:SetList(TGT.LEVEL_NAMES); f:SetListIndex(TGT.level(r[2])) end
    end

    local defaults = {
        { "LUA_BG_CabinPack",    state.cabinPack },
        { "LUA_BG_InstantBoard", state.instantBoard },
        { "LUA_BG_Experimental", state.experimental },
        { "LUA_BG_Preview",      state.showPreview },
        { "LUA_BG_DisableFriendOrgTargeting", state.disableFriendOrgTargeting },
        { "LUA_BG_NoRagdoll", state.noRagdoll },
        { "LUA_BG_NeverWanted", state.neverWanted },
    }
    for _, d in ipairs(defaults) do
        local ft = FeatureMgr.GetFeature(joaat(d[1]))
        if ft then ft:SetBoolValue(d[2]) end
    end

    refreshConfigList()
    logf("Feature init complete (infinite passengers %s)",
        state.cabinPack and "ON" or "OFF")
end)


