local function experimentalHint()
    if not ImGui.IsItemHovered() then return end
    if #guards + state.pedCount <= GROUP_SLOTS then return end

    if state.experimental then
        ImGui.SetTooltip(
            "Past " .. GROUP_SLOTS .. " is EXPERIMENTAL\n\n"
            .. "The engine ped group holds " .. GROUP_SLOTS .. ". Beyond that,\n"
            .. "guards follow on explicit tasks and ride attached to vehicles\n"
            .. "rather than sitting in seats.")
    else
        ImGui.SetTooltip(
            "Capped at " .. GROUP_SLOTS .. " bodyguards\n\n"
            .. "The engine ped group holds " .. GROUP_SLOTS .. ", and every\n"
            .. "guard sits in a real seat. Turn on Experimental Mode\n"
            .. "to spawn more.")
    end
end

local function modelTree()
    local changed = false
    ImGui.SetNextItemWidth(-1)
    modelFilter = ImGui.InputTextWithHint("##bg_modelsearch", "Search models",
        modelFilter) or ""
    local needle = modelFilter:lower():match("^%s*(.-)%s*$") or ""

    ImGui.BeginChild("bg_modeltree", 0, 260, true)

    local function row(ci, mi, m)
        local sel = (state.catIdx == ci - 1 and state.modelIdx == mi - 1)
        if ImGui.Selectable(m.n .. "##bg" .. ci .. "_" .. mi, sel) and not sel then
            state.catIdx, state.modelIdx = ci - 1, mi - 1
            changed = true
        end
    end

    for ci, cat in ipairs(MODELS) do
        if needle ~= "" then
            for mi, m in ipairs(cat) do
                if m.n:find(needle, 1, true) then row(ci, mi, m) end
            end
        else
            if state.catIdx == ci - 1 then
                ImGui.SetNextItemOpen(true, ImGuiCond.Once)
            end
            if ImGui.TreeNode("bg_cat" .. ci,
                    (CATEGORIES[ci] or "?") .. " (" .. #cat .. ")") then
                for mi, m in ipairs(cat) do row(ci, mi, m) end
                ImGui.TreePop()
            end
        end
    end

    ImGui.EndChild()

    if changed then
        local cf = FeatureMgr.GetFeature(joaat("LUA_BG_Category"))
        if cf then cf:SetListIndex(state.catIdx) end
        local mf = FeatureMgr.GetFeature(joaat("LUA_BG_Model"))
        if mf then
            mf:SetList(MODEL_NAMES[state.catIdx + 1] or {})
            mf:SetListIndex(state.modelIdx)
        end
    end
end

