    local function componentGroup(label)
        local s = cleanCompLabel(label):lower()
        if s:find("clip", 1, true) or s:find("magazine", 1, true)
           or s:find("rounds", 1, true) or s:find("shells", 1, true)
           or s:find("buckshot", 1, true) or s:find("slugs", 1, true)
           or s:find("flechette", 1, true) or s:find("dragon's breath", 1, true) then
            return "magazine"
        end
        if s:find("suppressor", 1, true) or s:find("compensator", 1, true)
           or s:find("muzzle brake", 1, true) then return "muzzle" end
        if s:find("scope", 1, true) or s:find("sight", 1, true) then return "optic" end
        if s:find("barrel", 1, true) then return "barrel" end
        if s:find("finish", 1, true) or s:find("varmod", 1, true)
           or s:find("camo", 1, true) or s:find("season's greetings", 1, true) then
            return "finish"
        end
        return nil
    end

    for _, category in ipairs(WDB) do
        for _, weapon in ipairs(category.w) do
            local attachments, cosmetics = {}, weapon.l or {}
            for _, camo in ipairs(cosmetics) do
                if COMPONENT_LABEL[camo[2]] then camo[1] = COMPONENT_LABEL[camo[2]] end
            end
            for _, component in ipairs(weapon.c or {}) do
                local hash = component[2]
                local cosmetic = VARMOD_ROOT[hash]
                    or JSCRIPT_COSMETIC[hash]
                    or componentGroup(component[1]) == "finish"
                    or category.n == "Melee"
                if cosmetic and not HIDDEN_COMPONENT[hash] then
                    cosmetics[#cosmetics + 1] = {
                        COMPONENT_LABEL[hash] or cleanCompLabel(component[1]), hash, nil, true
                    }
                else
                    attachments[#attachments + 1] = component
                end
            end
            weapon.c = (#attachments > 0) and attachments or nil
            weapon.l = (#cosmetics > 0) and cosmetics or nil
        end
    end

    local function compMeta(hash, comp)
        local rec = BY_HASH[hash]
        for _, c in ipairs((rec and rec.e.c) or {}) do
            if c[2] == comp then return c, componentGroup(c[1]) end
        end
        return nil, nil
    end

    local function clearCompConflicts(cfg, hash, comp)
        local _, group = compMeta(hash, comp)
        local removed = {}
        if not group then return removed end
        local rec = BY_HASH[hash]
        for _, c in ipairs((rec and rec.e.c) or {}) do
            if c[2] ~= comp and cfg.comps[c[2]] and componentGroup(c[1]) == group then
                cfg.comps[c[2]] = nil
                removed[#removed + 1] = c[2]
            end
        end
        return removed
    end

    local function visibleComps(entry, hash)
        local out = {}
        if not entry.c then return out end
        local ok = st.compOK[hash]
        for _, c in ipairs(entry.c) do
            if not HIDDEN_COMPONENT[c[2]] and ok and ok[c[2]] then
                out[#out + 1] = {
                    label = COMPONENT_LABEL[c[2]] or cleanCompLabel(c[1]), h = c[2]
                }
            end
        end
        if #out == 1 then
            local label = out[1].label:lower()
            if label:find("^default ") or label == tostring(entry.n or ""):lower() then
                return {}
            end
        end
        return out
    end



    local function releaseVariantModels()
        local req = st.pv.varReq
        st.pv.varReq, st.pv.varReqFor = {}, 0
        for model in pairs(req) do
            STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(model)
        end
    end

    local function destroyPreview(keepModels)
        local obj, asset = st.pv.obj, st.pv.asset
        st.pv.obj, st.pv.hash, st.pv.asset, st.pv.calib = 0, 0, 0, 0
        st.pv.calibTries = 0
        st.pv.applied, st.pv.camoOn = {}, {}
        st.pv.tint, st.pv.camoColor, st.pv.spinAt = -1, -1, nil
        st.pv.prevRel, st.pv.relLead = nil, nil
        st.pv.varComp, st.pv.varModel = 0, 0
        if not keepModels then releaseVariantModels() end
        if obj ~= 0 and ENTITY.DOES_ENTITY_EXIST(obj) then
            Memory.WriteInt(st.delBuf, obj)
            ENTITY.DELETE_ENTITY(st.delBuf)
            if ENTITY.DOES_ENTITY_EXIST(obj) then
                Memory.WriteInt(st.delBuf, obj)
                ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(st.delBuf)
            end
        end
        if asset ~= 0 then
            local ped = PLAYER.PLAYER_PED_ID()
            if ped and ped ~= 0 and not WEAPON.HAS_PED_GOT_WEAPON(ped, asset, false) then
                WEAPON.REMOVE_WEAPON_ASSET(asset)
            end
            if st.pv.reqFor == asset then st.pv.reqFor = 0 end
        end
    end

    local function anchorPx()
        local b = st.bay
        if not b or st.dispW <= 0 or st.dispH <= 0 then return nil end
        local bw, bh = b.x1 - b.x0, b.y1 - b.y0
        if bw <= 1 or bh <= 1 then return nil end
        return (b.x0 + b.x1) * 0.5, (b.y0 + b.y1) * 0.5, bw, bh
    end

    local function place(hash)
        local ax, ay, bw, bh = anchorPx()
        if not ax then return nil end
        local cam = CAM.GET_FINAL_RENDERED_CAM_COORD()
        local ped = PLAYER.PLAYER_PED_ID()
        if cam and ped and ped ~= 0 and not PED.IS_PED_IN_ANY_VEHICLE(ped, false) then
            local o = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(ped, 0.0, 0.0, 0.0)
            if o then
                local rx, ry, rz = cam.x - o.x, cam.y - o.y, cam.z - o.z
                local pr = st.pv.prevRel
                if pr then
                    local dx, dy, dz = rx - pr.x, ry - pr.y, rz - pr.z
                    if (dx * dx + dy * dy + dz * dz) <= 1.0 then
                        local lead = st.pv.relLead or { x = 0.0, y = 0.0, z = 0.0 }
                        lead.x = lead.x * 0.72 + dx * 0.28
                        lead.y = lead.y * 0.72 + dy * 0.28
                        lead.z = lead.z * 0.72 + dz * 0.28
                        local mag2 = lead.x * lead.x + lead.y * lead.y + lead.z * lead.z
                        if mag2 > 0.0144 then
                            local k = 0.12 / math.sqrt(mag2)
                            lead.x, lead.y, lead.z = lead.x * k, lead.y * k, lead.z * k
                        end
                        st.pv.relLead = lead
                        cam.x, cam.y, cam.z = cam.x + lead.x, cam.y + lead.y, cam.z + lead.z
                    end
                end
                st.pv.prevRel = { x = rx, y = ry, z = rz }
            end
        else
            st.pv.prevRel = nil
            st.pv.relLead = nil
        end
        local rot = CAM.GET_FINAL_RENDERED_CAM_ROT(2)
        if not cam or not rot then return nil end
        local fov = CAM.GET_FINAL_RENDERED_CAM_FOV()
        if not fov or fov < 1.0 or fov > 130.0 then fov = 50.0 end

        local ry, rp = math.rad(rot.z), math.rad(rot.x)
        local sy, cy = math.sin(ry), math.cos(ry)
        local sp, cp = math.sin(rp), math.cos(rp)
        local fx, fy, fz = -sy * cp,  cy * cp,  sp
        local gx, gy     =  cy,       sy
        local ux, uy, uz =  sy * sp, -cy * sp,  cp

        local A = st.dispW / st.dispH
        local t = math.tan(math.rad(fov) * 0.5)
        local rc = BY_HASH[hash]
        ax = ax + ((rc and CAT_PREVIEW_SHIFT_X[rc.tn]) or 0)
        ay = ay + (PREVIEW_DROP_Y[hash] or 0)
        local measured = st.size[hash]
        local layoutScale = PREVIEW_SCALE
        local baseL = (measured and measured.long) or ((rc and NOM_LEN[rc.tn]) or NOM_DEF)
        local baseC = (measured and measured.cross) or (baseL * CROSS)
        local L, C = baseL * layoutScale, baseC * layoutScale

        local fw = FILL_W * bw / st.dispW
        local fh = FILL_H * bh / st.dispH
        local dW = L / math.max(0.001, fw * 2.0 * t * A)
        local dH = C / math.max(0.001, fh * 2.0 * t)
        local D  = math.max(dW, dH)
        local scaleRatio = layoutScale / PREVIEW_REFERENCE_SCALE
        local dMin, dMax = D_MIN * scaleRatio, D_MAX * scaleRatio
        if D < dMin then D = dMin elseif D > dMax then D = dMax end

        local ndcX = (ax / st.dispW - 0.5) * 2.0
        local ndcY = (0.5 - ay / st.dispH) * 2.0
        local hh = D * t
        local hw = hh * A

        return cam.x + fx * D + gx * (ndcX * hw) + ux * (ndcY * hh),
               cam.y + fy * D + gy * (ndcX * hw) + uy * (ndcY * hh),
               cam.z + fz * D +                    uz * (ndcY * hh),
               rot.z
    end

    local function assetReady(now, hash)
        local prev = st.pv.reqFor
        if prev ~= 0 and prev ~= hash then
            st.pv.reqFor = 0
            local ped = PLAYER.PLAYER_PED_ID()
            if not (ped and ped ~= 0 and WEAPON.HAS_PED_GOT_WEAPON(ped, prev, false)) then
                WEAPON.REMOVE_WEAPON_ASSET(prev)
            end
        end
        if WEAPON.HAS_WEAPON_ASSET_LOADED(hash) then return true end
        if hash ~= st.pv.reqFor or now - (st.pv.reqAt or 0) > ASSET_REQ_MS then
            st.pv.reqFor, st.pv.reqAt = hash, now
            WEAPON.REQUEST_WEAPON_ASSET(hash, 31, 0)
        end
        return false
    end

    local function variantComp(hash, cfg)
        local rec = BY_HASH[hash]
        local sel = (cfg.camoIdx > 0) and rec and rec.e.l and rec.e.l[cfg.camoIdx]
        local comp = sel and sel[2] or 0
        return VARMOD_ROOT[comp] and comp or 0
    end

    local function variantReady(comp)
        if st.pv.varReqFor ~= comp then
            releaseVariantModels()
            st.pv.varReqFor = comp
        end
        local model = WEAPON.GET_WEAPON_COMPONENT_TYPE_MODEL(comp)
        if not model or model == 0 then return 0 end
        local ready = true
        st.pv.varReq[model] = true
        STREAMING.REQUEST_MODEL(model)
        if not STREAMING.HAS_MODEL_LOADED(model) then ready = false end
        local extras = WEAPON.GET_WEAPON_COMPONENT_VARIANT_EXTRA_COUNT(comp) or 0
        for i = 0, extras - 1 do
            local extra = WEAPON.GET_WEAPON_COMPONENT_VARIANT_EXTRA_MODEL(comp, i)
            if extra and extra ~= 0 then
                st.pv.varReq[extra] = true
                STREAMING.REQUEST_MODEL(extra)
                if not STREAMING.HAS_MODEL_LOADED(extra) then ready = false end
            end
        end
        return ready and model or nil
    end

    local function probeStep(hash)
        if hash == 0 or st.compOK[hash] then return end
        local rec = BY_HASH[hash]
        if not rec then return end
        local ok = {}
        if rec.e.c then
            for _, c in ipairs(rec.e.c) do
                ok[c[2]] = WEAPON.DOES_WEAPON_TAKE_WEAPON_COMPONENT(hash, c[2]) and true or false
            end
        end
        st.compOK[hash] = ok
        local camoOK = {}
        for i, camo in ipairs(rec.e.l or {}) do
            local accepted = WEAPON.DOES_WEAPON_TAKE_WEAPON_COMPONENT(hash, camo[2])
            if accepted and camo[3] then
                accepted = WEAPON.DOES_WEAPON_TAKE_WEAPON_COMPONENT(hash, camo[3])
            end
            camoOK[i] = accepted and true or false
        end
        st.camoOK[hash] = camoOK
        local n = WEAPON.GET_WEAPON_TINT_COUNT(hash) or 0
        st.tintMax[hash] = math.max(0, n)
    end

    local function calibrate()
        local bi = -1
        for _, nm in ipairs(MUZZLE_BONES) do
            bi = ENTITY.GET_ENTITY_BONE_INDEX_BY_NAME(st.pv.obj, nm)
            if bi and bi >= 0 then break end
        end
        local p = { pitch = 0.0, roll = 0.0, yawExtra = 0.0 }
        local ok = false
        if bi and bi >= 0 then
            local bp = ENTITY.GET_WORLD_POSITION_OF_ENTITY_BONE(st.pv.obj, bi)
            local op = ENTITY.GET_ENTITY_COORDS(st.pv.obj, true)
            if bp and op then
                local d, len = directionBetween(op, bp)
                if len >= 0.05 then
                    ok = true
                    local hl = math.sqrt(d.x * d.x + d.y * d.y)
                    if hl >= 0.25 then
                        local b = math.deg(math.atan(-d.x, d.y))
                        p.yawExtra = -b
                        p.pitch = 6.0
                    else
                        p.pitch = (d.z >= 0.0) and -90.0 or 90.0
                    end
                end
            end
        end
        if not ok then
            st.pv.calibTries = st.pv.calibTries + 1
            if st.pv.calibTries < 5 then return end
            local sz = st.size[st.pv.hash]
            if sz and sz.zLong then p.pitch = 90.0 end
        end
        st.pose[st.pv.hash] = p
        if LoadoutMgr and LoadoutMgr.verbose then
            logf("Loadout pose %d: pitch %.1f roll %.1f yawExtra %.1f (bone %d)",
                st.pv.hash, p.pitch, p.roll, p.yawExtra, bi or -1)
        end
        ENTITY.SET_ENTITY_VISIBLE(st.pv.obj, true, false)
        st.pv.calib = 0
    end

    local function syncConfig(cfg)
        local obj = st.pv.obj
        local rec = BY_HASH[st.pv.hash]
        if not rec then return end

        for h in pairs(cfg.comps) do
            if HIDDEN_COMPONENT[h] then
                cfg.comps[h] = nil
            elseif not st.pv.applied[h] then
                WEAPON.GIVE_WEAPON_COMPONENT_TO_WEAPON_OBJECT(obj, h)
                if WEAPON.HAS_WEAPON_GOT_WEAPON_COMPONENT(obj, h) then
                    st.pv.applied[h] = true
                end
            end
        end
        for h in pairs(st.pv.applied) do
            if not cfg.comps[h] then
                WEAPON.REMOVE_WEAPON_COMPONENT_FROM_WEAPON_OBJECT(obj, h)
                st.pv.applied[h] = nil
            end
        end

        if hasTintControl(rec) and (st.tintMax[st.pv.hash] or 0) > 1
           and st.pv.tint ~= cfg.tint then
            WEAPON.SET_WEAPON_OBJECT_TINT_INDEX(obj, cfg.tint)
            if WEAPON.GET_WEAPON_OBJECT_TINT_INDEX(obj) == cfg.tint then
                st.pv.tint = cfg.tint
                st.pv.camoOn = {}
                st.pv.camoColor = -1
            end
        elseif not hasTintControl(rec) then
            st.pv.tint = 0
        end

        local selectedCamo = (cfg.camoIdx > 0) and rec.e.l
            and rec.e.l[cfg.camoIdx] or nil
        local wantCamo = selectedCamo and not VARMOD_ROOT[selectedCamo[2]]
            and selectedCamo or nil
        local wantKey = wantCamo and wantCamo[2] or nil
        if st.pv.camoOn.key ~= wantKey then
            if st.pv.camoOn.a then
                WEAPON.REMOVE_WEAPON_COMPONENT_FROM_WEAPON_OBJECT(obj, st.pv.camoOn.a)
            end
            if st.pv.camoOn.b then
                WEAPON.REMOVE_WEAPON_COMPONENT_FROM_WEAPON_OBJECT(obj, st.pv.camoOn.b)
            end
            st.pv.camoOn = {}
            if wantCamo then
                WEAPON.GIVE_WEAPON_COMPONENT_TO_WEAPON_OBJECT(obj, wantCamo[2])
                if wantCamo[3] then
                    WEAPON.GIVE_WEAPON_COMPONENT_TO_WEAPON_OBJECT(obj, wantCamo[3])
                end
                local accepted = WEAPON.HAS_WEAPON_GOT_WEAPON_COMPONENT(obj, wantCamo[2])
                if accepted and wantCamo[3] then
                    accepted = WEAPON.HAS_WEAPON_GOT_WEAPON_COMPONENT(obj, wantCamo[3])
                end
                if accepted then
                    st.pv.camoOn = { key = wantCamo[2], a = wantCamo[2], b = wantCamo[3] }
                end
            end
            st.pv.camoColor = -1
        end
        if st.pv.camoOn.a and not (wantCamo and wantCamo[4])
           and st.pv.camoColor ~= cfg.camoColor then
            WEAPON.SET_WEAPON_OBJECT_COMPONENT_TINT_INDEX(obj, st.pv.camoOn.a, cfg.camoColor)
            if st.pv.camoOn.b then
                WEAPON.SET_WEAPON_OBJECT_COMPONENT_TINT_INDEX(obj, st.pv.camoOn.b, cfg.camoColor)
            end
            local accepted = WEAPON.GET_WEAPON_OBJECT_COMPONENT_TINT_INDEX(
                obj, st.pv.camoOn.a) == cfg.camoColor
            if accepted and st.pv.camoOn.b then
                accepted = WEAPON.GET_WEAPON_OBJECT_COMPONENT_TINT_INDEX(
                    obj, st.pv.camoOn.b) == cfg.camoColor
            end
            if accepted then st.pv.camoColor = cfg.camoColor end
        end

    end

    local function wantedHash()
        return st.sel
    end

    local function previewStep(now, want)
        if want == 0 then destroyPreview(); st.pvStatus = ""; return end

        local wantComp = variantComp(want, cfgFor(want))

        if st.pv.obj == 0 or st.pv.hash ~= want or st.pv.varComp ~= wantComp
           or not ENTITY.DOES_ENTITY_EXIST(st.pv.obj) then
            destroyPreview(true)
            if not assetReady(now, want) then
                st.pvStatus = "streaming..."
                return
            end
            local wantModel = 0
            if wantComp ~= 0 then
                wantModel = variantReady(wantComp)
                if not wantModel then
                    st.pvStatus = "streaming finish..."
                    return
                end
            elseif st.pv.varReqFor ~= 0 then
                releaseVariantModels()
            end
            local x, y, z = place(want)
            if not x then return end
            local obj = WEAPON.CREATE_WEAPON_OBJECT(want, 1, x, y, z, true,
                                                    previewScale(want), wantModel, 0, 0)
            if not obj or obj == 0 then return end
            st.pv.obj, st.pv.hash, st.pv.asset = obj, want, want
            st.pv.applied, st.pv.camoOn = {}, {}
            st.pv.tint, st.pv.camoColor, st.pv.phase, st.pv.spinAt = -1, -1, 0.0, nil
            st.pv.varComp, st.pv.varModel = wantComp, wantModel
            if wantComp ~= 0 then
                WEAPON.GIVE_WEAPON_COMPONENT_TO_WEAPON_OBJECT(obj, wantComp)
                local built = ENTITY.GET_ENTITY_MODEL(obj) or 0
                logf("Loadout variant: weapon %d comp %d model %d -> built %d (%s), registered=%s",
                    want, wantComp, wantModel, built,
                    (built == wantModel) and "applied" or "NOT APPLIED",
                    tostring(WEAPON.HAS_WEAPON_GOT_WEAPON_COMPONENT(obj, wantComp)))
            end
            if not st.size[want] and st.dimsBuf ~= 0 then
                local model = ENTITY.GET_ENTITY_MODEL(obj)
                MISC.GET_MODEL_DIMENSIONS(model, st.dimsBuf, st.dimsBuf + 12)
                local mn, mx = Memory.ReadV3(st.dimsBuf), Memory.ReadV3(st.dimsBuf + 12)
                if mn and mx then
                    local dz = math.abs(mx.z - mn.z)
                    local d = { math.abs(mx.x - mn.x), math.abs(mx.y - mn.y), dz }
                    table.sort(d, function(a, b) return a > b end)
                    if d[1] > 0.01 then
                        st.size[want] = { long = d[1], cross = math.max(0.01, d[2]),
                                          zLong = dz == d[1] }
                    end
                end
            end
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(obj, true, true)
            ENTITY.FREEZE_ENTITY_POSITION(obj, true)
            ENTITY.SET_ENTITY_HAS_GRAVITY(obj, false)
            ENTITY.SET_ENTITY_COLLISION(obj, false, false)
            ENTITY.SET_ENTITY_INVINCIBLE(obj, true)
            if previewUsesFirearmHD(want) then
                ENTITY.SET_ENTITY_ALPHA(obj, 255, false)
            else
                ENTITY.RESET_ENTITY_ALPHA(obj)
            end
            ENTITY.SET_ENTITY_MOTION_BLUR(obj, false)
            ENTITY.SET_ENTITY_ALWAYS_PRERENDER(obj, true)
            if previewUsesFirearmHD(want) then
                ENTITY.SET_ENTITY_LOD_DIST(obj, 0xFFFF)
            end
            if st.pose[want] then
                st.pv.calib = 0
            else
                ENTITY.SET_ENTITY_ROTATION(obj, 0.0, 0.0, 0.0, 2, true)
                ENTITY.SET_ENTITY_VISIBLE(obj, false, false)
                st.pv.calib, st.pv.calibTries = 2, 0
                return
            end
        end

        local rec = BY_HASH[st.pv.hash]
        st.pvStatus = rec and rec.e.n or ""
        syncConfig(cfgFor(st.pv.hash))

        if st.pv.calib == 2 then calibrate(); return end

        CAM.DISABLE_CAM_COLLISION_FOR_OBJECT(st.pv.obj)

        ENTITY.SET_ENTITY_MOTION_BLUR(st.pv.obj, false)
        ENTITY.SET_ENTITY_ALWAYS_PRERENDER(st.pv.obj, true)
        if previewUsesFirearmHD(st.pv.hash) then
            ENTITY.SET_ENTITY_LOD_DIST(st.pv.obj, 0xFFFF)
        end

        local x, y, z, camYaw = place(st.pv.hash)
        if not x then return end


        local p = st.pose[st.pv.hash] or { pitch = 0.0, roll = 0.0, yawExtra = 0.0 }
        local dt = math.min(0.1, (now - (st.pv.spinAt or now)) / 1000.0)
        st.pv.spinAt = now
        st.pv.phase = (st.pv.phase + SPIN_DPS * dt) % 360.0
        local yaw = (camYaw + 90.0 + p.yawExtra + st.pv.phase) % 360.0

        local ped = PLAYER.PLAYER_PED_ID()
        local inVehicle = ped and ped ~= 0 and PED.IS_PED_IN_ANY_VEHICLE(ped, false)
        local firstPerson = inVehicle
            and CAM.GET_FOLLOW_VEHICLE_CAM_VIEW_MODE() == 4
            or (not inVehicle and CAM.GET_FOLLOW_PED_CAM_VIEW_MODE() == 4)
        local anchor = ped
        if firstPerson and inVehicle then
            local vehicle = PED.GET_VEHICLE_PED_IS_IN(ped, false)
            if vehicle and vehicle ~= 0 and ENTITY.DOES_ENTITY_EXIST(vehicle) then
                anchor = vehicle
            end
        end
        local o = (anchor and anchor ~= 0)
            and ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(anchor, 0.0, 0.0, 0.0) or nil
        if o and not (firstPerson and not inVehicle) then
            ENTITY.ATTACH_ENTITY_TO_ENTITY(st.pv.obj, anchor, -1,
                x - o.x, y - o.y, z - o.z,
                p.pitch, p.roll, yaw,
                false, false, false, false,
                2,
                false,
                false)
        else
            ENTITY.DETACH_ENTITY(st.pv.obj, true, false)
            ENTITY.SET_ENTITY_COORDS_NO_OFFSET(st.pv.obj, x, y, z, false, false, false)
            ENTITY.SET_ENTITY_ROTATION(st.pv.obj, p.pitch, p.roll, yaw, 2, true)
        end

    end


    local function buildRow(ped, rec, maySync)
        local cfg = cfgFor(rec.h)
        local ammo = WEAPON.GET_AMMO_IN_PED_WEAPON(ped, rec.h) or 0
        if not cfg.ammoEdited then cfg.ammo = ammo end
        local didSync = false
        if maySync and not cfg.synced then
            cfg.synced, didSync = true, true
            if rec.e.c then
                for _, c in ipairs(rec.e.c) do
                    if not HIDDEN_COMPONENT[c[2]]
                       and WEAPON.HAS_PED_GOT_WEAPON_COMPONENT(ped, rec.h, c[2]) then
                        clearCompConflicts(cfg, rec.h, c[2])
                        cfg.comps[c[2]] = true
                    end
                end
            end
            local t = WEAPON.GET_PED_WEAPON_TINT_INDEX(ped, rec.h)
            if t and t >= 0 then cfg.tint = t end
        end
        local n = 0
        for _ in pairs(cfg.comps) do n = n + 1 end
        local sub = hasAmmoControl(rec)
            and (ammo .. ((ammo == 1) and " round" or " rounds")) or "Owned"
        if n > 0 then
            local attachmentText = n .. ((n == 1) and " attachment" or " attachments")
            sub = hasAmmoControl(rec) and (sub .. " - " .. attachmentText) or attachmentText
        end
        return { h = rec.h, rec = rec, cfg = cfg, ammo = ammo, sub = sub }, didSync
    end

    local function scanStep()
        if not st.scan.pending and nowMs() - st.scan.idleAt < SCAN_IDLE_MS then return end
        local ped = PLAYER.PLAYER_PED_ID()
        if not ped or ped == 0 then return end
        local budget = 1
        for _ = 1, SCAN_SLICE do
            local rec = FLAT[st.scan.i]
            if rec and hasAmmoControl(rec) and st.ammoBuf ~= 0 then
                Memory.WriteInt(st.ammoBuf, 0)
                if WEAPON.GET_MAX_AMMO(ped, rec.h, st.ammoBuf) then
                    local maximum = Memory.ReadInt(st.ammoBuf)
                    if maximum and maximum > 0 then st.maxAmmo[rec.h] = maximum end
                end
            end
            if rec and WEAPON.HAS_PED_GOT_WEAPON(ped, rec.h, false) then
                local row, didSync = buildRow(ped, rec, budget > 0)
                if didSync then budget = budget - 1 end
                st.scan.out[#st.scan.out + 1] = row
            end
            st.scan.i = st.scan.i + 1
            if st.scan.i > #FLAT then
                st.list = st.scan.out
                st.owned = {}
                for _, row in ipairs(st.list) do st.owned[row.h] = row end
                st.countLabel = (#st.list == 1) and "1 weapon carried"
                                                or (#st.list .. " weapons carried")
                st.scan.out, st.scan.i = {}, 1
                st.scan.pending, st.scan.idleAt = false, nowMs()
                return
            end
        end
    end


    local function safeLoadoutName(name)
        name = (tostring(name or ""):match("^%s*(.-)%s*$") or "")
        return name:gsub("[^%w%-%_ ]", "")
    end

    local function setLoadoutStatus(message)
        st.loadoutStatus = tostring(message or "")
        st.loadoutStatusUntil = st.loadoutStatus ~= "" and (nowMs() + 10000) or 0
    end

    local function refreshLoadouts()
        st.savedLoadouts = {}
        local files = FileMgr.FindFiles(LOADOUT_DIR, ".cfg", false)
        if files then
            for _, path in ipairs(files) do
                local name = path:match("([^\\/]+)%.cfg$")
                if name and name ~= "autoload" then
                    st.savedLoadouts[#st.savedLoadouts + 1] = name
                end
            end
        end
        table.sort(st.savedLoadouts)
        if st.savedIdx > #st.savedLoadouts then st.savedIdx = math.max(1, #st.savedLoadouts) end
    end

    local function findCamoState(ped, rec)
        for i, l in ipairs(rec.e.l or {}) do
            if WEAPON.HAS_PED_GOT_WEAPON_COMPONENT(ped, rec.h, l[2]) then
                local col = WEAPON.GET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, rec.h, l[2]) or 0
                return i, math.max(0, col)
            end
        end
        return 0, 0
    end

    local function captureCurrentLoadout(ped)
        local out = {}
        out.selected = WEAPON.GET_SELECTED_PED_WEAPON(ped) or 0
        for _, rec in ipairs(FLAT) do
            if WEAPON.HAS_PED_GOT_WEAPON(ped, rec.h, false) then
                local comps = {}
                for _, c in ipairs(rec.e.c or {}) do
                    if not HIDDEN_COMPONENT[c[2]]
                       and WEAPON.HAS_PED_GOT_WEAPON_COMPONENT(ped, rec.h, c[2]) then
                        clearCompConflicts({ comps = comps }, rec.h, c[2])
                        comps[c[2]] = true
                    end
                end
                local camo, camoCol = findCamoState(ped, rec)
                out[#out + 1] = {
                    hash = rec.h,
                    ammo = math.max(0, WEAPON.GET_AMMO_IN_PED_WEAPON(ped, rec.h) or 0),
                    tint = math.max(0, WEAPON.GET_PED_WEAPON_TINT_INDEX(ped, rec.h) or 0),
                    camo = camo, camoCol = camoCol, comps = comps,
                }
            end
        end
        return out
    end

    local function ensureBaseline(ped)
        if not st.baseline then st.baseline = captureCurrentLoadout(ped) end
    end

    local function queueStartupBaseline()
        if st.baseline or st.baselinePending then return end
        st.baselinePending = true
        Script.QueueJob(function()
            local ped = PLAYER.PLAYER_PED_ID()
            if ped and ped ~= 0 and ENTITY.DOES_ENTITY_EXIST(ped) then
                st.baseline = captureCurrentLoadout(ped)
            end
            st.baselinePending = false
        end)
    end

    local function serializeLoadout(records)
        local lines = { "-- VibeScript Loadout", "version=1",
                        "selected=" .. tostring(records.selected or 0) }
        for _, w in ipairs(records) do
            local comps = {}
            for comp in pairs(w.comps or {}) do
                if not HIDDEN_COMPONENT[comp] then comps[#comps + 1] = tostring(comp) end
            end
            table.sort(comps)
            lines[#lines + 1] = table.concat({
                "weapon", tostring(w.hash), tostring(w.ammo or 0), tostring(w.tint or 0),
                tostring(w.camo or 0), tostring(w.camoCol or 0), table.concat(comps, ",")
            }, "|")
        end
        return table.concat(lines, "\n")
    end

    local function saveNamedLoadout(name)
        name = safeLoadoutName(name)
        if name == "" then setLoadoutStatus("Enter a loadout name.") return end
        Script.QueueJob(function()
            local ped = PLAYER.PLAYER_PED_ID()
            local content = serializeLoadout(captureCurrentLoadout(ped))
            local ok = FileMgr.WriteFileContent(
                LOADOUT_DIR .. name .. ".cfg", content, false)
            setLoadoutStatus(ok and ("Saved " .. name .. ".") or "Save failed.")
            if ok then
                refreshLoadouts()
                for i, saved in ipairs(st.savedLoadouts) do
                    if saved == name then st.savedIdx = i break end
                end
            end
        end)
    end

    local function parseLoadout(content)
        if not content or not content:match("version=1") then return nil end
        local out = {}
        out.selected = tonumber(content:match("selected=(-?%d+)")) or 0
        for line in content:gmatch("[^\r\n]+") do
            local tag, hs, ammo, tint, camo, camoCol, compText =
                line:match("^([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]+)|(.*)$")
            local hash = (tag == "weapon") and tonumber(hs) or nil
            if hash and BY_HASH[hash] then
                local cfg = { comps = {} }
                for cs in tostring(compText or ""):gmatch("%d+") do
                    local comp = tonumber(cs)
                    if comp then
                        clearCompConflicts(cfg, hash, comp)
                        cfg.comps[comp] = true
                    end
                end
                out[#out + 1] = {
                    hash = hash, ammo = math.max(0, tonumber(ammo) or 0),
                    tint = math.max(0, tonumber(tint) or 0),
                    camo = math.max(0, tonumber(camo) or 0),
                    camoCol = math.max(0, tonumber(camoCol) or 0), comps = cfg.comps,
                }
            end
        end
        return out
    end

    local function applyLoadoutRecords(ped, weapons)
        WEAPON.REMOVE_ALL_PED_WEAPONS(ped, true)
        for _, w in ipairs(weapons) do
            local rec = BY_HASH[w.hash]
            WEAPON.GIVE_WEAPON_TO_PED(ped, w.hash, w.ammo, false, false)
            for comp in pairs(w.comps or {}) do
                if not HIDDEN_COMPONENT[comp] then
                    WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, w.hash, comp)
                end
            end
            if hasTintControl(rec) then
                WEAPON.SET_PED_WEAPON_TINT_INDEX(ped, w.hash, w.tint)
            end
            local l = rec and rec.e.l and rec.e.l[w.camo]
            if l then
                WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, w.hash, l[2])
                if not l[4] then
                    WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, w.hash, l[2], w.camoCol)
                end
                if l[3] then
                    WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, w.hash, l[3])
                    if not l[4] then
                        WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, w.hash, l[3], w.camoCol)
                    end
                end
            end
            WEAPON.SET_PED_AMMO(ped, w.hash, w.ammo, false)
            st.cfg[w.hash] = nil
        end
        if weapons.selected and weapons.selected ~= 0 then
            WEAPON.SET_CURRENT_PED_WEAPON(ped, weapons.selected, true)
        end
        st.scan.pending, st.used = true, true
    end

    local function loadNamedLoadout(name, startup)
        name = safeLoadoutName(name)
        if name == "" then return false end
        local ok, weapons = pcall(function()
            return parseLoadout(FileMgr.ReadFileContent(LOADOUT_DIR .. name .. ".cfg"))
        end)
        if not ok then
            setLoadoutStatus(name .. " is malformed.")
            logErr(("Loadout \"%s\" is malformed; not loaded."):format(name))
            GUI.AddToast("VibeScript", st.loadoutStatus, 10000)
            return false
        end
        if not weapons then
            setLoadoutStatus("Could not read " .. name .. ".")
            return false
        end
        Script.QueueJob(function()
            local ped = PLAYER.PLAYER_PED_ID()
            ensureBaseline(ped)
            st.dirty = true
            applyLoadoutRecords(ped, weapons)
            setLoadoutStatus((startup and "Autoloaded " or "Loaded ") .. name .. ".")
            GUI.AddToast("VibeScript", st.loadoutStatus, 2500)
        end)
        return true
    end

    local function resetSessionLoadout()
        if not st.dirty or not st.baseline then return end
        Script.QueueJob(function()
            local ped = PLAYER.PLAYER_PED_ID()
            applyLoadoutRecords(ped, st.baseline)
            st.dirty = false
            setLoadoutStatus("Restored the weapons carried when VibeScript started.")
            GUI.AddToast("VibeScript", "Startup weapons restored.", 2500)
        end)
    end

    local function deleteNamedLoadout(name)
        name = safeLoadoutName(name)
        if name == "" then return end
        FileMgr.DeleteFile(LOADOUT_DIR .. name .. ".cfg")
        if st.autoloadName == name then
            st.autoload, st.autoloadName = false, ""
            FileMgr.WriteFileContent(AUTOLOAD_FILE, "", false)
        end
        setLoadoutStatus("Deleted " .. name .. ".")
        refreshLoadouts()
    end

    refreshLoadouts()
    if FileMgr.DoesFileExist(AUTOLOAD_FILE) then
        local name = safeLoadoutName(FileMgr.ReadFileContent(AUTOLOAD_FILE))
        if name ~= "" then
            st.autoload, st.autoloadName = true, name
            for i, saved in ipairs(st.savedLoadouts) do
                if saved == name then st.savedIdx = i break end
            end
        end
    end


    local function camoEntry(hash, idx)
        local rec = BY_HASH[hash]
        local e = rec and rec.e
        if not e or not e.l or idx <= 0 then return nil end
        return e.l[idx]
    end

    local PENDING_SINK = {
        addComp    = function(cfg, hash, comp)
            clearCompConflicts(cfg, hash, comp)
            cfg.comps[comp] = true
        end,
        removeComp = function(cfg, hash, comp) cfg.comps[comp] = nil end,
        setTint    = function(cfg, hash, idx)
            cfg.tint = idx
            local finish = camoEntry(hash, cfg.camoIdx)
            if finish and finish[4] then cfg.camoIdx = 0 end
        end,
        setCamo    = function(cfg, hash, idx)
            local finish = camoEntry(hash, idx)
            cfg.camoIdx = idx
            if finish and finish[4] then cfg.tint = 0 end
        end,
        setCamoCol = function(cfg, hash, idx) cfg.camoColor = idx end,
    }

    local LIVE_SINK = {
        addComp = function(cfg, hash, comp)
            local removed = clearCompConflicts(cfg, hash, comp)
            cfg.comps[comp] = true
            Script.QueueJob(function()
                local ped = PLAYER.PLAYER_PED_ID()
                ensureBaseline(ped); st.dirty = true
                for _, old in ipairs(removed) do
                    WEAPON.REMOVE_WEAPON_COMPONENT_FROM_PED(ped, hash, old)
                end
                WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, hash, comp)
                st.scan.pending, st.used = true, true
            end)
        end,
        removeComp = function(cfg, hash, comp)
            cfg.comps[comp] = nil
            Script.QueueJob(function()
                local ped = PLAYER.PLAYER_PED_ID()
                ensureBaseline(ped); st.dirty = true
                WEAPON.REMOVE_WEAPON_COMPONENT_FROM_PED(ped, hash, comp)
                st.scan.pending, st.used = true, true
            end)
        end,
        setTint = function(cfg, hash, idx)
            cfg.tint = idx
            local finish = camoEntry(hash, cfg.camoIdx)
            local dropped = (finish and finish[4]) and finish or nil
            if dropped then cfg.camoIdx, finish = 0, nil end
            local finishColor = cfg.camoColor
            Script.QueueJob(function()
                local ped = PLAYER.PLAYER_PED_ID()
                ensureBaseline(ped); st.dirty = true
                if dropped then
                    WEAPON.REMOVE_WEAPON_COMPONENT_FROM_PED(ped, hash, dropped[2])
                    if dropped[3] then
                        WEAPON.REMOVE_WEAPON_COMPONENT_FROM_PED(ped, hash, dropped[3])
                    end
                end
                WEAPON.SET_PED_WEAPON_TINT_INDEX(ped, hash, idx)
                if finish then
                    WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, hash, finish[2])
                    if not finish[4] then
                        WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(
                            ped, hash, finish[2], finishColor)
                    end
                    if finish[3] then
                        WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, hash, finish[3])
                        if not finish[4] then
                            WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(
                                ped, hash, finish[3], finishColor)
                        end
                    end
                end
                st.used = true
                if dropped then st.scan.pending = true end
            end)
        end,
        setCamo = function(cfg, hash, idx)
            local old, new = camoEntry(hash, cfg.camoIdx), camoEntry(hash, idx)
            cfg.camoIdx = idx
            if new and new[4] then cfg.tint = 0 end
            local col = cfg.camoColor
            Script.QueueJob(function()
                local ped = PLAYER.PLAYER_PED_ID()
                ensureBaseline(ped); st.dirty = true
                if old then
                    WEAPON.REMOVE_WEAPON_COMPONENT_FROM_PED(ped, hash, old[2])
                    if old[3] then WEAPON.REMOVE_WEAPON_COMPONENT_FROM_PED(ped, hash, old[3]) end
                end
                if new then
                    if new[4] then WEAPON.SET_PED_WEAPON_TINT_INDEX(ped, hash, 0) end
                    WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, hash, new[2])
                    if not new[4] then
                        WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, hash, new[2], col)
                    end
                    if new[3] then
                        WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, hash, new[3])
                        if not new[4] then
                            WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, hash, new[3], col)
                        end
                    end
                end
                st.scan.pending, st.used = true, true
            end)
        end,
        setCamoCol = function(cfg, hash, idx)
            cfg.camoColor = idx
            local cur = camoEntry(hash, cfg.camoIdx)
            if not cur or cur[4] then return end
            Script.QueueJob(function()
                local ped = PLAYER.PLAYER_PED_ID()
                ensureBaseline(ped); st.dirty = true
                WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, hash, cur[2], idx)
                if cur[3] then
                    WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, hash, cur[3], idx)
                end
                st.used = true
            end)
        end,
    }

    local function queueAmmo(hash, amount)
        Script.QueueJob(function()
            local ped = PLAYER.PLAYER_PED_ID()
            ensureBaseline(ped); st.dirty = true
            WEAPON.SET_PED_AMMO(ped, hash, math.max(0, amount or 0), false)
            st.scan.pending, st.used = true, true
        end)
    end

    local function queueEquip(hash)
        Script.QueueJob(function()
            local ped = PLAYER.PLAYER_PED_ID()
            WEAPON.SET_CURRENT_PED_WEAPON(ped, hash, true)
            st.used = true
            if not MK2_SUPERSEDES[hash] then return end
            for _ = 1, 12 do
                Script.Yield(50)
                if not WEAPON.HAS_PED_GOT_WEAPON(PLAYER.PLAYER_PED_ID(), hash, false) then
                    local rec = BY_HASH[hash]
                    logf("Loadout: freemode stripped %s on equip (Mk II upgrade owned)",
                         rec and rec.e.n or tostring(hash))
                    GUI.AddToast("VibeScript", (rec and rec.e.n or "That weapon")
                        .. " was removed by GTA Online: you own its Mk II upgrade.", 5000)
                    st.scan.pending = true
                    return
                end
            end
        end)
    end

    local function queueRemove(hash)
        if st.sel == hash then st.sel = 0 end
        st.cfg[hash] = nil
        Script.QueueJob(function()
            local ped = PLAYER.PLAYER_PED_ID()
            ensureBaseline(ped); st.dirty = true
            WEAPON.REMOVE_WEAPON_FROM_PED(ped, hash)
            st.scan.pending, st.used = true, true
        end)
    end

    local function queueGive(we, cfg, ammo)
        local comps = {}
        for h in pairs(cfg.comps) do
            if not HIDDEN_COMPONENT[h] then comps[#comps + 1] = h end
        end
        local tint, camoIdx, camoCol = cfg.tint, cfg.camoIdx, cfg.camoColor
        local allowTint = hasTintControl(BY_HASH[we.h]) and (st.tintMax[we.h] or 0) > 1
        Script.QueueJob(function()
            WEAPON.REQUEST_WEAPON_ASSET(we.h, 31, 0)
            local tries = 0
            while not WEAPON.HAS_WEAPON_ASSET_LOADED(we.h) and tries < 100 do
                Script.Yield(10)
                tries = tries + 1
            end
            if not WEAPON.HAS_WEAPON_ASSET_LOADED(we.h) then
                logf("Loadout give failed: asset %d never loaded", we.h)
                GUI.AddToast("VibeScript", "That weapon did not load. Try again.", 3000)
                return
            end
            local ped = PLAYER.PLAYER_PED_ID()
            ensureBaseline(ped); st.dirty = true
            WEAPON.GIVE_WEAPON_TO_PED(ped, we.h, ammo, false, false)
            for _, h in ipairs(comps) do
                WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, we.h, h)
            end
            if allowTint then WEAPON.SET_PED_WEAPON_TINT_INDEX(ped, we.h, tint) end
            local l = (camoIdx > 0) and we.l and we.l[camoIdx] or nil
            if l then
                WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, we.h, l[2])
                if not l[4] then
                    WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, we.h, l[2], camoCol)
                end
                if l[3] then
                    WEAPON.GIVE_WEAPON_COMPONENT_TO_PED(ped, we.h, l[3])
                    if not l[4] then
                        WEAPON.SET_PED_WEAPON_COMPONENT_TINT_INDEX(ped, we.h, l[3], camoCol)
                    end
                end
            end
            WEAPON.SET_PED_AMMO(ped, we.h, ammo, false)
            st.cfg[we.h] = nil
            st.scan.pending, st.used = true, true
            GUI.AddToast("VibeScript", "Gave " .. we.n .. ".", 2500)
        end)
    end

    local ACT_BTN_W = 90
    local FIELD_LABEL_W = 118

    local function beginField(label, rightReserve)
        local x = ImGui.GetCursorPosX()
        ImGui.TextUnformatted(label)
        ImGui.SameLine()
        ImGui.SetCursorPosX(x + FIELD_LABEL_W)
        ImGui.SetNextItemWidth(rightReserve and -(rightReserve + 10) or -1)
    end

    local function cfgRows(cfg, entry, sink, hash)
        local list = visibleComps(entry, hash)
        if #list > 0 then
            if cfg.compIdx > #list then cfg.compIdx = 1 end
            local cur = list[cfg.compIdx]
            beginField("Attachment", ACT_BTN_W)
            if Widget.beginCombo("##attachment", cur and cur.label or "(none)") then
                for i, it in ipairs(list) do
                    if ImGui.Selectable(it.label, i == cfg.compIdx) then cfg.compIdx = i end
                end
                Widget.endCombo()
            end
            ImGui.SameLine()
            local on = cur and cfg.comps[cur.h]
            local actionLabel = on and "Remove##attachment" or "Add##attachment"
            if ImGui.Button(actionLabel, ACT_BTN_W, 0) and cur then
                if on then sink.removeComp(cfg, hash, cur.h)
                else sink.addComp(cfg, hash, cur.h) end
            end
            for i, it in ipairs(list) do
                if cfg.comps[it.h] then
                    ImGui.PushID(1000 + i)
                    if ImGui.SmallButton("X") then sink.removeComp(cfg, hash, it.h) end
                    ImGui.SameLine()
                    ImGui.TextUnformatted(it.label)
                    ImGui.PopID()
                end
            end
        end

        local labels = WDB_TINTS[entry.t] or WDB_TINTS[1]
        local rec = BY_HASH[hash]
        local tintAllowed = hasTintControl(rec)
        local nt = tintAllowed and math.min(#labels, st.tintMax[hash] or 0) or 0
        if nt > 1 then
            if cfg.tint >= nt then cfg.tint = 0 end
            beginField("Tint")
            if Widget.beginCombo("##tint", labels[cfg.tint + 1] or labels[1]) then
                for i = 1, nt do
                    local sel = ((i - 1) == cfg.tint)
                    if ImGui.Selectable(labels[i], sel) and not sel then
                        sink.setTint(cfg, hash, i - 1)
                    end
                end
                Widget.endCombo()
            end
        end

        local camoChoices = {}
        local camoOK = st.camoOK[hash]
        for i, camo in ipairs(entry.l or {}) do
            if camoOK and camoOK[i] then
                camoChoices[#camoChoices + 1] = { index = i, value = camo }
            end
        end
        if #camoChoices > 0 then
            if cfg.camoIdx > 0 and not (camoOK and camoOK[cfg.camoIdx]) then cfg.camoIdx = 0 end
            beginField("Finish / Camo")
            local cn = (cfg.camoIdx > 0) and entry.l[cfg.camoIdx] and entry.l[cfg.camoIdx][1]
                       or "None"
            if Widget.beginCombo("##finish_camo", cn) then
                local none = (cfg.camoIdx == 0)
                if ImGui.Selectable("None", none) and not none then
                    sink.setCamo(cfg, hash, 0)
                end
                for _, choice in ipairs(camoChoices) do
                    local sel = (choice.index == cfg.camoIdx)
                    if ImGui.Selectable(choice.value[1], sel) and not sel then
                        sink.setCamo(cfg, hash, choice.index)
                    end
                end
                Widget.endCombo()
            end
            local selectedCosmetic = (cfg.camoIdx > 0) and entry.l[cfg.camoIdx] or nil
            if selectedCosmetic and not selectedCosmetic[4] then
                beginField("Camo Colour")
                if Widget.beginCombo("##camo_colour",
                        WDB_CAMO_COLORS[cfg.camoColor + 1] or WDB_CAMO_COLORS[1]) then
                    for i, nm in ipairs(WDB_CAMO_COLORS) do
                        local sel = ((i - 1) == cfg.camoColor)
                        if ImGui.Selectable(nm, sel) and not sel then
                            sink.setCamoCol(cfg, hash, i - 1)
                        end
                    end
                    Widget.endCombo()
                end
            end
        end
    end


    local function renderCatalogRow(rec, ownedRow, availW)
        local owned = ownedRow ~= nil
        local cfg = owned and ownedRow.cfg or cfgFor(rec.h)
        local expanded = (st.sel == rec.h)
        local superseded = (not owned) and MK2_SUPERSEDES[rec.h]
                           and st.owned[MK2_SUPERSEDES[rec.h]] ~= nil
        local sx, sy = ImGui.GetCursorScreenPos()
        ImGui.InvisibleButton("##weapon", availW, ROW_H)
        local clicked, hover = ImGui.IsItemClicked(0), ImGui.IsItemHovered()
        local x2, y2 = sx + availW, sy + ROW_H

        local base = expanded and 48 or (hover and 38 or 28)
        if not owned then base = math.floor(base * 0.67) end
        ImGui.AddRectFilled(sx, sy, x2, y2, base - 5, base - 9, base + 7,
                            owned and 238 or 195, 6)
        ImGui.AddRect(sx, sy, x2, y2, 255, 255, 255,
            expanded and 62 or (hover and 34 or 14), 6, 0, 1)
        local c = CAT_COL[rec.tn] or CAT_DEF
        ImGui.AddRectFilled(sx + 2, sy + 3, sx + (expanded and 7 or 5), y2 - 3,
                            c[1], c[2], c[3], owned and 255 or 115, 2)
        local text = owned and 238 or 145
        ImGui.AddText(sx + 14, sy + 4, rec.e.n, text, text, owned and 242 or 152, 255)
        local sub = owned and ownedRow.sub
                    or (superseded and "Replaced by the Mk II" or "Not owned")
        ImGui.AddText(sx + 14, sy + 19, sub, owned and 155 or 105,
                      owned and 157 or 107, owned and 164 or 112, 255)
        local tag, tagOff, tr, tg, tb
        if owned then
            tag, tagOff, tr, tg, tb = "OWNED", 62, 110, 205, 150
        elseif superseded then
            tag, tagOff, tr, tg, tb = "UNAVAILABLE", 101, 242, 184, 77
        else
            tag, tagOff, tr, tg, tb = "AVAILABLE", 88, 115, 125, 135
        end
        ImGui.AddText(x2 - tagOff, sy + 11, tag, tr, tg, tb, 220)

        if clicked then st.sel = expanded and 0 or rec.h end
        if not expanded then return end

        ImGui.Indent(14)
        cfgRows(cfg, rec.e, owned and LIVE_SINK or PENDING_SINK, rec.h)
        if hasAmmoControl(rec) then
            local ammoMax = math.max(1, st.maxAmmo[rec.h] or 9999)
            cfg.ammo = math.min(cfg.ammo or math.min(250, ammoMax), ammoMax)
            beginField("Ammo")
            local ammo, changed = ImGui.SliderInt("##ammo", cfg.ammo, 0, ammoMax, "%d")
            if changed then cfg.ammo, cfg.ammoEdited = ammo, true end
        end
        ImGui.Spacing()

        if owned then
            if hasAmmoControl(rec) then
                if ImGui.Button("Apply Ammo", 110, 0) then queueAmmo(rec.h, cfg.ammo) end
                ImGui.SameLine()
            end
            if ImGui.Button("Equip", 82, 0) then queueEquip(rec.h) end
            ImGui.SameLine()
            ImGui.PushStyleColor(ImGuiCol.Button,        0.55, 0.18, 0.18, 0.95)
            ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.72, 0.24, 0.24, 1.00)
            ImGui.PushStyleColor(ImGuiCol.ButtonActive,  0.42, 0.13, 0.13, 1.00)
            if ImGui.Button("Remove##weapon", 100, 0) then queueRemove(rec.h) end
            ImGui.PopStyleColor(3)
        else
            if superseded then
                ImGui.TextColored(0.95, 0.72, 0.30, 1.00,
                    "You own the Mk II upgrade for this weapon.")
                ImGui.TextDisabled("GTA Online deletes the Mk I as soon as you equip it.")
                ImGui.Spacing()
            end
            ImGui.PushStyleColor(ImGuiCol.Button,        0.20, 0.62, 0.30, 0.95)
            ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.26, 0.78, 0.38, 1.00)
            ImGui.PushStyleColor(ImGuiCol.ButtonActive,  0.16, 0.52, 0.26, 1.00)
            if ImGui.Button("Give " .. rec.e.n, -1, 26) then
                queueGive(rec.e, cfg, cfg.ammo or 250)
            end
            ImGui.PopStyleColor(3)
        end
        ImGui.Unindent(14)
        ImGui.Spacing()
        ImGui.Separator()
    end

    local function renderCatalog()
        ImGui.PushID("LM_Catalog")
        if ClickGUI.BeginCustomChildWindow("Weapon Catalog") then
            ImGui.TextUnformatted(st.countLabel .. " / " .. #FLAT .. " available")
            ImGui.SameLine()
            if ImGui.SmallButton("Refresh") then st.scan.pending = true end
            ImGui.SameLine()
            st.hideUnowned = ImGui.Checkbox("Hide unowned", st.hideUnowned)

            ImGui.SetNextItemWidth(220)
            st.weaponFilter = ImGui.InputText("Search", st.weaponFilter or "", 0)
            ImGui.SameLine()

            if not st.dirty then
                ImGui.PushStyleColor(ImGuiCol.Button, 0.24, 0.24, 0.27, 0.55)
                ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.24, 0.24, 0.27, 0.55)
                ImGui.PushStyleColor(ImGuiCol.ButtonActive, 0.24, 0.24, 0.27, 0.55)
            end
            if ImGui.Button("Restore Weapons", 130, 0) and st.dirty then
                resetSessionLoadout()
            end
            if not st.dirty then ImGui.PopStyleColor(3) end
            if ImGui.IsItemHovered() then
                ImGui.SetTooltip(st.dirty
                    and "Restore every weapon, attachment, finish, tint, and ammo count captured when VibeScript started."
                     or "No loadout changes have been made this session.")
            end
            ImGui.SameLine()
            st.showPreview = ImGui.Checkbox("3D Model Preview", st.showPreview)

            if ImGui.SmallButton("Expand All") then
                for i = 1, #WDB do st.categoryOpen[i] = true end
            end
            ImGui.SameLine()
            if ImGui.SmallButton("Collapse All") then
                for i = 1, #WDB do st.categoryOpen[i] = false end
            end
            if st.pvStatus ~= "" then
                ImGui.SameLine()
                ImGui.TextDisabled(st.pvStatus)
            end
            ImGui.Separator()

                local filter = (st.weaponFilter or ""):lower()
                local availW = ImGui.GetContentRegionAvail() or 0
                local shown = 0
                for ti, category in ipairs(WDB) do
                    local visible = {}
                    for _, weapon in ipairs(category.w) do
                        local rec = BY_HASH[weapon.h]
                        local owned = st.owned[weapon.h]
                        local matches = filter == "" or weapon.n:lower():find(filter, 1, true)
                        if matches and (owned or not st.hideUnowned) then
                            visible[#visible + 1] = { rec = rec, owned = owned }
                        end
                    end
                    if #visible > 0 then
                        local open = filter ~= "" or st.categoryOpen[ti] == true
                        local hx, hy = ImGui.GetCursorScreenPos()
                        ImGui.InvisibleButton("##weapon_type_" .. ti, availW, 28)
                        local headerClicked = ImGui.IsItemClicked(0)
                        local headerHovered = ImGui.IsItemHovered()
                        if headerClicked and filter == "" then
                            st.categoryOpen[ti] = not open
                            open = st.categoryOpen[ti]
                        end
                        local shade = headerHovered and 50 or (open and 43 or 33)
                        ImGui.AddRectFilled(hx, hy, hx + availW, hy + 28,
                                            shade, shade - 5, shade + 12, 235, 5)
                        local col = CAT_COL[category.n] or CAT_DEF
                        ImGui.AddRectFilled(hx + 2, hy + 3, hx + 6, hy + 25,
                                            col[1], col[2], col[3], 230, 2)
                        ImGui.AddText(hx + 13, hy + 6,
                            (open and "v  " or ">  ") .. category.n .. " (" .. #visible .. ")",
                            220, 222, 230, 255)
                        if open then
                            for _, item in ipairs(visible) do
                                ImGui.PushID(tostring(item.rec.h))
                                renderCatalogRow(item.rec, item.owned, availW)
                                ImGui.PopID()
                                shown = shown + 1
                            end
                        else
                            shown = shown + #visible
                        end
                    end
                end
                if shown == 0 then ImGui.TextDisabled("No weapons match this view.") end
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()
    end

    local function renderTab()
        st.seenAt = nowMs()
        local dw, dh = ImGui.GetDisplaySize()
        st.dispW, st.dispH = dw or 0, dh or 0
        local mx, my = ClickGUI.GetPos()
        local mw, mh = ClickGUI.GetSize()
        if not mx or not mw or mw <= 0 then
            mx, my = ImGui.GetWindowPos()
            mw, mh = ImGui.GetWindowSize()
        end
        st.menuX0, st.menuX1 = mx or 0, (mx or 0) + (mw or 0)

        local bw = math.max(280.0, math.min(560.0, st.dispW * 0.28))
        local bh = bw * 0.62
        local mid = math.max(bh * 0.5 + 12, math.min(st.dispH - bh * 0.5 - 12,
                                                     (my or 0) + (mh or 0) * 0.5))
        local cx
        if st.menuX1 + SIDE_GAP + bw < st.dispW then
            cx = st.menuX1 + SIDE_GAP + bw * 0.5
        else
            cx = st.menuX0 - SIDE_GAP - bw * 0.5
        end
        cx = math.max(bw * 0.5 + 12, math.min(st.dispW - bw * 0.5 - 12, cx))
        st.bay = { x0 = cx - bw * 0.5, y0 = mid - bh * 0.5,
                   x1 = cx + bw * 0.5, y1 = mid + bh * 0.5 }
        st.bayAt = nowMs()

        if ImGui.CollapsingHeader("Saved Loadouts") then
            ImGui.SetNextItemWidth(190)
            local edited
            st.loadoutName, edited = ImGui.InputText("Name", st.loadoutName, 0)
            ImGui.SameLine()
            if ImGui.Button("Save", 72, 0) then saveNamedLoadout(st.loadoutName) end

            local selected = st.savedLoadouts[st.savedIdx]
            ImGui.SetNextItemWidth(190)
            if Widget.beginCombo("Saved", selected or "(none saved)") then
                for i, name in ipairs(st.savedLoadouts) do
                    local isSel = (i == st.savedIdx)
                    if ImGui.Selectable(name, isSel) and not isSel then
                        st.savedIdx = i
                        selected = name
                        if st.autoload then
                            st.autoloadName = name
                            FileMgr.WriteFileContent(AUTOLOAD_FILE, name, false)
                        end
                    end
                end
                Widget.endCombo()
            end
            ImGui.SameLine()
            if ImGui.Button("Load", 72, 0) and selected then loadNamedLoadout(selected, false) end
            ImGui.SameLine()
            if ImGui.Button("Delete", 72, 0) and selected then deleteNamedLoadout(selected) end

            local oldAuto = st.autoload
            st.autoload = ImGui.Checkbox("Load selected loadout on startup", st.autoload)
            if st.autoload ~= oldAuto then
                if st.autoload and selected then
                    st.autoloadName = selected
                    FileMgr.WriteFileContent(AUTOLOAD_FILE, selected, false)
                else
                    st.autoload, st.autoloadName = false, ""
                    FileMgr.WriteFileContent(AUTOLOAD_FILE, "", false)
                end
            end
            if st.loadoutStatus ~= "" and nowMs() >= st.loadoutStatusUntil then
                st.loadoutStatus, st.loadoutStatusUntil = "", 0
            end
            if st.loadoutStatus ~= "" then ImGui.TextUnformatted(st.loadoutStatus) end
        end

        ImGui.Separator()

        renderCatalog()
    end


    local function tick()
        if st.shuttingDown then return end
        local playerReady = isPlayerReady()
        if playerReady and not st.baseline then queueStartupBaseline() end

        if st.autoloadPending and playerReady and st.baseline then
            st.autoloadPending = false
            if st.autoload and st.autoloadName ~= "" then
                loadNamedLoadout(st.autoloadName, true)
            end
        end
        local seen = (nowMs() - st.seenAt) < LINGER_MS
        if not (seen and GUI.IsOpen()) then
            destroyPreview()
            st.pvStatus = ""
            return
        end
        if not isPlayerReady() then
            destroyPreview()
            st.pvStatus = "paused"
            return
        end
        scanStep()
        local want = wantedHash()
        probeStep(want)
        if not st.showPreview or not st.bay or (nowMs() - st.bayAt) >= LINGER_MS then
            destroyPreview()
            st.pvStatus = ""
            return
        end
        previewStep(nowMs(), want)
    end

    local function unloadCleanup()
        st.shuttingDown = true
    end

    local function drain()
        st.shuttingDown = true
        if st.drained then return end
        st.drained = true
        destroyPreview()
        releaseVariantModels()
        if st.pv.reqFor ~= 0 then
            local ped = PLAYER.PLAYER_PED_ID()
            local req = st.pv.reqFor
            st.pv.reqFor = 0
            if not (ped and ped ~= 0 and WEAPON.HAS_PED_GOT_WEAPON(ped, req, false)) then
                WEAPON.REMOVE_WEAPON_ASSET(req)
            end
        end
        if st.delBuf ~= 0 then Memory.Free(st.delBuf); st.delBuf = 0 end
        if st.ammoBuf ~= 0 then Memory.Free(st.ammoBuf); st.ammoBuf = 0 end
        if st.dimsBuf ~= 0 then Memory.Free(st.dimsBuf); st.dimsBuf = 0 end
        log("Loadout Manager teardown complete")
    end

    local function save()
        return {
            preview   = st.showPreview and 1 or 0,
        }
    end

    local function load(key, n)
        if type(n) ~= "number" then return end
        n = math.floor(n)
        if key == "preview" then
            st.showPreview = (n ~= 0)
        end
    end

    return {
        renderTab     = renderTab,
        tick          = tick,
        drain         = drain,
        unloadCleanup = unloadCleanup,
        wasUsed       = function() return st.used == true end,
        save          = save,
        load          = load,
        verbose       = false,
    }
end)()

