function sessionBrowser.verifyJoinTarget(row)
    local sb = sessionBrowser

    if sb.state.busy then
        return row.hostRid, "Scan running, joined without a freshness check."
    end
    if not sb.resolveAddresses() or not sb.allocBuffers() then
        return row.hostRid, nil
    end

    local cands, seen = {}, {}
    local function add(rid)
        rid = math.tointeger(rid or 0) or 0
        if rid > 0 and not seen[rid] and #cands < sb.MAX_BATCH then
            seen[rid] = true
            cands[#cands + 1] = rid
        end
    end
    add(row.hostRid)
    if row.members then
        for _, rid in ipairs(row.members) do add(rid) end
    end
    if #cands == 0 then return row.hostRid, nil end

    local got = sb.resolveBatch(cands)
    if #got == 0 then
        return nil, "Could not re-check that lobby - presence returned nothing. Rescan."
    end

    local want = sb.identity(row)

    local match, viaHost
    for _, session in ipairs(got) do
        if sb.identity(session) == want then
            match = match or session
            if session.viaRid == row.hostRid then
                viaHost = session
                break
            end
        end
    end

    local session = viaHost or match
    if session then
        local freshHost = session.hostRid
        local note
        if freshHost and freshHost ~= 0 and row.hostRid and row.hostRid ~= 0 then
            if freshHost ~= row.hostRid then
                note = viaHost
                    and "This lobby migrated - the host you saw is still in it, but no longer hosting."
                    or "Host left and the lobby migrated; joining through a player still in there."
            end
        elseif session.token ~= row.token then
            note = "Host left and the lobby migrated; joining through a player still in there."
        end
        return session.viaRid, note, session
    end

    return nil, "All known players have moved on. Session expired.", nil, true
end

function sessionBrowser.refreshRow(row, session)
    local sb = sessionBrowser
    if sb.state.busy then return false end
    local task = sb.detailSubmit({ session })
    if not task or not sb.awaitTask(task) then return false end
    local was = sb.identity(row)
    for _, fresh in ipairs(sb.detailCollect(task)) do
        if sb.identity(fresh) == was then
            for k, v in pairs(fresh) do
                if k ~= "members" and k ~= "viaRid" and k ~= "isOwn" then row[k] = v end
            end
            local now = sb.identity(row)
            if now ~= was then
                sb.cooldown[was] = nil
                sb.rowCache[was] = nil
            end
            sb.cooldown[now] = Time.GetEpoche()
            sb.rowCache[now] = row
            return true
        end
    end
    return false
end

function sessionBrowser.dropRow(row)
    local sb = sessionBrowser
    local key = sb.identity(row)
    if key ~= nil then
        sb.cooldown[key] = nil
        sb.rowCache[key] = nil
    end
    local snap = {}
    for _, r in ipairs(sb.state.results) do
        if r ~= row then snap[#snap + 1] = r end
    end
    sb.state.results = snap
    sb.state.answered = sb.listableCount(snap)
end

function sessionBrowser.joinLobby(row)
    local sb = sessionBrowser
    if not row or not row.hostRid or row.hostRid == 0 then
        sb.toast("This lobby has no readable host RID to join.", 5000)
        return
    end
    local mismatch = sb.rowIncompatible(row)
    if mismatch then
        sb.toast(("That lobby is on a different %s - the host would refuse the "
            .. "join."):format(mismatch), 7000)
        return
    end
    local joinFeat = rejoin.resolveBuiltin({ "Join Rockstar Id" })
    if not joinFeat then
        sb.toast("Cherax 'Join Rockstar Id' feature not found - cannot join.", 7000)
        return
    end
    if not FeatureMgr.GetFeature(rejoin.scapiRidHash) then
        sb.toast("Cherax SC-API Rockstar Id input not found - cannot join.", 7000)
        return
    end
    if sb.joinBusy then
        sb.toast("Already checking a lobby.", 4000)
        return
    end
    sb.toast("Confirming session still exists...", 3000)
    Script.QueueJob(function()
        sb.joinBusy = true
        local ok, err = pcall(sb.joinRun, row, joinFeat)
        sb.joinBusy = false
        if not ok then
            sb.logError("Join failed: %s", tostring(err))
            sb.toast("Join failed: " .. tostring(err), 8000)
        end
    end)
end

function sessionBrowser.joinRun(row, joinFeat)
    local sb = sessionBrowser
    local rid, note, session, expired = sb.verifyJoinTarget(row)
    if not rid then
        if expired then sb.dropRow(row) end
        sb.toast(note or "That lobby is gone. Rescan.", 6000)
        return
    end
    if session then sb.refreshRow(row, session) end

    if note then
        sb.toast(note, 7000)
    else
        sb.toast(("Joining %s..."):format(tostring(row.hostName or rid)), 4000)
    end

    if ShouldUnload() or scriptUnloading then return end

    FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, math.tointeger(rid) or 0)
    joinFeat:TriggerCallback()
    FeatureMgr.SetFeatureInt(rejoin.scapiRidHash, 0)

    sb.confirmJoinedDisc(math.tointeger(rid), row.disc)
end

function sessionBrowser.displayCap(row)
    return row.maxPlayers and sessionBrowser.PLAYER_CAP or nil
end

function sessionBrowser.fillColor(players, maxPlayers)
    local p = (maxPlayers and maxPlayers > 0) and (players / maxPlayers) or 0
    if p >= 0.75 then return { 120, 225, 130 } end
    if p >= 0.40 then return { 235, 205,  95 } end
    return { 165, 170, 185 }
end

function sessionBrowser.renderResults()
    local sb = sessionBrowser

    local shown, hidden, incompat = 0, 0, 0
    for _, row in ipairs(sb.state.results) do
        if sb.rowIncompatible(row) then
            incompat = incompat + 1
        elseif sb.isListable(row) then
            if sb.matchesSearch(row) then shown = shown + 1 else hidden = hidden + 1 end
        end
    end
    local note = (hidden > 0) and ("%d shown, %d hidden"):format(shown, hidden)
        or ("%d shown"):format(shown)
    if incompat > 0 then note = note .. (", %d other build"):format(incompat) end
    sb.sectionHeader("LOBBIES", note)

    if #sb.state.results == 0 then
        if sb.state.busy then
            ImGui.TextColored(0.55, 0.8, 1.0, 1.0,
                "Scanning - lobbies appear here as hosts answer...")
        else
            ImGui.TextDisabled("No results yet - press VibeNet Scan or Local Scan.")
        end
        return
    end

    if shown == 0 then
        ImGui.PushTextWrapPos(0)
        if hidden > 0 then
            ImGui.TextDisabled(("All %d lobbies are hidden by the filters."):format(hidden))
        elseif incompat > 0 and incompat == #sb.state.results then
            ImGui.TextDisabled(("All %d lobbies found are running a different game "
                .. "build and would refuse the join. Scan again - the shared pool "
                .. "carries players from both builds."):format(incompat))
        else
            ImGui.TextColored(1.0, 0.7, 0.3, 1.0, ("None of the %d lobbies found are "
                .. "joinable public sessions. If that looks wrong, run the Sanity "
                .. "check on the Debug tab - it says whether the decode is reading "
                .. "the right bytes."):format(#sb.state.results))
        end
        ImGui.PopTextWrapPos()
        return
    end

    local function clamp255(v)
        v = math.floor(v + 0.5)
        return (v < 0) and 0 or (v > 255) and 255 or v
    end

    local _, availY = ImGui.GetContentRegionAvail()
    if not availY or availY < 140 then availY = 140 end
    if ImGui.BeginChild("##BrowserResults", -1, availY, false, 0) then
        local H, JW, JH = 50, 74, 30
        local availW = ImGui.GetContentRegionAvail()
        local hoverChanged = false
        local visibleIndex = 0

        for _, row in ipairs(sb.state.results) do
            if sb.passesFilter(row) then
                visibleIndex = visibleIndex + 1
                local sx, sy = ImGui.GetCursorScreenPos()
                local wx, wy = ImGui.GetCursorPosX(), ImGui.GetCursorPosY()
                local x2, y2 = sx + availW, sy + H
                local hover = ImGui.IsMouseHoveringRect(sx, sy, x2, y2)
                if hover and (sb.state.busy or sb.state.hoveredResultKey) then
                    local key = sb.identity(row)
                    if key ~= sb.state.hoveredResultKey then
                        sb.state.hoveredResultKey = key
                        sb.state.hoveredResultIndex = visibleIndex
                        hoverChanged = true
                    end
                end

                local bg = hover and 46 or 30
                ImGui.AddRectFilled(sx, sy, x2, y2, bg - 4, bg - 8, bg + 6, 240, 8)
                ImGui.AddRect(sx, sy, x2, y2, 255, 255, 255, hover and 40 or 16, 8, 0, 1)

                local rc = (row.region and sb.REGION_COLOR[row.region])
                    or sb.REGION_COLOR_UNKNOWN
                ImGui.AddRectFilled(sx, sy + 2, sx + 4, y2 - 2, rc[1], rc[2], rc[3], 255, 2)

                local cap = sb.displayCap(row)
                local fc = sb.fillColor(row.players, cap)
                local px = sx + 16
                ImGui.SetWindowFontScale(1.15)
                local cnt = cap and ("%d / %d"):format(row.players, cap)
                    or tostring(row.players)
                ImGui.AddText(px, sy + 7, cnt, fc[1], fc[2], fc[3], 255)
                ImGui.SetWindowFontScale(1.0)
                local barW = 96
                ImGui.AddRectFilled(px, sy + 31, px + barW, sy + 36, 64, 64, 78, 255, 2)
                if cap and cap > 0 then
                    local fw = math.floor(barW * math.min(1, row.players / cap))
                    if fw > 0 then
                        ImGui.AddRectFilled(px, sy + 31, px + fw, sy + 36, fc[1], fc[2], fc[3], 255, 2)
                    end
                end

                local hx = sx + 132
                ImGui.SetWindowFontScale(1.12)
                ImGui.AddText(hx, sy + 6, tostring(row.hostName or "?"), 240, 240, 245, 255)
                local hw = ImGui.CalcTextSize(tostring(row.hostName or "?"))
                ImGui.SetWindowFontScale(1.0)

                if row.isOwn then
                    local tag, tx = "YOUR LOBBY", hx + hw + 12
                    local tw, tth = ImGui.CalcTextSize(tag)
                    local top, ht = sy + 6, 17
                    ImGui.AddRectFilled(tx, top, tx + tw + 12, top + ht, 90, 200, 110, 60, 4)
                    ImGui.AddText(tx + 6, top + (ht - tth) * 0.5, tag, 150, 235, 165, 255)
                end

                local age = Time.GetEpoche() - (row.seenAt or 0)
                local ageTxt = row.live and "LIVE"
                    or (age < 5) and "now"
                    or (age < 90) and ("%ds ago"):format(age)
                    or ("%dm ago"):format(math.floor(age / 60))
                local ageW = ImGui.CalcTextSize(ageTxt)
                local rightEdge = sx + availW - JW - 20
                if row.live then
                    ImGui.AddText(rightEdge - ageW, sy + 8, ageTxt, 150, 235, 165, 255)
                else
                    ImGui.AddText(rightEdge - ageW, sy + 8, ageTxt, 150, 150, 165, 255)
                end

                local function chip(cx, text, r, g, b)
                    local tw, tth = ImGui.CalcTextSize(text)
                    local w, top, ht = tw + 12, sy + 27, 18
                    if cx + w > rightEdge then return cx end
                    ImGui.AddRectFilled(cx, top, cx + w, top + ht, r, g, b, 45, 4)
                    ImGui.AddRect(cx, top, cx + w, top + ht, r, g, b, 150, 4, 0, 1)
                    ImGui.AddText(cx + 6, top + (ht - tth) * 0.5, text,
                        clamp255(r + (255 - r) * 0.45),
                        clamp255(g + (255 - g) * 0.45),
                        clamp255(b + (255 - b) * 0.45), 255)
                    return cx + w + 6
                end
                local cx = hx
                local regName = row.region and (sb.REGION_SHORT[row.region]
                    or ("R" .. row.region)) or "?"
                cx = chip(cx, regName, rc[1], rc[2], rc[3])
                if row.isJob then
                    local why = "JOB"
                    if row.purpose and row.purpose ~= sb.SP_FREEROAM then
                        why = (sb.PURPOSE_NAME[row.purpose] or "JOB"):upper()
                    elseif row.gameMode and row.gameMode ~= sb.GAMEMODE_FREEROAM then
                        why = "MODE " .. row.gameMode
                    end
                    cx = chip(cx, why, 255, 120, 90)
                end
                local closed = sb.closedLabel(row)
                if closed then cx = chip(cx, closed, 255, 190, 90) end
                if row.freeAim ~= nil then
                    if row.freeAim then cx = chip(cx, "Free aim", 120, 210, 255)
                    else cx = chip(cx, "Assisted", 255, 175, 90) end
                end
                if row.natType then
                    local nc = sb.NAT_COLOR[row.natType]
                    cx = chip(cx, sb.NAT_NAME[row.natType], nc[1], nc[2], nc[3])
                end
                if row.bosses and row.bosses > 0 then
                    local limit = sb.bossLimitForDisplay()
                    local br, bg, bb = 200, 165, 255
                    local label
                    if limit then
                        if row.bosses > limit then br, bg, bb = 255, 130, 120 end
                        label = ("%d/%d bosses"):format(row.bosses, limit)
                    else
                        label = ("%d bosses"):format(row.bosses)
                    end
                    cx = chip(cx, label, br, bg, bb)
                end
                if row.badSport then chip(cx, "Bad sport", 255, 110, 110) end

                ImGui.SetCursorPosX(wx + availW - JW - 12)
                ImGui.SetCursorPosY(wy + (H - JH) * 0.5)
                ImGui.PushStyleColor(ImGuiCol.Button, 0.20, 0.62, 0.30, 0.95)
                ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.26, 0.78, 0.38, 1.0)
                ImGui.PushStyleColor(ImGuiCol.ButtonActive, 0.16, 0.52, 0.26, 1.0)
                if ImGui.Button("Join##join" .. row.token, JW, JH) then
                    sb.joinLobby(row)
                end
                ImGui.PopStyleColor(3)

                ImGui.SetCursorPosX(wx)
                ImGui.SetCursorPosY(wy)
                ImGui.Dummy(availW, H)
            end
        end
        if hoverChanged then
            sb.state.results = sb.sortedResults(sb.state.results)
        end
    end
    ImGui.EndChild()
end

function sessionBrowser.renderTab()
    local sb = sessionBrowser
    sb.ensureInit()

    if not sb.supported and not sb.finderSupported then
        ImGui.PushID("BrowserUnsupported")
        if ClickGUI.BeginCustomChildWindow("Session Browser") then
            ImGui.PushTextWrapPos(0)
            ImGui.TextColored(1.0, 0.55, 0.35, 1.0, "Unsupported on this build.")
            ImGui.Text("No signature resolved for this edition.")
            ImGui.PopTextWrapPos()
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.PopID()
        return
    end

    ImGui.PushID("BrowserPanel")
    if ClickGUI.BeginCustomChildWindow("Session Browser") then
        sb.renderFilters()
        sb.renderControls()
        ClickGUI.EndCustomChildWindow()
    end
    ImGui.PopID()

    ImGui.PushID("BrowserResults")
    sb.renderResults()
    ImGui.PopID()
end

