                FileMgr.WriteFileContent(settings.autoloadFile, settings.autoload and "1" or "0", false)
            end

            local prevIntro = settings.introEnabled
            settings.introEnabled, _ = ImGui.Checkbox("Play Intro Animation", settings.introEnabled)
