                FileMgr.WriteFileContent(settings.introFile, settings.introEnabled and "1" or "0", false)
            end
            ImGui.SameLine()
            ImGui.TextDisabled("(applies on next inject)")

            ImGui.Spacing()
            ImGui.AlignTextToFramePadding()
            ImGui.Text("Menu Theme")
            ImGui.SameLine()
            ImGui.SetNextItemWidth(220)
            do
                local idx, changed = Widget.combo("##vs_theme", Theme.index(), Theme.labels, #Theme.labels)
                if changed then Theme.select(idx) end
            end
            ImGui.SameLine()
            ImGui.TextDisabled("(applies instantly, saved for next session)")

            ImGui.Spacing()
            ImGui.Separator()
            ImGui.Spacing()

            if ImGui.Button("Save Settings", 200, 30) then
                saveSettings()
            end
            ImGui.SameLine()
            ImGui.TextDisabled("(saves toggles, sliders, and selections)")

            ImGui.Spacing()

            if ImGui.Button("Load Settings", 200, 30) then
                loadSettings()
            end
            ImGui.SameLine()
            if FileMgr.DoesFileExist(settings.file) then
                ImGui.TextDisabled("(saved settings found)")
            else
                ImGui.TextDisabled("(no saved settings)")
            end

            ImGui.Spacing()
            ImGui.Separator()
            ImGui.Spacing()

            if ImGui.Button("Restore Defaults", 200, 30) then
                restoreDefaults()
            end
            ImGui.SameLine()
            ImGui.TextDisabled("(resets everything to defaults, keeps saved config)")

            ImGui.Spacing()

            if ImGui.Button("Delete Saved Settings", 200, 30) then
                deleteSavedSettings()
            end
            ImGui.SameLine()
            ImGui.TextDisabled("(resets to defaults and deletes config file)")

            if #settings.status > 0 then
                ImGui.Spacing()
                ImGui.Separator()
                ImGui.Spacing()
                ImGui.Text(settings.status)
            end

            do
                ImGui.Spacing()
                ImGui.Separator()
                ImGui.Spacing()
                local running = doomLauncher.isRunning()
                local busy = (doomLauncher.phase == "downloading" or doomLauncher.phase == "launching")
                local label = running and "Stop DOOM" or (busy and "Working..." or "DOOM")
                if ImGui.Button(label, 200, 30) then
                    if not busy then doomLauncher.toggle() end
                end
                ImGui.SameLine()
                if #doomLauncher.status > 0 then
                    ImGui.TextDisabled(doomLauncher.status)
                elseif running then
                    ImGui.TextDisabled("(running, close the menu to play)")
                else
                    ImGui.TextDisabled("(rip and tear)")
                end
            end

            ImGui.EndTabItem()
        end
        ImGui.PopID()

        ImGui.EndTabBar()
    end

    local versionText = "v" .. VIBE_VERSION
    local textWidth = ImGui.CalcTextSize(versionText)
    local availWidth = ImGui.GetContentRegionAvail()
    ImGui.SetCursorPosX(ImGui.GetCursorPosX() + availWidth - textWidth)
    local vx, vy = ImGui.GetCursorScreenPos()
    ImGui.TextColored(0, 0, 0, 0, versionText)
    local vt = ImGui.GetTime()
    for i = 1, #versionText do
        local ch  = versionText:sub(i, i)
        local hue = (vt * 0.25 + (i - 1) * 0.09) % 1.0
        local rr, gg, bb = ImGui.ColorConvertHSVtoRGB(hue, 0.85, 1.0)
        ImGui.AddText(vx, vy, ch,
            math.floor(rr * 255 + 0.5), math.floor(gg * 255 + 0.5), math.floor(bb * 255 + 0.5), 255)
        vx = vx + ImGui.CalcTextSize(ch)
    end
    Theme.restore()
end)

