blameDetect = {
    REASON = "Blame Kill (forged attacker)",

    EV_WEAPON_DAMAGE = 6,
    DAMAGE_PLAYER    = 3,
    INVALID_OBJ_ID   = 8191,

    KNOWN_FLAGS = 2 | 8 | 16 | 32 | 64 | 128 | 256 | 4096 | 8192 | 16384 | 131072 | 524288,

    MELEE_MAX_M = 8.0,
    SWEEP_MIN   = 4,
    SWEEP_MS    = 8000,
    QUEUE_CAP   = 64,
    DRAIN       = 4,
    REPEAT_MS   = 2500,
    damageObservers = {},

    LAYOUTS  = { {25, 5}, {24, 4}, {25, 4}, {24, 5} },
    MAX_BITS = 224,
    RELEARN  = 40,

    layout = 1,
    misses = 0,
    hookSeen = false,

    queue = {},
    seen  = {},
    enabled = true,
    protect = false,
    mePid   = -1,
}

;(function()

local bd = blameDetect

function bd.say(fmt, ...)
    local msg = select("#", ...) > 0 and string.format(fmt, ...) or fmt
    Logger.Log(eLogColor.YELLOW, "[VibeScript] BlameDetect: " .. msg)
end

function bd.name(pid)
    if type(pid) ~= "number" or pid < 0 or pid > 31 then return nil end
    local n = Players.GetName(pid)
    if type(n) == "string" and n ~= "" then return n end
    return nil
end


function bd.resolveObj(id)
    if id == nil or id == bd.INVALID_OBJ_ID then return nil end
    local o = NetworkObjectMgr.GetNetworkObject(id, true)
    if not o then return nil end

    local r = { id = id, owner = o.PlayerId, otype = o.ObjectType }
    local e = o:GetEntity()
    if e then
        r.addr = e:GetAddress()
        local p = e.Position
        if p then r.x, r.y, r.z = p.x, p.y, p.z end
    end

    if r.addr and type(r.owner) == "number" and r.owner >= 0 and r.owner <= 31 then
        local ped = Players.GetCPed(r.owner)
        if ped and ped:GetAddress() == r.addr then r.playerPed = true end
    end
    return r
end


function bd.readTail(buf, fw, aw, override)
    local out = {}
    out.flags = buf:ReadUns(fw)
    out.melee = buf:ReadBool()
    if out.melee then buf:ReadUns(32) buf:ReadUns(16) buf:ReadUns(32) end
    if override then out.damage = buf:ReadUns(17) end
    if buf:ReadBool() then buf:ReadUns(aw) end
    out.victimPlayer = buf:ReadBool()
    if out.victimPlayer then buf:ReadUns(16) buf:ReadUns(16) buf:ReadUns(16) end
    out.parentID = buf:ReadUns(13)
    local hit, ok = buf:ReadUns(13)
    if not ok then return nil end
    out.hitObjectID = hit
    return out
end

function bd.parseTail(bits, n, fw, aw, override)
    local i = 1
    local function u(w)
        if i + w - 1 > n then return nil end
        local v = 0
        for _ = 1, w do v = v * 2 + bits[i] i = i + 1 end
        return v
    end

    local out = {}
    out.flags = u(fw)                       if not out.flags then return nil end
    local m = u(1)                          if not m then return nil end
    out.melee = m == 1
    if out.melee then
        if not u(32) or not u(16) or not u(32) then return nil end
    end
    if override then
        out.damage = u(17)                  if not out.damage then return nil end
    end
    local agg = u(1)                        if not agg then return nil end
    if agg == 1 and not u(aw) then return nil end
    local vp = u(1)                         if not vp then return nil end
    out.victimPlayer = vp == 1
    if out.victimPlayer then
        if not u(16) or not u(16) or not u(16) then return nil end
    end
    out.parentID    = u(13)                 if not out.parentID then return nil end
    out.hitObjectID = u(13)                 if not out.hitObjectID then return nil end
    return out
end

function bd.calibrate(buf, override, senderPid)
    local bits, n = {}, 0
    for k = 1, bd.MAX_BITS do
        local v, ok = buf:ReadUns(1)
        if not ok then break end
        bits[k] = v
        n = k
    end

    local ordinary
    for idx = 1, #bd.LAYOUTS do
        local L  = bd.LAYOUTS[idx]
        local ev = bd.parseTail(bits, n, L[1], L[2], override)
        if ev then
            local p = bd.resolveObj(ev.parentID)
            local v = bd.resolveObj(ev.hitObjectID)
            if p and p.playerPed and p.owner ~= senderPid
               and v and v.playerPed then
                bd.layout = idx
                logf("BlameDetect: wire layout locked from forged player-ped pair: %d damage-flag bits, %d aggregation bits",
                     L[1], L[2])
                return ev
            end
            if not ordinary and p and p.owner == senderPid then
                ordinary = { idx = idx, ev = ev }
            end
        end
    end
    if ordinary then
        local L = bd.LAYOUTS[ordinary.idx]
        bd.layout = ordinary.idx
        logf("BlameDetect: wire layout locked from ordinary damage: %d damage-flag bits, %d aggregation bits",
             L[1], L[2])
        return ordinary.ev
    end
    return nil
end


function bd.inspect(sender, buf)
    local spid = sender.PlayerId
    if not bd.hookSeen then
        bd.hookSeen = true
        logf("BlameDetect: network hook active; first weapon-damage event from player %s",
             tostring(spid))
    end

    local dt       = buf:ReadUns(2)
    local weapon   = buf:ReadUns(32)
    local override = buf:ReadBool()
    buf:ReadBool()
    buf:ReadBool()
    buf:ReadBool()

    if dt == bd.DAMAGE_PLAYER then
        return
    end

    local ev
    if bd.layout then
        local L = bd.LAYOUTS[bd.layout]
        ev = bd.readTail(buf, L[1], L[2], override)
    else
        ev = bd.calibrate(buf, override, spid)
    end
    if not ev then return end

    local p = bd.resolveObj(ev.parentID)
    local v = bd.resolveObj(ev.hitObjectID)
    for i = 1, #bd.damageObservers do
        bd.damageObservers[i](
            p and p.playerPed and p.owner or nil, ev.parentID,
            v and v.playerPed and v.owner or nil, ev.hitObjectID)
    end
    if not p then
        bd.misses = bd.misses + 1
        if bd.layout and bd.misses >= bd.RELEARN then
            logf("BlameDetect: layout stopped resolving, re-learning")
            bd.layout, bd.misses = nil, 0
        end
        return
    end
    bd.misses = 0

    local why = {}
    if p.playerPed and p.owner ~= spid then
        why[#why + 1] = "attacker names another player ped"
    end
    if p.playerPed and v and v.playerPed then
        why[#why + 1] = "player-vs-player sent as DAMAGE_PED"
    end
    if #why == 0 then return end

    local dist
    if p.x and v and v.x then
        local dx, dy, dz = p.x - v.x, p.y - v.y, p.z - v.z
        dist = math.sqrt(dx * dx + dy * dy + dz * dz)
    end
    if ev.melee and dist and dist > bd.MELEE_MAX_M then
        why[#why + 1] = ("melee hit at %.0fm"):format(dist)
    end
    if ev.flags == bd.KNOWN_FLAGS then
        why[#why + 1] = "known blame-kill flag set"
    end

    local role = "bystander"
    if v and v.playerPed and v.owner == bd.mePid then
        role = "victim"
    elseif p.playerPed and p.owner == bd.mePid then
        role = "scapegoat"
    end
    local blocked = (bd.protect and role ~= "bystander") or false

    if #bd.queue >= bd.QUEUE_CAP then return blocked end
    bd.queue[#bd.queue + 1] = {
        at         = os.clock() * 1000,
        sender     = spid,
        senderName = bd.name(spid),
        blamed     = p.owner,
        blamedName = bd.name(p.owner),
        victim     = v and v.owner,
        victimName = v and bd.name(v.owner),
        weapon     = weapon,
        damage     = ev.damage,
        flags      = ev.flags,
        dist       = dist,
        role       = role,
        blocked    = blocked,
        why        = table.concat(why, ", "),
    }
    return blocked
end

function bd.onNetEvent(sender, eventId, buf)
    if not bd.enabled or scriptUnloading then return false end
    if eventId ~= bd.EV_WEAPON_DAMAGE or not sender or not buf then return false end
    return bd.inspect(sender, buf) == true
end


function bd.line(rec, h)
    if h.role == "victim" then
        if h.blocked then
            return "Blame Kill Blocked", ("%s tried to blame kill you"):format(rec.name)
        end
        return "Blame Kill", ("%s blame killed you - framed %s")
            :format(rec.name, rec.lastBlamed)
    elseif h.role == "scapegoat" then
        return "You Are Being Framed", ("%s is framing YOU for killing %s")
            :format(rec.name, rec.lastVictim)
    end
    return "Blame Kill", ("%s blame killed %s"):format(rec.name, rec.lastVictim)
end

function bd.tag(h)
    return (" [role=%s protect=%s dropped=%s]")
        :format(h.role or "?", tostring(bd.protect), tostring(h.blocked == true))
end

function bd.report(h)
    local rec = bd.seen[h.sender]
    if not rec then
        rec = { pid = h.sender, name = h.senderName or ("player " .. tostring(h.sender)),
                first = h.at, victims = {}, nVictims = 0, events = 0, sweep = false,
                toastAt = {}, sweepUntil = 0 }
        bd.seen[h.sender] = rec
    end

    rec.events     = rec.events + 1
    rec.last       = h.at
    rec.lastBlamed = h.blamedName or ("player " .. tostring(h.blamed))
    rec.lastVictim = h.victimName or ("player " .. tostring(h.victim))
    if h.victim and not rec.victims[h.victim] then
        rec.victims[h.victim] = h.at
        rec.nVictims = rec.nVictims + 1
    end

    local vkey  = h.victim or -1
    local last  = rec.toastAt[vkey]
    local fresh = (last == nil) or (h.at - last >= bd.REPEAT_MS)
    if fresh then rec.toastAt[vkey] = h.at end

    local recent = 0
    for _, t in pairs(rec.victims) do
        if h.at - t <= bd.SWEEP_MS then recent = recent + 1 end
    end
    local sweptNow = false
    if recent >= bd.SWEEP_MIN then
        rec.sweepUntil = h.at + bd.SWEEP_MS
        sweptNow = not rec.sweep
        rec.sweep = true
    end

    if rec.events == 1 then
        bd.say("%s is running Blame Kill - framed %s for killing %s (%s)%s",
            rec.name, rec.lastBlamed, rec.lastVictim, h.why, bd.tag(h))
        ModderDB.AddModderByPlayerId(h.sender, bd.REASON)
        local title, text = bd.line(rec, h)
        GUI.AddToast(title, text, 7000, eToastPos.TOP_RIGHT)
    elseif sweptNow then
        bd.say("%s blamed %d players at once - session-wide Blame Kill%s",
            rec.name, recent, bd.tag(h))
        GUI.AddToast(h.role == "scapegoat" and "You Are Being Framed"
                or "Blame Kill Detected",
            h.role == "scapegoat"
                and ("%s is framing YOU for the whole session"):format(rec.name)
                or ("%s blamed the whole session"):format(rec.name),
            7000, eToastPos.TOP_RIGHT)
    elseif fresh and h.at >= rec.sweepUntil then
        bd.say("%s blame killed %s - framed %s%s", rec.name, rec.lastVictim,
            rec.lastBlamed, bd.tag(h))
        local title, text = bd.line(rec, h)
        GUI.AddToast(title, text, 5000, eToastPos.TOP_RIGHT)
    end
end


function bd.tick()
    bd.mePid = GTA.GetLocalPlayerId()
    local q = bd.queue
    for _ = 1, bd.DRAIN do
        local h = table.remove(q, 1)
        if not h then break end
        bd.report(h)
    end
end

