local function telemetryJsonStr(s)
    s = s:gsub('\\', '\\\\'):gsub('"', '\\"'):gsub('\n', '\\n'):gsub('\r', '\\r'):gsub('\t', '\\t')
    return '"' .. s .. '"'
end

local function telemetryJsonEncode(v)
    local t = type(v)
    if t == "nil"     then return "null" end
    if t == "boolean" then return v and "true" or "false" end
    if t == "number"  then
        if v ~= v or v == math.huge or v == -math.huge then return "null" end
        if math.type and math.type(v) == "integer" then
            return string.format("%d", v)
        end
        if v == math.floor(v) and math.abs(v) < 1e15 then
            return string.format("%d", v)
        end
        return string.format("%.14g", v)
    end
    if t == "string"  then return telemetryJsonStr(v) end
    if t == "table"   then
        local parts = {}
        for k, val in pairs(v) do
            parts[#parts + 1] = telemetryJsonStr(tostring(k)) .. ":" .. telemetryJsonEncode(val)
        end
        return "{" .. table.concat(parts, ",") .. "}"
    end
    return "null"
end

local function telemetryHash(inputStr)
    local h = 2166136261
    local s = telemetry.SALT .. inputStr
    for i = 1, #s do
        h = (h ~ s:byte(i)) * 16777619 & 0xFFFFFFFF
    end
    return string.format("%08x", h)
end

local function telemetryBuildUid()
    return telemetryHash(tostring(Cherax.GetUID()))
end

local function telemetryFeatureBitmap()
    local lo, hi = 0, 0
    for i, hash in ipairs(TELEMETRY_FEATURES) do
        local on
        if hash == H.SUPER_MELEE then
            on = (FeatureMgr.GetFeatureInt(H.SUPER_MELEE) or 0) > 0
        elseif hash == H.PLAYER_SPEED_AUTO then
            local sp = playerState.vehAuthor.specByName["EnginePower"]
            on = sp and sp.everUsed
        elseif hash == H.RADIO_PICKER then
            on = radioCtl and radioCtl.pickerUsed
        elseif hash == H.BODYGUARDS then
            on = Bodyguards and Bodyguards.wasUsed and Bodyguards.wasUsed()
        elseif hash == H.BODYGUARDS_PACK then
            on = Bodyguards and Bodyguards.packUsed and Bodyguards.packUsed()
        elseif hash == H.BODYGUARDS_OVER_7 then
            on = Bodyguards and Bodyguards.over7Used and Bodyguards.over7Used()
        elseif hash == H.LOADOUT_MGR then
            on = LoadoutMgr and LoadoutMgr.wasUsed and LoadoutMgr.wasUsed()
        else
            local feat = FeatureMgr.GetFeature(hash)
            on = feat and feat:IsToggled()
        end
        if on then
            local bit = i - 1
            if bit < 53 then
                lo = lo | (1 << bit)
            else
                hi = hi | (1 << (bit - 53))
            end
        end
    end
    return lo, hi
end

local function telemetryCheraxVersion()
    local v = Cherax and Cherax.GetVersion and tostring(Cherax.GetVersion() or "?") or "?"
    local b = Cherax and Cherax.GetBuild and tostring(Cherax.GetBuild() or "?") or "?"
    return v .. "." .. b
end

local function telemetryGetIgn()
    local ign = ""
    local pid = GTA.GetLocalPlayerId()
    if pid and pid >= 0 then
        local name = PLAYER.GET_PLAYER_NAME(pid)
        if name and name ~= "" and name ~= "**Invalid**" and name ~= "NONE" then
            ign = tostring(name):sub(1, 32)
        end
    end
    return ign
end

telemetry._uid        = telemetryBuildUid()
telemetry._cuid       = math.tointeger(Cherax.GetUID() or 0) or 0
telemetry._battleye   = (Cherax.GetEdition():find("BE") ~= nil) and 1 or 0
telemetry._firstBeatSent = false
local telemetrySessionSeed = table.concat({
    telemetry._uid, tostring(os.time()), tostring(os.clock()), tostring({}),
}, ":")
telemetry._sessionId = telemetryHash(telemetrySessionSeed .. ":a")
                    .. telemetryHash(telemetrySessionSeed .. ":b")
telemetry._nextSeq = 1
telemetry._pendingBeat = nil

local TELEMETRY_FEATURE_LAYOUT = 4

local function telemetryBuildBody(counts, seq, firstBeat)
    local featuresLo, featuresHi = telemetryFeatureBitmap()
    return telemetryJsonEncode({
        uid            = telemetry._uid,
        cuid           = telemetry._cuid,
        version        = VIBE_VERSION,
        variant        = IS_ENHANCED and "enhanced" or "legacy",
        battleye       = telemetry._battleye,
        cherax         = telemetryCheraxVersion(),
        features       = featuresLo,
        features_hi    = featuresHi,
        feature_layout = TELEMETRY_FEATURE_LAYOUT,
        ign            = telemetryGetIgn(),
        loader         = VIBESCRIPT_LOADER and 1 or 0,
        first_beat     = firstBeat and 1 or 0,
        session_id    = telemetry._sessionId,
        seq            = seq,
        counts         = counts,
    })
end

local function telemetryBeatOnce()
    if not telemetry.ENABLED then return end
    for i = #telemetry._timedOut, 1, -1 do
        local finished = false
        pcall(function() finished = telemetry._timedOut[i]:GetFinished() end)
        if finished then table.remove(telemetry._timedOut, i) end
    end
    if not telemetry._pendingBeat then
        local counts = TELEMETRY_ACTIONS
        TELEMETRY_ACTIONS = {}
        local seq = telemetry._nextSeq
        telemetry._nextSeq = seq + 1
        local firstBeat = not telemetry._firstBeatSent
        telemetry._pendingBeat = {
            body = telemetryBuildBody(counts, seq, firstBeat),
            firstBeat = firstBeat,
        }
    end
    local pending = telemetry._pendingBeat

    local h
    local ok = pcall(function()
        h = Curl.Easy()
        h:Setopt(eCurlOption.CURLOPT_URL, telemetry.BEAT_URL)
        h:Setopt(eCurlOption.CURLOPT_CUSTOMREQUEST, "POST")
        h:Setopt(eCurlOption.CURLOPT_USERAGENT, "BladScript-Telemetry/1.0")
        h:Setopt(eCurlOption.CURLOPT_POSTFIELDS, pending.body)
        h:AddHeader("Content-Type: application/json")
        h:Perform()
    end)
    if not ok or not h then return end
    local deadline = Time.GetEpocheMs() + telemetry.REQUEST_TIMEOUT_MS
    while not h:GetFinished() do
        if Time.GetEpocheMs() >= deadline then
            telemetry._timedOut[#telemetry._timedOut + 1] = h
            return
        end
        Script.Yield()
    end
    local responseOk = false
    local banned = false
    pcall(function()
        local response = select(2, h:GetResponse())
        responseOk = type(response) == "string"
                 and response:find('"ok":true', 1, true) ~= nil
        banned = type(response) == "string"
             and response:find('"ban":1', 1, true) ~= nil
    end)
    if banned then
        GUI.AddToast("VibeScript",
            "You have been banned from using VibeScript.", 10000, eToastPos.TOP_RIGHT)
        SetShouldUnload()
        return
    end
    if responseOk then
        if pending.firstBeat then telemetry._firstBeatSent = true end
        telemetry._pendingBeat = nil
    end
end

Script.RegisterLooped(function()
    Script.Yield((telemetry._firstBeatSent and telemetry.INTERVAL_SEC or telemetry.WARMUP_SEC) * 1000)
    if scriptUnloading then return end
    telemetryBeatOnce()
end)

vibenet = {
    CONTRIBUTE_URL = "https://bladscript-telemetry.toasterboi.workers.dev/vibenet/contribute",
    CALIBRATE_URL  = "https://bladscript-telemetry.toasterboi.workers.dev/vibenet/calibrate",
    SCAN_URL       = "https://bladscript-telemetry.toasterboi.workers.dev/vibenet/scan",
    WARMUP_SEC     = 20,
    nextPollSec    = 600,
    POST_TIMEOUT_MS = 15000,
    SCAN_COOLDOWN_MS   = 30000,
    MAX_UNKNOWN_PER_TICK = 300,
    MAX_RIDS_PER_POST  = 1000,
    RESEND_SEC     = 86400,
    OPTIN_FILE     = settings.dir .. "\\vibenet.cfg",

    optIn          = false,
    consentPending = false,
    backoff        = false,
    lastScan       = 0,
    scanning       = false,
    sent           = {},
    pendingConfirmed = {},
    trustedIdentities = {},
    calibrationAnchors = {},
    scanAppendRids = {},
    queuedContribution = nil,
    manualScanQueued = false,
    manualScanKind = nil,
    _warmed        = false,
    _timedOut      = {},
}

function vibenet.loadOptIn()
    if not FileMgr.DoesFileExist(vibenet.OPTIN_FILE) then vibenet.optIn = false return end
    local content = FileMgr.ReadFileContent(vibenet.OPTIN_FILE)
    local value = content and tostring(content):match("^(%d+)%s*$") or nil
    vibenet.optIn = value == "1" or value == "2"
end

function vibenet.setOptIn(on)
    vibenet.optIn = on and true or false
    FileMgr.WriteFileContent(vibenet.OPTIN_FILE, vibenet.optIn and "1" or "0", false)
end

vibenet.loadOptIn()

function vibenet.post(url, body)
    for i = #vibenet._timedOut, 1, -1 do
        local finished = false
        pcall(function() finished = vibenet._timedOut[i]:GetFinished() end)
        if finished then table.remove(vibenet._timedOut, i) end
    end
    local h
    local ok = pcall(function()
        h = Curl.Easy()
        h:Setopt(eCurlOption.CURLOPT_URL, url)
        h:Setopt(eCurlOption.CURLOPT_CUSTOMREQUEST, "POST")
        h:Setopt(eCurlOption.CURLOPT_USERAGENT, "VibeNet/1.0")
        h:Setopt(eCurlOption.CURLOPT_POSTFIELDS, body)
        h:AddHeader("Content-Type: application/json")
        h:Perform()
    end)
    if not ok or not h then return nil end
    local deadline = Time.GetEpocheMs() + vibenet.POST_TIMEOUT_MS
    while not h:GetFinished() do
        if Time.GetEpocheMs() >= deadline then
            vibenet._timedOut[#vibenet._timedOut + 1] = h
            return nil
        end
        Script.Yield()
    end
    local response
    pcall(function()
        response = select(2, h:GetResponse())
    end)
    return response
end

function vibenet.liveSessionRids()
    local out, countries = {}, {}
    for pid = 0, 31 do
        local player = Players.GetById(pid)
        if player then
            local info = player:GetGamerInfo()
            local rid = info and math.tointeger(info.RockstarId or 0) or nil
            if rid and rid > 0 then
                out[#out + 1] = rid
                local ipInfo = Players.GetIPInfo(pid)
                local cc = ipInfo and tostring(ipInfo.countryCode or ""):upper() or ""
                if cc:match("^[A-Z][A-Z]$") and cc ~= "NA" then
                    countries[#countries + 1] = ('[%d,"%s"]'):format(rid, cc)
                end
            end
        end
    end
    return out, countries
end

function vibenet.publicIpv4(value)
    local a, b, c, d = tostring(value or ""):match(
        "^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
    a, b, c, d = tonumber(a), tonumber(b), tonumber(c), tonumber(d)
    if not a or a > 255 or b > 255 or c > 255 or d > 255 then return nil end
    if a == 0 or a == 10 or a == 127 or a >= 224 then return nil end
    if a == 100 and b >= 64 and b <= 127 then return nil end
    if a == 169 and b == 254 then return nil end
    if a == 172 and b >= 16 and b <= 31 then return nil end
    if a == 192 and b == 168 then return nil end
    if a == 192 and b == 0 and (c == 0 or c == 2) then return nil end
    if a == 198 and (b == 18 or b == 19 or b == 51 and c == 100) then return nil end
    if a == 203 and b == 0 and c == 113 then return nil end
    return ("%d.%d.%d.%d"):format(a, b, c, d)
end

function vibenet.trackerIpRows(rids)
    local rows = {}
    for _, rid in ipairs(rids or {}) do
        local entry = sessionBrowser.known[rid]
        local ip = entry and vibenet.publicIpv4(entry.directIp) or nil
        if ip then
            local seen = math.max(0, math.tointeger(entry.ipSeen or 0) or 0)
            rows[#rows + 1] = ('[%d,"%s",%d]'):format(rid, ip, seen)
        end
    end
    return rows
end

function vibenet.noteResolvedRows(rows)
    for _, row in ipairs(rows or {}) do
        if row.disc then
            for _, rid in ipairs(row.members or {}) do
                if vibenet.calibrationAnchors[rid] then
                    vibenet.trustedIdentities[
                        sessionBrowser.discIdentity(row.disc)] = true
                    break
                end
            end
        end
    end
    if not next(vibenet.trustedIdentities) then return end
    local before = 0
    for _ in pairs(vibenet.pendingConfirmed) do before = before + 1 end
    for _, row in ipairs(rows or {}) do
        if row.disc and vibenet.trustedIdentities[
                sessionBrowser.discIdentity(row.disc)] then
            local host = math.tointeger(row.hostRid)
            if host and host > 0 then vibenet.pendingConfirmed[host] = true end
            for _, value in ipairs(row.members or {}) do
                local rid = math.tointeger(value)
                if rid and rid > 0 then vibenet.pendingConfirmed[rid] = true end
            end
        end
    end
    local after = 0
    for _ in pairs(vibenet.pendingConfirmed) do after = after + 1 end
    if after > before then
        sessionBrowser.audit("VibeNet classifier: manual scan queued %d new "
            .. "same-build RID(s), pending=%d", after - before, after)
    end
end

function vibenet.unknownDelta(confirmedSet, cap)
    local now = Time.GetEpoche()
    local out = {}
    for rid in pairs(sessionBrowser.known) do
        if not confirmedSet[rid] then
            local last = vibenet.sent[rid]
            if not last or (now - last) >= vibenet.RESEND_SEC then
                out[#out + 1] = rid
                if #out >= cap then break end
            end
        end
    end
    return out
end

function vibenet.requestCalibration()
    local variant = IS_ENHANCED and "enhanced" or "legacy"
    local body = string.format('{"uid":"%s","variant":"%s"}', telemetry._uid, variant)
    local resp = vibenet.post(vibenet.CALIBRATE_URL, body)
    if type(resp) ~= "string" then return {} end
    local out = {}
    local section = resp:match('"rids"%s*:%s*%[(.-)%]')
    if section then
        for value in section:gmatch("%d+") do
            local rid = math.tointeger(value)
            if rid and rid > 0 then out[#out + 1] = rid end
        end
    end
    return out
end

function vibenet.contributeOnce(forcedUnknown, skipClassifier)
    if not vibenet.optIn then return end
    if not Natives.InvokeBool(sessionBrowser.N.IS_SIGNED_ONLINE) then return end
    sessionBrowser.ensureInit()
    sessionBrowser.harvestFriends()

    local variant = IS_ENHANCED and "enhanced" or "legacy"
    local confirmed, countries = vibenet.liveSessionRids()
    local confirmedSet = {}
    for _, rid in ipairs(confirmed) do confirmedSet[rid] = true end
    local unknown = forcedUnknown or vibenet.unknownDelta(
        confirmedSet, vibenet.MAX_UNKNOWN_PER_TICK)

    if #unknown > 0 and not forcedUnknown and vibenet.scanning
            and not sessionBrowser.state.busy then
        vibenet.queuedContribution = { unknown = unknown, resumeClassifier = true }
        sessionBrowser.audit("VibeNet contribution: queued behind pending VibeNet scan "
            .. "fetch; classifier runs afterward")
        return
    end

    if #unknown > 0 and sessionBrowser.state.busy
            and sessionBrowser.state.phase ~= "classifying" then
        local phase = sessionBrowser.state.phase
        local peerScan = phase == "seeding" or phase == "resolving"
            or phase == "querying"
        if not peerScan then
            vibenet.queuedContribution = { unknown = unknown }
            sessionBrowser.audit("VibeNet contribution: queued behind %s work",
                tostring(phase))
            return
        end
        vibenet.queuedContribution = { unknown = unknown, resumeClassifier = true }
        sessionBrowser.audit("VibeNet contribution: queued %d local RID(s) behind "
            .. "active scan; classifier resumes afterward", #unknown)
        return
    end

    if #unknown > 0 and not skipClassifier and not sessionBrowser.state.busy
            and not sessionBrowser.joinBusy then
        local calibration = vibenet.requestCalibration()
        local classified, classifyStatus = sessionBrowser.classifyCurrentBuild(
            unknown, calibration)
        for _, rid in ipairs(classified) do
            if not confirmedSet[rid] then
                confirmedSet[rid] = true
                confirmed[#confirmed + 1] = rid
            end
        end
        if #classified > 0 then
            local unresolved = {}
            for _, rid in ipairs(unknown) do
                if not confirmedSet[rid] then unresolved[#unresolved + 1] = rid end
            end
            unknown = unresolved
        end
        sessionBrowser.audit("VibeNet contribution: background status=%s classified=%d "
            .. "remaining-unknown=%d", tostring(classifyStatus), #classified, #unknown)
        if vibenet.manualScanQueued then
            for _, rid in ipairs(classified) do vibenet.pendingConfirmed[rid] = true end
            vibenet.queuedContribution = { unknown = unknown, resumeClassifier = true }
            local scanKind = vibenet.manualScanKind or "vibenet"
            vibenet.manualScanQueued = false
            vibenet.manualScanKind = nil
            sessionBrowser.audit("VibeNet contribution: manual scan queued; POST held "
                .. "until scan completion")
            if scanKind == "local" then
                Script.QueueJob(sessionBrowser.runScan)
            elseif scanKind == "native" then
                Script.QueueJob(sessionBrowser.runFind)
            else
                Script.QueueJob(function()
                    local left = vibenet.cooldownLeft()
                    if left > 0 then Script.Yield(left) end
                    vibenet.startScan()
                end)
            end
            return
        end
    elseif #unknown > 0 and not skipClassifier then
        sessionBrowser.audit("VibeNet contribution: classifier deferred "
            .. "(scan busy=%s join busy=%s)", tostring(sessionBrowser.state.busy),
            tostring(sessionBrowser.joinBusy))
    end

    for rid in pairs(vibenet.pendingConfirmed) do
        if #confirmed + #unknown >= vibenet.MAX_RIDS_PER_POST then break end
        if not confirmedSet[rid] then
            confirmedSet[rid] = true
            confirmed[#confirmed + 1] = rid
        end
    end
    if #unknown > 0 then
        local unresolved = {}
        for _, rid in ipairs(unknown) do
            if not confirmedSet[rid] then unresolved[#unresolved + 1] = rid end
        end
        unknown = unresolved
    end
    if #confirmed == 0 and #unknown == 0 then return end

    sessionBrowser.audit("VibeNet contribution: posting confirmed=%d unknown=%d pending=%d",
        #confirmed, #unknown, (function()
            local n = 0
            for _ in pairs(vibenet.pendingConfirmed) do n = n + 1 end
            return n
        end)())

    local ipRows = vibenet.trackerIpRows(unknown)
    local body = string.format(
        '{"uid":"%s","variant":"%s","confirmed":[%s],"unknown":[%s],'
            .. '"countries":[%s],"direct_ips":[%s]}',
        telemetry._uid, variant,
        table.concat(confirmed, ","), table.concat(unknown, ","),
        table.concat(countries, ","), table.concat(ipRows, ","))
    local resp = vibenet.post(vibenet.CONTRIBUTE_URL, body)
    if type(resp) ~= "string" then return end

    local nextPoll = resp:match('"next_poll_sec"%s*:%s*(%d+)')
    if nextPoll then vibenet.nextPollSec = math.max(60, math.tointeger(nextPoll) or 600) end

    local throttled = resp:find('"throttled":true', 1, true) ~= nil
    local disabled  = resp:find('"enabled":0', 1, true) ~= nil
    if throttled or disabled then
        vibenet.backoff = true
        return
    end
    if resp:find('"ok":true', 1, true) then
        vibenet.backoff = false
        local now = Time.GetEpoche()
        for _, rid in ipairs(confirmed) do
            vibenet.sent[rid] = now
            vibenet.pendingConfirmed[rid] = nil
        end
        for _, rid in ipairs(unknown) do vibenet.sent[rid] = now end
        sessionBrowser.audit("VibeNet contribution: accepted confirmed=%d unknown=%d",
            #confirmed, #unknown)
        if forcedUnknown then vibenet.queuedContribution = nil end
    end
end

function vibenet.requestScan()
    local variant = IS_ENHANCED and "enhanced" or "legacy"
    local body = string.format('{"uid":"%s","variant":"%s"}', telemetry._uid, variant)
    local resp = vibenet.post(vibenet.SCAN_URL, body)
    if type(resp) ~= "string" then return nil, "no response from VibeNet" end
    if resp:find('"enabled":0', 1, true) then return nil, "VibeNet is temporarily disabled" end

    local rids = {}
    local section = resp:match('"rids"%s*:%s*%[(.-)%]')
    if section then
        for rid in section:gmatch("%d+") do
            local n = math.tointeger(rid)
            if n and n > 0 then rids[#rids + 1] = n end
        end
    end
    return rids
end

function vibenet.onScanButton()
    if not vibenet.optIn then
        vibenet.consentPending = true
        return
    end
    vibenet.startScan()
end

function vibenet.cooldownLeft()
    if vibenet.lastScan <= 0 then return 0 end
    local left = vibenet.SCAN_COOLDOWN_MS - (Time.GetEpocheMs() - vibenet.lastScan)
    return (left > 0) and left or 0
end

function vibenet.startScan()
    if sessionBrowser.state.busy and sessionBrowser.state.phase == "classifying" then
        vibenet.manualScanQueued = true
        vibenet.manualScanKind = "vibenet"
        sessionBrowser.audit("VibeNet scan: queued behind active contribution classifier")
        return
    end
    if sessionBrowser.state.busy or vibenet.scanning then
        sessionBrowser.toast("A scan is already running.")
        return
    end
    local left = vibenet.cooldownLeft()
    if left > 0 then
        sessionBrowser.toast(("VibeNet cooldown: %ds left."):format(
            math.ceil(left / 1000)), 4000)
        return
    end
    vibenet.scanning = true
    Script.QueueJob(function()
        local ok, err = pcall(function()
            sessionBrowser.toast("VibeNet: fetching recent RIDs...", 4000)
            local rids, rerr = vibenet.requestScan()
            if not rids then
                sessionBrowser.toast("VibeNet: " .. tostring(rerr or "no RIDs"), 6000)
                return
            end
            if #rids == 0 then
                sessionBrowser.toast("VibeNet returned no RIDs yet. Try again shortly.", 6000)
                return
            end
            sessionBrowser.toast(("VibeNet: scanning %d RIDs..."):format(#rids), 4000)
            sessionBrowser.runScan(rids)
        end)
        vibenet.lastScan = Time.GetEpocheMs()
        vibenet.scanning = false
        if not ok then
            sessionBrowser.logError("VibeNet scan failed: %s", tostring(err))
        end
        if vibenet.queuedContribution and not sessionBrowser.state.busy then
            local queued = vibenet.queuedContribution
            vibenet.contributeOnce(queued.unknown, not queued.resumeClassifier)
        end
    end)
end

Script.RegisterLooped(function()
    local wait = vibenet._warmed and vibenet.nextPollSec or vibenet.WARMUP_SEC
    if vibenet.backoff then wait = wait * 2 end
    Script.Yield(wait * 1000)
    vibenet._warmed = true
    if scriptUnloading then return end
    sessionBrowser.audit("VibeNet contribution timer: fired optIn=%s",
        tostring(vibenet.optIn))
    local queued = vibenet.queuedContribution
    local ok, err
    if queued and not sessionBrowser.state.busy then
        ok, err = pcall(vibenet.contributeOnce, queued.unknown, false)
    else
        ok, err = pcall(vibenet.contributeOnce)
    end
    if not ok then
        sessionBrowser.logError("VibeNet contribution crashed: %s", tostring(err))
    end
end)

do
    local intro = {
        ENABLED    = (settings.introEnabled ~= false),
        TIMEOUT_MS = 0,
        BASE       = "https://vibescript-assets.pages.dev",
        COUNT      = 25,
        FPS        = 26,
        HOLD       = 2500,
        FADE       = 1200,
        WIDTH_FRAC = 0.75,
        MAX_H_FRAC = 0.85,
        PER_TICK   = 8,
        MAX_ATTEMPTS = 5,
        RETRY_DELAY  = 600,
        VALIDATE_TIMEOUT = 5000,
        loadAttempts = 0, retryAt = 0, validateStart = nil,
        t0 = nil, deadline = 0,
        netPhase = "checkver",
        texPhase = "idle",
        playPhase = "waiting",
        focused = false,
        frames = {}, loadCursor = 0,
        curlVer = nil, curlZip = nil, zipKicked = false,
        localVer = nil, remoteVer = nil, framesOnDisk = false, playStart = 0,
    }
    intro.dir       = FileMgr.GetMenuRootPath() .. "\\lua\\VibeScript\\intro"
    intro.framesDir = intro.dir .. "\\frames"
    intro.zipPath   = intro.dir .. "\\intro.zip"
    intro.verFile   = intro.dir .. "\\version.txt"

    function intro.framePath(i)
        return intro.framesDir .. "\\frame_" .. string.format("%02d", i) .. ".png"
    end

    function intro.dlog(msg)
        if VIBESCRIPT_VERBOSE then
            Logger.LogInfo("[VibeScript intro] " .. tostring(msg))
        end
    end

    function intro.log(msg)
        if not VIBESCRIPT_VERBOSE then return end
        Logger.LogInfo("[VibeScript intro] " .. tostring(msg))
    end

    function intro.newCurl(url)
        local h = Curl.Easy()
        h:Setopt(eCurlOption.CURLOPT_URL, url)
        h:Setopt(eCurlOption.CURLOPT_USERAGENT, "VibeScript-Intro")
        h:Perform()
        return h
    end

    function intro.startLoad()
        if intro.texPhase ~= "idle" and intro.texPhase ~= "failed" then return end
        intro.frames = {}
        intro.loadCursor = 0
        intro.validateStart = nil
        intro.loadAttempts = intro.loadAttempts + 1
        intro.texPhase = "loading"
        intro.log("load attempt " .. intro.loadAttempts .. "/" .. intro.MAX_ATTEMPTS)
    end

    function intro.driveLoad()
        if intro.texPhase ~= "failed" then return end
        if not intro.framesOnDisk then return end
        if intro.loadAttempts >= intro.MAX_ATTEMPTS then return end
        if Time.GetEpocheMs() < intro.retryAt then return end
        intro.startLoad()
    end

    function intro.ensureInit()
        if intro.t0 then return end
        local now = Time.GetEpocheMs()
        intro.t0 = now
        intro.deadline = now + intro.TIMEOUT_MS
        FileMgr.CreateDir(intro.dir)
        for i = intro.COUNT, 99 do
            local p = intro.framePath(i)
            if FileMgr.DoesFileExist(p) then FileMgr.DeleteFile(p) end
        end
        if FileMgr.DoesFileExist(intro.verFile) then
            local v = FileMgr.ReadFileContent(intro.verFile)
            if v then intro.localVer = v:gsub("%s+", "") end
        end
        intro.framesOnDisk = FileMgr.DoesFileExist(intro.framePath(0))
            and FileMgr.DoesFileExist(intro.framePath(intro.COUNT - 1))
        if intro.framesOnDisk then intro.startLoad() end
        local ok = pcall(function() intro.curlVer = intro.newCurl(intro.BASE .. "/version.txt") end)
        if not ok then
            intro.curlVer = nil
            intro.netPhase = intro.framesOnDisk and "done" or "failed"
        end
        intro.log("init cache=" .. tostring(intro.framesOnDisk) .. " ver=" .. tostring(intro.localVer))
    end

    function intro.stepNet()
        local np = intro.netPhase
        if np == "done" or np == "failed" then return end

        if np == "checkver" then
            if not intro.curlVer then
                intro.netPhase = intro.framesOnDisk and "done" or "failed"
                return
            end
            local fin = false
            pcall(function() fin = intro.curlVer:GetFinished() end)
            if not fin then return end
            local code, body
            pcall(function() code, body = intro.curlVer:GetResponse() end)
            intro.curlVer = nil
            if code == eCurlCode.CURLE_OK and body and #body > 0 then
                intro.remoteVer = body:gsub("%s+", "")
                if intro.framesOnDisk and intro.remoteVer == intro.localVer then
                    intro.netPhase = "done"
                else
                    intro.netPhase = "download"
                end
            else
                intro.netPhase = intro.framesOnDisk and "done" or "failed"
            end

        elseif np == "download" then
            if not intro.zipKicked then
                intro.zipKicked = true
                local ok = pcall(function() intro.curlZip = intro.newCurl(intro.BASE .. "/intro.zip") end)
                if not ok then intro.curlZip = nil end
            end
            if not intro.curlZip then
                intro.netPhase = intro.framesOnDisk and "done" or "failed"
                return
            end
            local fin = false
            pcall(function() fin = intro.curlZip:GetFinished() end)
            if not fin then return end
            local code, body
            pcall(function() code, body = intro.curlZip:GetResponse() end)
            intro.curlZip = nil
            if code == eCurlCode.CURLE_OK and body and #body > 1000 then
                local wrote = false
                pcall(function()
                    local f = io.open(intro.zipPath, "wb")
                    if f then f:write(body); f:close(); wrote = true end
                end)
                intro.netPhase = wrote and "unzip" or (intro.framesOnDisk and "done" or "failed")
            else
                intro.netPhase = intro.framesOnDisk and "done" or "failed"
            end

        elseif np == "unzip" then
            local runBody = function()
                FileMgr.CreateDir(intro.framesDir)
                FileMgr.Unzip(intro.zipPath, intro.framesDir)
            end
            runBody()
            if FileMgr.DoesFileExist(intro.framePath(0)) then
                if intro.remoteVer then
                    FileMgr.WriteFileContent(intro.verFile, intro.remoteVer, false)
                end
                intro.framesOnDisk = true
                intro.loadAttempts = 0
                if intro.texPhase == "idle" or intro.texPhase == "failed" then intro.startLoad() end
                intro.log("cache refreshed ver=" .. tostring(intro.remoteVer))
            end
            FileMgr.DeleteFile(intro.zipPath)
            intro.netPhase = "done"
        end
    end

    function intro.stepTex()
        if intro.texPhase == "loading" then
            local target = math.min(intro.loadCursor + intro.PER_TICK, intro.COUNT)
            while intro.loadCursor < target do
                local i = intro.loadCursor
                local id = 0
                pcall(function() id = Texture.LoadTexture(intro.framePath(i)) or 0 end)
                if id == 0 then
                    intro.texPhase = "failed"
                    intro.retryAt = Time.GetEpocheMs() + intro.RETRY_DELAY
                    intro.log("LoadTexture failed at frame " .. i .. " (attempt " .. intro.loadAttempts .. ")")
                    return
                end
                intro.frames[i] = id
                intro.loadCursor = i + 1
            end
            if intro.loadCursor >= intro.COUNT then
                intro.texPhase = "validating"
                intro.validateStart = Time.GetEpocheMs()
            end

        elseif intro.texPhase == "validating" then
            for i = 0, intro.COUNT - 1 do
                local valid = false
                pcall(function() valid = Texture.IsTextureValid(intro.frames[i]) end)
                if not valid then
                    if intro.validateStart
                       and (Time.GetEpocheMs() - intro.validateStart) > intro.VALIDATE_TIMEOUT then
                        intro.texPhase = "failed"
                        intro.retryAt = Time.GetEpocheMs() + intro.RETRY_DELAY
                        intro.log("validate timeout at frame " .. i .. " (attempt " .. intro.loadAttempts .. ")")
                    end
                    return
                end
            end
            intro.texPhase = "ready"
            intro.log("frames ready (attempt " .. intro.loadAttempts .. ")")
        end
    end

    function intro.render()
        local elapsed  = Time.GetEpocheMs() - intro.playStart
        local revealMs = (intro.COUNT / intro.FPS) * 1000.0
        local total    = revealMs + intro.HOLD + intro.FADE
        if elapsed >= total then intro.playPhase = "ended"; return end

        local idx, alpha = intro.COUNT - 1, 255
        if elapsed < revealMs then
            idx = math.floor(elapsed / 1000.0 * intro.FPS)
            if idx > intro.COUNT - 1 then idx = intro.COUNT - 1 end
        elseif elapsed < revealMs + intro.HOLD then
            idx = intro.COUNT - 1
        else
            local fo = elapsed - revealMs - intro.HOLD
            alpha = math.floor((1.0 - fo / intro.FADE) * 255)
            if alpha < 0 then alpha = 0 end
        end

        local texId = intro.frames[idx]
        if not texId then return end

        local handle, sw, sh, w, h
        local runBody = function()
            local d3d = Texture.GetTexture(texId)
            if not d3d then return end
            handle = d3d:GetCurrent()
            local tw, th = d3d:GetWidth(), d3d:GetHeight()
            sw, sh = ImGui.GetDisplaySize()
            local aspect = (tw and tw > 0 and th) and (th / tw) or (450.0 / 800.0)
            w = sw * intro.WIDTH_FRAC
            h = w * aspect
            local maxH = sh * intro.MAX_H_FRAC
            if h > maxH then h = maxH; w = h / aspect end
        end
        runBody()
        if not handle or not sw then return end

        ImGui.SetNextWindowPos(0, 0, ImGuiCond.Always)
        ImGui.SetNextWindowSize(sw, sh, ImGuiCond.Always)
        if not intro.focused then
            ImGui.SetNextWindowFocus()
            intro.focused = true
        end
        local flags = ImGuiWindowFlags.NoTitleBar
            | ImGuiWindowFlags.NoResize
            | ImGuiWindowFlags.NoMove
            | ImGuiWindowFlags.NoCollapse
            | ImGuiWindowFlags.NoScrollbar
            | ImGuiWindowFlags.NoSavedSettings
            | ImGuiWindowFlags.NoBackground
            | ImGuiWindowFlags.NoInputs
        ImGui.Begin("##VibeScriptIntro", true, flags)
        pcall(function() ImGui.AddImageRotated(handle, sw / 2.0, sh / 2.0, w, h, 0.0, alpha) end)
        ImGui.End()
    end

    function intro.stepPlay()
        if intro.playPhase == "waiting" then
            local now = Time.GetEpocheMs()
            local expired = (intro.TIMEOUT_MS > 0) and (now > intro.deadline)
            if intro.texPhase == "ready" and not expired then
                intro.playPhase = "playing"
                intro.playStart = now
                intro.log("playing")
            elseif (expired and intro.texPhase ~= "ready")
                or (intro.texPhase == "failed" and intro.loadAttempts >= intro.MAX_ATTEMPTS)
                or (intro.netPhase == "failed" and not intro.framesOnDisk) then
                intro.playPhase = "skipped"
                intro.log("skipped (assets unavailable or timed out)")
            end
        end
        if intro.playPhase == "playing" then intro.render() end
    end

    if intro.ENABLED then
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            if scriptUnloading then return end
            if (intro.playPhase == "ended" or intro.playPhase == "skipped")
               and (intro.netPhase == "done" or intro.netPhase == "failed") then
                return
            end
            intro.ensureInit()
            intro.stepNet()
            intro.driveLoad()
            intro.stepTex()
            intro.stepPlay()
        end)
    end
end
